/// One checked secure-credential request for builders and agents.
#[derive(Debug, Clone)]
pub enum SecureCredentialRequest {
    /// Write a credential to the platform keychain.
    Write(CredentialBuilder),
    /// Read a credential from the platform keychain.
    Read(CredentialServiceBuilder),
    /// Delete a credential from the platform keychain.
    Delete(CredentialServiceBuilder),
    /// Preflight native keychain/credential-manager support.
    FeaturePreflight(crate::CapabilityReport),
    /// Install or validate the app permission broker before credential work.
    PermissionBroker(PermissionBrokerInstallBuilder),
    /// Export redacted support diagnostics for credential flows.
    SupportDiagnostics(SupportDiagnosticsBuilder),
    /// Delegate auth state to an explicit hosted browser profile.
    HostedAuthProfile {
        /// Redacted hosted browser profile identifier.
        profile_id: String,
    },
    /// Native credential backend, rotation, or passkey/WebAuthn work still required.
    RoadmapWork {
        /// Redacted reason for credential roadmap work.
        reason: String,
    },
}

impl SecureCredentialRequest {
    /// Validate one secure-credential request without mutating keychain state.
    pub fn validate(&self, process_id: ProcessId) -> Result<()> {
        match self {
            Self::Write(credential) => credential.validate(),
            Self::Read(service) | Self::Delete(service) => service.validate(),
            Self::FeaturePreflight(report) => report
                .require_available(crate::PlatformFeature::SecureKeychain)
                .map_err(anyhow::Error::msg),
            Self::PermissionBroker(broker) => broker.validate(process_id),
            Self::SupportDiagnostics(diagnostics) => diagnostics.validate(),
            Self::HostedAuthProfile { profile_id } => {
                validate_app_storage_id(profile_id, "hosted auth profile id")
            }
            Self::RoadmapWork { reason } => {
                validate_app_metadata_text(reason, "secure credential roadmap reason", 160, false)
            }
        }
    }

    /// Privacy-preserving request kind for summaries.
    pub fn summary_kind(&self) -> &'static str {
        match self {
            Self::Write(_) => "write",
            Self::Read(_) => "read",
            Self::Delete(_) => "delete",
            Self::FeaturePreflight(_) => "feature-preflight",
            Self::PermissionBroker(_) => "permission-broker",
            Self::SupportDiagnostics(_) => "support-diagnostics",
            Self::HostedAuthProfile { .. } => "hosted-auth-profile",
            Self::RoadmapWork { .. } => "roadmap-work",
        }
    }
}

/// Recommended next implementation action for secure credential handoffs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SecureCredentialNextAction {
    /// Check native keychain/credential-manager support.
    CheckSecureKeychain,
    /// Install or validate the permission broker.
    InstallPermissionBroker,
    /// Write a credential.
    WriteCredential,
    /// Read a credential.
    ReadCredential,
    /// Delete a credential.
    DeleteCredential,
    /// Export redacted diagnostics.
    ExportSupportDiagnostics,
    /// Use an explicit hosted auth/profile island.
    UseHostedAuthProfile,
    /// Track native credential roadmap work.
    TrackRoadmapWork,
}

/// Checked native-first handoff for keychain writes, reads, deletes, diagnostics, and auth fallback.
#[derive(Debug, Clone)]
pub struct SecureCredentialHandoff {
    process_id: ProcessId,
    requests: Vec<SecureCredentialRequest>,
}

impl SecureCredentialHandoff {
    /// Start building a secure credential handoff.
    pub fn builder(process_id: ProcessId) -> SecureCredentialHandoffBuilder {
        SecureCredentialHandoffBuilder::new(process_id)
    }

    /// Process id used for permission-broker validation.
    pub fn process_id(&self) -> ProcessId {
        self.process_id
    }

    /// Requests covered by this handoff.
    pub fn requests(&self) -> &[SecureCredentialRequest] {
        &self.requests
    }

    /// Number of requests in the handoff.
    pub fn request_count(&self) -> usize {
        self.requests.len()
    }

    /// Whether this handoff includes native keychain support preflight.
    pub fn has_feature_preflight(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::FeaturePreflight(_)))
    }

    /// Whether this handoff includes permission broker setup.
    pub fn has_permission_broker(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::PermissionBroker(_)))
    }

    /// Whether this handoff writes a credential.
    pub fn has_write(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::Write(_)))
    }

    /// Whether this handoff reads a credential.
    pub fn has_read(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::Read(_)))
    }

    /// Whether this handoff deletes a credential.
    pub fn has_delete(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::Delete(_)))
    }

    /// Whether this handoff includes support diagnostics.
    pub fn has_support_diagnostics(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::SupportDiagnostics(_)))
    }

    /// Whether this handoff delegates to hosted browser auth state.
    pub fn has_hosted_auth_profile(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::HostedAuthProfile { .. }))
    }

    /// Whether this handoff includes roadmap work.
    pub fn has_roadmap_work(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, SecureCredentialRequest::RoadmapWork { .. }))
    }

    /// First recommended action for a builder or AI agent.
    pub fn next_action(&self) -> SecureCredentialNextAction {
        if self.has_feature_preflight() {
            SecureCredentialNextAction::CheckSecureKeychain
        } else if self.has_permission_broker() {
            SecureCredentialNextAction::InstallPermissionBroker
        } else if self.has_write() {
            SecureCredentialNextAction::WriteCredential
        } else if self.has_read() {
            SecureCredentialNextAction::ReadCredential
        } else if self.has_delete() {
            SecureCredentialNextAction::DeleteCredential
        } else if self.has_support_diagnostics() {
            SecureCredentialNextAction::ExportSupportDiagnostics
        } else if self.has_hosted_auth_profile() {
            SecureCredentialNextAction::UseHostedAuthProfile
        } else {
            SecureCredentialNextAction::TrackRoadmapWork
        }
    }

    /// Validate all handoff requests.
    pub fn validate(&self) -> Result<()> {
        anyhow::ensure!(
            !self.requests.is_empty(),
            "secure credential handoff must include at least one request"
        );
        anyhow::ensure!(
            self.requests.len() <= 32,
            "secure credential handoff cannot include more than 32 requests"
        );
        for request in &self.requests {
            request.validate(self.process_id)?;
        }
        Ok(())
    }

    /// Privacy-preserving summary for logs, tests, and AI-agent traces.
    pub fn to_text(&self) -> String {
        let kinds = self
            .requests
            .iter()
            .map(SecureCredentialRequest::summary_kind)
            .collect::<Vec<_>>()
            .join(", ");
        format!(
            "secure credential handoff: requests={} next_action={:?} feature_preflight={} permission_broker={} write={} read={} delete={} support_diagnostics={} hosted_auth_profile={} roadmap_work={} kinds=[{}]",
            self.request_count(),
            self.next_action(),
            self.has_feature_preflight(),
            self.has_permission_broker(),
            self.has_write(),
            self.has_read(),
            self.has_delete(),
            self.has_support_diagnostics(),
            self.has_hosted_auth_profile(),
            self.has_roadmap_work(),
            kinds
        )
    }
}

/// Builder for checked secure credential handoffs.
#[derive(Debug, Clone)]
pub struct SecureCredentialHandoffBuilder {
    process_id: ProcessId,
    requests: Vec<SecureCredentialRequest>,
}

impl SecureCredentialHandoffBuilder {
    /// Create an empty secure credential handoff builder.
    pub fn new(process_id: ProcessId) -> Self {
        Self {
            process_id,
            requests: Vec::new(),
        }
    }

    /// Add a credential write request.
    pub fn write(mut self, credential: CredentialBuilder) -> Self {
        self.requests
            .push(SecureCredentialRequest::Write(credential));
        self
    }

    /// Add a credential read request.
    pub fn read(mut self, service: CredentialServiceBuilder) -> Self {
        self.requests.push(SecureCredentialRequest::Read(service));
        self
    }

    /// Add a credential delete request.
    pub fn delete(mut self, service: CredentialServiceBuilder) -> Self {
        self.requests.push(SecureCredentialRequest::Delete(service));
        self
    }

    /// Add native keychain support preflight.
    pub fn feature_preflight(mut self, report: crate::CapabilityReport) -> Self {
        self.requests
            .push(SecureCredentialRequest::FeaturePreflight(report));
        self
    }

    /// Add permission broker setup.
    pub fn permission_broker(mut self, broker: PermissionBrokerInstallBuilder) -> Self {
        self.requests
            .push(SecureCredentialRequest::PermissionBroker(broker));
        self
    }

    /// Add support diagnostics.
    pub fn support_diagnostics(mut self, diagnostics: SupportDiagnosticsBuilder) -> Self {
        self.requests
            .push(SecureCredentialRequest::SupportDiagnostics(diagnostics));
        self
    }

    /// Add hosted auth profile fallback.
    pub fn hosted_auth_profile(mut self, profile_id: impl Into<String>) -> Self {
        self.requests
            .push(SecureCredentialRequest::HostedAuthProfile {
                profile_id: profile_id.into(),
            });
        self
    }

    /// Add roadmap credential work.
    pub fn roadmap_work(mut self, reason: impl Into<String>) -> Self {
        self.requests.push(SecureCredentialRequest::RoadmapWork {
            reason: reason.into(),
        });
        self
    }

    /// Validate the handoff without consuming the builder.
    pub fn validate(&self) -> Result<()> {
        self.as_handoff().validate()
    }

    /// Build a checked secure credential handoff.
    pub fn build_checked(self) -> Result<SecureCredentialHandoff> {
        let handoff = self.as_handoff();
        handoff.validate()?;
        Ok(handoff)
    }

    fn as_handoff(&self) -> SecureCredentialHandoff {
        SecureCredentialHandoff {
            process_id: self.process_id,
            requests: self.requests.clone(),
        }
    }
}

fn validate_credential_service(service: &str) -> Result<()> {
    validate_credential_label(service, "credential service")?;
    anyhow::ensure!(
        !service.contains('\0'),
        "credential service cannot contain NUL characters"
    );
    Ok(())
}

fn validate_credential_label(value: &str, label: &str) -> Result<()> {
    anyhow::ensure!(!value.trim().is_empty(), "{label} cannot be empty");
    anyhow::ensure!(
        value == value.trim(),
        "{label} cannot have leading or trailing whitespace"
    );
    anyhow::ensure!(
        value.len() <= 512,
        "{label} cannot be longer than 512 bytes"
    );
    anyhow::ensure!(
        !value.chars().any(char::is_control),
        "{label} cannot contain control characters"
    );
    Ok(())
}

/// Builder for launch-at-login settings.
#[derive(Debug, Clone)]
pub struct AutoLaunchBuilder {
    app_id: String,
    enabled: bool,
}

/// Checked launch-at-login configuration before platform mutation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AutoLaunchPlan {
    app_id: String,
    enabled: bool,
}

impl AutoLaunchPlan {
    /// Application identifier used for platform registration.
    pub fn app_id(&self) -> &str {
        &self.app_id
    }

    /// Requested launch-at-login state.
    pub fn requested_enabled(&self) -> bool {
        self.enabled
    }

    /// Whether this plan enables launch-at-login.
    pub fn enables_launch_at_login(&self) -> bool {
        self.enabled
    }

    /// Whether this plan disables launch-at-login.
    pub fn disables_launch_at_login(&self) -> bool {
        !self.enabled
    }

    /// Consume the plan into platform configuration arguments.
    pub fn into_parts(self) -> (String, bool) {
        (self.app_id, self.enabled)
    }

    /// Stable diagnostic text for generated preferences and setup flows.
    pub fn to_text(&self) -> String {
        format!(
            "auto-launch {} for app id configured true",
            if self.enabled { "enable" } else { "disable" },
        )
    }
}

impl AutoLaunchBuilder {
    /// Enable launch-at-login for the application identifier.
    pub fn enable(app_id: impl Into<String>) -> Self {
        Self {
            app_id: app_id.into(),
            enabled: true,
        }
    }

    /// Disable launch-at-login for the application identifier.
    pub fn disable(app_id: impl Into<String>) -> Self {
        Self {
            app_id: app_id.into(),
            enabled: false,
        }
    }

    /// Set whether launch-at-login should be enabled.
    pub fn enabled(mut self, enabled: bool) -> Self {
        self.enabled = enabled;
        self
    }

    /// Return the configured application identifier.
    pub fn app_id(&self) -> &str {
        &self.app_id
    }

    /// Return the requested launch-at-login state.
    pub fn requested_enabled(&self) -> bool {
        self.enabled
    }

    /// Validate the application identifier.
    pub fn validate(&self) -> Result<()> {
        anyhow::ensure!(
            !self.app_id.trim().is_empty(),
            "auto-launch app id cannot be empty"
        );
        anyhow::ensure!(
            self.app_id == self.app_id.trim(),
            "auto-launch app id cannot have leading or trailing whitespace"
        );
        anyhow::ensure!(
            !self
                .app_id
                .chars()
                .any(|ch| ch.is_control() || ch.is_whitespace()),
            "auto-launch app id cannot contain whitespace or control characters"
        );
        Ok(())
    }

    /// Build the validated app id and requested state.
    pub fn build_checked(self) -> Result<(String, bool)> {
        Ok(self.build_plan_checked()?.into_parts())
    }

    /// Build a checked launch-at-login plan.
    pub fn build_plan_checked(self) -> Result<AutoLaunchPlan> {
        self.validate()?;
        Ok(AutoLaunchPlan {
            app_id: self.app_id,
            enabled: self.enabled,
        })
    }
}

