/// Well-known application path roles for app-owned storage and user handoff locations.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AppPathRole {
    /// User data owned by the app, such as databases and durable state.
    Data,
    /// User-editable configuration owned by the app.
    Config,
    /// Rebuildable cache data owned by the app.
    Cache,
    /// App log output.
    Logs,
    /// Temporary files scoped to this app.
    Temp,
    /// The user's downloads directory.
    Downloads,
}

impl AppPathRole {
    /// Stable role key for diagnostics and generated manifests.
    pub fn key(self) -> &'static str {
        match self {
            Self::Data => "data",
            Self::Config => "config",
            Self::Cache => "cache",
            Self::Logs => "logs",
            Self::Temp => "temp",
            Self::Downloads => "downloads",
        }
    }

    /// Whether this role is app-owned and scoped by the app id.
    pub fn is_app_scoped(self) -> bool {
        !matches!(self, Self::Downloads)
    }
}

/// Resolved application paths for a validated app identifier.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppPathSet {
    app_id: String,
    paths: Vec<(AppPathRole, PathBuf)>,
}

impl AppPathSet {
    /// The application identifier used to scope app-owned paths.
    pub fn app_id(&self) -> &str {
        &self.app_id
    }

    /// All resolved role/path pairs, in builder order.
    pub fn paths(&self) -> &[(AppPathRole, PathBuf)] {
        &self.paths
    }

    /// Return the path for a role when it was requested.
    pub fn get(&self, role: AppPathRole) -> Option<&Path> {
        self.paths
            .iter()
            .find_map(|(candidate, path)| (*candidate == role).then_some(path.as_path()))
    }

    /// User data directory.
    pub fn data_dir(&self) -> Option<&Path> {
        self.get(AppPathRole::Data)
    }

    /// User configuration directory.
    pub fn config_dir(&self) -> Option<&Path> {
        self.get(AppPathRole::Config)
    }

    /// Rebuildable cache directory.
    pub fn cache_dir(&self) -> Option<&Path> {
        self.get(AppPathRole::Cache)
    }

    /// Log directory.
    pub fn logs_dir(&self) -> Option<&Path> {
        self.get(AppPathRole::Logs)
    }

    /// App-scoped temporary directory.
    pub fn temp_dir(&self) -> Option<&Path> {
        self.get(AppPathRole::Temp)
    }

    /// User downloads directory.
    pub fn downloads_dir(&self) -> Option<&Path> {
        self.get(AppPathRole::Downloads)
    }

    /// Number of resolved path roles.
    pub fn role_count(&self) -> usize {
        self.paths.len()
    }

    /// Whether a role was resolved.
    pub fn has_role(&self, role: AppPathRole) -> bool {
        self.get(role).is_some()
    }

    /// Number of app-scoped roles in this set.
    pub fn app_scoped_role_count(&self) -> usize {
        self.paths
            .iter()
            .filter(|(role, _)| role.is_app_scoped())
            .count()
    }

    /// Number of user-global roles in this set.
    pub fn user_global_role_count(&self) -> usize {
        self.paths
            .iter()
            .filter(|(role, _)| !role.is_app_scoped())
            .count()
    }

    /// Content-safe summary that avoids logging app ids or absolute paths.
    pub fn to_text(&self) -> String {
        format!(
            "app paths: roles {}, app-scoped {}, user-global {}, data {}, config {}, cache {}, logs {}, temp {}, downloads {}",
            self.role_count(),
            self.app_scoped_role_count(),
            self.user_global_role_count(),
            self.has_role(AppPathRole::Data),
            self.has_role(AppPathRole::Config),
            self.has_role(AppPathRole::Cache),
            self.has_role(AppPathRole::Logs),
            self.has_role(AppPathRole::Temp),
            self.has_role(AppPathRole::Downloads)
        )
    }
}

/// Builder for resolving common app-owned filesystem locations.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppPathBuilder {
    app_id: String,
    roles: Vec<AppPathRole>,
    create_dirs: bool,
}

impl AppPathBuilder {
    /// Create an app path builder for a stable app identifier.
    pub fn new(app_id: impl Into<String>) -> Self {
        Self {
            app_id: app_id.into(),
            roles: Vec::new(),
            create_dirs: false,
        }
    }

    /// Add one well-known path role.
    pub fn role(mut self, role: AppPathRole) -> Self {
        self.roles.push(role);
        self
    }

    /// Add multiple well-known path roles.
    pub fn roles(mut self, roles: impl IntoIterator<Item = AppPathRole>) -> Self {
        self.roles.extend(roles);
        self
    }

    /// Request the common app-owned storage roles.
    pub fn app_storage(self) -> Self {
        self.roles([
            AppPathRole::Data,
            AppPathRole::Config,
            AppPathRole::Cache,
            AppPathRole::Logs,
            AppPathRole::Temp,
        ])
    }

    /// Request app-owned storage plus the user's downloads directory.
    pub fn all_common(self) -> Self {
        self.app_storage().role(AppPathRole::Downloads)
    }

    /// Create resolved directories when they do not already exist.
    pub fn create_dirs(mut self) -> Self {
        self.create_dirs = true;
        self
    }

    /// Create resolved directories when `enabled` is true.
    pub fn create_dirs_if(mut self, enabled: bool) -> Self {
        self.create_dirs = enabled;
        self
    }

    /// Return the configured app identifier.
    pub fn app_id(&self) -> &str {
        &self.app_id
    }

    /// Return the configured path roles.
    pub fn configured_roles(&self) -> &[AppPathRole] {
        &self.roles
    }

    /// Whether missing resolved directories will be created.
    pub fn creates_dirs(&self) -> bool {
        self.create_dirs
    }

    /// Number of requested roles.
    pub fn role_count(&self) -> usize {
        self.roles.len()
    }

    /// Whether a role has been requested.
    pub fn has_role(&self, role: AppPathRole) -> bool {
        self.roles.contains(&role)
    }

    /// Content-safe summary that avoids logging app ids.
    pub fn to_text(&self) -> String {
        format!(
            "app path builder: roles {}, create-dirs {}, data {}, config {}, cache {}, logs {}, temp {}, downloads {}",
            self.role_count(),
            self.create_dirs,
            self.has_role(AppPathRole::Data),
            self.has_role(AppPathRole::Config),
            self.has_role(AppPathRole::Cache),
            self.has_role(AppPathRole::Logs),
            self.has_role(AppPathRole::Temp),
            self.has_role(AppPathRole::Downloads)
        )
    }

    /// Validate the app identifier and requested roles.
    pub fn validate(&self) -> Result<()> {
        validate_app_path_id(&self.app_id)?;
        anyhow::ensure!(
            !self.roles.is_empty(),
            "app path builder must request at least one role"
        );

        for (index, role) in self.roles.iter().enumerate() {
            anyhow::ensure!(
                !self.roles[..index].contains(role),
                "app path role requested more than once: {}",
                role.key()
            );
        }

        Ok(())
    }

    /// Resolve and optionally create the requested paths.
    pub fn build_checked(self) -> Result<AppPathSet> {
        self.validate()?;

        let mut paths = Vec::with_capacity(self.roles.len());
        for role in self.roles {
            let path = resolve_app_path_role(&self.app_id, role)?;
            if self.create_dirs {
                fs::create_dir_all(&path).with_context(|| {
                    format!(
                        "failed to create app path {} at {}",
                        role.key(),
                        path.display()
                    )
                })?;
            }
            paths.push((role, path));
        }

        Ok(AppPathSet {
            app_id: self.app_id,
            paths,
        })
    }
}

/// Storage class for app-owned persistent or rebuildable data.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AppStorageKind {
    /// JSON settings/preferences file.
    SettingsJson,
    /// SQLite or SQLite-compatible database file.
    SqliteDatabase,
    /// App-owned key-value store directory or file.
    KeyValueStore,
    /// Rebuildable blob/object cache.
    BlobCache,
    /// App log file.
    LogFile,
    /// Temporary workspace directory.
    TempWorkspace,
    /// App-defined storage kind.
    Custom(String),
}

impl AppStorageKind {
    /// Stable kind key for diagnostics and generated docs.
    pub fn key(&self) -> &str {
        match self {
            Self::SettingsJson => "settings-json",
            Self::SqliteDatabase => "sqlite-database",
            Self::KeyValueStore => "key-value-store",
            Self::BlobCache => "blob-cache",
            Self::LogFile => "log-file",
            Self::TempWorkspace => "temp-workspace",
            Self::Custom(kind) => kind,
        }
    }

    /// Whether this is an app-defined storage kind.
    pub fn is_custom(&self) -> bool {
        matches!(self, Self::Custom(_))
    }

    /// Content-safe storage kind class that avoids logging custom kind strings.
    pub fn to_text(&self) -> &'static str {
        match self {
            Self::SettingsJson => "settings-json",
            Self::SqliteDatabase => "sqlite-database",
            Self::KeyValueStore => "key-value-store",
            Self::BlobCache => "blob-cache",
            Self::LogFile => "log-file",
            Self::TempWorkspace => "temp-workspace",
            Self::Custom(_) => "custom",
        }
    }

    fn validate(&self) -> Result<()> {
        if let Self::Custom(kind) = self {
            validate_app_storage_id(kind, "app storage kind")?;
        }
        Ok(())
    }
}

/// Durability policy for an app storage entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AppStorageDurability {
    /// User data that should survive app upgrades and normal cleanup.
    Durable,
    /// Data that can be regenerated and may be cleared under pressure.
    Rebuildable,
    /// Short-lived data scoped to the current run or task.
    Temporary,
}

impl AppStorageDurability {
    /// Stable lowercase key for diagnostics and generated policies.
    pub fn key(self) -> &'static str {
        match self {
            Self::Durable => "durable",
            Self::Rebuildable => "rebuildable",
            Self::Temporary => "temporary",
        }
    }
}

/// One checked app-owned storage location.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppStorageEntry {
    id: String,
    kind: AppStorageKind,
    durability: AppStorageDurability,
    role: AppPathRole,
    relative_path: PathBuf,
    absolute_path: PathBuf,
    max_bytes: Option<u64>,
    sensitive: bool,
}

impl AppStorageEntry {
    /// Stable app-defined storage id.
    pub fn id(&self) -> &str {
        &self.id
    }

    /// Storage class.
    pub fn kind(&self) -> &AppStorageKind {
        &self.kind
    }

    /// Durability policy.
    pub fn durability(&self) -> AppStorageDurability {
        self.durability
    }

    /// App path role used as the base directory.
    pub fn role(&self) -> AppPathRole {
        self.role
    }

    /// Relative path under the role directory.
    pub fn relative_path(&self) -> &Path {
        &self.relative_path
    }

    /// Absolute resolved storage path.
    pub fn absolute_path(&self) -> &Path {
        &self.absolute_path
    }

    /// Optional storage quota/expectation.
    pub fn max_bytes(&self) -> Option<u64> {
        self.max_bytes
    }

    /// Whether diagnostics should redact this entry by default.
    pub fn is_sensitive(&self) -> bool {
        self.sensitive
    }

    /// Capability required by code that writes to this storage entry.
    pub fn write_capability(&self) -> Capability {
        Capability::FilesystemWrite {
            scope: PathScope::AppData,
        }
    }

    /// Capability required by code that reads from this storage entry.
    pub fn read_capability(&self) -> Capability {
        Capability::FilesystemRead {
            scope: PathScope::AppData,
        }
    }

    /// Directory that should exist before this entry is opened.
    pub fn required_directory(&self) -> PathBuf {
        match &self.kind {
            AppStorageKind::SettingsJson
            | AppStorageKind::SqliteDatabase
            | AppStorageKind::LogFile => self
                .absolute_path
                .parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| self.absolute_path.clone()),
            AppStorageKind::KeyValueStore
            | AppStorageKind::BlobCache
            | AppStorageKind::TempWorkspace
            | AppStorageKind::Custom(_) => self.absolute_path.clone(),
        }
    }

    /// Whether this entry has a quota/size expectation.
    pub fn has_max_bytes(&self) -> bool {
        self.max_bytes.is_some()
    }

    /// Content-safe summary that avoids logging ids, paths, and quotas.
    pub fn to_text(&self) -> String {
        format!(
            "app storage entry: kind {}, durability {}, role {}, quota {}, sensitive {}",
            self.kind.to_text(),
            self.durability.key(),
            self.role.key(),
            self.has_max_bytes(),
            self.sensitive
        )
    }
}

/// Checked plan for app-owned settings, databases, caches, logs, and temp data.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppStoragePlan {
    app_id: String,
    paths: AppPathSet,
    entries: Vec<AppStorageEntry>,
}

impl AppStoragePlan {
    /// Application identifier used to scope storage.
    pub fn app_id(&self) -> &str {
        &self.app_id
    }

    /// Resolved app path set backing the plan.
    pub fn paths(&self) -> &AppPathSet {
        &self.paths
    }

    /// Storage entries in builder order.
    pub fn entries(&self) -> &[AppStorageEntry] {
        &self.entries
    }

    /// Number of storage entries.
    pub fn entry_count(&self) -> usize {
        self.entries.len()
    }

    /// Look up an entry by id.
    pub fn entry(&self, id: &str) -> Option<&AppStorageEntry> {
        self.entries.iter().find(|entry| entry.id == id)
    }

    /// Return entries with a specific durability policy.
    pub fn entries_with_durability(
        &self,
        durability: AppStorageDurability,
    ) -> Vec<&AppStorageEntry> {
        self.entries
            .iter()
            .filter(|entry| entry.durability == durability)
            .collect()
    }

    /// Total declared quota across entries that specify one.
    pub fn declared_max_bytes(&self) -> u64 {
        self.entries
            .iter()
            .filter_map(AppStorageEntry::max_bytes)
            .sum()
    }

    /// Number of entries with a durability policy.
    pub fn durability_count(&self, durability: AppStorageDurability) -> usize {
        self.entries
            .iter()
            .filter(|entry| entry.durability == durability)
            .count()
    }

    /// Number of entries marked sensitive.
    pub fn sensitive_count(&self) -> usize {
        self.entries.iter().filter(|entry| entry.sensitive).count()
    }

    /// Number of entries that declare a quota/size expectation.
    pub fn quota_count(&self) -> usize {
        self.entries
            .iter()
            .filter(|entry| entry.max_bytes.is_some())
            .count()
    }

    /// Directories that must exist before opening the declared storage entries.
    pub fn required_directories(&self) -> Vec<PathBuf> {
        let mut directories = Vec::new();
        for (_, path) in self.paths.paths() {
            push_unique_path(&mut directories, path.clone());
        }
        for entry in &self.entries {
            push_unique_path(&mut directories, entry.required_directory());
        }
        directories
    }

    /// Create all directories required by this storage plan.
    pub fn ensure_directories_checked(&self) -> Result<()> {
        for directory in self.required_directories() {
            fs::create_dir_all(&directory).with_context(|| {
                format!(
                    "failed to create app storage directory {}",
                    directory.display()
                )
            })?;
        }
        Ok(())
    }

    /// Content-safe summary that avoids logging app ids and paths.
    pub fn to_text(&self) -> String {
        format!(
            "app storage plan: entries {}, durable {}, rebuildable {}, temporary {}, sensitive {}, quotas {}, roles {}, required-dirs {}",
            self.entry_count(),
            self.durability_count(AppStorageDurability::Durable),
            self.durability_count(AppStorageDurability::Rebuildable),
            self.durability_count(AppStorageDurability::Temporary),
            self.sensitive_count(),
            self.quota_count(),
            self.paths.role_count(),
            self.required_directories().len()
        )
    }
}

fn push_unique_path(paths: &mut Vec<PathBuf>, path: PathBuf) {
    if !paths.iter().any(|candidate| candidate == &path) {
        paths.push(path);
    }
}

/// Builder for one app storage entry.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppStorageEntryBuilder {
    id: String,
    kind: AppStorageKind,
    durability: AppStorageDurability,
    role: AppPathRole,
    relative_path: PathBuf,
    max_bytes: Option<u64>,
    sensitive: bool,
}

impl AppStorageEntryBuilder {
    /// Create an entry builder.
    pub fn new(
        id: impl Into<String>,
        kind: AppStorageKind,
        role: AppPathRole,
        relative_path: impl Into<PathBuf>,
    ) -> Self {
        Self {
            id: id.into(),
            kind,
            durability: AppStorageDurability::Durable,
            role,
            relative_path: relative_path.into(),
            max_bytes: None,
            sensitive: false,
        }
    }

    /// JSON settings/preferences file under the config directory.
    pub fn settings_json(id: impl Into<String>, file_name: impl Into<PathBuf>) -> Self {
        Self::new(
            id,
            AppStorageKind::SettingsJson,
            AppPathRole::Config,
            file_name,
        )
        .max_bytes(10 * 1024 * 1024)
    }

    /// SQLite database file under the data directory.
    pub fn sqlite_database(id: impl Into<String>, file_name: impl Into<PathBuf>) -> Self {
        Self::new(
            id,
            AppStorageKind::SqliteDatabase,
            AppPathRole::Data,
            file_name,
        )
        .max_bytes(2 * 1024 * 1024 * 1024)
    }

    /// Key-value store under the data directory.
    pub fn key_value_store(id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::new(id, AppStorageKind::KeyValueStore, AppPathRole::Data, path)
            .max_bytes(512 * 1024 * 1024)
    }

    /// Rebuildable blob cache under the cache directory.
    pub fn blob_cache(id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::new(id, AppStorageKind::BlobCache, AppPathRole::Cache, path)
            .rebuildable()
            .max_bytes(4 * 1024 * 1024 * 1024)
    }

    /// App log file under the logs directory.
    pub fn log_file(id: impl Into<String>, file_name: impl Into<PathBuf>) -> Self {
        Self::new(id, AppStorageKind::LogFile, AppPathRole::Logs, file_name)
            .rebuildable()
            .max_bytes(256 * 1024 * 1024)
    }

    /// Temporary workspace under the app temp directory.
    pub fn temp_workspace(id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::new(id, AppStorageKind::TempWorkspace, AppPathRole::Temp, path)
            .temporary()
            .max_bytes(1024 * 1024 * 1024)
    }

    /// Mark the entry durable.
    pub fn durable(mut self) -> Self {
        self.durability = AppStorageDurability::Durable;
        self
    }

    /// Mark the entry rebuildable.
    pub fn rebuildable(mut self) -> Self {
        self.durability = AppStorageDurability::Rebuildable;
        self
    }

    /// Mark the entry temporary.
    pub fn temporary(mut self) -> Self {
        self.durability = AppStorageDurability::Temporary;
        self
    }

    /// Set the optional storage quota/expectation.
    pub fn max_bytes(mut self, max_bytes: u64) -> Self {
        self.max_bytes = Some(max_bytes);
        self
    }

    /// Clear the storage quota/expectation.
    pub fn unlimited_bytes(mut self) -> Self {
        self.max_bytes = None;
        self
    }

    /// Mark the entry as sensitive for diagnostics.
    pub fn sensitive(mut self) -> Self {
        self.sensitive = true;
        self
    }

    fn validate(&self) -> Result<()> {
        validate_app_storage_id(&self.id, "app storage id")?;
        self.kind.validate()?;
        anyhow::ensure!(
            self.role != AppPathRole::Downloads,
            "app storage entries cannot use the downloads directory"
        );
        validate_app_storage_relative_path(&self.relative_path)?;
        if let Some(max_bytes) = self.max_bytes {
            anyhow::ensure!(
                max_bytes > 0,
                "app storage max bytes must be greater than zero"
            );
            anyhow::ensure!(
                max_bytes <= 1_099_511_627_776,
                "app storage max bytes cannot exceed 1 TiB"
            );
        }
        Ok(())
    }

    fn build_checked(&self, paths: &AppPathSet) -> Result<AppStorageEntry> {
        self.validate()?;
        let base = paths
            .get(self.role)
            .with_context(|| format!("app storage role not resolved: {}", self.role.key()))?;
        Ok(AppStorageEntry {
            id: self.id.clone(),
            kind: self.kind.clone(),
            durability: self.durability,
            role: self.role,
            relative_path: self.relative_path.clone(),
            absolute_path: base.join(&self.relative_path),
            max_bytes: self.max_bytes,
            sensitive: self.sensitive,
        })
    }
}

/// Builder for checked app-owned storage plans.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppStoragePlanBuilder {
    app_id: String,
    entries: Vec<AppStorageEntryBuilder>,
    create_dirs: bool,
}

impl AppStoragePlanBuilder {
    /// Create an empty storage plan builder.
    pub fn new(app_id: impl Into<String>) -> Self {
        Self {
            app_id: app_id.into(),
            entries: Vec::new(),
            create_dirs: false,
        }
    }

    /// Add a storage entry.
    pub fn entry(mut self, entry: AppStorageEntryBuilder) -> Self {
        self.entries.push(entry);
        self
    }

    /// Add a settings JSON file.
    pub fn settings_json(mut self, id: impl Into<String>, file_name: impl Into<PathBuf>) -> Self {
        self.entries
            .push(AppStorageEntryBuilder::settings_json(id, file_name));
        self
    }

    /// Add a SQLite database file.
    pub fn sqlite_database(mut self, id: impl Into<String>, file_name: impl Into<PathBuf>) -> Self {
        self.entries
            .push(AppStorageEntryBuilder::sqlite_database(id, file_name));
        self
    }

    /// Add a key-value store path.
    pub fn key_value_store(mut self, id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        self.entries
            .push(AppStorageEntryBuilder::key_value_store(id, path));
        self
    }

    /// Add a rebuildable blob cache path.
    pub fn blob_cache(mut self, id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        self.entries
            .push(AppStorageEntryBuilder::blob_cache(id, path));
        self
    }

    /// Add an app log file.
    pub fn log_file(mut self, id: impl Into<String>, file_name: impl Into<PathBuf>) -> Self {
        self.entries
            .push(AppStorageEntryBuilder::log_file(id, file_name));
        self
    }

    /// Add a temporary workspace path.
    pub fn temp_workspace(mut self, id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        self.entries
            .push(AppStorageEntryBuilder::temp_workspace(id, path));
        self
    }

    /// Create resolved role directories when building.
    pub fn create_dirs(mut self) -> Self {
        self.create_dirs = true;
        self
    }

    /// Return configured entries.
    pub fn configured_entries(&self) -> &[AppStorageEntryBuilder] {
        &self.entries
    }

    /// Number of configured entries.
    pub fn entry_count(&self) -> usize {
        self.entries.len()
    }

    /// Whether resolved base directories will be created while building.
    pub fn creates_dirs(&self) -> bool {
        self.create_dirs
    }

    /// Content-safe summary that avoids logging app ids, entry ids, and paths.
    pub fn to_text(&self) -> String {
        format!(
            "app storage plan builder: entries {}, create-dirs {}",
            self.entry_count(),
            self.create_dirs
        )
    }

    /// Validate the storage plan.
    pub fn validate(&self) -> Result<()> {
        validate_app_path_id(&self.app_id)?;
        anyhow::ensure!(
            !self.entries.is_empty(),
            "app storage plan must include at least one entry"
        );
        let mut seen = std::collections::HashSet::new();
        for entry in &self.entries {
            entry.validate()?;
            anyhow::ensure!(
                seen.insert(entry.id.clone()),
                "app storage id configured more than once: {}",
                entry.id
            );
        }
        Ok(())
    }

    /// Build a checked storage plan and resolve role paths.
    pub fn build_checked(self) -> Result<AppStoragePlan> {
        self.validate()?;
        let roles = self
            .entries
            .iter()
            .map(|entry| entry.role)
            .unique()
            .collect::<Vec<_>>();
        let paths = AppPathBuilder::new(&self.app_id)
            .roles(roles)
            .create_dirs_if(self.create_dirs)
            .build_checked()?;
        let entries = self
            .entries
            .iter()
            .map(|entry| entry.build_checked(&paths))
            .collect::<Result<Vec<_>>>()?;
        Ok(AppStoragePlan {
            app_id: self.app_id,
            paths,
            entries,
        })
    }
}

/// App-scoped storage migration operation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StorageMigrationKind {
    /// Move one app-owned storage path to another app-owned path.
    MovePath,
    /// Copy one app-owned storage path to another app-owned path.
    CopyPath,
    /// Rewrite a storage file or directory in place for a schema version change.
    RewriteInPlace,
}

impl StorageMigrationKind {
    /// Stable lowercase key for diagnostics and generated plans.
    pub fn key(self) -> &'static str {
        match self {
            Self::MovePath => "move-path",
            Self::CopyPath => "copy-path",
            Self::RewriteInPlace => "rewrite-in-place",
        }
    }
}

/// One checked app-scoped storage migration step.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageMigrationStep {
    id: String,
    kind: StorageMigrationKind,
    from_version: u32,
    to_version: u32,
    source_role: AppPathRole,
    source_path: PathBuf,
    target_role: AppPathRole,
    target_path: PathBuf,
    backup_required: bool,
}

impl StorageMigrationStep {
    /// Stable app-defined migration step id.
    pub fn id(&self) -> &str {
        &self.id
    }

    /// Migration operation kind.
    pub fn kind(&self) -> StorageMigrationKind {
        self.kind
    }

    /// Source schema/profile version.
    pub fn from_version(&self) -> u32 {
        self.from_version
    }

    /// Target schema/profile version.
    pub fn to_version(&self) -> u32 {
        self.to_version
    }

    /// Source app path role.
    pub fn source_role(&self) -> AppPathRole {
        self.source_role
    }

    /// Source relative path under the source role.
    pub fn source_path(&self) -> &Path {
        &self.source_path
    }

    /// Target app path role.
    pub fn target_role(&self) -> AppPathRole {
        self.target_role
    }

    /// Target relative path under the target role.
    pub fn target_path(&self) -> &Path {
        &self.target_path
    }

    /// Whether the app should create a backup before applying this step.
    pub fn backup_required(&self) -> bool {
        self.backup_required
    }

    /// Content-safe summary that avoids logging ids, paths, or version numbers.
    pub fn to_text(&self) -> String {
        format!(
            "storage migration step: kind {}, source role {}, target role {}, backup {}, version change {}",
            self.kind.key(),
            self.source_role.key(),
            self.target_role.key(),
            self.backup_required,
            self.from_version != self.to_version
        )
    }
}

/// Builder for one app-scoped storage migration step.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageMigrationStepBuilder {
    id: String,
    kind: StorageMigrationKind,
    from_version: u32,
    to_version: u32,
    source_role: AppPathRole,
    source_path: PathBuf,
    target_role: AppPathRole,
    target_path: PathBuf,
    backup_required: bool,
}

impl StorageMigrationStepBuilder {
    /// Create a migration step builder.
    pub fn new(
        id: impl Into<String>,
        kind: StorageMigrationKind,
        from_version: u32,
        to_version: u32,
        source_role: AppPathRole,
        source_path: impl Into<PathBuf>,
        target_role: AppPathRole,
        target_path: impl Into<PathBuf>,
    ) -> Self {
        Self {
            id: id.into(),
            kind,
            from_version,
            to_version,
            source_role,
            source_path: source_path.into(),
            target_role,
            target_path: target_path.into(),
            backup_required: true,
        }
    }

    /// Move one app-owned storage path.
    pub fn move_path(
        id: impl Into<String>,
        from_version: u32,
        to_version: u32,
        source_role: AppPathRole,
        source_path: impl Into<PathBuf>,
        target_role: AppPathRole,
        target_path: impl Into<PathBuf>,
    ) -> Self {
        Self::new(
            id,
            StorageMigrationKind::MovePath,
            from_version,
            to_version,
            source_role,
            source_path,
            target_role,
            target_path,
        )
    }

    /// Copy one app-owned storage path.
    pub fn copy_path(
        id: impl Into<String>,
        from_version: u32,
        to_version: u32,
        source_role: AppPathRole,
        source_path: impl Into<PathBuf>,
        target_role: AppPathRole,
        target_path: impl Into<PathBuf>,
    ) -> Self {
        Self::new(
            id,
            StorageMigrationKind::CopyPath,
            from_version,
            to_version,
            source_role,
            source_path,
            target_role,
            target_path,
        )
    }

    /// Rewrite one app-owned storage path in place.
    pub fn rewrite_in_place(
        id: impl Into<String>,
        from_version: u32,
        to_version: u32,
        role: AppPathRole,
        path: impl Into<PathBuf>,
    ) -> Self {
        let path = path.into();
        Self::new(
            id,
            StorageMigrationKind::RewriteInPlace,
            from_version,
            to_version,
            role,
            path.clone(),
            role,
            path,
        )
    }

    /// Require a backup before the step is applied.
    pub fn require_backup(mut self) -> Self {
        self.backup_required = true;
        self
    }

    /// Mark the step as not requiring a backup.
    pub fn without_backup(mut self) -> Self {
        self.backup_required = false;
        self
    }

    fn validate(&self) -> Result<()> {
        validate_app_storage_id(&self.id, "storage migration id")?;
        validate_storage_version_range(self.from_version, self.to_version)?;
        validate_app_storage_role(self.source_role, "storage migration source role")?;
        validate_app_storage_role(self.target_role, "storage migration target role")?;
        validate_app_storage_relative_path(&self.source_path)?;
        validate_app_storage_relative_path(&self.target_path)?;
        if matches!(
            self.kind,
            StorageMigrationKind::MovePath | StorageMigrationKind::CopyPath
        ) {
            anyhow::ensure!(
                self.source_role != self.target_role || self.source_path != self.target_path,
                "storage migration source and target must differ"
            );
        } else {
            anyhow::ensure!(
                self.source_role == self.target_role && self.source_path == self.target_path,
                "rewrite-in-place migrations must use the same source and target"
            );
        }
        Ok(())
    }

    fn build_checked(&self) -> Result<StorageMigrationStep> {
        self.validate()?;
        Ok(StorageMigrationStep {
            id: self.id.clone(),
            kind: self.kind,
            from_version: self.from_version,
            to_version: self.to_version,
            source_role: self.source_role,
            source_path: self.source_path.clone(),
            target_role: self.target_role,
            target_path: self.target_path.clone(),
            backup_required: self.backup_required,
        })
    }
}

/// Checked app-scoped storage migration plan.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageMigrationPlan {
    app_id: String,
    steps: Vec<StorageMigrationStep>,
}

impl StorageMigrationPlan {
    /// Application identifier used to scope migration work.
    pub fn app_id(&self) -> &str {
        &self.app_id
    }

    /// Ordered migration steps.
    pub fn steps(&self) -> &[StorageMigrationStep] {
        &self.steps
    }

    /// Number of migration steps.
    pub fn step_count(&self) -> usize {
        self.steps.len()
    }

    /// Number of steps that require backups.
    pub fn backup_count(&self) -> usize {
        self.steps
            .iter()
            .filter(|step| step.backup_required)
            .count()
    }

    /// Returns true when at least one step moves or copies across app path roles.
    pub fn crosses_roles(&self) -> bool {
        self.steps
            .iter()
            .any(|step| step.source_role != step.target_role)
    }

    /// Content-safe summary that avoids logging app ids, paths, and versions.
    pub fn to_text(&self) -> String {
        format!(
            "storage migration plan: {} steps, {} backups, crosses roles {}",
            self.step_count(),
            self.backup_count(),
            self.crosses_roles()
        )
    }
}

/// Builder for checked app-scoped storage migration plans.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageMigrationPlanBuilder {
    app_id: String,
    steps: Vec<StorageMigrationStepBuilder>,
}

impl StorageMigrationPlanBuilder {
    /// Create an empty storage migration plan builder.
    pub fn new(app_id: impl Into<String>) -> Self {
        Self {
            app_id: app_id.into(),
            steps: Vec::new(),
        }
    }

    /// Add a migration step.
    pub fn step(mut self, step: StorageMigrationStepBuilder) -> Self {
        self.steps.push(step);
        self
    }

    /// Add a path move step.
    pub fn move_path(
        self,
        id: impl Into<String>,
        from_version: u32,
        to_version: u32,
        source_role: AppPathRole,
        source_path: impl Into<PathBuf>,
        target_role: AppPathRole,
        target_path: impl Into<PathBuf>,
    ) -> Self {
        self.step(StorageMigrationStepBuilder::move_path(
            id,
            from_version,
            to_version,
            source_role,
            source_path,
            target_role,
            target_path,
        ))
    }

    /// Add a path copy step.
    pub fn copy_path(
        self,
        id: impl Into<String>,
        from_version: u32,
        to_version: u32,
        source_role: AppPathRole,
        source_path: impl Into<PathBuf>,
        target_role: AppPathRole,
        target_path: impl Into<PathBuf>,
    ) -> Self {
        self.step(StorageMigrationStepBuilder::copy_path(
            id,
            from_version,
            to_version,
            source_role,
            source_path,
            target_role,
            target_path,
        ))
    }

    /// Add an in-place schema rewrite step.
    pub fn rewrite_in_place(
        self,
        id: impl Into<String>,
        from_version: u32,
        to_version: u32,
        role: AppPathRole,
        path: impl Into<PathBuf>,
    ) -> Self {
        self.step(StorageMigrationStepBuilder::rewrite_in_place(
            id,
            from_version,
            to_version,
            role,
            path,
        ))
    }

    /// Number of configured migration steps.
    pub fn step_count(&self) -> usize {
        self.steps.len()
    }

    /// Content-safe summary that avoids logging app ids, paths, and versions.
    pub fn to_text(&self) -> String {
        format!(
            "storage migration plan builder: {} steps",
            self.step_count()
        )
    }

    /// Validate the migration plan.
    pub fn validate(&self) -> Result<()> {
        validate_app_path_id(&self.app_id)?;
        anyhow::ensure!(
            !self.steps.is_empty(),
            "storage migration plan must include at least one step"
        );
        let mut seen = FxHashSet::default();
        for step in &self.steps {
            step.validate()?;
            anyhow::ensure!(
                seen.insert(step.id.clone()),
                "storage migration id configured more than once: {}",
                step.id
            );
        }
        Ok(())
    }

    /// Build a checked storage migration plan.
    pub fn build_checked(self) -> Result<StorageMigrationPlan> {
        self.validate()?;
        let steps = self
            .steps
            .iter()
            .map(StorageMigrationStepBuilder::build_checked)
            .collect::<Result<Vec<_>>>()?;
        Ok(StorageMigrationPlan {
            app_id: self.app_id,
            steps,
        })
    }
}

/// App-scoped storage cleanup target class.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StorageCleanupKind {
    /// Rebuildable cache data.
    Cache,
    /// App log files.
    Logs,
    /// Temporary workspace data.
    Temporary,
    /// Orphaned data from a previous schema, account, or profile layout.
    Orphaned,
    /// App-defined cleanup target.
    Custom(String),
}

impl StorageCleanupKind {
    /// Stable cleanup kind key for diagnostics and generated plans.
    pub fn key(&self) -> &str {
        match self {
            Self::Cache => "cache",
            Self::Logs => "logs",
            Self::Temporary => "temporary",
            Self::Orphaned => "orphaned",
            Self::Custom(kind) => kind,
        }
    }

    /// Content-safe cleanup kind class that avoids logging custom kind strings.
    pub fn to_text(&self) -> &'static str {
        match self {
            Self::Cache => "cache",
            Self::Logs => "logs",
            Self::Temporary => "temporary",
            Self::Orphaned => "orphaned",
            Self::Custom(_) => "custom",
        }
    }

    fn validate(&self) -> Result<()> {
        if let Self::Custom(kind) = self {
            validate_app_storage_id(kind, "storage cleanup kind")?;
        }
        Ok(())
    }
}

/// One checked app-scoped storage cleanup target.
