/// Builder for one app-scoped storage cleanup target.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StorageCleanupTargetBuilder {
    id: String,
    kind: StorageCleanupKind,
    role: AppPathRole,
    relative_path: PathBuf,
    include_sensitive: bool,
}

impl StorageCleanupTargetBuilder {
    /// Create a cleanup target builder.
    pub fn new(
        id: impl Into<String>,
        kind: StorageCleanupKind,
        role: AppPathRole,
        relative_path: impl Into<PathBuf>,
    ) -> Self {
        Self {
            id: id.into(),
            kind,
            role,
            relative_path: relative_path.into(),
            include_sensitive: false,
        }
    }

    /// Create a rebuildable cache cleanup target.
    pub fn cache(id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::new(id, StorageCleanupKind::Cache, AppPathRole::Cache, path)
    }

    /// Create an app logs cleanup target.
    pub fn logs(id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::new(id, StorageCleanupKind::Logs, AppPathRole::Logs, path)
    }

    /// Create a temporary workspace cleanup target.
    pub fn temporary(id: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self::new(id, StorageCleanupKind::Temporary, AppPathRole::Temp, path)
    }

    /// Create an orphaned app-storage cleanup target.
    pub fn orphaned(id: impl Into<String>, role: AppPathRole, path: impl Into<PathBuf>) -> Self {
        Self::new(id, StorageCleanupKind::Orphaned, role, path)
    }

    /// Allow this cleanup target to include sensitive storage.
    pub fn include_sensitive(mut self) -> Self {
        self.include_sensitive = true;
        self
    }

    fn validate(&self) -> Result<()> {
        validate_app_storage_id(&self.id, "storage cleanup id")?;
        self.kind.validate()?;
        validate_app_storage_role(self.role, "storage cleanup role")?;
        validate_app_storage_relative_path(&self.relative_path)?;
        if matches!(
            self.kind,
            StorageCleanupKind::Cache | StorageCleanupKind::Logs | StorageCleanupKind::Temporary
        ) {
            anyhow::ensure!(
                matches!(
                    (self.kind.clone(), self.role),
                    (StorageCleanupKind::Cache, AppPathRole::Cache)
                        | (StorageCleanupKind::Logs, AppPathRole::Logs)
                        | (StorageCleanupKind::Temporary, AppPathRole::Temp)
                ),
                "storage cleanup kind must use its matching app path role"
            );
        }
        Ok(())
    }

    fn build_checked(&self) -> Result<StorageCleanupTarget> {
        self.validate()?;
        Ok(StorageCleanupTarget {
            id: self.id.clone(),
            kind: self.kind.clone(),
            role: self.role,
            relative_path: self.relative_path.clone(),
            include_sensitive: self.include_sensitive,
        })
    }
}

