/// Environment allowlist and redaction policy for startup diagnostics.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchEnvironmentAllowlist {
    keys: Vec<String>,
}

impl LaunchEnvironmentAllowlist {
    /// Allowed environment keys.
    pub fn keys(&self) -> &[String] {
        &self.keys
    }

    /// Summarize allowlisted environment state from a launch snapshot.
    pub fn summarize_snapshot(
        &self,
        launch: &LaunchContextSnapshot,
    ) -> Result<LaunchEnvironmentSnapshot> {
        let mut present_count = 0;
        let mut denied_count = 0;
        for (key, value) in launch.environment() {
            validate_environment_key(key)?;
            validate_no_nul(value, "launch environment value")?;
            if self.keys.iter().any(|allowed| allowed == key) {
                present_count += 1;
            } else {
                denied_count += 1;
            }
        }

        Ok(LaunchEnvironmentSnapshot {
            allowlisted_key_count: self.keys.len(),
            present_count,
            missing_count: self.keys.len().saturating_sub(present_count),
            denied_count,
        })
    }

    /// Content-safe summary.
    pub fn to_text(&self) -> String {
        format!("launch environment allowlist: {} keys", self.keys.len())
    }
}

/// Builder for [`LaunchEnvironmentAllowlist`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchEnvironmentAllowlistBuilder {
    keys: Vec<String>,
}

impl LaunchEnvironmentAllowlistBuilder {
    /// Create an empty environment allowlist.
    pub fn new() -> Self {
        Self { keys: Vec::new() }
    }

    /// Allow one environment key.
    pub fn key(mut self, key: impl Into<String>) -> Self {
        self.keys.push(key.into());
        self
    }

    /// Allow multiple environment keys.
    pub fn keys(mut self, keys: impl IntoIterator<Item = impl Into<String>>) -> Self {
        self.keys.extend(keys.into_iter().map(Into::into));
        self
    }

    /// Build and validate the allowlist.
    pub fn build_checked(self) -> Result<LaunchEnvironmentAllowlist> {
        for (index, key) in self.keys.iter().enumerate() {
            validate_environment_key(key)?;
            anyhow::ensure!(
                !self.keys[..index].contains(key),
                "launch environment key allowlisted more than once: {key}"
            );
        }
        Ok(LaunchEnvironmentAllowlist { keys: self.keys })
    }

    /// Content-safe summary.
    pub fn to_text(&self) -> String {
        format!(
            "launch environment allowlist builder: {} keys",
            self.keys.len()
        )
    }
}

impl Default for LaunchEnvironmentAllowlistBuilder {
    fn default() -> Self {
        Self::new()
    }
}

/// Content-safe summary of allowlisted environment state.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchEnvironmentSnapshot {
    allowlisted_key_count: usize,
    present_count: usize,
    missing_count: usize,
    denied_count: usize,
}

impl LaunchEnvironmentSnapshot {
    /// Number of keys requested by policy.
    pub fn allowlisted_key_count(&self) -> usize {
        self.allowlisted_key_count
    }

    /// Number of allowlisted keys present in the launch snapshot.
    pub fn present_count(&self) -> usize {
        self.present_count
    }

    /// Number of allowlisted keys not present in the launch snapshot.
    pub fn missing_count(&self) -> usize {
        self.missing_count
    }

    /// Number of captured keys denied by this allowlist.
    pub fn denied_count(&self) -> usize {
        self.denied_count
    }

    /// Content-safe summary.
    pub fn to_text(&self) -> String {
        format!(
            "launch environment snapshot: {} allowlisted, {} present, {} missing, {} denied",
            self.allowlisted_key_count, self.present_count, self.missing_count, self.denied_count
        )
    }
}

/// Redacted payload that can be forwarded from a duplicate app launch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DuplicateLaunchPayload {
    argument_report: LaunchArgumentReport,
    environment_snapshot: LaunchEnvironmentSnapshot,
    has_executable_path: bool,
    has_current_dir: bool,
    startup_mode: StartupMode,
}

impl DuplicateLaunchPayload {
    /// Build a content-safe payload from a launch snapshot and policies.
    pub fn from_launch(
        launch: &LaunchContextSnapshot,
        argument_policy: &LaunchArgumentPolicy,
        environment_allowlist: &LaunchEnvironmentAllowlist,
        startup_mode: StartupMode,
    ) -> Result<Self> {
        Ok(Self {
            argument_report: argument_policy.classify_snapshot(launch)?,
            environment_snapshot: environment_allowlist.summarize_snapshot(launch)?,
            has_executable_path: launch.executable_path().is_some(),
            has_current_dir: launch.current_dir().is_some(),
            startup_mode,
        })
    }

    /// Argument classification for the duplicate launch.
    pub fn argument_report(&self) -> &LaunchArgumentReport {
        &self.argument_report
    }

    /// Environment summary for the duplicate launch.
    pub fn environment_snapshot(&self) -> &LaunchEnvironmentSnapshot {
        &self.environment_snapshot
    }

    /// Whether the original launch snapshot had an executable path.
    pub fn has_executable_path(&self) -> bool {
        self.has_executable_path
    }

    /// Whether the original launch snapshot had a current directory.
    pub fn has_current_dir(&self) -> bool {
        self.has_current_dir
    }

    /// Startup mode associated with this payload.
    pub fn startup_mode(&self) -> StartupMode {
        self.startup_mode
    }

    /// Content-safe summary.
    pub fn to_text(&self) -> String {
        format!(
            "duplicate launch payload: mode {}, {} args, env {} present, executable {}, current_dir {}",
            self.startup_mode.as_str(),
            self.argument_report.argument_count(),
            self.environment_snapshot.present_count(),
            self.has_executable_path,
            self.has_current_dir
        )
    }
}

/// Duplicate-launch routing handoff for existing-instance activation.
