/// How the application should behave when all windows are closed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WindowCloseBehavior {
    /// Quit when the final window closes.
    QuitWhenAllWindowsClose,
    /// Keep the process alive after all windows close.
    KeepAliveWithoutWindows,
}

impl WindowCloseBehavior {
    /// Return whether the platform should keep the app alive without windows.
    pub fn keep_alive_without_windows(self) -> bool {
        matches!(self, Self::KeepAliveWithoutWindows)
    }

    /// Return a stable behavior label for diagnostics.
    pub fn to_text(self) -> &'static str {
        match self {
            Self::QuitWhenAllWindowsClose => "quit",
            Self::KeepAliveWithoutWindows => "keep-alive",
        }
    }
}

/// Validated app lifecycle configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppLifecyclePolicy {
    window_close_behavior: WindowCloseBehavior,
    quit_cleanup_timeout: Duration,
    reason: Option<String>,
}

impl AppLifecyclePolicy {
    /// Behavior used when the final window closes.
    pub fn window_close_behavior(&self) -> WindowCloseBehavior {
        self.window_close_behavior
    }

    /// Whether the app stays alive after all windows close.
    pub fn keep_alive_without_windows(&self) -> bool {
        self.window_close_behavior.keep_alive_without_windows()
    }

    /// Timeout for futures registered with `on_app_quit`.
    pub fn quit_cleanup_timeout(&self) -> Duration {
        self.quit_cleanup_timeout
    }

    /// Optional human-readable reason for telemetry or startup diagnostics.
    pub fn reason(&self) -> Option<&str> {
        self.reason.as_deref()
    }

    /// Whether lifecycle diagnostics include a reason.
    pub fn has_reason(&self) -> bool {
        self.reason.is_some()
    }

    /// Content-safe summary for lifecycle policy traces.
    pub fn to_text(&self) -> String {
        format!(
            "app lifecycle policy: behavior {}, keep-alive {}, quit cleanup ms {}, reason {}",
            self.window_close_behavior.to_text(),
            self.keep_alive_without_windows(),
            self.quit_cleanup_timeout.as_millis(),
            self.has_reason()
        )
    }
}

/// Builder for configuring app lifetime and bounded quit cleanup.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppLifecyclePolicyBuilder {
    window_close_behavior: WindowCloseBehavior,
    quit_cleanup_timeout: Duration,
    reason: Option<String>,
}

impl AppLifecyclePolicyBuilder {
    /// Create the default lifecycle policy.
    pub fn new() -> Self {
        Self {
            window_close_behavior: WindowCloseBehavior::QuitWhenAllWindowsClose,
            quit_cleanup_timeout: SHUTDOWN_TIMEOUT,
            reason: None,
        }
    }

    /// Quit when the final app window closes.
    pub fn quit_when_all_windows_close(mut self) -> Self {
        self.window_close_behavior = WindowCloseBehavior::QuitWhenAllWindowsClose;
        self
    }

    /// Keep the app process alive when all windows close.
    pub fn keep_alive_without_windows(mut self) -> Self {
        self.window_close_behavior = WindowCloseBehavior::KeepAliveWithoutWindows;
        self
    }

    /// Set the timeout for `on_app_quit` cleanup futures.
    pub fn quit_cleanup_timeout(mut self, timeout: Duration) -> Self {
        self.quit_cleanup_timeout = timeout;
        self
    }

    /// Set a human-readable reason for lifecycle diagnostics.
    pub fn reason(mut self, reason: impl Into<String>) -> Self {
        self.reason = Some(reason.into());
        self
    }

    /// Return the configured final-window behavior.
    pub fn window_close_behavior(&self) -> WindowCloseBehavior {
        self.window_close_behavior
    }

    /// Return the configured quit cleanup timeout.
    pub fn configured_quit_cleanup_timeout(&self) -> Duration {
        self.quit_cleanup_timeout
    }

    /// Whether lifecycle diagnostics include a reason.
    pub fn has_reason(&self) -> bool {
        self.reason.is_some()
    }

    /// Content-safe summary for lifecycle policy traces before applying platform state.
    pub fn to_text(&self) -> String {
        format!(
            "app lifecycle policy builder: behavior {}, keep-alive {}, quit cleanup ms {}, reason {}",
            self.window_close_behavior.to_text(),
            self.window_close_behavior.keep_alive_without_windows(),
            self.configured_quit_cleanup_timeout().as_millis(),
            self.has_reason()
        )
    }

    /// Validate lifecycle policy before applying platform state.
    pub fn validate(&self) -> Result<()> {
        anyhow::ensure!(
            self.quit_cleanup_timeout > Duration::ZERO,
            "quit cleanup timeout must be greater than zero"
        );
        anyhow::ensure!(
            self.quit_cleanup_timeout <= Duration::from_secs(30),
            "quit cleanup timeout cannot exceed 30 seconds"
        );
        if let Some(reason) = &self.reason {
            validate_app_metadata_text(reason, "lifecycle policy reason", 256, true)?;
        }
        Ok(())
    }

    /// Build the validated lifecycle policy.
    pub fn build_checked(self) -> Result<AppLifecyclePolicy> {
        self.validate()?;
        Ok(AppLifecyclePolicy {
            window_close_behavior: self.window_close_behavior,
            quit_cleanup_timeout: self.quit_cleanup_timeout,
            reason: self.reason,
        })
    }
}

impl Default for AppLifecyclePolicyBuilder {
    fn default() -> Self {
        Self::new()
    }
}

/// Runtime state for active-window edit commands.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct EditCommandStateSnapshot {
    can_undo: bool,
    can_redo: bool,
    undo_label: Option<String>,
    redo_label: Option<String>,
}

impl EditCommandStateSnapshot {
    /// Build an edit-command snapshot from explicit command state.
    pub fn new(
        can_undo: bool,
        undo_label: Option<String>,
        can_redo: bool,
        redo_label: Option<String>,
    ) -> Result<Self> {
        let snapshot = Self {
            can_undo,
            can_redo,
            undo_label,
            redo_label,
        };
        snapshot.validate()?;
        Ok(snapshot)
    }

    /// Whether the active focused element can undo.
    pub fn can_undo(&self) -> bool {
        self.can_undo
    }

    /// Whether the active focused element can redo.
    pub fn can_redo(&self) -> bool {
        self.can_redo
    }

    /// Label for the next undo action, when available.
    pub fn undo_label(&self) -> Option<&str> {
        self.undo_label.as_deref()
    }

    /// Label for the next redo action, when available.
    pub fn redo_label(&self) -> Option<&str> {
        self.redo_label.as_deref()
    }

    /// Whether either edit command is currently available.
    pub fn has_available_command(&self) -> bool {
        self.can_undo || self.can_redo
    }

    /// Number of available edit commands.
    pub fn available_command_count(&self) -> usize {
        [self.can_undo, self.can_redo]
            .into_iter()
            .filter(|available| *available)
            .count()
    }

    /// Whether an undo label is present.
    pub fn has_undo_label(&self) -> bool {
        self.undo_label.is_some()
    }

    /// Whether a redo label is present.
    pub fn has_redo_label(&self) -> bool {
        self.redo_label.is_some()
    }

    /// Content-safe summary for edit menus, command palettes, and agent traces.
    pub fn to_text(&self) -> String {
        format!(
            "edit command state: undo {}, redo {}, available {}, undo label {}, redo label {}",
            self.can_undo(),
            self.can_redo(),
            self.available_command_count(),
            self.has_undo_label(),
            self.has_redo_label()
        )
    }

    /// Validate generated labels before they reach menus or command palettes.
    pub fn validate(&self) -> Result<()> {
        if let Some(label) = &self.undo_label {
            validate_app_metadata_text(label, "undo command label", 128, false)?;
            anyhow::ensure!(
                self.can_undo,
                "undo command label requires undo to be available"
            );
        }
        if let Some(label) = &self.redo_label {
            validate_app_metadata_text(label, "redo command label", 128, false)?;
            anyhow::ensure!(
                self.can_redo,
                "redo command label requires redo to be available"
            );
        }
        Ok(())
    }
}

/// One checked focus target in an app-owned traversal plan.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FocusTraversalStop {
    id: String,
    label: Option<String>,
    context: Option<String>,
    disabled: bool,
    default: bool,
}

impl FocusTraversalStop {
    /// Stable app-defined focus stop id.
    pub fn id(&self) -> &str {
        &self.id
    }

    /// Optional user-visible label for diagnostics or focus UIs.
    pub fn label(&self) -> Option<&str> {
        self.label.as_deref()
    }

    /// Optional keybinding-style context predicate for this stop.
    pub fn context(&self) -> Option<&str> {
        self.context.as_deref()
    }

    /// Whether this stop should be skipped during normal traversal.
    pub fn disabled(&self) -> bool {
        self.disabled
    }

    /// Whether this stop is the preferred initial focus target.
    pub fn is_default(&self) -> bool {
        self.default
    }

    /// Whether this stop is enabled for normal traversal.
    pub fn enabled(&self) -> bool {
        !self.disabled
    }

    /// Whether this stop has a context predicate.
    pub fn has_context(&self) -> bool {
        self.context.is_some()
    }

    /// Content-safe summary for traces and generated focus UIs.
    pub fn to_text(&self) -> String {
        format!(
            "focus traversal stop: label {}, context {}, disabled {}, default {}",
            self.label.is_some(),
            self.has_context(),
            self.disabled,
            self.default
        )
    }
}

/// Checked focus traversal plan for native forms, editors, menus, and overlays.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FocusTraversalPlan {
    scope: String,
    stops: Vec<FocusTraversalStop>,
    wraps: bool,
    traps_focus: bool,
    restores_previous_focus: bool,
}

impl FocusTraversalPlan {
    /// Stable app-defined scope for this focus traversal plan.
    pub fn scope(&self) -> &str {
        &self.scope
    }

    /// Stops in traversal order.
    pub fn stops(&self) -> &[FocusTraversalStop] {
        &self.stops
    }

    /// Number of configured stops.
    pub fn stop_count(&self) -> usize {
        self.stops.len()
    }

    /// Number of enabled stops.
    pub fn enabled_stop_count(&self) -> usize {
        self.stops.iter().filter(|stop| stop.enabled()).count()
    }

    /// Number of disabled stops.
    pub fn disabled_stop_count(&self) -> usize {
        self.stops.iter().filter(|stop| stop.disabled()).count()
    }

    /// Number of stops with context predicates.
    pub fn context_count(&self) -> usize {
        self.stops.iter().filter(|stop| stop.has_context()).count()
    }

    /// Number of default stops.
    pub fn default_stop_count(&self) -> usize {
        self.stops.iter().filter(|stop| stop.is_default()).count()
    }

    /// Whether traversal wraps at the beginning/end of the plan.
    pub fn wraps(&self) -> bool {
        self.wraps
    }

    /// Whether focus should be contained inside this plan while active.
    pub fn traps_focus(&self) -> bool {
        self.traps_focus
    }

    /// Whether closing the scope should restore previous focus.
    pub fn restores_previous_focus(&self) -> bool {
        self.restores_previous_focus
    }

    /// Return the default stop, when configured.
    pub fn default_stop(&self) -> Option<&FocusTraversalStop> {
        self.stops.iter().find(|stop| stop.is_default())
    }

    /// Return the first enabled stop, when present.
    pub fn first_enabled_stop(&self) -> Option<&FocusTraversalStop> {
        self.stops.iter().find(|stop| stop.enabled())
    }

    /// Content-safe summary for traces and agent audits.
    pub fn to_text(&self) -> String {
        format!(
            "focus traversal plan: {} stops, {} enabled, {} disabled, {} contexts, default {}, wraps {}, traps {}, restores {}",
            self.stop_count(),
            self.enabled_stop_count(),
            self.disabled_stop_count(),
            self.context_count(),
            self.default_stop_count(),
            self.wraps,
            self.traps_focus,
            self.restores_previous_focus
        )
    }
}

/// Builder for checked focus traversal plans.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FocusTraversalPlanBuilder {
    scope: String,
    stops: Vec<FocusTraversalStopBuilder>,
    wraps: bool,
    traps_focus: bool,
    restores_previous_focus: bool,
}

impl FocusTraversalPlanBuilder {
    /// Create an empty focus traversal plan for an app-defined scope.
    pub fn new(scope: impl Into<String>) -> Self {
        Self {
            scope: scope.into(),
            stops: Vec::new(),
            wraps: false,
            traps_focus: false,
            restores_previous_focus: false,
        }
    }

    /// Create a form-style traversal plan.
    pub fn form(scope: impl Into<String>) -> Self {
        Self::new(scope).wrap()
    }

    /// Create an overlay-style traversal plan that contains focus and restores it on close.
    pub fn overlay(scope: impl Into<String>) -> Self {
        Self::new(scope)
            .wrap()
            .trap_focus()
            .restore_previous_focus()
    }

    /// Add a focus stop.
    pub fn stop(mut self, id: impl Into<String>) -> Self {
        self.stops.push(FocusTraversalStopBuilder::new(id));
        self
    }

    /// Add a focus stop with a user-visible label.
    pub fn labeled_stop(mut self, id: impl Into<String>, label: impl Into<String>) -> Self {
        self.stops
            .push(FocusTraversalStopBuilder::new(id).label(label));
        self
    }

    /// Add a disabled focus stop.
    pub fn disabled_stop(mut self, id: impl Into<String>) -> Self {
        self.stops
            .push(FocusTraversalStopBuilder::new(id).disabled());
        self
    }

    /// Add the preferred initial focus stop.
    pub fn default_stop(mut self, id: impl Into<String>) -> Self {
        self.stops
            .push(FocusTraversalStopBuilder::new(id).default());
        self
    }

    /// Add a fully configured stop.
    pub fn custom_stop(mut self, stop: FocusTraversalStopBuilder) -> Self {
        self.stops.push(stop);
        self
    }

    /// Enable wrapping traversal.
    pub fn wrap(mut self) -> Self {
        self.wraps = true;
        self
    }

    /// Disable wrapping traversal.
    pub fn no_wrap(mut self) -> Self {
        self.wraps = false;
        self
    }

    /// Keep focus inside the planned stops while the scope is active.
    pub fn trap_focus(mut self) -> Self {
        self.traps_focus = true;
        self
    }

    /// Allow focus to leave the planned stops.
    pub fn allow_escape(mut self) -> Self {
        self.traps_focus = false;
        self
    }

    /// Restore the previously focused element when the scope closes.
    pub fn restore_previous_focus(mut self) -> Self {
        self.restores_previous_focus = true;
        self
    }

    /// Do not restore the previous focused element when the scope closes.
    pub fn do_not_restore_previous_focus(mut self) -> Self {
        self.restores_previous_focus = false;
        self
    }

    /// Number of configured focus stops.
    pub fn stop_count(&self) -> usize {
        self.stops.len()
    }

    /// Whether traversal wraps.
    pub fn wraps(&self) -> bool {
        self.wraps
    }

    /// Whether the plan traps focus.
    pub fn traps_focus(&self) -> bool {
        self.traps_focus
    }

    /// Whether the plan restores previous focus on close.
    pub fn restores_previous_focus(&self) -> bool {
        self.restores_previous_focus
    }

    /// Content-safe summary for traces and agent audits.
    pub fn to_text(&self) -> String {
        format!(
            "focus traversal plan builder: {} stops, wraps {}, traps {}, restores {}",
            self.stop_count(),
            self.wraps,
            self.traps_focus,
            self.restores_previous_focus
        )
    }

    /// Validate the focus traversal plan.
    pub fn validate(&self) -> Result<()> {
        validate_app_storage_id(&self.scope, "focus traversal scope")?;
        anyhow::ensure!(
            !self.stops.is_empty(),
            "focus traversal plan must include at least one stop"
        );
        anyhow::ensure!(
            self.stops.len() <= 256,
            "focus traversal plan cannot contain more than 256 stops"
        );

        let mut seen = FxHashSet::default();
        let mut default_count = 0usize;
        let mut enabled_count = 0usize;
        for stop in &self.stops {
            stop.validate()?;
            anyhow::ensure!(
                seen.insert(stop.id.clone()),
                "focus traversal stop configured more than once: {}",
                stop.id
            );
            if stop.default {
                default_count += 1;
            }
            if !stop.disabled {
                enabled_count += 1;
            }
        }
        anyhow::ensure!(
            default_count <= 1,
            "focus traversal plan cannot have more than one default stop"
        );
        anyhow::ensure!(
            enabled_count > 0,
            "focus traversal plan must include at least one enabled stop"
        );
        Ok(())
    }

    /// Build the checked focus traversal plan.
    pub fn build_checked(self) -> Result<FocusTraversalPlan> {
        self.validate()?;
        let stops = self
            .stops
            .into_iter()
            .map(FocusTraversalStopBuilder::build_checked)
            .collect::<Result<Vec<_>>>()?;
        Ok(FocusTraversalPlan {
            scope: self.scope,
            stops,
            wraps: self.wraps,
            traps_focus: self.traps_focus,
            restores_previous_focus: self.restores_previous_focus,
        })
    }
}

/// Builder for one focus traversal stop.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FocusTraversalStopBuilder {
    id: String,
    label: Option<String>,
    context: Option<String>,
    disabled: bool,
    default: bool,
}

impl FocusTraversalStopBuilder {
    /// Create a focus stop builder.
    pub fn new(id: impl Into<String>) -> Self {
        Self {
            id: id.into(),
            label: None,
            context: None,
            disabled: false,
            default: false,
        }
    }

    /// Set a user-visible label.
    pub fn label(mut self, label: impl Into<String>) -> Self {
        self.label = Some(label.into());
        self
    }

    /// Set a keybinding-style context predicate.
    pub fn context(mut self, context: impl Into<String>) -> Self {
        self.context = Some(context.into());
        self
    }

    /// Mark this stop as disabled.
    pub fn disabled(mut self) -> Self {
        self.disabled = true;
        self
    }

    /// Mark this stop as enabled.
    pub fn enabled(mut self) -> Self {
        self.disabled = false;
        self
    }

    /// Mark this stop as the preferred initial focus target.
    pub fn default(mut self) -> Self {
        self.default = true;
        self
    }

    /// Clear preferred initial focus for this stop.
    pub fn not_default(mut self) -> Self {
        self.default = false;
        self
    }

    fn validate(&self) -> Result<()> {
        validate_app_storage_id(&self.id, "focus traversal stop id")?;
        if let Some(label) = &self.label {
            validate_app_metadata_text(label, "focus traversal stop label", 128, false)?;
        }
        if let Some(context) = &self.context {
            validate_key_binding_context(context)?;
        }
        anyhow::ensure!(
            !(self.disabled && self.default),
            "disabled focus traversal stops cannot be default"
        );
        Ok(())
    }

    fn build_checked(self) -> Result<FocusTraversalStop> {
        self.validate()?;
        Ok(FocusTraversalStop {
            id: self.id,
            label: self.label,
            context: self.context,
            disabled: self.disabled,
            default: self.default,
        })
    }
}

/// Pointer affordance class expected by an app-owned native surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum PointerInputCapability {
    /// Hover previews, hover chrome, or tooltips.
    Hover,
    /// Primary button clicks or taps.
    PrimaryClick,
    /// Secondary button clicks or context-menu triggers.
    SecondaryClick,
    /// Drag handles, reorder handles, splitters, sliders, or canvas drags.
    Drag,
    /// Wheel or trackpad scrolling.
    Wheel,
    /// Touch-adjacent behavior such as larger hit targets.
    TouchLike,
    /// Stylus-adjacent behavior without promising pressure or tilt streams.
    StylusLike,
}

impl PointerInputCapability {
    /// Stable key for diagnostics and generated setup.
    pub fn key(self) -> &'static str {
        match self {
            Self::Hover => "hover",
            Self::PrimaryClick => "primary-click",
            Self::SecondaryClick => "secondary-click",
            Self::Drag => "drag",
            Self::Wheel => "wheel",
            Self::TouchLike => "touch-like",
            Self::StylusLike => "stylus-like",
        }
    }
}

/// Checked pointer-input policy for an app-owned native surface.
#[derive(Debug, Clone, PartialEq)]
pub struct PointerInputPolicy {
    scope: String,
    capabilities: Vec<PointerInputCapability>,
    minimum_hit_size_px: Option<f32>,
    drag_threshold_px: Option<f32>,
    require_hover_fallback: bool,
    capture_during_drag: bool,
}

impl PointerInputPolicy {
    /// Stable app-defined scope for this pointer policy.
    pub fn scope(&self) -> &str {
        &self.scope
    }

    /// Pointer capabilities expected by this surface.
    pub fn capabilities(&self) -> &[PointerInputCapability] {
        &self.capabilities
    }

    /// Number of requested pointer capabilities.
    pub fn capability_count(&self) -> usize {
        self.capabilities.len()
    }

    /// Whether a capability is requested.
    pub fn has_capability(&self, capability: PointerInputCapability) -> bool {
        self.capabilities.contains(&capability)
    }

    /// Optional minimum hit target size in physical pixels.
    pub fn minimum_hit_size_px(&self) -> Option<f32> {
        self.minimum_hit_size_px
    }

    /// Optional drag threshold in physical pixels.
    pub fn drag_threshold_px(&self) -> Option<f32> {
        self.drag_threshold_px
    }

    /// Whether hover-dependent UI must provide non-hover fallback behavior.
    pub fn requires_hover_fallback(&self) -> bool {
        self.require_hover_fallback
    }

    /// Whether active drags should capture pointer input until release/cancel.
    pub fn captures_during_drag(&self) -> bool {
        self.capture_during_drag
    }

    /// Content-safe summary for traces and agent audits.
    pub fn to_text(&self) -> String {
        format!(
            "pointer input policy: {} capabilities, hit size {}, drag threshold {}, hover fallback {}, capture drag {}",
            self.capability_count(),
            self.minimum_hit_size_px.is_some(),
            self.drag_threshold_px.is_some(),
            self.require_hover_fallback,
            self.capture_during_drag
        )
    }
}

/// Builder for checked pointer-input policy.
#[derive(Debug, Clone, PartialEq)]
pub struct PointerInputPolicyBuilder {
    scope: String,
    capabilities: Vec<PointerInputCapability>,
    minimum_hit_size_px: Option<f32>,
    drag_threshold_px: Option<f32>,
    require_hover_fallback: bool,
    capture_during_drag: bool,
}

impl PointerInputPolicyBuilder {
    /// Create an empty pointer policy for an app-defined scope.
    pub fn new(scope: impl Into<String>) -> Self {
        Self {
            scope: scope.into(),
            capabilities: Vec::new(),
            minimum_hit_size_px: None,
            drag_threshold_px: None,
            require_hover_fallback: false,
            capture_during_drag: false,
        }
    }

    /// Policy for a draggable native surface.
    pub fn drag_surface(scope: impl Into<String>) -> Self {
        Self::new(scope)
            .primary_click()
            .drag()
            .capture_during_drag()
            .drag_threshold_px(4.0)
    }

    /// Policy for a hover-preview native surface with a non-hover fallback.
    pub fn hover_preview(scope: impl Into<String>) -> Self {
        Self::new(scope).hover().require_hover_fallback()
    }

    /// Add a pointer capability.
    pub fn capability(mut self, capability: PointerInputCapability) -> Self {
        if !self.capabilities.contains(&capability) {
            self.capabilities.push(capability);
        }
        self
    }

    /// Add hover behavior.
    pub fn hover(self) -> Self {
        self.capability(PointerInputCapability::Hover)
    }

    /// Add primary click behavior.
    pub fn primary_click(self) -> Self {
        self.capability(PointerInputCapability::PrimaryClick)
    }

    /// Add secondary click behavior.
    pub fn secondary_click(self) -> Self {
        self.capability(PointerInputCapability::SecondaryClick)
    }

    /// Add drag behavior.
    pub fn drag(self) -> Self {
        self.capability(PointerInputCapability::Drag)
    }

    /// Add wheel behavior.
    pub fn wheel(self) -> Self {
        self.capability(PointerInputCapability::Wheel)
    }

    /// Add touch-adjacent behavior.
    pub fn touch_like(self) -> Self {
        self.capability(PointerInputCapability::TouchLike)
    }

    /// Add stylus-adjacent behavior without promising pressure or tilt streams.
    pub fn stylus_like(self) -> Self {
        self.capability(PointerInputCapability::StylusLike)
    }

    /// Set the minimum hit target size in physical pixels.
    pub fn minimum_hit_size_px(mut self, size: f32) -> Self {
        self.minimum_hit_size_px = Some(size);
        self
    }

    /// Set the drag threshold in physical pixels.
    pub fn drag_threshold_px(mut self, threshold: f32) -> Self {
        self.drag_threshold_px = Some(threshold);
        self
    }

    /// Require non-hover fallback behavior.
    pub fn require_hover_fallback(mut self) -> Self {
        self.require_hover_fallback = true;
        self
    }

    /// Mark hover fallback as optional.
    pub fn allow_hover_only(mut self) -> Self {
        self.require_hover_fallback = false;
        self
    }

    /// Capture pointer input during active drags.
    pub fn capture_during_drag(mut self) -> Self {
        self.capture_during_drag = true;
        self
    }

    /// Do not capture pointer input during active drags.
    pub fn do_not_capture_during_drag(mut self) -> Self {
        self.capture_during_drag = false;
        self
    }

    /// Number of configured capabilities.
    pub fn capability_count(&self) -> usize {
        self.capabilities.len()
    }

    /// Content-safe summary for traces and agent audits.
    pub fn to_text(&self) -> String {
        format!(
            "pointer input policy builder: {} capabilities, hit size {}, drag threshold {}, hover fallback {}, capture drag {}",
            self.capability_count(),
            self.minimum_hit_size_px.is_some(),
            self.drag_threshold_px.is_some(),
            self.require_hover_fallback,
            self.capture_during_drag
        )
    }

    /// Validate the pointer policy.
    pub fn validate(&self) -> Result<()> {
        validate_app_storage_id(&self.scope, "pointer input policy scope")?;
        anyhow::ensure!(
            !self.capabilities.is_empty(),
            "pointer input policy must include at least one capability"
        );
        if let Some(size) = self.minimum_hit_size_px {
            validate_positive_finite(size, "pointer input minimum hit size")?;
            anyhow::ensure!(
                size <= 512.0,
                "pointer input minimum hit size cannot exceed 512 px"
            );
        }
        if let Some(threshold) = self.drag_threshold_px {
            validate_positive_finite(threshold, "pointer input drag threshold")?;
            anyhow::ensure!(
                threshold <= 128.0,
                "pointer input drag threshold cannot exceed 128 px"
            );
            anyhow::ensure!(
                self.capabilities.contains(&PointerInputCapability::Drag),
                "pointer input drag threshold requires drag capability"
            );
        }
        anyhow::ensure!(
            !self.capture_during_drag || self.capabilities.contains(&PointerInputCapability::Drag),
            "pointer input drag capture requires drag capability"
        );
        anyhow::ensure!(
            !self.require_hover_fallback
                || self.capabilities.contains(&PointerInputCapability::Hover),
            "pointer input hover fallback requires hover capability"
        );
        Ok(())
    }

    /// Build the checked pointer policy.
    pub fn build_checked(self) -> Result<PointerInputPolicy> {
        self.validate()?;
        Ok(PointerInputPolicy {
            scope: self.scope,
            capabilities: self.capabilities,
            minimum_hit_size_px: self.minimum_hit_size_px,
            drag_threshold_px: self.drag_threshold_px,
            require_hover_fallback: self.require_hover_fallback,
            capture_during_drag: self.capture_during_drag,
        })
    }
}

