/// Unit of work covered by a checked shortcut/input handoff.
pub enum ShortcutInputRequest {
    /// App-local keybindings/accelerators.
    AppKeybindings(KeyBindingSetBuilder),
    /// System-wide global hotkey registrations.
    GlobalHotkeys(GlobalHotkeyBuilder),
    /// System-wide global hotkey cleanup.
    GlobalHotkeyCleanup(GlobalHotkeyUnregistration),
    /// App-local keybinding cleanup.
    KeyBindingCleanup(KeyBindingClearBuilder),
    /// Snapshot the keyboard layout before showing or normalizing shortcuts.
    KeyboardLayout(KeyboardLayoutSnapshotBuilder),
    /// Explicit browser island for browser-owned keyboard semantics.
    HostedShortcutIsland {
        /// Hosted surface id.
        surface_id: SharedString,
    },
    /// Shortcut/input work that remains roadmap/native-backend work.
    RoadmapWork {
        /// Product-safe reason label.
        reason: String,
    },
}

impl ShortcutInputRequest {
    /// Validate one shortcut/input handoff request.
    pub fn validate(&self, app: &App) -> Result<()> {
        match self {
            Self::AppKeybindings(bindings) => bindings.validate(app),
            Self::GlobalHotkeys(hotkeys) => hotkeys.validate(),
            Self::GlobalHotkeyCleanup(cleanup) => cleanup.validate(),
            Self::KeyBindingCleanup(cleanup) => cleanup.validate(),
            Self::KeyboardLayout(snapshot) => snapshot.build_checked(app).map(drop),
            Self::HostedShortcutIsland { surface_id } => {
                validate_app_storage_id(surface_id, "hosted shortcut island surface id")
            }
            Self::RoadmapWork { reason } => {
                validate_app_metadata_text(reason, "shortcut input roadmap reason", 192, false)
            }
        }
    }

    /// Privacy-preserving request kind for summaries.
    pub fn summary_kind(&self) -> &'static str {
        match self {
            Self::AppKeybindings(_) => "app-keybindings",
            Self::GlobalHotkeys(_) => "global-hotkeys",
            Self::GlobalHotkeyCleanup(_) => "global-hotkey-cleanup",
            Self::KeyBindingCleanup(_) => "keybinding-cleanup",
            Self::KeyboardLayout(_) => "keyboard-layout",
            Self::HostedShortcutIsland { .. } => "hosted-shortcut-island",
            Self::RoadmapWork { .. } => "roadmap-work",
        }
    }
}

/// Recommended next action for shortcut/input handoffs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ShortcutInputNextAction {
    /// Validate or install app-local accelerators.
    InstallAppKeybindings,
    /// Validate or register system-wide hotkeys.
    RegisterGlobalHotkeys,
    /// Validate or unregister system-wide hotkeys.
    UnregisterGlobalHotkeys,
    /// Validate or clear app-local keybindings.
    ClearAppKeybindings,
    /// Snapshot keyboard layout before displaying shortcut UI.
    SnapshotKeyboardLayout,
    /// Use an explicit hosted browser keyboard island.
    UseHostedShortcutIsland,
    /// Track shortcut/input roadmap work.
    TrackShortcutRoadmap,
}

impl ShortcutInputNextAction {
    /// Stable key for logs and agent plans.
    pub fn key(&self) -> &'static str {
        match self {
            Self::InstallAppKeybindings => "install-app-keybindings",
            Self::RegisterGlobalHotkeys => "register-global-hotkeys",
            Self::UnregisterGlobalHotkeys => "unregister-global-hotkeys",
            Self::ClearAppKeybindings => "clear-app-keybindings",
            Self::SnapshotKeyboardLayout => "snapshot-keyboard-layout",
            Self::UseHostedShortcutIsland => "use-hosted-shortcut-island",
            Self::TrackShortcutRoadmap => "track-shortcut-roadmap",
        }
    }
}

/// Checked native-first shortcut/input handoff for app accelerators and global shortcuts.
pub struct ShortcutInputHandoff {
    requests: Vec<ShortcutInputRequest>,
}

impl ShortcutInputHandoff {
    /// Start building a shortcut/input handoff.
    pub fn builder() -> ShortcutInputHandoffBuilder {
        ShortcutInputHandoffBuilder::new()
    }

    /// Requests covered by this handoff.
    pub fn requests(&self) -> &[ShortcutInputRequest] {
        &self.requests
    }

    /// Number of requests in the handoff.
    pub fn request_count(&self) -> usize {
        self.requests.len()
    }

    /// Whether this handoff includes app-local keybindings.
    pub fn has_app_keybindings(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::AppKeybindings(_)))
    }

    /// Whether this handoff includes system-wide hotkeys.
    pub fn has_global_hotkeys(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::GlobalHotkeys(_)))
    }

    /// Whether this handoff includes global hotkey cleanup.
    pub fn has_global_hotkey_cleanup(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::GlobalHotkeyCleanup(_)))
    }

    /// Whether this handoff includes app keybinding cleanup.
    pub fn has_keybinding_cleanup(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::KeyBindingCleanup(_)))
    }

    /// Whether this handoff includes keyboard-layout snapshot work.
    pub fn has_keyboard_layout_snapshot(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::KeyboardLayout(_)))
    }

    /// Whether this handoff delegates to a hosted keyboard island.
    pub fn has_hosted_shortcut_island(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::HostedShortcutIsland { .. }))
    }

    /// Whether this handoff tracks roadmap work.
    pub fn has_roadmap_work(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, ShortcutInputRequest::RoadmapWork { .. }))
    }

    /// First recommended action for builders and AI agents.
    pub fn next_action(&self) -> ShortcutInputNextAction {
        if self.has_app_keybindings() {
            ShortcutInputNextAction::InstallAppKeybindings
        } else if self.has_global_hotkeys() {
            ShortcutInputNextAction::RegisterGlobalHotkeys
        } else if self.has_global_hotkey_cleanup() {
            ShortcutInputNextAction::UnregisterGlobalHotkeys
        } else if self.has_keybinding_cleanup() {
            ShortcutInputNextAction::ClearAppKeybindings
        } else if self.has_keyboard_layout_snapshot() {
            ShortcutInputNextAction::SnapshotKeyboardLayout
        } else if self.has_hosted_shortcut_island() {
            ShortcutInputNextAction::UseHostedShortcutIsland
        } else {
            ShortcutInputNextAction::TrackShortcutRoadmap
        }
    }

    /// Validate all shortcut/input requests.
    pub fn validate(&self, app: &App) -> Result<()> {
        anyhow::ensure!(
            !self.requests.is_empty(),
            "shortcut input handoff requires at least one request"
        );
        anyhow::ensure!(
            self.requests.len() <= 32,
            "shortcut input handoff supports at most 32 requests"
        );
        for request in &self.requests {
            request.validate(app)?;
        }
        Ok(())
    }

    /// Content-safe summary for logs, docs, and generated agent plans.
    pub fn to_text(&self) -> String {
        let mut kinds = BTreeMap::new();
        for request in &self.requests {
            *kinds.entry(request.summary_kind()).or_insert(0usize) += 1;
        }
        let kinds = kinds
            .iter()
            .map(|(kind, count)| format!("{kind}:{count}"))
            .collect::<Vec<_>>()
            .join(", ");
        format!(
            "shortcut input handoff: {} requests, next action {}, kinds [{}], app keybindings {}, global hotkeys {}, global cleanup {}, keybinding cleanup {}, layout {}, hosted {}, roadmap {}",
            self.request_count(),
            self.next_action().key(),
            kinds,
            self.has_app_keybindings(),
            self.has_global_hotkeys(),
            self.has_global_hotkey_cleanup(),
            self.has_keybinding_cleanup(),
            self.has_keyboard_layout_snapshot(),
            self.has_hosted_shortcut_island(),
            self.has_roadmap_work()
        )
    }
}

/// Builder for checked native-first shortcut/input handoffs.
#[derive(Default)]
pub struct ShortcutInputHandoffBuilder {
    requests: Vec<ShortcutInputRequest>,
}

impl ShortcutInputHandoffBuilder {
    /// Create an empty shortcut/input handoff builder.
    pub fn new() -> Self {
        Self::default()
    }

    /// Add app-local keybindings.
    pub fn app_keybindings(mut self, bindings: KeyBindingSetBuilder) -> Self {
        self.requests
            .push(ShortcutInputRequest::AppKeybindings(bindings));
        self
    }

    /// Add system-wide global hotkeys.
    pub fn global_hotkeys(mut self, hotkeys: GlobalHotkeyBuilder) -> Self {
        self.requests
            .push(ShortcutInputRequest::GlobalHotkeys(hotkeys));
        self
    }

    /// Add system-wide global hotkey cleanup.
    pub fn global_hotkey_cleanup(mut self, cleanup: GlobalHotkeyUnregistration) -> Self {
        self.requests
            .push(ShortcutInputRequest::GlobalHotkeyCleanup(cleanup));
        self
    }

    /// Add app-local keybinding cleanup.
    pub fn keybinding_cleanup(mut self, cleanup: KeyBindingClearBuilder) -> Self {
        self.requests
            .push(ShortcutInputRequest::KeyBindingCleanup(cleanup));
        self
    }

    /// Add a keyboard-layout snapshot.
    pub fn keyboard_layout(mut self, snapshot: KeyboardLayoutSnapshotBuilder) -> Self {
        self.requests
            .push(ShortcutInputRequest::KeyboardLayout(snapshot));
        self
    }

    /// Add an explicit browser island for browser-owned keyboard semantics.
    pub fn hosted_shortcut_island(mut self, surface_id: impl Into<SharedString>) -> Self {
        self.requests
            .push(ShortcutInputRequest::HostedShortcutIsland {
                surface_id: surface_id.into(),
            });
        self
    }

    /// Add shortcut/input roadmap work.
    pub fn roadmap_work(mut self, reason: impl Into<String>) -> Self {
        self.requests.push(ShortcutInputRequest::RoadmapWork {
            reason: reason.into(),
        });
        self
    }

    /// Validate without consuming the builder.
    pub fn validate(&self, app: &App) -> Result<()> {
        anyhow::ensure!(
            !self.requests.is_empty(),
            "shortcut input handoff requires at least one request"
        );
        anyhow::ensure!(
            self.requests.len() <= 32,
            "shortcut input handoff supports at most 32 requests"
        );
        for request in &self.requests {
            request.validate(app)?;
        }
        Ok(())
    }

    /// Build a checked shortcut/input handoff.
    pub fn build_checked(self, app: &App) -> Result<ShortcutInputHandoff> {
        self.validate(app)?;
        Ok(ShortcutInputHandoff {
            requests: self.requests,
        })
    }
}

/// Builder for checked app-global removal.
