/// App-level lifecycle or activation command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AppLifecycleCommandKind {
    /// Bring the app to the foreground.
    Activate {
        /// Whether to ask the OS to ignore other apps while activating.
        ignoring_other_apps: bool,
    },
    /// Hide this app.
    Hide,
    /// Hide other apps.
    HideOtherApps,
    /// Unhide other apps.
    UnhideOtherApps,
    /// Quit the app.
    Quit,
    /// Restart/relaunch the app.
    Restart,
}

impl AppLifecycleCommandKind {
    /// Return a stable command-kind label for diagnostics.
    pub fn to_text(self) -> &'static str {
        match self {
            Self::Activate { .. } => "activate",
            Self::Hide => "hide",
            Self::HideOtherApps => "hide-other-apps",
            Self::UnhideOtherApps => "unhide-other-apps",
            Self::Quit => "quit",
            Self::Restart => "restart",
        }
    }

    /// Whether activation should ask the OS to ignore other apps.
    pub fn ignores_other_apps(self) -> bool {
        match self {
            Self::Activate {
                ignoring_other_apps,
            } => ignoring_other_apps,
            Self::Hide
            | Self::HideOtherApps
            | Self::UnhideOtherApps
            | Self::Quit
            | Self::Restart => false,
        }
    }
}

/// Checked app-level lifecycle command for native desktop app control.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppLifecycleCommand {
    kind: AppLifecycleCommandKind,
    reason: Option<String>,
}

impl AppLifecycleCommand {
    /// Bring the app to the foreground without forcing other apps aside.
    pub fn activate() -> Self {
        Self::activate_with_options(false)
    }

    /// Bring the app to the foreground, optionally asking the OS to ignore other apps.
    pub fn activate_with_options(ignoring_other_apps: bool) -> Self {
        Self {
            kind: AppLifecycleCommandKind::Activate {
                ignoring_other_apps,
            },
            reason: None,
        }
    }

    /// Hide this app.
    pub fn hide() -> Self {
        Self {
            kind: AppLifecycleCommandKind::Hide,
            reason: None,
        }
    }

    /// Hide other apps.
    pub fn hide_other_apps() -> Self {
        Self {
            kind: AppLifecycleCommandKind::HideOtherApps,
            reason: None,
        }
    }

    /// Unhide other apps.
    pub fn unhide_other_apps() -> Self {
        Self {
            kind: AppLifecycleCommandKind::UnhideOtherApps,
            reason: None,
        }
    }

    /// Quit the app with a required human-readable reason.
    pub fn quit(reason: impl Into<String>) -> Self {
        Self {
            kind: AppLifecycleCommandKind::Quit,
            reason: Some(reason.into()),
        }
    }

    /// Restart the app with a required human-readable reason.
    pub fn restart(reason: impl Into<String>) -> Self {
        Self {
            kind: AppLifecycleCommandKind::Restart,
            reason: Some(reason.into()),
        }
    }

    /// Attach a diagnostic reason to a non-terminal activation/hide command.
    pub fn reason(mut self, reason: impl Into<String>) -> Self {
        self.reason = Some(reason.into());
        self
    }

    /// The command kind.
    pub fn kind(&self) -> AppLifecycleCommandKind {
        self.kind
    }

    /// Optional human-readable reason for telemetry or command auditing.
    pub fn reason_text(&self) -> Option<&str> {
        self.reason.as_deref()
    }

    /// Whether this command can terminate the current process.
    pub fn is_terminal(&self) -> bool {
        matches!(
            self.kind,
            AppLifecycleCommandKind::Quit | AppLifecycleCommandKind::Restart
        )
    }

    /// Whether a diagnostic reason is configured.
    pub fn has_reason(&self) -> bool {
        self.reason.is_some()
    }

    /// Content-safe summary for lifecycle command traces.
    pub fn to_text(&self) -> String {
        format!(
            "lifecycle command: kind {}, terminal {}, reason {}, ignoring other apps {}",
            self.kind.to_text(),
            self.is_terminal(),
            self.has_reason(),
            self.kind.ignores_other_apps()
        )
    }

    /// Validate the command before dispatching it to the platform.
    pub fn validate(&self) -> Result<()> {
        if self.is_terminal() {
            anyhow::ensure!(
                self.reason.is_some(),
                "quit and restart lifecycle commands require a reason"
            );
        }

        if let Some(reason) = &self.reason {
            validate_app_metadata_text(reason, "lifecycle command reason", 256, true)?;
        }

        Ok(())
    }

    /// Evaluate this command against a runtime snapshot before dispatch.
    pub fn plan_against(&self, snapshot: &AppRuntimeSnapshot) -> Result<AppLifecycleCommandPlan> {
        self.plan_against_with_restart_path(snapshot, false)
    }

    /// Evaluate this command against runtime state and restart-path setup.
    pub fn plan_against_with_restart_path(
        &self,
        snapshot: &AppRuntimeSnapshot,
        restart_path_configured: bool,
    ) -> Result<AppLifecycleCommandPlan> {
        self.validate()?;
        Ok(AppLifecycleCommandPlan {
            command: self.clone(),
            window_count: snapshot.window_count(),
            background_runtime: snapshot.is_background_runtime(),
            quitting: snapshot.is_quitting(),
            restart_path_configured,
        })
    }
}

/// Checked lifecycle-command readiness plan for native desktop app control.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppLifecycleCommandPlan {
    command: AppLifecycleCommand,
    window_count: usize,
    background_runtime: bool,
    quitting: bool,
    restart_path_configured: bool,
}

impl AppLifecycleCommandPlan {
    /// The validated lifecycle command.
    pub fn command(&self) -> &AppLifecycleCommand {
        &self.command
    }

    /// Command kind that would be dispatched.
    pub fn kind(&self) -> AppLifecycleCommandKind {
        self.command.kind()
    }

    /// Whether this command can terminate the current process.
    pub fn is_terminal(&self) -> bool {
        self.command.is_terminal()
    }

    /// Whether the command carries a diagnostic reason.
    pub fn has_reason(&self) -> bool {
        self.command.has_reason()
    }

    /// Whether activation asks the OS to ignore other apps.
    pub fn ignores_other_apps(&self) -> bool {
        self.command.kind().ignores_other_apps()
    }

    /// Number of windows open when the plan was built.
    pub fn window_count(&self) -> usize {
        self.window_count
    }

    /// Whether there were open windows when the plan was built.
    pub fn has_windows(&self) -> bool {
        self.window_count > 0
    }

    /// Whether the runtime was background-only when the plan was built.
    pub fn is_background_runtime(&self) -> bool {
        self.background_runtime
    }

    /// Whether app shutdown had already begun when the plan was built.
    pub fn is_quitting(&self) -> bool {
        self.quitting
    }

    /// Whether a custom restart path was configured before planning.
    pub fn restart_path_configured(&self) -> bool {
        self.restart_path_configured
    }

    /// Whether the command is safe to dispatch for the captured runtime state.
    pub fn is_ready(&self) -> bool {
        !self.quitting
    }

    /// Whether this command plan has a runtime readiness gap.
    pub fn has_gap(&self) -> bool {
        !self.is_ready()
    }

    /// Content-safe summary for lifecycle setup screens, tests, and agent traces.
    pub fn to_text(&self) -> String {
        format!(
            "lifecycle command plan: kind {}, terminal {}, reason {}, windows {}, background {}, quitting {}, restart path {}, ready {}",
            self.kind().to_text(),
            self.is_terminal(),
            self.has_reason(),
            self.window_count(),
            self.is_background_runtime(),
            self.is_quitting(),
            self.restart_path_configured(),
            self.is_ready()
        )
    }
}

/// Next action for a checked lifecycle/startup handoff.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AppLifecycleStartupNextAction {
    /// Apply app lifecycle policy before opening or closing windows.
    ConfigureLifecyclePolicy,
    /// Plan a foreground, hide, quit, or restart command against runtime state.
    PlanLifecycleCommand,
    /// Route a duplicate process launch into the already-running instance.
    RouteDuplicateLaunch,
    /// Configure launch-at-login settings.
    ConfigureAutoLaunch,
    /// Add documents to the platform recent-documents list.
    AddRecentDocuments,
    /// Clear platform recent-document state.
    ClearRecentDocuments,
}

impl AppLifecycleStartupNextAction {
    /// Stable action label for diagnostics and agent routing.
    pub fn key(self) -> &'static str {
        match self {
            Self::ConfigureLifecyclePolicy => "configure-lifecycle-policy",
            Self::PlanLifecycleCommand => "plan-lifecycle-command",
            Self::RouteDuplicateLaunch => "route-duplicate-launch",
            Self::ConfigureAutoLaunch => "configure-auto-launch",
            Self::AddRecentDocuments => "add-recent-documents",
            Self::ClearRecentDocuments => "clear-recent-documents",
        }
    }
}

/// Checked lifecycle/startup request for generated app setup and activation flows.
#[derive(Debug, Clone)]
pub enum AppLifecycleStartupRequest {
    /// Final-window and quit-cleanup policy.
    Policy(AppLifecyclePolicyBuilder),
    /// App activation, hide, quit, or restart command.
    Command(AppLifecycleCommand),
    /// Duplicate launch payload for existing-instance routing.
    DuplicateLaunch(DuplicateLaunchHandoff),
    /// Launch-at-login configuration.
    AutoLaunch(AutoLaunchBuilder),
    /// Add documents to OS recents.
    RecentDocuments(RecentDocumentsBuilder),
    /// Clear OS recents.
    ClearRecentDocuments(RecentDocumentsClearBuilder),
}

impl AppLifecycleStartupRequest {
    /// Whether this request configures lifecycle policy.
    pub fn is_policy(&self) -> bool {
        matches!(self, Self::Policy(_))
    }

    /// Whether this request plans a lifecycle command.
    pub fn is_command(&self) -> bool {
        matches!(self, Self::Command(_))
    }

    /// Whether this request routes a duplicate launch.
    pub fn is_duplicate_launch(&self) -> bool {
        matches!(self, Self::DuplicateLaunch(_))
    }

    /// Whether this request configures launch-at-login.
    pub fn is_auto_launch(&self) -> bool {
        matches!(self, Self::AutoLaunch(_))
    }

    /// Whether this request adds recent documents.
    pub fn is_recent_documents(&self) -> bool {
        matches!(self, Self::RecentDocuments(_))
    }

    /// Whether this request clears recent documents.
    pub fn is_clear_recent_documents(&self) -> bool {
        matches!(self, Self::ClearRecentDocuments(_))
    }

    /// Next action implied by this request.
    pub fn next_action(&self) -> AppLifecycleStartupNextAction {
        match self {
            Self::Policy(_) => AppLifecycleStartupNextAction::ConfigureLifecyclePolicy,
            Self::Command(_) => AppLifecycleStartupNextAction::PlanLifecycleCommand,
            Self::DuplicateLaunch(_) => AppLifecycleStartupNextAction::RouteDuplicateLaunch,
            Self::AutoLaunch(_) => AppLifecycleStartupNextAction::ConfigureAutoLaunch,
            Self::RecentDocuments(_) => AppLifecycleStartupNextAction::AddRecentDocuments,
            Self::ClearRecentDocuments(_) => AppLifecycleStartupNextAction::ClearRecentDocuments,
        }
    }

    /// Lifecycle policy builder when this request configures policy.
    pub fn policy_builder(&self) -> Option<&AppLifecyclePolicyBuilder> {
        match self {
            Self::Policy(policy) => Some(policy),
            _ => None,
        }
    }

    /// Lifecycle command when this request plans a command.
    pub fn command(&self) -> Option<&AppLifecycleCommand> {
        match self {
            Self::Command(command) => Some(command),
            _ => None,
        }
    }

    /// Duplicate-launch handoff when this request routes a duplicate launch.
    pub fn duplicate_launch(&self) -> Option<&DuplicateLaunchHandoff> {
        match self {
            Self::DuplicateLaunch(handoff) => Some(handoff),
            _ => None,
        }
    }

    /// Auto-launch builder when this request configures launch-at-login.
    pub fn auto_launch_builder(&self) -> Option<&AutoLaunchBuilder> {
        match self {
            Self::AutoLaunch(auto_launch) => Some(auto_launch),
            _ => None,
        }
    }

    /// Recent-documents builder when this request adds recent documents.
    pub fn recent_documents_builder(&self) -> Option<&RecentDocumentsBuilder> {
        match self {
            Self::RecentDocuments(documents) => Some(documents),
            _ => None,
        }
    }

    /// Clear-recents request when this request clears recent documents.
    pub fn clear_recent_documents_request(&self) -> Option<&RecentDocumentsClearBuilder> {
        match self {
            Self::ClearRecentDocuments(request) => Some(request),
            _ => None,
        }
    }

    /// Content-safe request summary.
    pub fn to_text(&self) -> String {
        let detail = match self {
            Self::Policy(policy) => policy.to_text(),
            Self::Command(command) => command.to_text(),
            Self::DuplicateLaunch(handoff) => handoff.to_text(),
            Self::AutoLaunch(auto_launch) => format!(
                "auto-launch builder: requested enabled {}",
                auto_launch.requested_enabled()
            ),
            Self::RecentDocuments(documents) => documents.to_text(),
            Self::ClearRecentDocuments(request) => request.to_text(),
        };
        format!(
            "app lifecycle startup request: action {}, {}",
            self.next_action().key(),
            detail
        )
    }

    /// Validate the request before routing it.
    pub fn validate(&self) -> Result<()> {
        match self {
            Self::Policy(policy) => policy.validate(),
            Self::Command(command) => command.validate(),
            Self::DuplicateLaunch(_) => Ok(()),
            Self::AutoLaunch(auto_launch) => auto_launch.validate(),
            Self::RecentDocuments(documents) => documents.validate(),
            Self::ClearRecentDocuments(request) => request.validate(),
        }
    }
}

/// Builder for a checked lifecycle/startup handoff.
#[derive(Debug, Clone)]
pub struct AppLifecycleStartupHandoffBuilder {
    request: AppLifecycleStartupRequest,
}

impl AppLifecycleStartupHandoffBuilder {
    /// Handoff for app lifecycle policy.
    pub fn policy(policy: AppLifecyclePolicyBuilder) -> Self {
        Self {
            request: AppLifecycleStartupRequest::Policy(policy),
        }
    }

    /// Handoff for a lifecycle command.
    pub fn command(command: AppLifecycleCommand) -> Self {
        Self {
            request: AppLifecycleStartupRequest::Command(command),
        }
    }

    /// Handoff for duplicate-launch routing.
    pub fn duplicate_launch(handoff: DuplicateLaunchHandoff) -> Self {
        Self {
            request: AppLifecycleStartupRequest::DuplicateLaunch(handoff),
        }
    }

    /// Handoff for launch-at-login configuration.
    pub fn auto_launch(auto_launch: AutoLaunchBuilder) -> Self {
        Self {
            request: AppLifecycleStartupRequest::AutoLaunch(auto_launch),
        }
    }

    /// Handoff for adding recent documents.
    pub fn recent_documents(documents: RecentDocumentsBuilder) -> Self {
        Self {
            request: AppLifecycleStartupRequest::RecentDocuments(documents),
        }
    }

    /// Handoff for clearing recent documents.
    pub fn clear_recent_documents(request: RecentDocumentsClearBuilder) -> Self {
        Self {
            request: AppLifecycleStartupRequest::ClearRecentDocuments(request),
        }
    }

    /// Request carried by this handoff builder.
    pub fn request(&self) -> &AppLifecycleStartupRequest {
        &self.request
    }

    /// Next action implied by this handoff builder.
    pub fn next_action(&self) -> AppLifecycleStartupNextAction {
        self.request.next_action()
    }

    /// Content-safe builder summary.
    pub fn to_text(&self) -> String {
        format!(
            "app lifecycle startup handoff builder: {}",
            self.request.to_text()
        )
    }

    /// Validate the handoff builder before dispatch.
    pub fn validate(&self) -> Result<()> {
        self.request.validate()
    }

    /// Build a checked handoff.
    pub fn build_checked(self) -> Result<AppLifecycleStartupHandoff> {
        self.validate()?;
        let next_action = self.request.next_action();
        Ok(AppLifecycleStartupHandoff {
            request: self.request,
            next_action,
        })
    }
}

