/// Unit of work covered by a checked visual capture handoff.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum VisualCaptureRequest {
    /// Native app-window capture.
    AppWindowCapture(AppWindowCaptureRequest),
    /// Native headless/cached/effect evidence.
    NativeSnapshotEvidence {
        /// Product-safe evidence kind.
        kind: String,
        /// Number of expected artifacts.
        artifact_count: usize,
    },
    /// Scoped hosted visual capture.
    HostedCapture(HostedVisualCaptureDescriptor),
    /// Redacted support diagnostics bundle setup.
    SupportDiagnostics(SupportDiagnosticsBuilder),
    /// Roadmap visual capture work.
    RoadmapWork {
        /// Product-safe roadmap reason.
        reason: String,
    },
}

impl VisualCaptureRequest {
    /// Validate one visual capture request.
    pub fn validate(&self) -> Result<()> {
        match self {
            Self::AppWindowCapture(request) => request.validate(),
            Self::NativeSnapshotEvidence {
                kind,
                artifact_count,
            } => {
                validate_app_storage_id(kind, "native visual evidence kind")?;
                validate_visual_artifact_count(*artifact_count, "native visual evidence artifact")?;
                Ok(())
            }
            Self::HostedCapture(descriptor) => descriptor.validate(),
            Self::SupportDiagnostics(builder) => builder.validate(),
            Self::RoadmapWork { reason } => {
                validate_app_metadata_text(reason, "visual capture roadmap reason", 160, false)
            }
        }
    }

    /// Privacy-preserving request kind for summaries.
    pub fn summary_kind(&self) -> &'static str {
        match self {
            Self::AppWindowCapture(_) => "app-window-capture",
            Self::NativeSnapshotEvidence { .. } => "native-snapshot-evidence",
            Self::HostedCapture(descriptor) => descriptor.kind().to_text(),
            Self::SupportDiagnostics(_) => "support-diagnostics",
            Self::RoadmapWork { .. } => "roadmap-work",
        }
    }
}

fn validate_visual_artifact_count(count: usize, label: &str) -> Result<()> {
    anyhow::ensure!(count > 0, "{label} count must be greater than zero");
    anyhow::ensure!(
        count <= 10_000,
        "{label} count is too high for generated visual capture readiness"
    );
    Ok(())
}

/// Recommended next implementation action for visual capture handoffs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VisualCaptureNextAction {
    /// Prepare native app-window capture.
    CaptureAppWindow,
    /// Capture native headless/cached/effect evidence.
    CaptureNativeEvidence,
    /// Use scoped WebView element/DOM/media capture.
    CaptureHostedSurface,
    /// Export redacted support diagnostics.
    ExportSupportDiagnostics,
    /// Track roadmap capture work.
    TrackRoadmapWork,
}

/// Checked native-first visual capture handoff for screenshots, thumbnails, and evidence.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VisualCaptureHandoff {
    requests: Vec<VisualCaptureRequest>,
}

impl VisualCaptureHandoff {
    /// Start building a visual capture handoff.
    pub fn builder() -> VisualCaptureHandoffBuilder {
        VisualCaptureHandoffBuilder::new()
    }

    /// Requests covered by this handoff.
    pub fn requests(&self) -> &[VisualCaptureRequest] {
        &self.requests
    }

    /// Number of requests in the handoff.
    pub fn request_count(&self) -> usize {
        self.requests.len()
    }

    /// Whether this handoff includes app-window capture.
    pub fn has_app_window_capture(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, VisualCaptureRequest::AppWindowCapture(_)))
    }

    /// Whether this handoff includes native evidence.
    pub fn has_native_evidence(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, VisualCaptureRequest::NativeSnapshotEvidence { .. }))
    }

    /// Whether this handoff includes hosted capture.
    pub fn has_hosted_capture(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, VisualCaptureRequest::HostedCapture(_)))
    }

    /// Whether this handoff includes support diagnostics.
    pub fn has_support_diagnostics(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, VisualCaptureRequest::SupportDiagnostics(_)))
    }

    /// Whether this handoff includes roadmap work.
    pub fn has_roadmap_work(&self) -> bool {
        self.requests
            .iter()
            .any(|request| matches!(request, VisualCaptureRequest::RoadmapWork { .. }))
    }

    /// First recommended action for a builder or AI agent.
    pub fn next_action(&self) -> VisualCaptureNextAction {
        if self.has_app_window_capture() {
            VisualCaptureNextAction::CaptureAppWindow
        } else if self.has_native_evidence() {
            VisualCaptureNextAction::CaptureNativeEvidence
        } else if self.has_hosted_capture() {
            VisualCaptureNextAction::CaptureHostedSurface
        } else if self.has_support_diagnostics() {
            VisualCaptureNextAction::ExportSupportDiagnostics
        } else {
            VisualCaptureNextAction::TrackRoadmapWork
        }
    }

    /// Validate all handoff requests.
    pub fn validate(&self) -> Result<()> {
        anyhow::ensure!(
            !self.requests.is_empty(),
            "visual capture handoff must include at least one request"
        );
        anyhow::ensure!(
            self.requests.len() <= 32,
            "visual capture handoff cannot include more than 32 requests"
        );
        for request in &self.requests {
            request.validate()?;
        }
        Ok(())
    }

    /// Privacy-preserving summary for logs, tests, and AI-agent traces.
    pub fn to_text(&self) -> String {
        let kinds = self
            .requests
            .iter()
            .map(VisualCaptureRequest::summary_kind)
            .collect::<Vec<_>>()
            .join(", ");
        format!(
            "visual capture handoff: requests={} next_action={:?} app_window={} native_evidence={} hosted_capture={} support_diagnostics={} roadmap_work={} kinds=[{}]",
            self.request_count(),
            self.next_action(),
            self.has_app_window_capture(),
            self.has_native_evidence(),
            self.has_hosted_capture(),
            self.has_support_diagnostics(),
            self.has_roadmap_work(),
            kinds
        )
    }
}

/// Builder for checked visual capture handoffs.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct VisualCaptureHandoffBuilder {
    requests: Vec<VisualCaptureRequest>,
}

impl VisualCaptureHandoffBuilder {
    /// Create an empty visual capture handoff builder.
    pub fn new() -> Self {
        Self {
            requests: Vec::new(),
        }
    }

    /// Add a checked app-window capture request.
    pub fn app_window_capture(mut self, request: AppWindowCaptureRequest) -> Self {
        self.requests
            .push(VisualCaptureRequest::AppWindowCapture(request));
        self
    }

    /// Add an app-window capture builder after checking it.
    pub fn app_window_capture_builder(
        mut self,
        request: AppWindowCaptureRequestBuilder,
    ) -> Result<Self> {
        self.requests.push(VisualCaptureRequest::AppWindowCapture(
            request.build_checked()?,
        ));
        Ok(self)
    }

    /// Add native headless/cached/effect evidence.
    pub fn native_snapshot_evidence(
        mut self,
        kind: impl Into<String>,
        artifact_count: usize,
    ) -> Self {
        self.requests
            .push(VisualCaptureRequest::NativeSnapshotEvidence {
                kind: kind.into(),
                artifact_count,
            });
        self
    }

    /// Add a hosted visual capture descriptor.
    pub fn hosted_capture(mut self, descriptor: HostedVisualCaptureDescriptor) -> Self {
        self.requests
            .push(VisualCaptureRequest::HostedCapture(descriptor));
        self
    }

    /// Add redacted support diagnostics setup.
    pub fn support_diagnostics(mut self, builder: SupportDiagnosticsBuilder) -> Self {
        self.requests
            .push(VisualCaptureRequest::SupportDiagnostics(builder));
        self
    }

    /// Add roadmap visual capture work.
    pub fn roadmap_work(mut self, reason: impl Into<String>) -> Self {
        self.requests.push(VisualCaptureRequest::RoadmapWork {
            reason: reason.into(),
        });
        self
    }

    /// Validate the handoff without consuming the builder.
    pub fn validate(&self) -> Result<()> {
        self.as_handoff().validate()
    }

    /// Build a checked visual capture handoff.
    pub fn build_checked(self) -> Result<VisualCaptureHandoff> {
        let handoff = self.as_handoff();
        handoff.validate()?;
        Ok(handoff)
    }

    fn as_handoff(&self) -> VisualCaptureHandoff {
        VisualCaptureHandoff {
            requests: self.requests.clone(),
        }
    }
}

/// Read-only snapshot of app runtime state for startup gates and agent audits.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppRuntimeSnapshot {
    process_id: ProcessId,
    uptime: Duration,
    window_count: usize,
    keep_alive_without_windows: bool,
    quit_cleanup_timeout: Duration,
    quitting: bool,
    network_status: NetworkStatus,
    power: SystemPowerSnapshot,
    theme: NativeThemeSnapshot,
}

impl AppRuntimeSnapshot {
    /// Process identifier used for capability checks.
    pub fn process_id(&self) -> ProcessId {
        self.process_id
    }

    /// Duration since the Kael app state was created.
    pub fn uptime(&self) -> Duration {
        self.uptime
    }

    /// Number of open Kael windows.
    pub fn window_count(&self) -> usize {
        self.window_count
    }

    /// Whether the app is configured to stay alive without windows.
    pub fn keep_alive_without_windows(&self) -> bool {
        self.keep_alive_without_windows
    }

    /// Timeout for futures registered with `on_app_quit`.
    pub fn quit_cleanup_timeout(&self) -> Duration {
        self.quit_cleanup_timeout
    }

    /// Whether app shutdown has begun.
    pub fn is_quitting(&self) -> bool {
        self.quitting
    }

    /// Current network connectivity status.
    pub fn network_status(&self) -> NetworkStatus {
        self.network_status
    }

    /// Current power, idle, and reduce-motion state.
    pub fn power(&self) -> &SystemPowerSnapshot {
        &self.power
    }

    /// Current native theme and accessibility state.
    pub fn theme(&self) -> NativeThemeSnapshot {
        self.theme
    }

    /// Whether the snapshot represents a background/tray-style runtime.
    pub fn is_background_runtime(&self) -> bool {
        self.keep_alive_without_windows && self.window_count == 0
    }
}

/// Builder for checked app runtime snapshot queries.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AppRuntimeSnapshotQueryBuilder {
    require_not_quitting: bool,
    require_window: bool,
    require_background_runtime: bool,
    allow_background_runtime: bool,
    require_network_online: bool,
}

impl Default for AppRuntimeSnapshotQueryBuilder {
    fn default() -> Self {
        Self {
            require_not_quitting: false,
            require_window: false,
            require_background_runtime: false,
            allow_background_runtime: true,
            require_network_online: false,
        }
    }
}

impl AppRuntimeSnapshotQueryBuilder {
    /// Create a permissive runtime snapshot query.
    pub fn new() -> Self {
        Self::default()
    }

    /// Require shutdown not to have begun.
    pub fn require_not_quitting(mut self) -> Self {
        self.require_not_quitting = true;
        self
    }

    /// Require at least one open Kael window.
    pub fn require_window(mut self) -> Self {
        self.require_window = true;
        self.allow_background_runtime = false;
        self
    }

    /// Require a tray/agent-style runtime with no open windows.
    pub fn require_background_runtime(mut self) -> Self {
        self.require_background_runtime = true;
        self.allow_background_runtime = true;
        self
    }

    /// Allow a no-window background runtime when validating startup state.
    pub fn allow_background_runtime(mut self) -> Self {
        self.allow_background_runtime = true;
        self
    }

    /// Require the app to be online before starting network-dependent work.
    pub fn require_network_online(mut self) -> Self {
        self.require_network_online = true;
        self
    }

    /// Whether this query requires shutdown not to have begun.
    pub fn requires_not_quitting(&self) -> bool {
        self.require_not_quitting
    }

    /// Whether this query requires at least one open window.
    pub fn requires_window(&self) -> bool {
        self.require_window
    }

    /// Whether this query requires a background runtime.
    pub fn requires_background_runtime(&self) -> bool {
        self.require_background_runtime
    }

    /// Whether no-window background runtime is allowed.
    pub fn allows_background_runtime(&self) -> bool {
        self.allow_background_runtime
    }

    /// Whether this query requires online network status.
    pub fn requires_network_online(&self) -> bool {
        self.require_network_online
    }

    /// Validate a runtime snapshot against this query.
    pub fn validate_snapshot(&self, snapshot: &AppRuntimeSnapshot) -> Result<()> {
        anyhow::ensure!(
            !(self.require_window && self.require_background_runtime),
            "runtime query cannot require both a window and background runtime"
        );
        anyhow::ensure!(
            !self.require_not_quitting || !snapshot.is_quitting(),
            "app shutdown has already begun"
        );
        anyhow::ensure!(
            !self.require_window || snapshot.window_count() > 0,
            "runtime has no open windows"
        );
        anyhow::ensure!(
            !self.require_background_runtime || snapshot.is_background_runtime(),
            "runtime is not a background runtime"
        );
        anyhow::ensure!(
            self.allow_background_runtime
                || snapshot.window_count() > 0
                || !snapshot.is_background_runtime(),
            "runtime is background-only"
        );
        anyhow::ensure!(
            !self.require_network_online || snapshot.network_status() == NetworkStatus::Online,
            "network is offline"
        );
        Ok(())
    }
}

/// Builder for a biometric authentication prompt.
#[derive(Debug, Clone)]
pub struct BiometricAuthBuilder {
    reason: String,
    require_available: bool,
}

impl BiometricAuthBuilder {
    /// Create a biometric prompt with the user-facing reason shown by the OS.
    pub fn new(reason: impl Into<String>) -> Self {
        Self {
            reason: reason.into(),
            require_available: true,
        }
    }

    /// Create a common vault-unlock biometric prompt.
    pub fn unlock_vault() -> Self {
        Self::new("Unlock your vault")
    }

    /// Create a common payment-approval biometric prompt.
    pub fn approve_payment() -> Self {
        Self::new("Approve payment")
    }

    /// Allow forwarding the prompt to the platform even when Kael cannot detect
    /// biometric availability up front.
    pub fn allow_unavailable(mut self) -> Self {
        self.require_available = false;
        self
    }

    /// Return the configured prompt reason.
    pub fn reason(&self) -> &str {
        &self.reason
    }

    /// Return whether this prompt requires an available biometric method.
    pub fn requires_available(&self) -> bool {
        self.require_available
    }

    /// Validate the prompt copy before asking the platform to show UI.
    pub fn validate(&self) -> Result<()> {
        anyhow::ensure!(
            !self.reason.trim().is_empty(),
            "biometric authentication reason cannot be empty"
        );
        anyhow::ensure!(
            self.reason == self.reason.trim(),
            "biometric authentication reason cannot have leading or trailing whitespace"
        );
        anyhow::ensure!(
            self.reason.len() <= 256,
            "biometric authentication reason cannot be longer than 256 bytes"
        );
        anyhow::ensure!(
            !self.reason.chars().any(char::is_control),
            "biometric authentication reason cannot contain control characters"
        );
        Ok(())
    }

    /// Build the validated prompt reason and availability policy.
    pub fn build_checked(self) -> Result<(String, bool)> {
        self.validate()?;
        Ok((self.reason, self.require_available))
    }
}

/// Snapshot returned when requesting a biometric prompt.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BiometricAuthRequest {
    status: BiometricStatus,
    prompted: bool,
    reason: String,
}

impl BiometricAuthRequest {
    /// The biometric availability observed before the request.
    pub fn status(&self) -> BiometricStatus {
        self.status
    }

    /// Whether Kael forwarded the prompt to the platform.
    pub fn prompted(&self) -> bool {
        self.prompted
    }

    /// The validated reason used for the prompt.
    pub fn reason(&self) -> &str {
        &self.reason
    }

    /// Whether biometric authentication was available before the request.
    pub fn available(&self) -> bool {
        matches!(self.status, BiometricStatus::Available(_))
    }

    /// The available biometric method, if one was detected.
    pub fn kind(&self) -> Option<BiometricKind> {
        match self.status {
            BiometricStatus::Available(kind) => Some(kind),
            BiometricStatus::Unavailable => None,
        }
    }

    /// Human-readable, deterministic summary for fallback UI, logs, and agents.
    pub fn to_text(&self) -> String {
        let status = match self.status {
            BiometricStatus::Available(BiometricKind::TouchId) => "available Touch ID",
            BiometricStatus::Available(BiometricKind::WindowsHello) => "available Windows Hello",
            BiometricStatus::Available(BiometricKind::Fingerprint) => "available fingerprint",
            BiometricStatus::Unavailable => "unavailable",
        };
        let prompt = if self.prompted {
            "prompted"
        } else {
            "not prompted"
        };
        format!(
            "biometric authentication {status}, {prompt}, reason '{}'",
            self.reason
        )
    }
}

type NetworkStatusCallback = Box<dyn FnMut(NetworkStatus, &mut App)>;
type NetworkTransitionCallback = Box<dyn FnMut(&mut App)>;

/// Snapshot of system state relevant to adaptive rendering and background work.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SystemPowerSnapshot {
    power_mode: PowerMode,
    reduce_motion: bool,
    idle_time: Option<Duration>,
}

impl SystemPowerSnapshot {
    /// Current OS power policy.
    pub fn power_mode(&self) -> PowerMode {
        self.power_mode
    }

    /// Whether the OS reduce-motion accessibility preference is enabled.
    pub fn reduce_motion(&self) -> bool {
        self.reduce_motion
    }

    /// Duration since the last user input event, when the platform exposes it.
    pub fn idle_time(&self) -> Option<Duration> {
        self.idle_time
    }

    /// Whether apps should prefer lower CPU/GPU work for this snapshot.
    pub fn should_reduce_work(&self) -> bool {
        self.reduce_motion || matches!(self.power_mode, PowerMode::LowPower)
    }

    /// Stable summary for adaptive rendering and background-work decisions.
    pub fn to_text(&self) -> String {
        format!(
            "system power: mode {}, reduce motion {}, idle known {}, reduce work {}",
            self.power_mode.to_text(),
            self.reduce_motion(),
            self.idle_time().is_some(),
            self.should_reduce_work()
        )
    }

    /// Evaluate this snapshot against an idle policy.
    pub fn evaluate_idle(&self, policy: &SystemIdlePolicy) -> SystemIdleEvaluation {
        policy.evaluate(self)
    }
}

