/// A checked request in an embedded-hosted-view workflow.
#[derive(Clone, Debug)]
pub enum EmbeddedHostedViewRequest {
    /// Compose a pane from native layout, tabs, routes, splitters, or surfaces.
    NativePaneComposition {
        /// Stable pane identifier.
        pane_id: SharedString,
    },
    /// Bound an expensive native preview, inspector, or document pane.
    CachedDeferredPane {
        /// Stable pane identifier.
        pane_id: SharedString,
    },
    /// Place a floating inspector, palette, or preview pane/window.
    FloatingPane {
        /// Stable pane identifier.
        pane_id: SharedString,
    },
    /// Create an explicit hosted WebView pane with a known policy profile.
    HostedPane {
        /// Stable hosted pane identifier.
        pane_id: SharedString,
        /// Hosted-pane WebView policy profile.
        profile: EmbeddedHostedPaneProfile,
    },
    /// Keep a pane-scoped controller for navigation, focus, zoom, find, print, downloads, and bridges.
    ControllerOwnership {
        /// Stable controller owner identifier.
        pane_id: SharedString,
    },
    /// Check GPU, pointer, and WebView support before promising embedded hosted-view parity.
    SupportPreflight,
    /// Track missing pane ownership, docking, lifecycle, or restoration templates.
    RoadmapWork {
        /// Content-safe roadmap reason for missing embedded-view capability.
        reason: SharedString,
    },
}

impl EmbeddedHostedViewRequest {
    /// Return the next native or hosted action implied by this request.
    pub fn next_action(&self) -> EmbeddedHostedViewNextAction {
        match self {
            Self::NativePaneComposition { .. } => EmbeddedHostedViewNextAction::ComposeNativePane,
            Self::CachedDeferredPane { .. } => EmbeddedHostedViewNextAction::BoundExpensivePane,
            Self::FloatingPane { .. } => EmbeddedHostedViewNextAction::PlaceFloatingPane,
            Self::HostedPane { .. } => EmbeddedHostedViewNextAction::CreateHostedPane,
            Self::ControllerOwnership { .. } => EmbeddedHostedViewNextAction::AttachController,
            Self::SupportPreflight => EmbeddedHostedViewNextAction::PreflightSupport,
            Self::RoadmapWork { .. } => EmbeddedHostedViewNextAction::TrackHostedViewRoadmap,
        }
    }

    /// Validate this request without creating UI.
    pub fn validate(&self) -> Result<()> {
        match self {
            Self::NativePaneComposition { pane_id }
            | Self::CachedDeferredPane { pane_id }
            | Self::FloatingPane { pane_id }
            | Self::HostedPane { pane_id, .. }
            | Self::ControllerOwnership { pane_id } => {
                validate_app_storage_id(pane_id, "embedded hosted view pane id")
            }
            Self::SupportPreflight => Ok(()),
            Self::RoadmapWork { reason } => validate_app_metadata_text(
                reason,
                "embedded hosted view roadmap reason",
                256,
                false,
            ),
        }
    }
}

