    /// Show an OS notification.
    pub fn show_notification(&self, title: &str, body: &str) -> Result<()> {
        match self
            .permission_broker
            .check(self.current_process_id, &Capability::Notification)
        {
            PermissionResult::Granted => self.platform.show_notification(title, body),
            PermissionResult::Denied => Err(anyhow!("capability denied: Notification")),
            PermissionResult::Prompt => Err(anyhow!("capability prompt required: Notification")),
        }
    }

    /// Validate and show a plain OS notification.
    pub fn show_notification_checked(
        &self,
        title: impl Into<String>,
        body: impl Into<String>,
    ) -> Result<()> {
        self.show_desktop_notification(NotificationBuilder::new(title, body))
    }

    /// Show an OS notification using the builder-friendly notification API.
    ///
    /// Use [`Self::show_desktop_notification_with_actions`] when the notification
    /// includes action buttons.
    pub fn show_desktop_notification(&self, notification: NotificationBuilder) -> Result<()> {
        notification.validate()?;

        if notification.has_actions() {
            return Err(anyhow!(
                "notification has action buttons; use show_desktop_notification_with_actions to handle them"
            ));
        }

        let (title, body, _) = notification.into_parts();
        self.show_notification(&title, &body)
    }

    /// Show an OS notification with action buttons.
    pub fn show_notification_with_actions(
        &self,
        title: &str,
        body: &str,
        actions: &[NotificationAction],
        callback: impl FnMut(String) + 'static,
    ) -> Result<()> {
        match self
            .permission_broker
            .check(self.current_process_id, &Capability::Notification)
        {
            PermissionResult::Granted => self.platform.show_notification_with_actions(
                title,
                body,
                actions,
                Box::new(callback),
            ),
            PermissionResult::Denied => Err(anyhow!("capability denied: Notification")),
            PermissionResult::Prompt => Err(anyhow!("capability prompt required: Notification")),
        }
    }

    /// Show an OS notification using the builder-friendly action API.
    pub fn show_desktop_notification_with_actions(
        &self,
        notification: NotificationBuilder,
        callback: impl FnMut(String) + 'static,
    ) -> Result<()> {
        notification.validate()?;

        let (title, body, actions) = notification.into_parts();
        if actions.is_empty() {
            return self.show_notification(&title, &body);
        }

        self.show_notification_with_actions(&title, &body, &actions, callback)
    }

    /// Show an OS notification and route action callbacks through typed events.
    pub fn show_desktop_notification_with_action_router(
        &self,
        notification: NotificationBuilder,
        mut callback: impl FnMut(NotificationActionEvent) + 'static,
    ) -> Result<()> {
        notification.validate()?;
        let known_action_ids = notification
            .action_ids()
            .map(str::to_string)
            .collect::<Vec<_>>();

        let (title, body, actions) = notification.into_parts();
        if actions.is_empty() {
            return self.show_notification(&title, &body);
        }

        self.show_notification_with_actions(&title, &body, &actions, move |action_id| {
            let event = if known_action_ids.iter().any(|known| known == &action_id) {
                NotificationActionEvent::Known(action_id)
            } else {
                NotificationActionEvent::Unknown(action_id)
            };
            callback(event);
        })
    }

    /// Validate a notification flow and required capabilities without dispatching it.
    pub fn notification_flow_handoff_checked(
        &self,
        flow: NotificationFlowHandoffBuilder,
    ) -> Result<NotificationFlowHandoff> {
        let handoff = flow.build_checked()?;
        match self
            .permission_broker
            .check(self.current_process_id, &Capability::Notification)
        {
            PermissionResult::Granted => {}
            PermissionResult::Denied => return Err(anyhow!("capability denied: Notification")),
            PermissionResult::Prompt => {
                return Err(anyhow!("capability prompt required: Notification"));
            }
        }
        if let Some(shell_targets) = handoff.shell_targets() {
            if shell_targets.requires_open_external_url() {
                match self
                    .permission_broker
                    .check(self.current_process_id, &Capability::OpenExternalUrl)
                {
                    PermissionResult::Granted => {}
                    PermissionResult::Denied => {
                        return Err(anyhow!("capability denied: OpenExternalUrl"));
                    }
                    PermissionResult::Prompt => {
                        return Err(anyhow!("capability prompt required: OpenExternalUrl"));
                    }
                }
            }
            if shell_targets.requires_shell_execute() {
                match self
                    .permission_broker
                    .check(self.current_process_id, &Capability::ShellExecute)
                {
                    PermissionResult::Granted => {}
                    PermissionResult::Denied => {
                        return Err(anyhow!("capability denied: ShellExecute"));
                    }
                    PermissionResult::Prompt => {
                        return Err(anyhow!("capability prompt required: ShellExecute"));
                    }
                }
            }
        }
        Ok(handoff)
    }

    /// Validate a notification action follow-up and required capabilities without dispatching it.
    pub fn notification_action_follow_up_checked(
        &self,
        follow_up: NotificationActionFollowUpBuilder,
    ) -> Result<NotificationActionFollowUpPlan> {
        let plan = follow_up.build_checked()?;
        if let Some(shell_targets) = plan.shell_targets() {
            if shell_targets.requires_open_external_url() {
                match self
                    .permission_broker
                    .check(self.current_process_id, &Capability::OpenExternalUrl)
                {
                    PermissionResult::Granted => {}
                    PermissionResult::Denied => {
                        return Err(anyhow!("capability denied: OpenExternalUrl"));
                    }
                    PermissionResult::Prompt => {
                        return Err(anyhow!("capability prompt required: OpenExternalUrl"));
                    }
                }
            }
            if shell_targets.requires_shell_execute() {
                match self
                    .permission_broker
                    .check(self.current_process_id, &Capability::ShellExecute)
                {
                    PermissionResult::Granted => {}
                    PermissionResult::Denied => {
                        return Err(anyhow!("capability denied: ShellExecute"));
                    }
                    PermissionResult::Prompt => {
                        return Err(anyhow!("capability prompt required: ShellExecute"));
                    }
                }
            }
        }
        Ok(plan)
    }

