    /// Compute window bounds from a desired size and a semantic position.
    pub fn compute_window_bounds(
        &self,
        size: Size<Pixels>,
        position: &WindowPosition,
    ) -> Bounds<Pixels> {
        let displays = self.platform.displays();
        let primary = self.platform.primary_display();
        crate::platform::window_positioner::compute_window_bounds(
            size,
            position,
            &displays,
            primary.as_ref(),
        )
    }

    /// Resolve a builder-friendly placement into concrete screen bounds.
    pub fn resolve_window_placement(
        &self,
        placement: WindowPlacementBuilder,
    ) -> Result<WindowPlacement> {
        placement.validate()?;
        let bounds = self.compute_window_bounds(placement.size, &placement.position);
        let center = bounds.center();
        let display_id = self
            .displays()
            .iter()
            .find(|display| display.bounds().contains(&center))
            .map(|display| display.id());

        Ok(WindowPlacement {
            size: placement.size,
            position: placement.position,
            bounds,
            display_id,
        })
    }

    /// Resolve tray-panel placement using tray icon bounds when available.
    pub fn resolve_tray_panel_placement_checked(
        &self,
        placement: TrayPanelPlacementBuilder,
    ) -> Result<WindowPlacement> {
        placement.validate()?;
        let placement = if let Some(tray_bounds) = self.tray_icon_bounds() {
            WindowPlacementBuilder::new(placement.size).tray_center(tray_bounds)
        } else {
            anyhow::ensure!(
                !placement.requires_tray_icon_bounds(),
                "tray icon bounds are unavailable"
            );
            WindowPlacementBuilder {
                size: placement.size,
                position: placement.fallback_position,
            }
        };
        self.resolve_window_placement(placement)
    }

