    /// Validates and dispatches an app-owned deep link through runtime handlers.
    pub fn dispatch_deep_link_checked(&self, url: impl Into<String>) -> Result<bool> {
        let request = OpenRequest::try_parse(url)?;
        anyhow::ensure!(
            matches!(request.kind(), OpenRequestKind::DeepLink { .. }),
            "URL must be an app-owned deep link: {}",
            request.raw()
        );
        self.deep_link_registry.try_handle(request.raw())
    }

