    struct TestDeepLinkHandler {
        scheme: &'static str,
        hits: Arc<Mutex<Vec<String>>>,
    }

    impl DeepLinkHandler for TestDeepLinkHandler {
        fn scheme(&self) -> &str {
            self.scheme
        }

        fn handle(&self, url: &str) {
            self.hits.lock().unwrap().push(url.to_string());
        }
    }

    #[test]
    fn test_gpui_borrow() {
        let cx = TestAppContext::single();
        let observation_count = Rc::new(RefCell::new(0));

        let state = cx.update(|cx| {
            let state = cx.new(|_| false);
            cx.observe(&state, {
                let observation_count = observation_count.clone();
                move |_, _| {
                    let mut count = observation_count.borrow_mut();
                    *count += 1;
                }
            })
            .detach();

            state
        });

        cx.update(|cx| {
            // Calling this like this so that we don't clobber the borrow_mut above
            *std::borrow::BorrowMut::borrow_mut(&mut state.as_mut(cx)) = true;
        });

        cx.update(|cx| {
            state.write(cx, false);
        });

        assert_eq!(*observation_count.borrow(), 2);
    }

    #[test]
    fn test_open_url_dispatch_multiplexes_observers_and_deep_links() {
        let cx = TestAppContext::single();
        let batch_urls = Rc::new(RefCell::new(Vec::new()));
        let single_urls = Rc::new(RefCell::new(Vec::new()));
        let batch_requests = Rc::new(RefCell::new(Vec::new()));
        let single_requests = Rc::new(RefCell::new(Vec::new()));
        let deep_link_urls = Rc::new(RefCell::new(Vec::new()));
        let runtime_hits = Arc::new(Mutex::new(Vec::new()));

        cx.app.on_open_urls({
            let batch_urls = batch_urls.clone();
            move |urls| {
                batch_urls.borrow_mut().push(urls);
            }
        });

        cx.app.on_open_url({
            let single_urls = single_urls.clone();
            move |url, _| {
                single_urls.borrow_mut().push(url);
            }
        });

        cx.app.on_open_requests({
            let batch_requests = batch_requests.clone();
            move |requests| {
                batch_requests.borrow_mut().push(requests);
            }
        });

        cx.app.on_open_request({
            let single_requests = single_requests.clone();
            move |request, _| {
                single_requests.borrow_mut().push(request);
            }
        });

        cx.app.on_deep_link("myapp", {
            let deep_link_urls = deep_link_urls.clone();
            move |url, _| {
                deep_link_urls.borrow_mut().push(url);
            }
        });

        let route_urls = Rc::new(RefCell::new(Vec::new()));
        cx.app
            .deep_links_checked(DeepLinkRouterBuilder::new().route("myapp", {
                let route_urls = route_urls.clone();
                move |url, _| {
                    route_urls.borrow_mut().push(url);
                }
            }))
            .unwrap();

        cx.update(|app| {
            app.register_deep_link_handler(Box::new(TestDeepLinkHandler {
                scheme: "myapp",
                hits: runtime_hits.clone(),
            }));
        });

        cx.simulate_open_urls(&[
            "myapp://settings",
            "https://example.com/help",
            "file:///tmp/Project%20Plan.kael",
        ]);

        assert_eq!(
            batch_urls.borrow().clone(),
            vec![vec![
                "myapp://settings".to_string(),
                "https://example.com/help".to_string(),
                "file:///tmp/Project%20Plan.kael".to_string(),
            ]]
        );
        assert_eq!(
            single_urls.borrow().clone(),
            vec![
                "myapp://settings".to_string(),
                "https://example.com/help".to_string(),
                "file:///tmp/Project%20Plan.kael".to_string(),
            ]
        );
        assert_eq!(batch_requests.borrow().len(), 1);
        assert_eq!(
            batch_requests.borrow()[0]
                .iter()
                .map(|request| request.kind().clone())
                .collect::<Vec<_>>(),
            vec![
                OpenRequestKind::DeepLink {
                    scheme: "myapp".to_string()
                },
                OpenRequestKind::Url {
                    scheme: "https".to_string()
                },
                OpenRequestKind::File {
                    path: PathBuf::from("/tmp/Project Plan.kael")
                },
            ]
        );
        assert_eq!(
            single_requests
                .borrow()
                .iter()
                .filter_map(|request| request.scheme().map(str::to_string))
                .collect::<Vec<_>>(),
            vec!["myapp", "https", "file"]
        );
        assert_eq!(
            single_requests.borrow()[2].file_path(),
            Some(std::path::Path::new("/tmp/Project Plan.kael"))
        );
        assert!(single_requests.borrow()[0].is_deep_link());
        assert!(single_requests.borrow()[1].is_url());
        assert!(single_requests.borrow()[2].is_file());
        assert_eq!(single_requests.borrow()[0].kind().key(), "deep-link");
        assert_eq!(
            single_requests.borrow()[0].to_text(),
            "open request: kind deep-link, scheme true, file false, deep-link true, url false, unknown false"
        );
        assert_eq!(
            single_requests.borrow()[1].to_text(),
            "open request: kind url, scheme true, file false, deep-link false, url true, unknown false"
        );
        assert_eq!(
            single_requests.borrow()[2].to_text(),
            "open request: kind file, scheme true, file true, deep-link false, url false, unknown false"
        );
        assert!(!single_requests.borrow()[0].to_text().contains("myapp"));
        assert!(!single_requests.borrow()[1].to_text().contains("https"));
        assert!(
            !single_requests.borrow()[2]
                .to_text()
                .contains("Project Plan")
        );
        assert_eq!(
            deep_link_urls.borrow().clone(),
            vec!["myapp://settings".to_string()]
        );
        assert_eq!(
            route_urls.borrow().clone(),
            vec!["myapp://settings".to_string()]
        );
        assert_eq!(
            runtime_hits.lock().unwrap().clone(),
            vec!["myapp://settings".to_string()]
        );
        assert!(OpenRequest::try_parse("").is_err());
        assert!(OpenRequest::try_parse("bad\nrequest").is_err());
        assert!(OpenRequest::try_parse("x".repeat(MAX_OPEN_REQUEST_BYTES + 1)).is_err());
    }

    #[test]
    fn panicking_open_observers_are_restored_and_do_not_block_peers() {
        let cx = TestAppContext::single();
        let counts = Rc::new(RefCell::new([0usize; 5]));

        cx.app.on_open_urls(|_| panic!("batch URL observer panic"));
        cx.app.on_open_urls({
            let counts = counts.clone();
            move |_| counts.borrow_mut()[0] += 1
        });
        cx.app
            .on_open_requests(|_| panic!("batch request observer panic"));
        cx.app.on_open_requests({
            let counts = counts.clone();
            move |_| counts.borrow_mut()[1] += 1
        });
        cx.app
            .on_deep_link("MYAPP", |_, _| panic!("deep-link observer panic"));
        cx.app.on_deep_link("myapp", {
            let counts = counts.clone();
            move |_, _| counts.borrow_mut()[2] += 1
        });
        cx.app
            .on_open_url(|_, _| panic!("single URL observer panic"));
        cx.app.on_open_url({
            let counts = counts.clone();
            move |_, _| counts.borrow_mut()[3] += 1
        });
        cx.app
            .on_open_request(|_, _| panic!("single request observer panic"));
        cx.app.on_open_request({
            let counts = counts.clone();
            move |_, _| counts.borrow_mut()[4] += 1
        });

        cx.simulate_open_urls(&["myapp:settings"]);
        cx.simulate_open_urls(&["MYAPP:again"]);
        assert_eq!(*counts.borrow(), [2; 5]);
    }

    #[test]
    fn platform_open_batches_are_bounded_before_observer_dispatch() {
        let cx = TestAppContext::single();
        let observed = Rc::new(RefCell::new(Vec::new()));
        cx.app.on_open_urls({
            let observed = observed.clone();
            move |urls| observed.borrow_mut().push(urls.len())
        });

        let mut urls = (0..MAX_PLATFORM_OPEN_REQUESTS + 20)
            .map(|index| format!("myapp:item-{index}"))
            .collect::<Vec<_>>();
        urls.insert(0, "bad\nrequest".to_string());
        urls.insert(0, "x".repeat(MAX_OPEN_REQUEST_BYTES + 1));
        cx.update(|app| app.handle_open_urls(urls));

        assert_eq!(*observed.borrow(), vec![MAX_PLATFORM_OPEN_REQUESTS - 2]);
    }

    #[test]
    fn open_request_route_plan_routes_files_deep_links_and_urls() {
        let file = OpenRequestRoutePlanBuilder::new()
            .request("file:///tmp/Project%20Plan.kael")
            .build_checked()
            .unwrap();
        assert_eq!(
            file.next_action(),
            OpenRequestRouteNextAction::OpenFilePaths
        );
        assert!(file.can_route_immediately());
        assert_eq!(file.file_count(), 1);
        assert_eq!(
            file.to_text(),
            "open request route plan: requests 1, files 1, deep links 0, external urls 0, unknown 0, registered deep links 0, native route false, hosted bridge false, allow external false, allow files true, next action open-file-paths"
        );
        assert!(!file.to_text().contains("Project Plan"));

        let deep_link = OpenRequestRoutePlanBuilder::new()
            .request("myapp://settings/account")
            .registered_deep_link_scheme("myapp")
            .build_checked()
            .unwrap();
        assert_eq!(
            deep_link.next_action(),
            OpenRequestRouteNextAction::DispatchDeepLink
        );
        assert!(deep_link.deep_links_registered());
        assert_eq!(deep_link.deep_link_count(), 1);
        assert!(!deep_link.to_text().contains("myapp"));

        let external = OpenRequestRoutePlanBuilder::new()
            .request("https://example.com/help")
            .allow_external_urls()
            .build_checked()
            .unwrap();
        assert_eq!(
            external.next_action(),
            OpenRequestRouteNextAction::OpenExternalUrl
        );
        assert_eq!(external.external_url_count(), 1);
        assert!(!external.to_text().contains("example.com"));
    }

    #[test]
    fn open_request_route_plan_routes_unregistered_or_blocked_requests() {
        let native_route = OpenRequestRoutePlanBuilder::new()
            .request("myapp://settings")
            .native_route("settings")
            .build_checked()
            .unwrap();
        assert_eq!(
            native_route.next_action(),
            OpenRequestRouteNextAction::PushNativeRoute
        );
        assert_eq!(native_route.native_route_id(), Some("settings"));
        assert!(!native_route.deep_links_registered());
        assert!(!native_route.to_text().contains("settings"));

        let hosted = OpenRequestRoutePlanBuilder::new()
            .request("https://example.com/docs")
            .hosted_navigation_bridge("docs-web")
            .build_checked()
            .unwrap();
        assert_eq!(
            hosted.next_action(),
            OpenRequestRouteNextAction::UseHostedNavigationBridge
        );
        assert_eq!(hosted.hosted_navigation_id(), Some("docs-web"));
        assert!(!hosted.allows_external_urls());
        assert!(!hosted.to_text().contains("docs-web"));

        let unknown = OpenRequestRoutePlanBuilder::new()
            .request("not a url")
            .allow_external_urls()
            .build_checked()
            .unwrap();
        assert_eq!(
            unknown.next_action(),
            OpenRequestRouteNextAction::ReviewUnknownRequest
        );
        assert_eq!(unknown.unknown_count(), 1);
        assert!(!unknown.can_route_immediately());
    }

