    #[test]
    fn deep_link_router_builder_validates_routes() {
        assert!(DeepLinkRouterBuilder::new().validate().is_err());
        assert!(
            DeepLinkRouterBuilder::new()
                .route("1bad", |_, _| {})
                .validate()
                .is_err()
        );
        assert!(
            DeepLinkRouterBuilder::new()
                .route("myapp", |_, _| {})
                .route("MYAPP", |_, _| {})
                .validate()
                .is_err()
        );
        let mut oversized = DeepLinkRouterBuilder::new();
        for index in 0..=MAX_DEEP_LINK_ROUTES {
            oversized = oversized.route(format!("route-{index}"), |_, _| {});
        }
        assert!(oversized.validate().is_err());

        let routes = DeepLinkRouterBuilder::new()
            .route("myapp", |_, _| {})
            .route("oauth", |_, _| {});
        assert_eq!(routes.route_count(), 2);
        assert_eq!(routes.schemes(), vec!["myapp", "oauth"]);
        assert_eq!(routes.to_text(), "deep-link routes: 2 schemes");
        assert!(!routes.to_text().contains("myapp"));
        assert!(!routes.to_text().contains("oauth"));
        assert!(routes.validate().is_ok());

        let registration = UrlSchemeRegistrationBuilder::new().schemes(["myapp", "oauth"]);
        let setup = routes.setup_plan(&registration).unwrap();
        assert_eq!(setup.route_count(), 2);
        assert_eq!(setup.registration_scheme_count(), 2);
        assert_eq!(setup.default_handler_scheme_count(), 0);
        assert!(setup.registration_complete());
        assert!(setup.default_handler_complete());
        assert!(setup.all_registered_schemes_handled());
        assert!(!setup.has_gap());
        assert_eq!(
            setup.to_text(),
            "deep-link setup: routes 2, registered 2, default-handler 0, missing registration 0, missing default-handler 0, unhandled registered 0, gap false"
        );
        assert!(!setup.to_text().contains("myapp"));
        assert!(!setup.to_text().contains("oauth"));

        let cx = TestAppContext::single();
        assert!(
            cx.app
                .deep_links_checked(DeepLinkRouterBuilder::new().route("bad scheme", |_, _| {}))
                .is_err()
        );
    }

    #[test]
    fn deep_link_setup_plan_reports_registration_and_default_handler_gaps() {
        let routes = DeepLinkRouterBuilder::new()
            .route("myapp", |_, _| {})
            .route("oauth", |_, _| {});
        let registration = UrlSchemeRegistrationBuilder::new().schemes(["myapp", "extra"]);
        let default_handler = DefaultHandlerPlanBuilder::new("com.example.kael")
            .scheme("myapp")
            .build_checked()
            .unwrap();

        let setup = routes
            .setup_plan_with_default_handler(&registration, &default_handler)
            .unwrap();

        assert_eq!(setup.route_count(), 2);
        assert_eq!(setup.registration_scheme_count(), 2);
        assert_eq!(setup.default_handler_scheme_count(), 1);
        assert_eq!(setup.missing_registration_schemes(), &["oauth".to_string()]);
        assert_eq!(
            setup.missing_default_handler_schemes(),
            &["oauth".to_string()]
        );
        assert_eq!(
            setup.unhandled_registration_schemes(),
            &["extra".to_string()]
        );
        assert_eq!(setup.missing_registration_count(), 1);
        assert_eq!(setup.missing_default_handler_count(), 1);
        assert_eq!(setup.unhandled_registration_count(), 1);
        assert!(!setup.registration_complete());
        assert!(!setup.default_handler_complete());
        assert!(!setup.all_registered_schemes_handled());
        assert!(setup.has_gap());
        assert_eq!(
            setup.to_text(),
            "deep-link setup: routes 2, registered 2, default-handler 1, missing registration 1, missing default-handler 1, unhandled registered 1, gap true"
        );
        assert!(!setup.to_text().contains("oauth"));
        assert!(!setup.to_text().contains("extra"));
    }

    #[test]
    fn deep_link_setup_plan_summary_is_content_safe() {
        let routes = DeepLinkRouterBuilder::new().route("secret-app", |_, _| {});
        let registration = UrlSchemeRegistrationBuilder::new().scheme("other-secret");
        let setup = routes.setup_plan(&registration).unwrap();

        assert!(setup.has_gap());
        assert_eq!(setup.missing_registration_count(), 1);
        assert_eq!(setup.unhandled_registration_count(), 1);
        assert!(!setup.to_text().contains("secret-app"));
        assert!(!setup.to_text().contains("other-secret"));
    }

    #[test]
    fn register_deep_link_handler_checked_validates_runtime_scheme() {
        let cx = TestAppContext::single();
        let hits = Arc::new(Mutex::new(Vec::new()));

        assert!(
            cx.update(|app| {
                app.register_deep_link_handler_checked(Box::new(TestDeepLinkHandler {
                    scheme: "bad scheme",
                    hits: hits.clone(),
                }))
            })
            .is_err()
        );
        assert!(!cx.read(|app| app.dispatch_deep_link("bad scheme://settings")));

        cx.update(|app| {
            app.register_deep_link_handler_checked(Box::new(TestDeepLinkHandler {
                scheme: "myapp",
                hits: hits.clone(),
            }))
        })
        .unwrap();

        assert!(cx.read(|app| app.dispatch_deep_link_checked("myapp://settings").unwrap()));
        assert_eq!(hits.lock().unwrap().clone(), vec!["myapp://settings"]);

        assert!(
            cx.read(|app| app.dispatch_deep_link_checked("https://example.com/settings"))
                .is_err()
        );
        assert!(
            cx.read(|app| app.dispatch_deep_link_checked("bad scheme://settings"))
                .is_err()
        );
        assert_eq!(hits.lock().unwrap().clone(), vec!["myapp://settings"]);
    }

    #[test]
    fn custom_protocol_request_parses_typed_parts() {
        let request = CustomProtocolRequest::parse("app://assets/icons/logo.svg?v=1").unwrap();
        assert_eq!(request.raw_url(), "app://assets/icons/logo.svg?v=1");
        assert_eq!(request.scheme(), "app");
        assert_eq!(request.host(), Some("assets"));
        assert_eq!(request.path(), "/icons/logo.svg");
        assert_eq!(request.query(), Some("v=1"));
        assert_eq!(request.path_segment_count(), 2);
        assert_eq!(
            request.to_text(),
            "custom protocol request: host true, path segments 2, query true"
        );
        assert!(!request.to_text().contains("app://assets"));
        assert!(!request.to_text().contains("assets"));
        assert!(!request.to_text().contains("logo.svg"));
        assert!(!request.to_text().contains("v=1"));

        assert!(CustomProtocolRequest::parse(" https://example.com").is_err());
        assert!(CustomProtocolRequest::parse("https://example.com").is_err());
        assert!(CustomProtocolRequest::parse("javascript:alert(1)").is_err());
        assert!(
            CustomProtocolRequest::parse(format!(
                "app://assets/{}",
                "x".repeat(MAX_CUSTOM_PROTOCOL_URL_BYTES)
            ))
            .is_err()
        );
        assert!(
            CustomProtocolRequest::parse(format!(
                "app://assets/{}",
                vec!["segment"; MAX_CUSTOM_PROTOCOL_PATH_SEGMENTS + 1].join("/")
            ))
            .is_err()
        );
    }

    #[test]
    fn custom_protocol_response_builder_validates_metadata() {
        let response = CustomProtocolResponse::html("<h1>Hello</h1>").unwrap();
        assert_eq!(response.status, 200);
        assert_eq!(response.mime_type, "text/html; charset=utf-8");
        assert_eq!(response.header_count(), 0);
        assert_eq!(response.body_len(), 14);
        assert_eq!(
            response.to_text(),
            "custom protocol response: status 200, MIME true, headers 0, body bytes 14"
        );
        assert!(!response.to_text().contains("text/html"));
        assert!(!response.to_text().contains("Hello"));

        let response_summary = CustomProtocolResponseBuilder::new("text/plain")
            .status(201)
            .header("X-Asset-Path", "/private/readme.txt")
            .body("private response body")
            .to_text();
        assert_eq!(
            response_summary,
            "custom protocol response builder: status 201, MIME true, headers 1, body bytes 21"
        );
        assert!(!response_summary.contains("text/plain"));
        assert!(!response_summary.contains("X-Asset-Path"));
        assert!(!response_summary.contains("/private/readme.txt"));
        assert!(!response_summary.contains("private response body"));

        assert!(
            CustomProtocolResponseBuilder::new("text/plain")
                .status(99)
                .build_checked()
                .is_err()
        );
        assert!(
            CustomProtocolResponseBuilder::new("plain")
                .build_checked()
                .is_err()
        );
        assert!(
            CustomProtocolResponseBuilder::new("text /plain")
                .build_checked()
                .is_err()
        );
        assert!(
            CustomProtocolResponseBuilder::new("text//plain")
                .build_checked()
                .is_err()
        );
        assert!(
            CustomProtocolResponseBuilder::new("text/plain")
                .header("Bad Header", "value")
                .build_checked()
                .is_err()
        );
        assert!(
            CustomProtocolResponseBuilder::new("text/plain")
                .header("X-Test", "bad\nvalue")
                .build_checked()
                .is_err()
        );
        let mut too_many_headers = CustomProtocolResponseBuilder::new("text/plain");
        for index in 0..=MAX_CUSTOM_PROTOCOL_RESPONSE_HEADERS {
            too_many_headers = too_many_headers.header(format!("X-Test-{index}"), "value");
        }
        assert!(too_many_headers.build_checked().is_err());
    }

    #[test]
    fn custom_protocol_file_resolver_serves_checked_files() {
        let root =
            std::env::temp_dir().join(format!("kael_custom_protocol_files_{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(root.join("icons")).unwrap();
        fs::write(root.join("index.html"), "<main>Home</main>").unwrap();
        fs::write(root.join("icons").join("logo.svg"), "<svg></svg>").unwrap();

        let resolver = CustomProtocolFileResolver::builder(&root)
            .host("assets")
            .index_file("index.html")
            .cache_control("public, max-age=60")
            .require_existing_root()
            .canonicalize_root()
            .build_checked()
            .unwrap();

        let resolver_summary = resolver.to_text();
        assert_eq!(
            resolver_summary,
            "custom protocol file resolver: root true, host true, index true, cache control true"
        );
        assert!(!resolver_summary.contains(root.to_string_lossy().as_ref()));
        assert!(!resolver_summary.contains("assets"));
        assert!(!resolver_summary.contains("index.html"));
        assert!(!resolver_summary.contains("max-age=60"));

        let request = CustomProtocolRequest::parse("app://assets/icons/logo.svg").unwrap();
        let response = resolver.response(&request).unwrap();
        assert_eq!(response.status, 200);
        assert_eq!(response.mime_type, "image/svg+xml");
        assert_eq!(response.body, b"<svg></svg>".to_vec());
        assert_eq!(
            response.headers,
            vec![(
                "Cache-Control".to_string(),
                "public, max-age=60".to_string()
            )]
        );

        let index = resolver
            .response(&CustomProtocolRequest::parse("app://assets/").unwrap())
            .unwrap();
        assert_eq!(index.mime_type, "text/html; charset=utf-8");
        assert_eq!(index.body, b"<main>Home</main>".to_vec());

        let wrong_host = resolver
            .response(&CustomProtocolRequest::parse("app://other/icons/logo.svg").unwrap())
            .unwrap();
        assert_eq!(wrong_host.status, 404);

        let missing = resolver
            .response(&CustomProtocolRequest::parse("app://assets/missing.txt").unwrap())
            .unwrap();
        assert_eq!(missing.status, 404);

        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn custom_protocol_file_resolver_rejects_unsafe_paths() {
        let root = std::env::temp_dir().join(format!(
            "kael_custom_protocol_escape_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let resolver = CustomProtocolFileResolver::builder(&root)
            .require_existing_root()
            .build_checked()
            .unwrap();

        let builder_summary = CustomProtocolFileResolver::builder(&root)
            .host("assets")
            .index_file("index.html")
            .cache_control("private, max-age=5")
            .canonicalize_root()
            .to_text();
        assert_eq!(
            builder_summary,
            "custom protocol file resolver builder: root true, host true, index true, cache control true, require existing root true, canonicalize root true"
        );
        assert!(!builder_summary.contains(root.to_string_lossy().as_ref()));
        assert!(!builder_summary.contains("assets"));
        assert!(!builder_summary.contains("index.html"));
        assert!(!builder_summary.contains("max-age=5"));

        assert!(
            resolver
                .resolve_path(&CustomProtocolRequest::parse("app://assets/../secret.txt").unwrap())
                .is_err()
        );
        assert!(
            resolver
                .resolve_path(
                    &CustomProtocolRequest::parse("app://assets/%2e%2e/secret.txt").unwrap()
                )
                .is_err()
        );
        assert!(
            CustomProtocolFileResolver::builder("")
                .build_checked()
                .is_err()
        );
        assert!(
            CustomProtocolFileResolver::builder(&root)
                .host("bad host")
                .validate()
                .is_err()
        );
        assert!(
            CustomProtocolFileResolver::builder(&root)
                .index_file("../index.html")
                .validate()
                .is_err()
        );

        let oversized = root.join("oversized.bin");
        fs::File::create(&oversized)
            .unwrap()
            .set_len(MAX_CUSTOM_PROTOCOL_RESPONSE_BYTES as u64 + 1)
            .unwrap();
        assert!(
            resolver
                .response(&CustomProtocolRequest::parse("app://assets/oversized.bin").unwrap())
                .is_err()
        );

        #[cfg(unix)]
        {
            use std::os::unix::fs::symlink;
            let outside = root.with_extension("secret");
            fs::write(&outside, "private").unwrap();
            symlink(&outside, root.join("escape.txt")).unwrap();
            assert!(
                resolver
                    .resolve_path(&CustomProtocolRequest::parse("app://assets/escape.txt").unwrap())
                    .is_err()
            );
            fs::remove_file(outside).unwrap();
        }

        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn custom_protocol_router_builder_validates_routes() {
        assert!(CustomProtocolRouterBuilder::new().validate().is_err());
        let route = CustomProtocolRoute::new("app", |_, _| Ok(CustomProtocolResponse::not_found()));
        assert_eq!(
            route.to_text(),
            "custom protocol route: scheme true, handler true"
        );
        assert!(!route.to_text().contains("app"));

        let router = CustomProtocolRouterBuilder::new()
            .route("private", |_, _| Ok(CustomProtocolResponse::not_found()));
        assert_eq!(router.route_count(), 1);
        assert_eq!(router.to_text(), "custom protocol router: 1 route(s)");
        assert!(!router.to_text().contains("private"));

        assert!(
            CustomProtocolRouterBuilder::new()
                .route("1bad", |_, _| Ok(CustomProtocolResponse::not_found()))
                .validate()
                .is_err()
        );
        let mut oversized = CustomProtocolRouterBuilder::new();
        for index in 0..=MAX_CUSTOM_PROTOCOL_ROUTES {
            oversized = oversized.route(format!("route-{index}"), |_, _| {
                Ok(CustomProtocolResponse::not_found())
            });
        }
        assert!(oversized.validate().is_err());
        assert!(
            CustomProtocolRouterBuilder::new()
                .route("https", |_, _| Ok(CustomProtocolResponse::not_found()))
                .validate()
                .is_err()
        );
        assert!(
            CustomProtocolRouterBuilder::new()
                .route("app", |_, _| Ok(CustomProtocolResponse::not_found()))
                .route("app", |_, _| Ok(CustomProtocolResponse::not_found()))
                .validate()
                .is_err()
        );
    }

