    #[test]
    fn notification_flow_handoff_guides_action_shell_and_attention_flow() {
        let executable = std::env::current_exe().unwrap();
        let builder = NotificationFlowHandoffBuilder::rich(
            NotificationBuilder::new("Export ready", "Open or reveal the export")
                .open_and_dismiss_actions("Open", "Later")
                .tag("export-ready")
                .group("exports"),
        )
        .shell_targets(
            ShellTargetsBuilder::new()
                .url("https://example.com/export-help")
                .reveal_path(&executable)
                .require_existing_paths(),
        )
        .attention(UserAttentionBuilder::informational().reason("export finished"));

        assert!(builder.has_shell_targets());
        assert!(builder.has_attention());
        assert!(builder.validate().is_ok());
        assert_eq!(
            builder.to_text(),
            "notification flow handoff builder: actions true, support notification support: basic true, actions true, urgency true, silent true, tag true, group true, timeout true, shell targets true, attention true"
        );
        assert!(!builder.to_text().contains("Export ready"));
        assert!(!builder.to_text().contains("example.com"));
        assert!(!builder.to_text().contains("export finished"));

        let handoff = builder.build_checked().unwrap();
        assert!(handoff.has_actions());
        assert!(handoff.has_shell_targets());
        assert!(handoff.has_attention());
        assert!(!handoff.requires_fallback());
        assert_eq!(handoff.shell_target_count(), 2);
        assert_eq!(
            handoff.next_action(),
            NotificationFlowNextAction::RequestAttentionThenDispatch
        );
        assert!(handoff.delivery_plan().is_fully_supported());
        assert!(
            handoff
                .shell_targets()
                .unwrap()
                .requires_open_external_url()
        );
        assert!(handoff.shell_targets().unwrap().requires_shell_execute());
        assert!(handoff.attention().unwrap().is_informational());
        assert_eq!(
            handoff.to_text(),
            "notification flow handoff: actions true, fallback false, missing features 0, shell targets 2, attention true, next action request attention then dispatch"
        );
        assert!(!handoff.to_text().contains("Export ready"));
        assert!(!handoff.to_text().contains("example.com"));
        assert!(!handoff.to_text().contains("export finished"));
    }

