    #[test]
    fn shell_targets_builder_validates_and_batches_targets() {
        let executable = std::env::current_exe().unwrap();
        let targets = ShellTargetsBuilder::new()
            .url("https://example.com/docs")
            .reveal_path(&executable)
            .require_existing_paths();

        assert_eq!(targets.len(), 2);
        assert!(!targets.is_empty());
        assert!(targets.contains_url_targets());
        assert!(!targets.contains_path_targets());
        assert!(targets.contains_reveal_targets());
        assert!(targets.requires_existing_paths());
        assert!(!targets.canonicalizes_paths());
        assert_eq!(
            targets.to_text(),
            "shell targets builder: 2 targets, url true, path false, reveal true, existing true, canonicalize false"
        );
        assert!(!targets.to_text().contains("example.com"));
        assert!(
            !targets
                .to_text()
                .contains(&executable.display().to_string())
        );
        assert_eq!(
            targets.configured_targets(),
            &[
                ShellTarget::url("https://example.com/docs"),
                ShellTarget::reveal_path(&executable)
            ]
        );
        assert!(targets.validate().is_ok());
        assert!(ShellTargetsBuilder::new().validate().is_err());
        assert!(
            ShellTargetsBuilder::new()
                .url("javascript:alert(1)")
                .validate()
                .is_err()
        );
        assert!(
            ShellTargetsBuilder::new()
                .url(" https://example.com")
                .validate()
                .is_err()
        );
        assert!(ShellTargetsBuilder::new().path("").validate().is_err());
        assert!(
            ShellTargetsBuilder::new()
                .path("/definitely/not/a/path")
                .require_existing_paths()
                .validate()
                .is_err()
        );
        let built = ShellTargetsBuilder::new()
            .path(&executable)
            .canonicalize_paths()
            .build()
            .unwrap();
        assert_eq!(
            built,
            vec![ShellTarget::path(executable.canonicalize().unwrap())]
        );

        let plan: ShellTargetsPlan = ShellTargetsBuilder::new()
            .url("https://example.com/docs")
            .path(&executable)
            .canonicalize_paths()
            .build_checked()
            .unwrap();
        assert_eq!(plan.len(), 2);
        assert!(!plan.is_empty());
        assert!(plan.requires_existing_paths());
        assert!(plan.canonicalized_paths());
        assert!(plan.contains_url_targets());
        assert!(plan.contains_path_targets());
        assert!(!plan.contains_reveal_targets());
        assert!(plan.requires_open_external_url());
        assert!(plan.requires_shell_execute());
        assert_eq!(
            plan.to_text(),
            "shell targets: 2 targets, url true, path true, reveal false, existing true, canonicalized true"
        );
        assert!(!plan.to_text().contains("example.com"));
        assert!(!plan.to_text().contains(&executable.display().to_string()));
    }

