    #[test]
    fn trash_request_builder_validates_safe_trash_targets() {
        let temp = std::env::temp_dir().join(format!(
            "kael_trash_request_{}_absolute.tmp",
            std::process::id()
        ));
        let relative = PathBuf::from(format!(
            "target/kael_trash_request_{}_relative.tmp",
            std::process::id()
        ));
        let _ = fs::remove_file(&temp);
        let _ = fs::remove_file(&relative);
        fs::create_dir_all(relative.parent().unwrap()).unwrap();
        fs::write(&temp, "trash me").unwrap();
        fs::write(&relative, "trash me too").unwrap();

        let builder = TrashRequestBuilder::new(&temp).canonicalize_path();
        assert!(builder.requires_existing_path());
        assert!(builder.canonicalizes_path());
        assert!(!builder.allows_relative_path());
        assert!(!builder.has_relative_path());
        assert_eq!(
            builder.to_text(),
            "trash request builder: relative false, require existing path true, canonicalize true, allow relative path false"
        );
        assert!(!builder.to_text().contains(&temp.display().to_string()));

        let request = builder.build_checked().unwrap();

        assert_eq!(request.path(), temp.canonicalize().unwrap().as_path());
        assert!(request.requires_existing_path());
        assert!(request.is_canonicalized());
        assert!(!request.allows_relative_path());
        assert_eq!(
            request.display_name(),
            temp.file_name().and_then(|name| name.to_str())
        );
        assert_eq!(request.parent_path(), request.path().parent());
        assert!(request.requires_shell_execute());
        assert_eq!(
            request.to_text(),
            "trash request: display-name true, parent true, require existing path true, canonicalized true, allow relative path false"
        );
        assert!(!request.to_text().contains(&temp.display().to_string()));
        assert!(
            !request
                .to_text()
                .contains(&temp.file_name().unwrap().to_string_lossy().to_string())
        );

        let relative_builder = TrashRequestBuilder::new(&relative).allow_relative_path();
        assert!(relative_builder.has_relative_path());
        assert!(relative_builder.allows_relative_path());
        assert_eq!(
            relative_builder.to_text(),
            "trash request builder: relative true, require existing path true, canonicalize false, allow relative path true"
        );
        assert!(
            !relative_builder
                .to_text()
                .contains(&relative.display().to_string())
        );

        let relative_request = relative_builder.build_checked().unwrap();

        assert_eq!(relative_request.path(), relative.as_path());
        assert!(relative_request.requires_existing_path());
        assert!(!relative_request.is_canonicalized());
        assert!(relative_request.allows_relative_path());
        assert_eq!(
            relative_request.display_name(),
            relative.file_name().and_then(|name| name.to_str())
        );
        assert_eq!(
            relative_request.to_text(),
            "trash request: display-name true, parent true, require existing path true, canonicalized false, allow relative path true"
        );
        assert!(
            !relative_request
                .to_text()
                .contains(&relative.display().to_string())
        );

        let _ = fs::remove_file(&temp);
        let _ = fs::remove_file(&relative);
    }

    #[test]
    fn trash_request_builder_rejects_generated_footguns() {
        let missing = std::env::temp_dir().join(format!(
            "kael_trash_request_{}_missing.tmp",
            std::process::id()
        ));
        let _ = fs::remove_file(&missing);

        assert!(TrashRequestBuilder::new("").validate().is_err());
        assert!(TrashRequestBuilder::new("bad\0path").validate().is_err());
        assert!(TrashRequestBuilder::new("relative.txt").validate().is_err());
        assert!(TrashRequestBuilder::new(Path::new("/")).validate().is_err());
        assert!(TrashRequestBuilder::new(missing).validate().is_err());
    }

