    #[test]
    fn file_association_builder_validates_document_types() {
        let builder = FileAssociationBuilder::new("Markdown")
            .extensions([".md", "markdown", "MD"])
            .mime_type("text/markdown")
            .editor()
            .description("Markdown documents");
        assert_eq!(builder.extension_count(), 2);
        assert_eq!(builder.mime_type_count(), 1);
        assert!(builder.is_editor());
        assert!(builder.has_description());
        assert_eq!(
            builder.to_text(),
            "file association builder: extensions 2, MIME types 1, editor true, description true"
        );
        assert!(!builder.to_text().contains("Markdown"));
        assert!(!builder.to_text().contains("md"));
        assert!(!builder.to_text().contains("text/markdown"));

        let association = builder.build_checked().unwrap();

        assert_eq!(association.name(), "Markdown");
        assert_eq!(
            association.extensions(),
            &["md".to_string(), "markdown".to_string()]
        );
        assert_eq!(association.mime_types(), &["text/markdown".to_string()]);
        assert_eq!(association.role(), FileAssociationRole::Editor);
        assert_eq!(association.description(), Some("Markdown documents"));
        assert_eq!(association.extension_count(), 2);
        assert_eq!(association.mime_type_count(), 1);
        assert!(association.is_editor());
        assert!(association.has_description());
        assert_eq!(
            association.to_text(),
            "file association: extensions 2, MIME types 1, editor true, description true"
        );
        assert!(!association.to_text().contains("Markdown"));
        assert!(!association.to_text().contains("md"));
        assert!(!association.to_text().contains("text/markdown"));

        assert!(
            FileAssociationBuilder::new("")
                .extension("md")
                .validate()
                .is_err()
        );
        assert!(FileAssociationBuilder::new("Empty").validate().is_err());
        assert!(
            FileAssociationBuilder::new("Bad")
                .extension("bad ext")
                .validate()
                .is_err()
        );
        assert!(
            FileAssociationBuilder::new("Bad")
                .mime_type("not a mime")
                .validate()
                .is_err()
        );
        assert!(
            FileAssociationBuilder::new("Bad")
                .description(" bad")
                .extension("bad")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn file_association_set_rejects_duplicate_claims() {
        let builder = FileAssociationSetBuilder::new()
            .association(
                FileAssociationBuilder::new("Markdown")
                    .extension("md")
                    .mime_type("text/markdown")
                    .editor(),
            )
            .association(
                FileAssociationBuilder::new("PDF")
                    .extension("pdf")
                    .mime_type("application/pdf"),
            );

        assert_eq!(builder.association_count(), 2);
        assert_eq!(builder.extension_count(), 2);
        assert_eq!(builder.mime_type_count(), 2);
        assert_eq!(
            builder.to_text(),
            "file association set builder: 2 associations, 2 extensions, 2 MIME types"
        );
        assert!(!builder.to_text().contains("Markdown"));
        assert!(!builder.to_text().contains("PDF"));
        assert!(!builder.to_text().contains("md"));
        assert!(!builder.to_text().contains("application/pdf"));

        let set = builder.build_checked().unwrap();

        assert_eq!(set.associations().len(), 2);
        assert_eq!(set.association_count(), 2);
        assert_eq!(set.extension_count(), 2);
        assert_eq!(set.mime_type_count(), 2);
        assert_eq!(
            set.to_text(),
            "file association set: 2 associations, 2 extensions, 2 MIME types"
        );
        assert!(!set.to_text().contains("Markdown"));
        assert!(!set.to_text().contains("PDF"));
        assert!(!set.to_text().contains("md"));
        assert!(!set.to_text().contains("application/pdf"));
        assert!(set.accepts_extension(".MD"));
        assert!(set.accepts_mime_type("APPLICATION/PDF"));
        assert!(!set.accepts_extension("txt"));
        assert!(FileAssociationSetBuilder::new().validate().is_err());
        assert!(
            FileAssociationSetBuilder::new()
                .association(FileAssociationBuilder::new("One").extension("md"))
                .association(FileAssociationBuilder::new("Two").extension(".MD"))
                .validate()
                .is_err()
        );
        assert!(
            FileAssociationSetBuilder::new()
                .association(FileAssociationBuilder::new("One").mime_type("text/markdown"))
                .association(FileAssociationBuilder::new("Two").mime_type("TEXT/MARKDOWN"))
                .validate()
                .is_err()
        );
    }

