    #[test]
    fn default_handler_plan_builder_validates_runtime_claims() {
        let plan = DefaultHandlerPlanBuilder::new("com.example.kael")
            .app_name("Kael Studio")
            .schemes(["kael", "kael-auth"])
            .file_association(
                FileAssociationBuilder::new("Kael Project")
                    .extension("kaelproj")
                    .mime_type("application/x-kael-project")
                    .editor(),
            )
            .system_scope()
            .require_user_confirmation(true)
            .build_checked()
            .unwrap();

        assert_eq!(plan.app_id(), "com.example.kael");
        assert_eq!(plan.app_name(), Some("Kael Studio"));
        assert_eq!(plan.scope(), DefaultHandlerScope::System);
        assert!(plan.requires_user_confirmation());
        assert_eq!(plan.scheme_count(), 2);
        assert_eq!(plan.file_association_count(), 1);
        assert_eq!(plan.claimed_extensions(), vec!["kaelproj"]);
        assert_eq!(
            plan.claimed_mime_types(),
            vec!["application/x-kael-project"]
        );
        assert!(plan.claims_scheme("KAEL"));
        assert!(plan.claims_extension(".KAELPROJ"));
        assert!(plan.claims_mime_type("APPLICATION/X-KAEL-PROJECT"));
        assert!(!plan.claims_scheme("mailto"));
        assert_eq!(
            plan.to_text(),
            "default handler: app id true, app name true, 2 schemes, 1 file association, extensions 1, MIME types 1, scope system, confirmation required"
        );
        assert!(!plan.to_text().contains("com.example.kael"));
        assert!(!plan.to_text().contains("Kael Studio"));
        assert!(!plan.to_text().contains("kael-auth"));
        assert!(!plan.to_text().contains("kaelproj"));
        assert!(!plan.to_text().contains("application/x-kael-project"));
    }

