    #[test]
    fn file_handling_setup_plan_reports_package_and_default_handler_gaps() {
        let runtime = FileDropIntentBuilder::open_document().extensions(["kaelproj", ".md"]);
        let associations = FileAssociationSetBuilder::new()
            .association(
                FileAssociationBuilder::new("Kael Project")
                    .extension("kaelproj")
                    .mime_type("application/x-kael-project")
                    .editor(),
            )
            .build_checked()
            .unwrap();
        let default_handler = DefaultHandlerPlanBuilder::new("com.example.kael")
            .file_association(
                FileAssociationBuilder::new("Markdown")
                    .extension("md")
                    .mime_type("text/markdown")
                    .editor(),
            )
            .build_checked()
            .unwrap();

        let setup = runtime.setup_plan_with_default_handler(&associations, &default_handler);

        assert_eq!(setup.purpose(), &FileDropPurpose::OpenDocument);
        assert_eq!(setup.path_kind(), FileDropPathKind::FilesOnly);
        assert_eq!(
            setup.runtime_extensions(),
            &["kaelproj".to_string(), "md".to_string()]
        );
        assert_eq!(setup.missing_association_extensions(), &["md".to_string()]);
        assert_eq!(
            setup.missing_default_handler_extensions(),
            &["kaelproj".to_string()]
        );
        assert_eq!(setup.runtime_extension_count(), 2);
        assert_eq!(setup.association_count(), 1);
        assert!(setup.default_handler_checked());
        assert_eq!(setup.default_handler_association_count(), 1);
        assert_eq!(setup.missing_association_extension_count(), 1);
        assert_eq!(setup.missing_default_handler_extension_count(), 1);
        assert!(setup.is_extension_restricted());
        assert!(setup.has_association_gaps());
        assert!(setup.has_default_handler_gaps());
        assert!(!setup.is_ready());
        assert_eq!(
            setup.to_text(),
            "file handling setup: purpose open-document, kind files-only, runtime extensions 2, associations 1, default handler checked true, default handler associations 1, missing associations 1, missing default handlers 1, ready false"
        );
        assert!(!setup.to_text().contains("kaelproj"));
        assert!(!setup.to_text().contains("md"));
        assert!(!setup.to_text().contains("application/x-kael-project"));
        assert!(!setup.to_text().contains("text/markdown"));
    }

    #[test]
    fn file_handling_setup_plan_summary_is_content_safe() {
        let runtime = FileDropIntentBuilder::open_document().extensions(["secretproj"]);
        let associations = FileAssociationSetBuilder::new()
            .association(
                FileAssociationBuilder::new("Other")
                    .extension("othersecret")
                    .mime_type("application/x-other-secret"),
            )
            .build_checked()
            .unwrap();

        let setup = runtime.setup_plan(&associations);

        assert_eq!(
            setup.missing_association_extensions(),
            &["secretproj".to_string()]
        );
        assert!(!setup.default_handler_checked());
        assert_eq!(setup.default_handler_association_count(), 0);
        assert!(!setup.has_default_handler_gaps());
        assert!(setup.has_association_gaps());
        assert!(!setup.is_ready());
        assert_eq!(
            setup.to_text(),
            "file handling setup: purpose open-document, kind files-only, runtime extensions 1, associations 1, default handler checked false, default handler associations 0, missing associations 1, missing default handlers 0, ready false"
        );
        assert!(!setup.to_text().contains("secretproj"));
        assert!(!setup.to_text().contains("othersecret"));
        assert!(!setup.to_text().contains("application/x-other-secret"));
    }

