    #[test]
    fn file_icon_request_builder_validates_native_icon_requests() {
        let existing = std::env::current_exe().unwrap();
        let request = FileIconRequestBuilder::new(&existing)
            .large()
            .require_existing_path()
            .allow_generic_fallback(false)
            .build_checked()
            .unwrap();

        assert_eq!(request.path(), existing.as_path());
        assert_eq!(request.size(), FileIconSize::Large);
        assert_eq!(request.size().pixels(), 64);
        assert_eq!(request.size().key(), "large");
        assert!(request.requires_existing_path());
        assert!(!request.allows_generic_fallback());
        assert!(request.path_exists());
        let existing_summary = request.to_text();
        assert!(existing_summary.contains("file icon request: large 64px"));
        assert!(existing_summary.contains("existing true"));
        assert!(existing_summary.contains("require existing true"));
        assert!(existing_summary.contains("generic fallback false"));
        assert!(!existing_summary.contains(&existing.display().to_string()));

        let planned = FileIconRequestBuilder::new("Report.KAELPROJ")
            .small()
            .build_checked()
            .unwrap();
        assert_eq!(planned.size(), FileIconSize::Small);
        assert_eq!(planned.extension_hint(), Some("kaelproj".to_string()));
        assert!(!planned.path_exists());
        assert_eq!(
            planned.to_text(),
            "file icon request: small 16px, existing false, require existing false, generic fallback true, extension kaelproj"
        );
        assert!(!planned.to_text().contains("Report"));

        let custom = FileIconRequestBuilder::new("Design.fig")
            .custom_size_px(128)
            .build_checked()
            .unwrap();
        assert_eq!(custom.size(), FileIconSize::Custom(128));
        assert_eq!(custom.size().key(), "custom");
    }

