    #[test]
    fn image_icon_asset_handoff_builder_validates_native_asset_workflow() {
        let handoff = ImageIconAssetHandoffBuilder::new()
            .app_icons(
                AppIconSetBuilder::new()
                    .icon(AppIconAssetBuilder::app("assets/app.icns"))
                    .icon(AppIconAssetBuilder::tray("assets/tray.svg").template())
                    .icon(AppIconAssetBuilder::document("assets/document.png").size_px(128)),
            )
            .file_icon(FileIconRequestBuilder::new("Project.kaelproj").large())
            .tray_icon(TrayIconBuilder::png(b"\x89PNG\r\n\x1a\nrest".to_vec()))
            .ui_image()
            .render_image()
            .clipboard_image()
            .canvas_image()
            .print_image()
            .drop_image()
            .hosted_image_island("web-image-editor")
            .roadmap_work("native resize encode pipeline")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 11);
        assert!(handoff.has_app_icons());
        assert!(handoff.has_file_icon_request());
        assert!(handoff.has_tray_icon());
        assert!(handoff.has_native_image_route());
        assert!(handoff.has_hosted_image_island());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            ImageIconAssetNextAction::PrepareAppIconAssets
        );
        assert_eq!(handoff.next_action().key(), "prepare-app-icon-assets");

        let text = handoff.to_text();
        assert!(text.contains("image/icon asset handoff"));
        assert!(text.contains("app-icons:1"));
        assert!(text.contains("file-icon:1"));
        assert!(text.contains("canvas-image:1"));
        assert!(!text.contains("assets/app.icns"));
        assert!(!text.contains("Project.kaelproj"));
        assert!(!text.contains("web-image-editor"));
        assert!(!text.contains("resize encode"));
        assert!(!text.contains("PNG"));
    }

