    #[test]
    fn app_identity_metadata_handoff_builder_validates_full_identity_stack() {
        let manifest = AppPackageManifestBuilder::new(
            AppMetadataBuilder::new("Kael Studio")
                .identifier("com.example.kael")
                .version("1.2.3")
                .support_url("https://example.com/support"),
        )
        .url_schemes(UrlSchemeRegistrationBuilder::new().scheme("kael"))
        .file_associations(
            FileAssociationSetBuilder::new().association(
                FileAssociationBuilder::new("Kael Project")
                    .extension("kaelproj")
                    .mime_type("application/x-kael-project")
                    .editor(),
            ),
        )
        .icons(
            AppIconSetBuilder::new()
                .icon(AppIconAssetBuilder::app("assets/app.icns"))
                .icon(AppIconAssetBuilder::document("assets/document.png").size_px(128)),
        );
        let checked_manifest = manifest.clone().build_checked().unwrap();

        let handoff = AppIdentityMetadataHandoffBuilder::new()
            .metadata(
                AppMetadataBuilder::new("Kael Studio")
                    .identifier("com.example.kael")
                    .version("1.2.3"),
            )
            .package_manifest(manifest)
            .package_readiness(AppPackageReadinessBuilder::new(checked_manifest))
            .url_schemes(UrlSchemeRegistrationBuilder::new().scheme("kael-auth"))
            .file_associations(
                FileAssociationSetBuilder::new().association(
                    FileAssociationBuilder::new("Kael Workspace")
                        .extension("kaelspace")
                        .mime_type("application/x-kael-workspace"),
                ),
            )
            .default_handler(
                DefaultHandlerPlanBuilder::new("com.example.kael")
                    .scheme("kael")
                    .file_association(
                        FileAssociationBuilder::new("Kael Project")
                            .extension("kaelproj")
                            .mime_type("application/x-kael-project"),
                    ),
            )
            .icons(AppIconSetBuilder::new().icon(AppIconAssetBuilder::tray("assets/tray.svg")))
            .window_app_id(WindowAppIdBuilder::new("com.example.kael"))
            .dock_badge(DockBadgeBuilder::count(3))
            .roadmap_work("localized about metadata")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 10);
        assert!(handoff.has_metadata());
        assert!(handoff.has_package_manifest());
        assert!(handoff.has_package_readiness());
        assert!(handoff.has_registration_claims());
        assert!(handoff.has_window_grouping());
        assert!(handoff.has_badge());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            AppIdentityMetadataNextAction::BuildPackageManifest
        );

        let text = handoff.to_text();
        assert!(text.contains("app identity metadata handoff"));
        assert!(text.contains("package-manifest"));
        assert!(!text.contains("Kael Studio"));
        assert!(!text.contains("com.example.kael"));
        assert!(!text.contains("kaelproj"));
        assert!(!text.contains("kael-auth"));
        assert!(!text.contains("localized about metadata"));
    }

