    #[test]
    fn app_identity_metadata_handoff_next_action_covers_routes() {
        let ready_manifest = AppPackageManifestBuilder::new(
            AppMetadataBuilder::new("Kael Studio")
                .identifier("com.example.kael")
                .version("1.2.3"),
        )
        .icons(AppIconSetBuilder::new().icon(AppIconAssetBuilder::app("assets/app.icns")))
        .build_checked()
        .unwrap();

        let cases = [
            (
                AppIdentityMetadataHandoffBuilder::new().package_manifest(
                    AppPackageManifestBuilder::new(
                        AppMetadataBuilder::new("Kael Studio").identifier("com.example.kael"),
                    ),
                ),
                AppIdentityMetadataNextAction::BuildPackageManifest,
            ),
            (
                AppIdentityMetadataHandoffBuilder::new()
                    .package_readiness(AppPackageReadinessBuilder::new(ready_manifest)),
                AppIdentityMetadataNextAction::EvaluatePackageReadiness,
            ),
            (
                AppIdentityMetadataHandoffBuilder::new()
                    .url_schemes(UrlSchemeRegistrationBuilder::new().scheme("kael")),
                AppIdentityMetadataNextAction::PrepareDefaultHandlerRegistration,
            ),
            (
                AppIdentityMetadataHandoffBuilder::new()
                    .window_app_id(WindowAppIdBuilder::new("com.example.kael")),
                AppIdentityMetadataNextAction::ApplyWindowGrouping,
            ),
            (
                AppIdentityMetadataHandoffBuilder::new().dock_badge(DockBadgeBuilder::clear()),
                AppIdentityMetadataNextAction::UpdateDockBadge,
            ),
            (
                AppIdentityMetadataHandoffBuilder::new()
                    .metadata(AppMetadataBuilder::new("Kael Studio")),
                AppIdentityMetadataNextAction::SurfaceMetadata,
            ),
            (
                AppIdentityMetadataHandoffBuilder::new().roadmap_work("store listing generator"),
                AppIdentityMetadataNextAction::TrackRoadmapWork,
            ),
        ];

        for (builder, expected) in cases {
            let handoff = builder.build_checked().unwrap();
            assert_eq!(handoff.next_action(), expected);
        }
    }

