    #[test]
    fn packaging_update_handoff_builder_validates_full_release_stack() {
        let restart_path = std::env::current_exe().unwrap();
        let handoff = PackagingUpdateHandoffBuilder::new()
            .package_readiness(AppPackageReadinessBuilder::new(ready_release_manifest()))
            .distribution_plan(release_distribution_plan())
            .signing_plan(release_signing_plan())
            .update_release(
                AppUpdateReleaseBuilder::new("1.2.4")
                    .channel(AppUpdateChannel::Stable)
                    .download_url("https://example.com/downloads/kael-1.2.4.dmg")
                    .signed(),
            )
            .update_offer(
                AppUpdateOfferPolicyBuilder::stable().cohort_key("install-123"),
                AppUpdateReleaseBuilder::new("1.2.4")
                    .channel(AppUpdateChannel::Stable)
                    .download_url("https://example.com/downloads/kael-1.2.4.dmg")
                    .signed()
                    .rollout_percentage(100),
            )
            .update_state(
                AppUpdateStateBuilder::new("1.2.3")
                    .phase(AppUpdatePhase::Available)
                    .release(
                        AppUpdateReleaseBuilder::new("1.2.4")
                            .download_url("https://example.com/downloads/kael-1.2.4.dmg"),
                    ),
            )
            .crash_reporter(CrashReporterBuilder::new("com.example.kael"))
            .restart_path(RestartPathBuilder::new(restart_path))
            .roadmap_work("store upload backend")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 9);
        assert!(handoff.has_package_readiness());
        assert!(handoff.has_distribution_plan());
        assert!(handoff.has_signing_plan());
        assert!(handoff.has_update_offer());
        assert!(handoff.has_update_state());
        assert!(handoff.has_crash_reporter());
        assert!(handoff.has_restart_path());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            PackagingUpdateNextAction::CheckPackageReadiness
        );

        let text = handoff.to_text();
        assert!(text.contains("packaging update handoff"));
        assert!(text.contains("package-readiness"));
        assert!(text.contains("restart-path"));
        assert!(!text.contains("Kael Studio"));
        assert!(!text.contains("com.example.kael"));
        assert!(!text.contains("1.2.4"));
        assert!(!text.contains("example.com"));
        assert!(!text.contains("Developer ID"));
        assert!(!text.contains("store upload backend"));
    }

