    #[test]
    fn packaging_update_handoff_next_action_covers_routes() {
        let restart_path = std::env::current_exe().unwrap();
        let cases = [
            (
                PackagingUpdateHandoffBuilder::new()
                    .package_readiness(AppPackageReadinessBuilder::new(ready_release_manifest())),
                PackagingUpdateNextAction::CheckPackageReadiness,
            ),
            (
                PackagingUpdateHandoffBuilder::new().distribution_plan(release_distribution_plan()),
                PackagingUpdateNextAction::PlanDistributionTargets,
            ),
            (
                PackagingUpdateHandoffBuilder::new().signing_plan(release_signing_plan()),
                PackagingUpdateNextAction::PlanSigning,
            ),
            (
                PackagingUpdateHandoffBuilder::new().update_offer(
                    AppUpdateOfferPolicyBuilder::stable(),
                    AppUpdateReleaseBuilder::new("1.2.4")
                        .download_url("https://example.com/downloads/kael-1.2.4.dmg")
                        .signed(),
                ),
                PackagingUpdateNextAction::EvaluateUpdateOffer,
            ),
            (
                PackagingUpdateHandoffBuilder::new()
                    .update_state(AppUpdateStateBuilder::new("1.2.3").phase(AppUpdatePhase::Idle)),
                PackagingUpdateNextAction::UpdateAppUiState,
            ),
            (
                PackagingUpdateHandoffBuilder::new()
                    .crash_reporter(CrashReporterBuilder::new("com.example.kael")),
                PackagingUpdateNextAction::ConfigureCrashReporting,
            ),
            (
                PackagingUpdateHandoffBuilder::new()
                    .restart_path(RestartPathBuilder::new(restart_path)),
                PackagingUpdateNextAction::ConfigureRestartPath,
            ),
            (
                PackagingUpdateHandoffBuilder::new().roadmap_work("release templates"),
                PackagingUpdateNextAction::TrackRoadmapWork,
            ),
        ];

        for (builder, expected) in cases {
            let handoff = builder.build_checked().unwrap();
            assert_eq!(handoff.next_action(), expected);
        }
    }

