    #[test]
    fn file_drop_intent_builder_validates_files_extensions_and_canonical_paths() {
        let root =
            std::env::temp_dir().join(format!("kael_file_drop_intent_{}", std::process::id()));
        let nested = root.join("nested");
        let file = nested.join("Clip.MP4");
        std::fs::create_dir_all(&nested).unwrap();
        std::fs::write(&file, "video").unwrap();

        let relative_file = nested.join("..").join("nested").join("Clip.MP4");
        let builder = FileDropIntentBuilder::media_source()
            .path(relative_file)
            .path(file.clone())
            .max_paths(2)
            .canonicalize_paths();

        assert_eq!(builder.configured_path_count(), 2);
        assert!(builder.allowed_extension_count() >= 1);
        assert_eq!(builder.max_path_count(), Some(2));
        assert_eq!(builder.path_kind().to_text(), "files-only");
        assert!(builder.requires_existing_paths());
        assert!(builder.canonicalizes_paths());
        assert!(builder.to_text().contains("purpose media-source"));
        assert!(builder.to_text().contains("paths 2"));
        assert!(builder.to_text().contains("kind files-only"));
        assert!(!builder.to_text().contains("Clip.MP4"));

        let intent = builder.build_checked().unwrap();

        assert_eq!(intent.purpose().label(), "media-source");
        assert_eq!(intent.path_count(), 1);
        assert_eq!(
            intent.to_text(),
            "file drop intent: purpose media-source, paths 1"
        );
        assert!(!intent.to_text().contains("Clip.MP4"));
        assert_eq!(intent.paths(), &[std::fs::canonicalize(&file).unwrap()]);
        assert_eq!(
            intent.first_path(),
            Some(std::fs::canonicalize(&file).unwrap().as_path())
        );

        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn file_drop_intent_builder_rejects_mismatched_drops() {
        let root =
            std::env::temp_dir().join(format!("kael_file_drop_reject_{}", std::process::id()));
        let file = root.join("notes.txt");
        let folder = root.join("folder");
        std::fs::create_dir_all(&folder).unwrap();
        std::fs::write(&file, "notes").unwrap();

        assert!(
            FileDropIntentBuilder::new(FileDropPurpose::custom(" bad"))
                .path(&file)
                .validate()
                .is_err()
        );
        assert!(FileDropIntentBuilder::import_files().validate().is_err());
        assert!(
            FileDropIntentBuilder::import_files()
                .path(&folder)
                .validate()
                .is_err()
        );
        assert!(
            FileDropIntentBuilder::import_folder()
                .path(&file)
                .validate()
                .is_err()
        );
        assert!(
            FileDropIntentBuilder::open_document()
                .path(&file)
                .extensions(["md"])
                .validate()
                .is_err()
        );
        assert!(
            FileDropIntentBuilder::open_document()
                .path(&file)
                .max_paths(0)
                .validate()
                .is_err()
        );
        assert!(
            FileDropIntentBuilder::open_document()
                .path(root.join("missing.txt"))
                .validate()
                .is_err()
        );

        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn file_drop_intent_checked_uses_builder_validation() {
        let cx = TestAppContext::single();
        let path = PathBuf::from("/virtual/report.md");

        let intent = cx
            .read(|app| {
                app.file_drop_intent_checked(
                    FileDropIntentBuilder::open_document()
                        .allow_missing_paths()
                        .path(path.clone())
                        .extensions(["md"]),
                )
            })
            .unwrap();

        assert_eq!(intent.paths(), &[path]);
        assert_eq!(intent.purpose(), &FileDropPurpose::OpenDocument);

        assert!(
            cx.read(|app| app.file_drop_intent_checked(FileDropIntentBuilder::open_document()))
                .is_err()
        );
        assert_eq!(
            FileDropIntentBuilder::project_workspace()
                .any_path_kind()
                .allow_missing_paths()
                .path("/virtual/workspace")
                .path_kind(),
            FileDropPathKind::Any
        );
        let builder = FileDropIntentBuilder::project_workspace()
            .any_path_kind()
            .allow_missing_paths()
            .path("/virtual/workspace");
        assert_eq!(builder.configured_path_count(), 1);
        assert_eq!(builder.allowed_extension_count(), 0);
        assert_eq!(builder.max_path_count(), None);
        assert!(!builder.requires_existing_paths());
        assert!(!builder.canonicalizes_paths());
        assert_eq!(
            builder.to_text(),
            "file drop intent builder: purpose project-workspace, paths 1, kind any, extensions 0, max paths none, require existing false, canonicalize false"
        );
        assert!(!builder.to_text().contains("/virtual/workspace"));
    }

