    #[test]
    fn file_export_drag_checked_preflights_existing_file_capability() {
        let cx = TestAppContext::single();
        let root = std::env::temp_dir().join(format!(
            "kael_file_export_capability_{}",
            std::process::id()
        ));
        let file = root.join("report.pdf");
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(&file, "pdf").unwrap();

        let denied = cx
            .read(|app| {
                app.file_export_drag_checked(
                    FileExportDragIntentBuilder::existing_files("Drag report.").path(&file),
                )
            })
            .unwrap_err()
            .to_string();
        assert!(denied.contains("FilesystemRead"));

        let export = cx
            .update(|app| {
                app.permission_broker.grant(
                    app.current_process_id,
                    Capability::FilesystemRead {
                        scope: PathScope::UserSelected,
                    },
                );
                app.file_export_drag_checked(
                    FileExportDragIntentBuilder::existing_files("Drag report.").path(&file),
                )
            })
            .unwrap();

        assert_eq!(export.existing_path_count(), 1);
        assert_eq!(export.display_names(), vec!["report.pdf"]);

        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn drag_drop_transfer_handoff_guides_incoming_export_internal_and_hosted_flows() {
        let root =
            std::env::temp_dir().join(format!("kael_drag_drop_handoff_{}", std::process::id()));
        let file = root.join("movie.mp4");
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(&file, "video").unwrap();

        let incoming = DragDropTransferHandoffBuilder::media_drop([file.clone()])
            .build_checked()
            .unwrap();
        assert!(incoming.is_incoming_drop());
        assert!(!incoming.is_file_export_drag());
        assert_eq!(
            incoming.next_action(),
            DragDropTransferNextAction::AcceptIncomingDrop
        );
        assert_eq!(
            incoming
                .incoming_drop_builder()
                .unwrap()
                .configured_path_count(),
            1
        );
        assert!(incoming.to_text().contains("accept-incoming-drop"));
        assert!(incoming.to_text().contains("incoming paths 1"));
        assert!(!incoming.to_text().contains("movie.mp4"));

        let export = DragDropTransferHandoffBuilder::generated_file_export(
            "Drag generated poster.",
            "poster.png",
            "image/png",
            vec![1, 2, 3, 4],
        );
        assert_eq!(
            export.next_action(),
            DragDropTransferNextAction::StartFileExportDrag
        );
        assert!(export.validate().is_ok());
        assert_eq!(
            export.to_text(),
            "drag/drop transfer handoff builder: drag/drop transfer request: action start-file-export-drag, export items 1"
        );
        assert!(!export.to_text().contains("poster.png"));
        assert!(!export.to_text().contains("generated poster"));

        let export = export.build_checked().unwrap();
        assert!(export.is_file_export_drag());
        assert_eq!(
            export.next_action(),
            DragDropTransferNextAction::StartFileExportDrag
        );
        assert_eq!(
            export
                .file_export_drag_builder()
                .unwrap()
                .configured_items()
                .len(),
            1
        );

        let internal = DragDropTransferHandoffBuilder::internal_drag("layer-reorder")
            .require_precision_pointer(false)
            .build_checked()
            .unwrap();
        assert!(internal.is_internal_drag());
        assert_eq!(
            internal.next_action(),
            DragDropTransferNextAction::ConfigureInternalDrag
        );
        assert_eq!(internal.internal_drag_route(), Some("layer-reorder"));
        assert!(!internal.requires_precision_pointer());
        assert!(!internal.to_text().contains("layer-reorder"));

        let hosted = DragDropTransferHandoff::hosted_data_transfer("editor-webview").unwrap();
        assert!(hosted.is_hosted_data_transfer());
        assert_eq!(
            hosted.next_action(),
            DragDropTransferNextAction::UseHostedDataTransfer
        );
        assert_eq!(hosted.webview_id(), Some("editor-webview"));
        assert_eq!(
            DragDropTransferNextAction::UseHostedDataTransfer.key(),
            "use-hosted-data-transfer"
        );
        assert!(!hosted.to_text().contains("editor-webview"));

        std::fs::remove_dir_all(root).unwrap();
    }

