    #[test]
    fn data_transfer_drop_intake_routes_native_paths_urls_and_text() {
        let plan =
            DataTransferDropIntakePlanBuilder::paths(["/virtual/movie.mp4", "/virtual/readme.md"])
                .allow_missing_paths()
                .file_filter(
                    FileDropFilter::media()
                        .extensions(["mp4", "md"])
                        .max_files(2),
                )
                .build_checked()
                .unwrap();

        assert_eq!(
            plan.next_action(),
            DataTransferDropIntakeNextAction::RoutePaths
        );
        assert!(plan.can_route_immediately());
        assert_eq!(plan.path_count(), 2);
        assert_eq!(plan.url_count(), 0);
        assert!(!plan.has_text());
        assert!(plan.file_filter().is_some());
        assert!(plan.file_filter_accepts_paths());
        assert_eq!(plan.file_intake().unwrap().entry_count(), 2);
        assert_eq!(plan.file_intake().unwrap().media_count(), 1);
        assert_eq!(plan.file_intake().unwrap().document_count(), 1);
        assert_eq!(
            plan.to_text(),
            "data transfer drop intake: paths 2, urls 0, text false, mixed false, filter true, file intake true, unknown false, hosted false, next action route-paths"
        );
        assert!(!plan.to_text().contains("movie"));
        assert!(!plan.to_text().contains("readme"));

        let url = DataTransferDropIntakePlanBuilder::url("https://example.com/import")
            .max_urls(1)
            .build_checked()
            .unwrap();
        assert_eq!(
            url.next_action(),
            DataTransferDropIntakeNextAction::RouteUrls
        );
        assert!(url.can_route_immediately());
        assert!(!url.to_text().contains("example.com"));

        let text = DataTransferDropIntakePlanBuilder::text("Paste this into a note.")
            .max_text_bytes(64)
            .build_checked()
            .unwrap();
        assert_eq!(
            text.next_action(),
            DataTransferDropIntakeNextAction::RouteText
        );
        assert!(text.can_route_immediately());
        assert!(!text.to_text().contains("Paste this"));
    }

    #[test]
    fn data_transfer_drop_intake_reviews_mixed_unknown_and_hosted_payloads() {
        let mixed = DataTransferDropIntakePlanBuilder::new(
            ExternalDropData::from_paths([PathBuf::from("/virtual/movie.mp4")])
                .with_text("caption")
                .with_url("https://example.com/source"),
        )
        .allow_missing_paths()
        .build_checked()
        .unwrap();

        assert_eq!(
            mixed.next_action(),
            DataTransferDropIntakeNextAction::ReviewMixedPayload
        );
        assert!(mixed.is_mixed_payload());
        assert!(!mixed.can_route_immediately());

        let mixed_allowed = DataTransferDropIntakePlanBuilder::new(mixed.data().clone())
            .allow_missing_paths()
            .allow_mixed_payload()
            .build_checked()
            .unwrap();
        assert_eq!(
            mixed_allowed.next_action(),
            DataTransferDropIntakeNextAction::RoutePaths
        );
        assert!(mixed_allowed.allows_mixed_payload());

        let unknown = DataTransferDropIntakePlanBuilder::paths(["/virtual/blob.unknown"])
            .allow_missing_paths()
            .build_checked()
            .unwrap();
        assert_eq!(
            unknown.next_action(),
            DataTransferDropIntakeNextAction::ReviewUnknownPaths
        );
        assert!(unknown.has_unknown_paths());

        let hosted = DataTransferDropIntakePlanBuilder::text("browser owned")
            .hosted_data_transfer("editor-webview")
            .build_checked()
            .unwrap();
        assert_eq!(
            hosted.next_action(),
            DataTransferDropIntakeNextAction::UseHostedDataTransfer
        );
        assert!(hosted.uses_hosted_data_transfer());
        assert_eq!(hosted.hosted_webview_id(), Some("editor-webview"));
        assert!(!hosted.to_text().contains("browser owned"));
        assert!(!hosted.to_text().contains("editor-webview"));
    }

