    #[test]
    fn file_intake_plan_builder_classifies_common_content() {
        let paths = [
            "/virtual/movie.MP4",
            "/virtual/song.flac",
            "/virtual/image.PNG",
            "/virtual/report.pdf",
            "/virtual/readme.md",
            "/virtual/data.json",
            "/virtual/archive.zip",
            "/virtual/app.code-workspace",
            "/virtual/unknown.bin",
        ];

        let plan = FileIntakePlanBuilder::new()
            .allow_missing_paths()
            .paths(paths)
            .build_checked()
            .unwrap();

        let kinds = plan
            .entries()
            .iter()
            .map(|entry| entry.kind())
            .collect::<Vec<_>>();
        assert_eq!(
            kinds,
            vec![
                FileIntakeKind::Video,
                FileIntakeKind::Audio,
                FileIntakeKind::Image,
                FileIntakeKind::Pdf,
                FileIntakeKind::Text,
                FileIntakeKind::Data,
                FileIntakeKind::Archive,
                FileIntakeKind::Project,
                FileIntakeKind::Unknown,
            ]
        );
        assert!(plan.has_media());
        assert!(plan.has_documents());
        assert!(plan.has_projects());
        assert!(plan.has_archives());
        assert!(plan.has_unknown());
        assert!(!plan.is_empty());
        assert_eq!(plan.entry_count(), 9);
        assert_eq!(plan.media_count(), 3);
        assert_eq!(plan.document_count(), 3);
        assert_eq!(plan.project_count(), 1);
        assert_eq!(plan.archive_count(), 1);
        assert_eq!(plan.directory_count(), 0);
        assert_eq!(plan.unknown_count(), 1);
        assert_eq!(plan.kind_count(FileIntakeKind::Video), 1);
        assert_eq!(plan.kind_count(FileIntakeKind::Directory), 0);
        assert_eq!(
            plan.paths_of_kind(FileIntakeKind::Video),
            vec![std::path::Path::new("/virtual/movie.MP4")]
        );
        assert_eq!(
            plan.media_paths(),
            vec![
                std::path::Path::new("/virtual/movie.MP4"),
                std::path::Path::new("/virtual/song.flac"),
                std::path::Path::new("/virtual/image.PNG"),
            ]
        );
        assert_eq!(
            plan.document_paths(),
            vec![
                std::path::Path::new("/virtual/report.pdf"),
                std::path::Path::new("/virtual/readme.md"),
                std::path::Path::new("/virtual/data.json"),
            ]
        );
        assert_eq!(
            plan.archive_paths(),
            vec![std::path::Path::new("/virtual/archive.zip")]
        );
        assert_eq!(
            plan.project_paths(),
            vec![std::path::Path::new("/virtual/app.code-workspace")]
        );
        assert_eq!(
            plan.unknown_paths(),
            vec![std::path::Path::new("/virtual/unknown.bin")]
        );
        assert_eq!(plan.entries()[0].extension(), Some("mp4"));
        assert!(FileIntakeKind::Video.is_media());
        assert!(FileIntakeKind::Text.is_document());

        let summary = plan.to_text();
        assert_eq!(
            summary,
            "file intake: 9 entries, 3 media, 3 documents, 1 projects, 1 archives, 0 directories, 1 unknown"
        );
        assert!(!summary.contains("/virtual"));
        assert!(!summary.contains("movie"));
        assert!(!summary.contains("readme"));
    }

    #[test]
    fn file_intake_plan_builder_validates_and_canonicalizes_paths() {
        let root =
            std::env::temp_dir().join(format!("kael_file_intake_plan_{}", std::process::id()));
        let nested = root.join("nested");
        let file = nested.join("notes.md");
        std::fs::create_dir_all(&nested).unwrap();
        std::fs::write(&file, "notes").unwrap();

        let relative_file = nested.join("..").join("nested").join("notes.md");
        let plan = FileIntakePlanBuilder::new()
            .canonicalize_paths()
            .path(relative_file)
            .path(file.clone())
            .build_checked()
            .unwrap();

        assert_eq!(plan.entries().len(), 1);
        assert_eq!(plan.entries()[0].kind(), FileIntakeKind::Text);
        assert_eq!(
            plan.entries()[0].path(),
            std::fs::canonicalize(&file).unwrap()
        );

        assert!(
            FileIntakePlanBuilder::new()
                .allow_missing_paths()
                .path("/virtual/unknown.bin")
                .reject_unknown()
                .validate()
                .is_err()
        );
        assert!(FileIntakePlanBuilder::new().validate().is_err());
        assert!(
            FileIntakePlanBuilder::new()
                .allow_missing_paths()
                .path("/virtual/a.md")
                .max_paths(0)
                .validate()
                .is_err()
        );
        assert!(
            FileIntakePlanBuilder::new()
                .path(root.join("missing.md"))
                .validate()
                .is_err()
        );

        std::fs::remove_dir_all(root).unwrap();
    }

