    #[test]
    fn file_operation_handoff_validates_scoped_operations() {
        let handoff = FileOperationHandoffBuilder::new()
            .read(AppPathRole::Config, "settings.json")
            .operation(
                FileOperationRequestBuilder::write(AppPathRole::Data, "projects/index.json")
                    .create_parent_dirs()
                    .overwrite()
                    .max_bytes(4096),
            )
            .copy(
                AppPathRole::Data,
                "projects/index.json",
                AppPathRole::Cache,
                "snapshots/index.json",
            )
            .move_path(
                AppPathRole::Cache,
                "snapshots/index.json",
                AppPathRole::Cache,
                "snapshots/latest.json",
            )
            .delete(AppPathRole::Temp, "exports/draft.tmp")
            .hosted_file_manager("cloud-drive")
            .roadmap_work("recursive safe delete")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 7);
        assert!(handoff.has_read());
        assert!(handoff.has_write());
        assert!(handoff.has_copy());
        assert!(handoff.has_move());
        assert!(handoff.has_delete());
        assert!(handoff.has_hosted_file_manager());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            FileOperationNextAction::ReadScopedFile
        );
        assert_eq!(
            FileOperationNextAction::DeleteScopedPath.key(),
            "delete-scoped-path"
        );

        let write = FileOperationRequestBuilder::write(AppPathRole::Data, "projects/index.json")
            .create_parent_dirs()
            .overwrite()
            .max_bytes(4096)
            .build_checked()
            .unwrap();
        assert_eq!(write.kind().key(), "write");
        assert_eq!(write.source_role(), AppPathRole::Data);
        assert_eq!(write.source_path(), Path::new("projects/index.json"));
        assert!(write.creates_parent_dirs());
        assert!(write.overwrites());
        assert_eq!(write.max_bytes(), Some(4096));
        assert!(!write.to_text().contains("projects/index.json"));

        let text = handoff.to_text();
        assert!(text.contains("file operation handoff"));
        assert!(text.contains("read:1"));
        assert!(text.contains("write:1"));
        assert!(text.contains("copy:1"));
        assert!(text.contains("move:1"));
        assert!(text.contains("delete:1"));
        assert!(text.contains("hosted-file-manager:1"));
        assert!(text.contains("roadmap-work:1"));
        assert!(!text.contains("settings.json"));
        assert!(!text.contains("cloud-drive"));
        assert!(!text.contains("recursive safe delete"));
    }

    #[test]
    fn file_operation_handoff_rejects_unscoped_or_unsafe_requests() {
        assert!(FileOperationHandoffBuilder::new().validate().is_err());
        assert!(
            FileOperationHandoffBuilder::new()
                .read(AppPathRole::Downloads, "report.pdf")
                .validate()
                .is_err()
        );
        assert!(
            FileOperationHandoffBuilder::new()
                .write(AppPathRole::Data, "../escape.txt")
                .validate()
                .is_err()
        );
        assert!(
            FileOperationHandoffBuilder::new()
                .operation(
                    FileOperationRequestBuilder::read(AppPathRole::Config, "settings.json")
                        .overwrite(),
                )
                .validate()
                .is_err()
        );
        assert!(
            FileOperationHandoffBuilder::new()
                .operation(FileOperationRequestBuilder::copy(
                    AppPathRole::Data,
                    "source.json",
                    AppPathRole::Downloads,
                    "target.json",
                ))
                .validate()
                .is_err()
        );
        assert!(
            FileOperationHandoffBuilder::new()
                .operation(
                    FileOperationRequestBuilder::write(AppPathRole::Data, "large.bin")
                        .max_bytes(1024 * 1024 * 1024 + 1),
                )
                .validate()
                .is_err()
        );
        assert!(
            FileOperationHandoffBuilder::new()
                .hosted_file_manager("bad manager")
                .validate()
                .is_err()
        );
        assert!(
            FileOperationHandoffBuilder::new()
                .roadmap_work(" ")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn file_operation_handoff_next_action_covers_routes() {
        let cases = [
            (
                FileOperationHandoffBuilder::new().write(AppPathRole::Data, "settings.json"),
                FileOperationNextAction::WriteScopedFile,
            ),
            (
                FileOperationHandoffBuilder::new().copy(
                    AppPathRole::Data,
                    "source.json",
                    AppPathRole::Cache,
                    "source.json",
                ),
                FileOperationNextAction::CopyScopedPath,
            ),
            (
                FileOperationHandoffBuilder::new().move_path(
                    AppPathRole::Cache,
                    "old.json",
                    AppPathRole::Cache,
                    "new.json",
                ),
                FileOperationNextAction::MoveScopedPath,
            ),
            (
                FileOperationHandoffBuilder::new().delete(AppPathRole::Temp, "draft.tmp"),
                FileOperationNextAction::DeleteScopedPath,
            ),
            (
                FileOperationHandoffBuilder::new().hosted_file_manager("cloud-drive"),
                FileOperationNextAction::UseHostedFileManager,
            ),
            (
                FileOperationHandoffBuilder::new().roadmap_work("workspace diff previews"),
                FileOperationNextAction::TrackFilesystemRoadmap,
            ),
        ];

        for (builder, expected) in cases {
            assert_eq!(builder.build_checked().unwrap().next_action(), expected);
        }
    }

