    #[test]
    fn clipboard_item_summary_is_content_safe() {
        let builder = crate::ClipboardItem::builder()
            .html(
                "Copied secret token",
                "<strong>Copied secret token</strong>",
            )
            .unwrap()
            .try_text_with_json_metadata(
                "metadata secret",
                serde_json::json!({ "source": "vault", "token": "sensitive" }),
            )
            .unwrap()
            .image(crate::Image::from_bytes(
                crate::ImageFormat::Png,
                vec![1, 2, 3, 4],
            ));

        assert_eq!(builder.entry_count(), 3);
        assert_eq!(builder.text_count(), 2);
        assert_eq!(builder.image_count(), 1);
        assert_eq!(builder.metadata_count(), 2);
        assert_eq!(builder.text_len_bytes(), 34);
        assert!(builder.has_text());
        assert!(builder.has_html());
        assert!(builder.has_image());

        let builder_summary = builder.to_text();
        assert_eq!(
            builder_summary,
            "clipboard item builder: 3 entries, 2 text, 1 images, html true, metadata 2, text 34 bytes"
        );
        assert!(!builder_summary.contains("secret"));
        assert!(!builder_summary.contains("token"));
        assert!(!builder_summary.contains("sensitive"));
        assert!(!builder_summary.contains("vault"));
        assert!(!builder_summary.contains("strong"));

        let item = builder.build_checked().unwrap();

        assert_eq!(item.entry_count(), 3);
        assert_eq!(item.text_count(), 2);
        assert_eq!(item.image_count(), 1);
        assert_eq!(item.metadata_count(), 2);
        assert_eq!(item.text_len_bytes(), 34);
        assert!(item.has_text());
        assert!(item.has_html());
        assert!(item.has_image());

        let summary = item.to_text();
        assert_eq!(
            summary,
            "clipboard item: 3 entries, 2 text, 1 images, html true, metadata 2, text 34 bytes"
        );
        assert!(!summary.contains("secret"));
        assert!(!summary.contains("token"));
        assert!(!summary.contains("sensitive"));
        assert!(!summary.contains("vault"));
        assert!(!summary.contains("strong"));
    }

