    #[test]
    fn clipboard_editing_handoff_guides_write_read_clear_and_edit_state() {
        let write = ClipboardEditingHandoffBuilder::write_text("secret token");
        assert_eq!(
            write.next_action(),
            ClipboardEditingNextAction::WriteClipboard
        );
        assert!(write.validate().is_ok());
        assert_eq!(
            write.to_text(),
            "clipboard editing handoff builder: clipboard editing request: action write-clipboard, clipboard item builder: 1 entries, 1 text, 0 images, html false, metadata 0, text 12 bytes"
        );
        assert!(!write.to_text().contains("secret token"));

        let write = write.build_checked().unwrap();
        assert!(write.is_write());
        assert!(!write.is_read());
        assert_eq!(
            write.next_action(),
            ClipboardEditingNextAction::WriteClipboard
        );
        assert!(write.write_builder().unwrap().has_text());
        assert_eq!(write.read_builder(), None);
        assert_eq!(write.clear_builder(), None);
        assert_eq!(
            write.to_text(),
            "clipboard editing handoff: clipboard editing request: action write-clipboard, clipboard item builder: 1 entries, 1 text, 0 images, html false, metadata 0, text 12 bytes"
        );

        let html =
            ClipboardEditingHandoffBuilder::write_html("fallback", "<strong>secret</strong>")
                .unwrap()
                .build_checked()
                .unwrap();
        assert!(html.write_builder().unwrap().has_html());
        assert!(!html.to_text().contains("secret"));
        assert!(!html.to_text().contains("fallback"));

        let read = ClipboardEditingHandoff::read_any("Paste into editor").unwrap();
        assert!(read.is_read());
        assert_eq!(
            read.next_action(),
            ClipboardEditingNextAction::ReadClipboard
        );
        assert_eq!(read.read_builder().unwrap().expected_format_count(), 3);
        assert!(!read.to_text().contains("Paste into editor"));

        let clear = ClipboardEditingHandoff::clear("Copied password expired").unwrap();
        assert!(clear.is_clear());
        assert_eq!(
            clear.next_action(),
            ClipboardEditingNextAction::ClearClipboard
        );
        assert!(clear.clear_builder().unwrap().has_reason());
        assert!(!clear.to_text().contains("password"));

        let snapshot = ClipboardEditingHandoff::snapshot_edit_commands().unwrap();
        assert!(snapshot.is_edit_snapshot());
        assert_eq!(
            snapshot.next_action(),
            ClipboardEditingNextAction::SnapshotEditCommands
        );
        assert_eq!(
            ClipboardEditingNextAction::SnapshotEditCommands.key(),
            "snapshot-edit-commands"
        );
        assert_eq!(
            snapshot.to_text(),
            "clipboard editing handoff: clipboard editing request: action snapshot-edit-commands, edit command snapshot"
        );
    }

