    #[test]
    fn css_token_migration_builder_maps_css_variables_to_native_tokens() {
        let plan = CssTokenMigrationPlan::builder()
            .map("--color-primary", "primary")
            .map("--color-background", "background")
            .map("--space-md", "space_md")
            .map("--radius-card", "radius_card")
            .dark_mode()
            .require_all_referenced_tokens()
            .build_checked()
            .unwrap();

        assert_eq!(plan.entry_count(), 4);
        assert!(plan.includes_dark_mode());
        assert!(plan.requires_all_referenced_tokens());
        assert!(plan.has_color_tokens());
        assert!(plan.has_layout_tokens());
        assert_eq!(
            plan.to_text(),
            "CSS token migration: mappings=4 dark_mode=true require_all_referenced_tokens=true color_tokens=true layout_tokens=true"
        );
        assert!(!plan.to_text().contains("--color-primary"));
        assert!(!plan.to_text().contains("background"));
        assert_eq!(plan.entries()[0].css_variable(), "--color-primary");
        assert_eq!(plan.entries()[0].native_token(), "primary");
    }

