    #[test]
    fn animation_timeline_builder_builds_checked_sequence() {
        let plan = AnimationTimelinePlan::builder()
            .step("enter", Duration::from_millis(180))
            .easing_last(Easing::EaseOutCubic)
            .keyframes_last(3)
            .step("settle", Duration::from_millis(120))
            .delay_last(Duration::from_millis(20))
            .easing_last(Easing::CubicBezier(0.2, 0.0, 0.0, 1.0))
            .keyframes_last(2)
            .overlap_previous_last(Duration::from_millis(40))
            .reduce_motion_fallback()
            .build_checked()
            .unwrap();

        assert_eq!(plan.step_count(), 2);
        assert_eq!(plan.total_keyframes(), 5);
        assert!(!plan.has_infinite_animation());
        assert!(plan.has_reduce_motion_fallback());
        let sequence = plan.animation_sequence();
        assert_eq!(sequence.len(), 2);
        assert_eq!(sequence.scheduled_duration(), Duration::from_millis(280));
        assert_eq!(
            plan.to_text(),
            "animation timeline: steps=2 keyframes=5 scheduled_ms=280 infinite=false reduce_motion_fallback=true"
        );
        assert!(!plan.to_text().contains("enter"));
        assert!(!plan.to_text().contains("settle"));
    }

    #[test]
    fn animation_timeline_builder_rejects_invalid_generated_timelines() {
        assert!(AnimationTimelineBuilder::new().validate().is_err());
        assert!(
            AnimationTimelineBuilder::new()
                .step("bad step", Duration::from_millis(120))
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("enter", Duration::ZERO)
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("enter", Duration::from_millis(120))
                .keyframes_last(0)
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("enter", Duration::from_millis(120))
                .overlap_previous_last(Duration::from_millis(240))
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("enter", Duration::from_millis(120))
                .easing_last(Easing::Steps(0))
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("enter", Duration::from_millis(120))
                .easing_last(Easing::CubicBezier(-0.1, 0.0, 1.0, 1.0))
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("loop", Duration::from_millis(120))
                .repeat_last(Repeat::Forever)
                .validate()
                .is_err()
        );
        assert!(
            AnimationTimelineBuilder::new()
                .step("enter", Duration::from_millis(120))
                .step("enter", Duration::from_millis(120))
                .validate()
                .is_err()
        );
    }

