    #[test]
    fn responsive_layout_plan_builder_guides_native_breakpoints() {
        let plan = ResponsiveLayoutPlan::builder("dashboard")
            .breakpoint("xs", 0, ResponsiveLayoutMode::Stack, 1)
            .collapse_panes_last(2)
            .breakpoint("md", 768, ResponsiveLayoutMode::Tabs, 2)
            .collapse_panes_last(1)
            .breakpoint("lg", 1024, ResponsiveLayoutMode::Split, 3)
            .splitter_policy()
            .restore_focus()
            .evidence_snapshots(3)
            .build_checked()
            .unwrap();

        assert_eq!(plan.surface_id(), "dashboard");
        assert_eq!(plan.breakpoint_count(), 3);
        assert_eq!(plan.max_columns(), 3);
        assert!(plan.has_collapsed_panes());
        assert!(plan.uses_mode(ResponsiveLayoutMode::Stack));
        assert!(plan.uses_mode(ResponsiveLayoutMode::Tabs));
        assert!(plan.uses_mode(ResponsiveLayoutMode::Split));
        assert!(plan.has_splitter_policy());
        assert!(plan.restores_focus());
        assert_eq!(plan.evidence_snapshots(), 3);
        assert_eq!(
            plan.to_text(),
            "responsive layout plan: breakpoints=3 max_columns=3 collapsed_panes=true splitter_policy=true restore_focus=true evidence_snapshots=3"
        );
        assert!(!plan.to_text().contains("dashboard"));
        assert!(!plan.to_text().contains("xs"));
    }

