    #[test]
    fn layout_styling_handoff_guides_theme_layout_motion_effects_and_hosted_css() {
        let handoff = LayoutStylingHandoffBuilder::new()
            .theme_tokens("main-surface")
            .responsive_layout("dashboard")
            .transition_motion("routes")
            .layer_effect("overlays")
            .virtualized_list("results")
            .headless_render_evidence("main-surface", 3)
            .hosted_css_island("legacy-css")
            .roadmap_work("keyframe authoring templates")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 8);
        assert_eq!(
            handoff.next_action(),
            LayoutStylingNextAction::ApplyThemeTokens
        );
        assert!(handoff.has_theme_tokens());
        assert!(handoff.has_responsive_layout());
        assert!(handoff.has_transition_motion());
        assert!(handoff.has_layer_effect());
        assert!(handoff.has_virtualized_list());
        assert!(handoff.has_headless_render_evidence());
        assert!(handoff.has_hosted_css_island());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.to_text(),
            "layout styling handoff: 8 requests, theme tokens true, responsive layout true, transition motion true, layer effects true, virtualized lists true, headless evidence true, evidence snapshots 3, hosted css island true, roadmap true, next ApplyThemeTokens"
        );
        assert!(!handoff.to_text().contains("main-surface"));
        assert!(!handoff.to_text().contains("legacy-css"));
        assert!(!handoff.to_text().contains("keyframe"));
    }

