    #[test]
    fn menu_bar_checked_previews_menu_without_installing() {
        let cx = TestAppContext::single();

        let file_menu = MenuBuilder::new("File").action("Open", JumpListOpen);
        assert_eq!(file_menu.item_count(), 1);
        assert_eq!(file_menu.action_count(), 1);
        assert!(!file_menu.has_os_actions());
        assert_eq!(
            file_menu.to_text(),
            "menu: items 1, actions 1, os actions false, system menus false"
        );
        assert!(!file_menu.to_text().contains("File"));
        assert!(!file_menu.to_text().contains("Open"));

        let menu_bar = MenuBarBuilder::new()
            .menu(file_menu)
            .menu(MenuBuilder::standard_edit(
                "Edit",
                JumpListOpen,
                JumpListOpen,
                JumpListOpen,
                JumpListOpen,
                JumpListOpen,
                JumpListOpen,
            ));
        assert_eq!(menu_bar.top_level_names(), vec!["File", "Edit"]);
        assert_eq!(menu_bar.menu_count(), 2);
        assert_eq!(menu_bar.item_count(), 9);
        assert_eq!(menu_bar.action_count(), 7);
        assert!(menu_bar.has_os_actions());
        assert_eq!(
            menu_bar.to_text(),
            "menu bar builder: 2 menus, 9 items, 7 actions, os actions true, system menus false"
        );
        assert!(!menu_bar.to_text().contains("File"));
        assert!(!menu_bar.to_text().contains("Edit"));

        let plan = cx.read(|app| app.menu_bar_checked(menu_bar)).unwrap();

        assert_eq!(plan.top_level_names(), vec!["File", "Edit"]);
        assert_eq!(plan.menu_count(), 2);
        assert_eq!(plan.item_count(), 9);
        assert_eq!(plan.action_count(), 7);
        assert!(plan.has_os_actions());
        assert_eq!(
            plan.to_text(),
            "menu bar: 2 menus, 9 items, 7 actions, os actions true, system menus false"
        );
        assert!(!plan.to_text().contains("File"));
        assert!(!plan.to_text().contains("Edit"));
        assert!(cx.read(|app| app.get_menus()).is_none());
    }

    #[test]
    fn menu_command_handoff_guides_menu_context_edit_and_hosted_routes() {
        let handoff = MenuCommandHandoffBuilder::new()
            .menu_bar(
                MenuBarBuilder::new()
                    .menu(MenuBuilder::new("File").action("Open Project", JumpListOpen))
                    .menu(MenuBuilder::standard_edit(
                        "Edit",
                        JumpListOpen,
                        JumpListOpen,
                        JumpListOpen,
                        JumpListOpen,
                        JumpListOpen,
                        JumpListOpen,
                    )),
            )
            .context_menu(
                NativeContextMenuBuilder::new()
                    .action("Open", "open")
                    .separator()
                    .toggle("Pinned", true, "pin"),
            )
            .edit_command_snapshot()
            .hosted_context_menu("editor-surface")
            .roadmap_work("native role menu parity")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 5);
        assert_eq!(handoff.next_action(), MenuCommandNextAction::InstallMenuBar);
        assert!(handoff.has_menu_bar());
        assert!(handoff.has_context_menu());
        assert!(handoff.has_edit_command_snapshot());
        assert!(handoff.has_hosted_context_menu());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.to_text(),
            "menu command handoff: 5 requests, menu bar true, context menu true, edit snapshot true, hosted context menu true, roadmap true, next InstallMenuBar"
        );
        assert!(!handoff.to_text().contains("File"));
        assert!(!handoff.to_text().contains("Open Project"));
        assert!(!handoff.to_text().contains("editor-surface"));
        assert!(!handoff.to_text().contains("role menu"));
    }

