    #[test]
    fn perform_dock_menu_action_checked_validates_installed_actions() {
        let cx = TestAppContext::single();

        cx.read(|app| {
            let missing_menu = app
                .perform_dock_menu_action_checked(DockMenuActionBuilder::new(0))
                .unwrap_err()
                .to_string();
            assert!(missing_menu.contains("no dock menu actions are installed"));

            app.set_dock_menu_checked(
                DockMenuBuilder::new()
                    .action("Open", JumpListOpen)
                    .separator()
                    .submenu(MenuBuilder::new("Recent").action("Project", JumpListOpen))
                    .action("Pin", JumpListOpen),
            )
            .unwrap();

            app.perform_dock_menu_action_checked(DockMenuActionBuilder::new(0))
                .unwrap();
            app.perform_dock_menu_action_checked(1usize).unwrap();

            let invalid_action = app
                .perform_dock_menu_action_checked(DockMenuActionBuilder::new(2))
                .unwrap_err()
                .to_string();
            assert!(invalid_action.contains("out of range for 2 installed dock menu actions"));
        });
    }

    #[test]
    fn recent_documents_clear_builder_validates_reason() {
        let request = RecentDocumentsClearBuilder::new("User cleared recent files");
        assert!(request.validate().is_ok());
        assert_eq!(request.reason(), "User cleared recent files");
        assert!(request.has_reason());
        assert_eq!(request.to_text(), "clear recent documents: reason true");
        assert!(!request.to_text().contains("User cleared recent files"));

        assert!(RecentDocumentsClearBuilder::new("").validate().is_err());
        assert!(!RecentDocumentsClearBuilder::new("").has_reason());
        assert_eq!(
            RecentDocumentsClearBuilder::new("").to_text(),
            "clear recent documents: reason false"
        );
        assert!(
            RecentDocumentsClearBuilder::new(" User cleared recent files")
                .validate()
                .is_err()
        );
        assert!(
            RecentDocumentsClearBuilder::new("User cleared\nrecent files")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn clear_recent_documents_checked_clears_test_platform() {
        let cx = TestAppContext::single();
        let first = PathBuf::from("/tmp/first.txt");
        let second = PathBuf::from("/tmp/second.txt");

        cx.read(|app| {
            app.add_recent_documents(
                RecentDocumentsBuilder::new()
                    .document(first.clone())
                    .document(second.clone()),
            )
        })
        .unwrap();
        assert_eq!(cx.recent_documents(), vec![first, second]);

        let request = cx
            .read(|app| {
                app.clear_recent_documents_checked(RecentDocumentsClearBuilder::new(
                    "User cleared recent files",
                ))
            })
            .unwrap();

        assert_eq!(request.reason(), "User cleared recent files");
        assert!(cx.recent_documents().is_empty());
        assert!(
            cx.read(|app| app.clear_recent_documents_checked(RecentDocumentsClearBuilder::new("")))
                .is_err()
        );
    }

    #[test]
    fn jump_list_builder_validates_tasks_and_workspaces() {
        let first = PathBuf::from("/tmp/project-a");
        let second = PathBuf::from("/tmp/project-b");
        let jump_list = JumpListBuilder::new()
            .action("Open Project", JumpListOpen)
            .workspace([first.clone(), second.clone()])
            .workspace([first.clone(), second.clone()]);

        assert_eq!(jump_list.menus().len(), 1);
        assert_eq!(jump_list.entries().len(), 1);
        assert_eq!(jump_list.task_count(), 1);
        assert_eq!(jump_list.workspace_count(), 1);
        assert_eq!(jump_list.workspace_path_count(), 2);
        assert!(jump_list.has_tasks());
        assert!(jump_list.has_workspaces());
        assert!(!jump_list.requires_existing_paths());
        assert!(!jump_list.canonicalizes_paths());
        assert_eq!(
            jump_list.to_text(),
            "jump list builder: 1 tasks, 1 workspaces, 2 workspace paths, require existing paths false, canonicalize paths false"
        );
        assert!(!jump_list.to_text().contains("Open Project"));
        assert!(!jump_list.to_text().contains("project-a"));
        assert!(!jump_list.to_text().contains("project-b"));
        assert!(jump_list.validate().is_ok());

        let plan = jump_list.build_checked().unwrap();
        assert_eq!(plan.task_count(), 1);
        assert_eq!(plan.workspace_count(), 1);
        assert_eq!(plan.workspace_path_count(), 2);
        assert!(plan.has_tasks());
        assert!(plan.has_workspaces());
        assert!(!plan.requires_existing_paths());
        assert!(!plan.canonicalized_paths());
        assert_eq!(plan.entries()[0].as_slice(), &[first, second]);
        assert_eq!(
            plan.to_text(),
            "1 tasks, 1 workspaces, 2 workspace paths, require existing paths: false, canonicalized paths: false"
        );
        assert!(!plan.to_text().contains("Open Project"));
        assert!(!plan.to_text().contains("project-a"));
        assert!(!plan.to_text().contains("project-b"));
        let (_menus, entries) = plan.into_parts();
        assert_eq!(entries.len(), 1);

        assert!(JumpListBuilder::new().validate().is_err());
        assert!(
            JumpListBuilder::new()
                .workspace(Vec::<PathBuf>::new())
                .validate()
                .is_err()
        );
        assert!(
            JumpListBuilder::new()
                .workspace_path(PathBuf::new())
                .validate()
                .is_err()
        );
        assert!(
            JumpListBuilder::new()
                .action(" Open Project", JumpListOpen)
                .validate()
                .is_err()
        );
        assert!(
            JumpListBuilder::new()
                .menu_item(MenuItem::separator())
                .validate()
                .is_err()
        );
    }

    #[test]
    fn jump_list_builder_can_require_existing_canonical_paths() {
        let root =
            std::env::temp_dir().join(format!("kael_jump_list_builder_{}", std::process::id()));
        let workspace = root.join("workspace");
        std::fs::create_dir_all(&workspace).unwrap();

        let relative_workspace = workspace.join("..").join("workspace");
        let builder = JumpListBuilder::new()
            .action("Open Project", JumpListOpen)
            .require_existing_paths()
            .canonicalize()
            .workspace_path(relative_workspace);
        assert_eq!(
            builder.to_text(),
            "jump list builder: 1 tasks, 1 workspaces, 1 workspace paths, require existing paths true, canonicalize paths true"
        );
        assert!(!builder.to_text().contains("Open Project"));
        assert!(!builder.to_text().contains("kael_jump_list_builder_"));

        let plan = builder.build_checked().unwrap();

        assert_eq!(plan.task_count(), 1);
        assert_eq!(plan.workspace_count(), 1);
        assert!(plan.requires_existing_paths());
        assert!(plan.canonicalized_paths());
        assert_eq!(
            plan.to_text(),
            "1 tasks, 1 workspaces, 1 workspace paths, require existing paths: true, canonicalized paths: true"
        );
        assert!(!plan.to_text().contains("Open Project"));
        assert!(!plan.to_text().contains("kael_jump_list_builder_"));
        let (_menus, entries) = plan.into_parts();
        assert_eq!(
            entries[0].as_slice(),
            &[std::fs::canonicalize(&workspace).unwrap()]
        );
        assert!(
            JumpListBuilder::new()
                .require_existing_paths()
                .workspace_path(root.join("missing"))
                .validate()
                .is_err()
        );

        std::fs::remove_dir_all(root).unwrap();
    }

