    #[test]
    fn permission_preflight_plan_reports_manifest_coverage() {
        let request = PermissionRequestBuilder::capture_studio();
        let manifest = AppPrivacyManifestBuilder::new()
            .permission(AppPrivacyPermissionBuilder::camera(
                "Camera access records video notes.",
            ))
            .permission(AppPrivacyPermissionBuilder::microphone(
                "Microphone access records voice notes.",
            ))
            .build_checked()
            .unwrap();

        assert_eq!(manifest.permission_count(), 2);
        assert_eq!(
            manifest.to_text(),
            "privacy manifest: permissions 2, macOS usage descriptions 2"
        );
        let plan = request.plan_against_manifest(&manifest).unwrap();
        assert_eq!(plan.requested_count(), 4);
        assert_eq!(plan.manifest_permission_count(), 2);
        assert_eq!(plan.manifest_backed_count(), 2);
        assert_eq!(
            plan.missing_manifest_permissions(),
            &[AppPrivacyPermissionKind::ScreenCapture]
        );
        assert_eq!(plan.missing_manifest_count(), 1);
        assert!(plan.requests_accessibility());
        assert!(!plan.manifest_complete());
        assert!(plan.requires_manifest_update());
        assert_eq!(
            plan.to_text(),
            "permission preflight plan: requested 4, manifest permissions 2, manifest backed 2, missing [screen-capture], accessibility true"
        );

        let complete_manifest = AppPrivacyManifestBuilder::new()
            .permission(AppPrivacyPermissionBuilder::camera(
                "Camera access records video notes.",
            ))
            .permission(AppPrivacyPermissionBuilder::microphone(
                "Microphone access records voice notes.",
            ))
            .permission(AppPrivacyPermissionBuilder::screen_capture(
                "Screen capture shares your workspace.",
            ))
            .build_checked()
            .unwrap();
        let complete = request.plan_against_manifest(&complete_manifest).unwrap();
        assert!(complete.manifest_complete());
        assert!(!complete.requires_manifest_update());
        assert_eq!(complete.missing_manifest_count(), 0);
        assert!(complete.to_text().contains("missing [none]"));
    }

    #[test]
    fn permission_preflight_plan_summary_is_content_safe() {
        let request = PermissionRequestBuilder::new()
            .microphone_with_callback(|_| {})
            .camera();
        let manifest = AppPrivacyManifestBuilder::new()
            .permission(AppPrivacyPermissionBuilder::microphone(
                "Secret workspace microphone rationale.",
            ))
            .build_checked()
            .unwrap();

        assert_eq!(
            AppPrivacyManifestBuilder::new()
                .permission(AppPrivacyPermissionBuilder::microphone(
                    "Use the microphone."
                ))
                .to_text(),
            "privacy manifest builder: permissions 1"
        );

        let plan = request.plan_against_manifest(&manifest).unwrap();
        assert_eq!(request.requested_privacy_permissions().len(), 2);
        assert_eq!(plan.missing_manifest_count(), 1);
        assert_eq!(
            plan.missing_manifest_permissions(),
            &[AppPrivacyPermissionKind::Camera]
        );
        assert_eq!(
            request.to_text(),
            "permission request: requested 2, accessibility false, microphone true, camera true, screen capture false, callbacks 1"
        );

        let summary = plan.to_text();
        assert!(summary.contains("permission preflight plan"));
        assert!(summary.contains("camera"));
        assert!(!summary.contains("Secret workspace"));
        assert!(!summary.contains("microphone rationale"));
    }

    #[test]
    fn request_permissions_returns_status_snapshot() {
        let cx = TestAppContext::single();

        let result = cx
            .read(|app| {
                app.request_permissions(
                    PermissionRequestBuilder::new()
                        .accessibility()
                        .microphone()
                        .camera()
                        .screen_capture(),
                )
            })
            .unwrap();

        assert_eq!(result.accessibility, Some(PermissionStatus::Granted));
        assert_eq!(result.microphone, Some(PermissionStatus::Granted));
        assert_eq!(result.camera, Some(PermissionStatus::Granted));
        assert!(matches!(
            result.screen_capture,
            Some(PermissionStatus::Granted | PermissionStatus::Denied)
        ));
        assert!(!result.prompted());
        assert!(!result.has_pending_permission());
        assert!(result.pending_permissions().is_empty());
        assert_eq!(result.requested_permission_count(), 4);
        assert_eq!(result.pending_permission_count(), 0);
        assert_eq!(result.requested_permissions().len(), 4);
        if result.screen_capture == Some(PermissionStatus::Granted) {
            assert!(!result.has_blocking_denial());
            assert!(result.all_granted());
            assert_eq!(result.granted_permission_count(), 4);
            assert_eq!(result.blocking_denial_count(), 0);
            assert_eq!(result.granted_permissions().len(), 4);
            assert_eq!(
                result.granted_summary().as_deref(),
                Some("Accessibility, Microphone, Camera, Screen Capture")
            );
            assert_eq!(
                result.to_text(),
                "permissions: 4 requested permissions, 4 granted permissions, 0 pending permissions, 0 blocking denials, prompted false"
            );
        } else {
            assert!(result.has_blocking_denial());
            assert!(!result.all_granted());
            assert_eq!(result.granted_permission_count(), 3);
            assert_eq!(result.blocking_denial_count(), 1);
            assert_eq!(result.granted_permissions().len(), 3);
            assert_eq!(
                result.granted_summary().as_deref(),
                Some("Accessibility, Microphone, Camera")
            );
            assert_eq!(
                result.to_text(),
                "permissions: 4 requested permissions, 3 granted permissions, 0 pending permissions, 1 blocking denial, prompted false"
            );
        }
    }

    #[test]
    fn permission_request_result_reports_blocking_denials() {
        let result = super::PermissionRequestResult {
            accessibility: Some(PermissionStatus::Denied),
            microphone: Some(PermissionStatus::Granted),
            camera: Some(PermissionStatus::Restricted),
            screen_capture: Some(PermissionStatus::Denied),
            requested_accessibility: false,
            requested_microphone: false,
            requested_camera: false,
        };

        assert!(!result.all_granted());
        assert!(result.has_blocking_denial());
        assert_eq!(result.requested_permission_count(), 4);
        assert_eq!(result.granted_permission_count(), 1);
        assert_eq!(result.pending_permission_count(), 0);
        assert_eq!(result.blocking_denial_count(), 3);
        let denials = result.blocking_denials();
        assert_eq!(denials.len(), 3);
        assert_eq!(denials[0].key, "accessibility");
        assert_eq!(denials[0].label, "Accessibility");
        assert_eq!(denials[0].status, PermissionStatus::Denied);
        assert!(!denials[0].is_restricted());
        assert_eq!(denials[1].key, "camera");
        assert_eq!(denials[1].status, PermissionStatus::Restricted);
        assert!(denials[1].is_restricted());
        assert_eq!(denials[2].key, "screen-capture");
        assert_eq!(denials[2].label, "Screen Capture");
        assert_eq!(denials[2].status, PermissionStatus::Denied);
        assert_eq!(
            result.blocking_denial_summary().as_deref(),
            Some("Accessibility: Denied, Camera: Restricted, Screen Capture: Denied")
        );
        assert_eq!(
            result.to_text(),
            "permissions: 4 requested permissions, 1 granted permission, 0 pending permissions, 3 blocking denials, prompted false"
        );
    }

    #[test]
    fn permission_request_result_reports_pending_permissions() {
        let result = super::PermissionRequestResult {
            accessibility: Some(PermissionStatus::NotDetermined),
            microphone: Some(PermissionStatus::Denied),
            camera: Some(PermissionStatus::Granted),
            screen_capture: None,
            requested_accessibility: true,
            requested_microphone: true,
            requested_camera: false,
        };

        assert!(result.has_pending_permission());
        let pending = result.pending_permissions();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].key, "accessibility");
        assert_eq!(pending[0].status, PermissionStatus::NotDetermined);
        assert_eq!(result.granted_permissions().len(), 1);
        assert_eq!(result.granted_summary().as_deref(), Some("Camera"));
        assert_eq!(result.requested_permission_count(), 3);
        assert_eq!(result.granted_permission_count(), 1);
        assert_eq!(result.pending_permission_count(), 1);
        assert_eq!(result.blocking_denial_count(), 1);
        assert_eq!(
            result.to_text(),
            "permissions: 3 requested permissions, 1 granted permission, 1 pending permission, 1 blocking denial, prompted true"
        );
    }

    #[test]
    fn permission_broker_install_builder_validates_capability_grants() {
        let process_id = ProcessId(42);
        let (broker, report) = PermissionBrokerInstallBuilder::new()
            .process_class(ProcessClass::Worker)
            .grant(Capability::ShellExecute)
            .grant(Capability::Network {
                hosts: vec!["api.example.com".to_string()],
            })
            .prompt_ungranted()
            .build_checked(process_id)
            .unwrap();

        assert_eq!(report.process_id(), process_id);
        assert_eq!(report.process_class(), ProcessClass::Worker);
        assert_eq!(report.prompt_result(), Some(PermissionResult::Prompt));
        assert_eq!(report.default_capability_count(), 2);
        assert_eq!(report.granted_capability_count(), 4);
        assert!(report.has_prompt_policy());
        assert!(report.grants(&Capability::ShellExecute));
        assert_eq!(
            report.to_text(),
            "permission broker process 42 Worker: 2 default capabilities, 4 granted capabilities, prompt policy Prompt"
        );
        assert_eq!(
            broker.check(process_id, &Capability::ShellExecute),
            PermissionResult::Granted
        );
        assert_eq!(
            broker.check(process_id, &Capability::Camera),
            PermissionResult::Prompt
        );

        assert!(
            PermissionBrokerInstallBuilder::new()
                .grant(Capability::Network { hosts: Vec::new() })
                .build_checked(process_id)
                .is_err()
        );
        assert!(
            PermissionBrokerInstallBuilder::new()
                .grant(Capability::Network {
                    hosts: vec!["https://api.example.com".to_string()]
                })
                .build_checked(process_id)
                .is_err()
        );
        assert!(
            PermissionBrokerInstallBuilder::new()
                .grant(Capability::Network {
                    hosts: vec!["api.example.com".to_string(), "API.example.com".to_string()]
                })
                .build_checked(process_id)
                .is_err()
        );

        let too_many_grants = (0..129).map(|index| Capability::Network {
            hosts: vec![format!("host{index}.example.com")],
        });
        assert!(
            PermissionBrokerInstallBuilder::new()
                .grants(too_many_grants)
                .build_checked(process_id)
                .is_err()
        );
    }

    #[test]
    fn security_permission_handoff_validates_policy_requests() {
        let process_id = ProcessId(42);
        let manifest = AppPrivacyManifestBuilder::new()
            .permission(AppPrivacyPermissionBuilder::camera(
                "Camera access records video notes.",
            ))
            .permission(AppPrivacyPermissionBuilder::microphone(
                "Microphone access records voice notes.",
            ))
            .build_checked()
            .unwrap();
        let preflight = PermissionRequestBuilder::capture_studio()
            .plan_against_manifest(&manifest)
            .unwrap();

        let handoff = SecurityPermissionHandoffBuilder::new()
            .permission_broker_install(
                process_id,
                PermissionBrokerInstallBuilder::new()
                    .process_class(ProcessClass::Worker)
                    .grant(Capability::ShellExecute)
                    .grant(Capability::Network {
                        hosts: vec!["api.example.com".into()],
                    })
                    .deny_ungranted(),
            )
            .process_context(ProcessContextBuilder::worker(ProcessId(7)))
            .network_policy(NetworkPolicyBuilder::new().allow_host("api.example.com"))
            .check_capability(process_id, Capability::ShellExecute)
            .runtime_permission_preflight(preflight)
            .hosted_webview_permission("media")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 6);
        assert_eq!(
            handoff.next_action(),
            SecurityPermissionNextAction::InstallPermissionBroker
        );
        assert!(handoff.installs_permission_broker());
        assert!(handoff.configures_process_context());
        assert!(handoff.builds_network_policy());
        assert!(handoff.preflights_runtime_permissions());
        assert!(handoff.uses_hosted_permission_bridge());
        assert_eq!(
            SecurityPermissionNextAction::UseHostedPermissionBridge.key(),
            "use-hosted-permission-bridge"
        );
        assert_eq!(
            handoff.to_text(),
            "security permission handoff: 6 requests, next action install-permission-broker, broker true, process context true, network policy true, runtime preflight true, hosted bridge true"
        );

        let network_handoff = SecurityPermissionHandoffBuilder::new()
            .built_network_policy(NetworkPolicy::AllowList(vec!["cdn.example.com".into()]))
            .build_checked()
            .unwrap();
        assert_eq!(
            network_handoff.next_action(),
            SecurityPermissionNextAction::BuildNetworkPolicy
        );

        assert!(
            SecurityPermissionHandoffBuilder::new()
                .hosted_webview_permission(" media ")
                .build_checked()
                .is_err()
        );
        assert!(
            SecurityPermissionHandoffBuilder::new()
                .check_capability(
                    ProcessId(0),
                    Capability::Network {
                        hosts: vec!["api.example.com".into()]
                    },
                )
                .build_checked()
                .is_err()
        );
        assert!(
            SecurityPermissionHandoffBuilder::new()
                .grant_capability(
                    process_id,
                    Capability::Network {
                        hosts: vec!["https://api.example.com".into()]
                    },
                )
                .build_checked()
                .is_err()
        );
        assert!(
            SecurityPermissionHandoffBuilder::new()
                .build_checked()
                .is_err()
        );
    }

