    #[test]
    fn configure_permission_broker_checked_installs_atomically() {
        let cx = TestAppContext::single();
        let process_id = cx.read(|app| app.current_process_id());

        assert_eq!(
            cx.read(|app| {
                app.permission_broker()
                    .check(process_id, &Capability::ShellExecute)
            }),
            PermissionResult::Denied
        );

        let report = cx
            .update(|app| {
                app.configure_permission_broker_checked(
                    PermissionBrokerInstallBuilder::new()
                        .threat_model(ThreatModel::new())
                        .grant(Capability::ShellExecute)
                        .deny_ungranted(),
                )
            })
            .unwrap();

        assert!(report.grants(&Capability::ShellExecute));
        assert_eq!(report.default_capability_count(), 4);
        assert_eq!(report.granted_capability_count(), 5);
        assert!(report.has_prompt_policy());
        assert_eq!(
            report.to_text(),
            format!(
                "permission broker process {} Ui: 4 default capabilities, 5 granted capabilities, prompt policy Denied",
                process_id.0
            )
        );
        assert_eq!(
            cx.read(|app| {
                app.permission_broker()
                    .check(process_id, &Capability::ShellExecute)
            }),
            PermissionResult::Granted
        );
        assert_eq!(
            cx.read(|app| app
                .permission_broker()
                .check(process_id, &Capability::Camera)),
            PermissionResult::Denied
        );

        assert!(
            cx.update(|app| {
                app.configure_permission_broker_checked(
                    PermissionBrokerInstallBuilder::new().grant(Capability::Network {
                        hosts: vec!["api.example.com/path".to_string()],
                    }),
                )
            })
            .is_err()
        );

        assert_eq!(
            cx.read(|app| {
                app.permission_broker()
                    .check(process_id, &Capability::ShellExecute)
            }),
            PermissionResult::Granted
        );
    }

    #[test]
    fn set_current_process_id_checked_validates_broker_registration() {
        let cx = TestAppContext::single();
        let original_process_id = cx.read(|app| app.current_process_id());
        let worker_process_id = ProcessId(99);

        let missing = cx
            .update(|app| {
                app.set_current_process_id_checked(ProcessContextBuilder::existing(
                    worker_process_id,
                ))
            })
            .unwrap_err()
            .to_string();
        assert!(missing.contains("not registered with the permission broker"));
        assert_eq!(cx.read(|app| app.current_process_id()), original_process_id);

        let report = cx
            .update(|app| {
                app.set_current_process_id_checked(ProcessContextBuilder::worker(worker_process_id))
            })
            .unwrap();
        assert_eq!(report.previous_process_id(), original_process_id);
        assert_eq!(report.process_id(), worker_process_id);
        assert_eq!(report.process_class(), ProcessClass::Worker);
        assert!(report.registered_process());
        assert_eq!(report.granted_capability_count(), 2);
        assert_eq!(
            report.to_text(),
            format!(
                "process context {} -> 99 Worker: registered true, 2 granted capabilities",
                original_process_id.0
            )
        );
        assert_eq!(cx.read(|app| app.current_process_id()), worker_process_id);
        assert_eq!(
            cx.read(|app| app.permission_broker().process_class(worker_process_id)),
            Some(ProcessClass::Worker)
        );

        cx.update(|app| {
            let mut broker = app.permission_broker().clone();
            broker.grant(worker_process_id, Capability::ShellExecute);
            app.set_permission_broker(broker);
        });

        let report = cx
            .update(|app| {
                app.set_current_process_id_checked(ProcessContextBuilder::existing(
                    worker_process_id,
                ))
            })
            .unwrap();
        assert!(!report.registered_process());
        assert!(report.grants(&Capability::ShellExecute));
        assert_eq!(report.granted_capability_count(), 3);
        assert_eq!(
            report.to_text(),
            "process context 99 -> 99 Worker: registered false, 3 granted capabilities"
        );
    }

    #[test]
    fn auto_launch_builder_validates_app_id() {
        assert!(
            AutoLaunchBuilder::enable("com.example.app")
                .validate()
                .is_ok()
        );
        assert!(AutoLaunchBuilder::enable(" ").validate().is_err());
        assert!(
            AutoLaunchBuilder::enable(" com.example.app")
                .validate()
                .is_err()
        );
        assert!(
            AutoLaunchBuilder::enable("com.example.app ")
                .validate()
                .is_err()
        );
        assert!(
            AutoLaunchBuilder::enable("com.example app")
                .validate()
                .is_err()
        );
        assert!(
            AutoLaunchBuilder::enable("com.example\napp")
                .validate()
                .is_err()
        );

        let disabled = AutoLaunchBuilder::enable("com.example.app").enabled(false);
        assert_eq!(disabled.app_id(), "com.example.app");
        assert!(!disabled.requested_enabled());

        let plan = disabled.clone().build_plan_checked().unwrap();
        assert_eq!(plan.app_id(), "com.example.app");
        assert!(!plan.requested_enabled());
        assert!(!plan.enables_launch_at_login());
        assert!(plan.disables_launch_at_login());
        assert_eq!(
            plan.to_text(),
            "auto-launch disable for app id configured true"
        );
        assert!(!plan.to_text().contains("com.example.app"));
        assert_eq!(plan.into_parts(), ("com.example.app".to_string(), false));

        assert_eq!(
            disabled.build_checked().unwrap(),
            ("com.example.app".to_string(), false)
        );
    }

    #[test]
    fn configure_auto_launch_returns_platform_state() {
        let cx = TestAppContext::single();

        let plan = cx
            .read(|app| app.auto_launch_plan_checked(AutoLaunchBuilder::enable("com.example.app")))
            .unwrap();
        assert_eq!(plan.app_id(), "com.example.app");
        assert!(plan.enables_launch_at_login());
        assert_eq!(
            plan.to_text(),
            "auto-launch enable for app id configured true"
        );
        assert!(!plan.to_text().contains("com.example.app"));
        assert!(!cx.read(|app| app.is_auto_launch_enabled("com.example.app")));
        assert!(
            cx.read(|app| app.auto_launch_plan_checked(AutoLaunchBuilder::enable("bad app id")))
                .is_err()
        );

        let enabled = cx
            .read(|app| app.configure_auto_launch(AutoLaunchBuilder::enable("com.example.app")))
            .unwrap();
        assert_eq!(enabled.app_id(), "com.example.app");
        assert!(enabled.enabled());
        assert!(!enabled.disabled());
        assert_eq!(
            enabled.to_text(),
            "auto-launch enabled for app id configured true"
        );
        assert!(!enabled.to_text().contains("com.example.app"));
        assert!(cx.read(|app| app.is_auto_launch_enabled("com.example.app")));

        let disabled = cx
            .read(|app| app.configure_auto_launch(AutoLaunchBuilder::disable("com.example.app")))
            .unwrap();
        assert_eq!(disabled.app_id(), "com.example.app");
        assert!(!disabled.enabled());
        assert!(disabled.disabled());
        assert_eq!(
            disabled.to_text(),
            "auto-launch disabled for app id configured true"
        );
        assert!(!disabled.to_text().contains("com.example.app"));
        assert!(!cx.read(|app| app.is_auto_launch_enabled("com.example.app")));
    }

    #[test]
    fn app_path_builder_validates_roles_and_app_id() {
        let builder = AppPathBuilder::new("com.example.app").app_storage();
        assert!(builder.validate().is_ok());
        assert_eq!(builder.app_id(), "com.example.app");
        assert_eq!(
            builder.configured_roles(),
            &[
                AppPathRole::Data,
                AppPathRole::Config,
                AppPathRole::Cache,
                AppPathRole::Logs,
                AppPathRole::Temp,
            ]
        );
        assert!(!builder.creates_dirs());
        assert_eq!(builder.role_count(), 5);
        assert!(builder.has_role(AppPathRole::Config));
        assert!(!builder.has_role(AppPathRole::Downloads));
        assert_eq!(
            builder.to_text(),
            "app path builder: roles 5, create-dirs false, data true, config true, cache true, logs true, temp true, downloads false"
        );
        assert!(!builder.to_text().contains("com.example.app"));

        assert!(
            AppPathBuilder::new("")
                .role(AppPathRole::Data)
                .validate()
                .is_err()
        );
        assert!(
            AppPathBuilder::new(" com.example.app")
                .role(AppPathRole::Data)
                .validate()
                .is_err()
        );
        assert!(
            AppPathBuilder::new("com.example app")
                .role(AppPathRole::Data)
                .validate()
                .is_err()
        );
        assert!(
            AppPathBuilder::new("com/example/app")
                .role(AppPathRole::Data)
                .validate()
                .is_err()
        );
        assert!(AppPathBuilder::new("com.example.app").validate().is_err());
        assert!(
            AppPathBuilder::new("com.example.app")
                .role(AppPathRole::Data)
                .role(AppPathRole::Data)
                .validate()
                .is_err()
        );
    }

    #[test]
    fn app_path_builder_resolves_common_paths() {
        let set = AppPathBuilder::new("com.example.app")
            .roles([
                AppPathRole::Data,
                AppPathRole::Config,
                AppPathRole::Cache,
                AppPathRole::Logs,
                AppPathRole::Temp,
                AppPathRole::Downloads,
            ])
            .build_checked()
            .unwrap();

        assert_eq!(set.app_id(), "com.example.app");
        assert_eq!(set.paths().len(), 6);
        assert_eq!(set.role_count(), 6);
        assert_eq!(set.app_scoped_role_count(), 5);
        assert_eq!(set.user_global_role_count(), 1);
        assert!(set.has_role(AppPathRole::Downloads));
        assert_eq!(
            set.to_text(),
            "app paths: roles 6, app-scoped 5, user-global 1, data true, config true, cache true, logs true, temp true, downloads true"
        );
        assert!(!set.to_text().contains("com.example.app"));
        assert!(!set.to_text().contains("Downloads"));
        assert!(set.data_dir().unwrap().ends_with("com.example.app"));
        assert!(set.config_dir().unwrap().ends_with("com.example.app"));
        assert!(set.cache_dir().unwrap().ends_with("com.example.app"));
        assert!(
            set.logs_dir()
                .unwrap()
                .to_string_lossy()
                .contains("com.example.app")
        );
        assert!(set.temp_dir().unwrap().ends_with("com.example.app"));
        assert!(set.downloads_dir().unwrap().ends_with("Downloads"));
        assert_eq!(set.get(AppPathRole::Cache), Some(set.cache_dir().unwrap()));
    }

