    #[test]
    fn app_storage_plan_builder_validates_entries_and_resolves_paths() {
        let plan = AppStoragePlanBuilder::new("com.example.app")
            .settings_json("settings", "settings.json")
            .sqlite_database("main-db", "state/app.sqlite")
            .key_value_store("kv", "kv")
            .blob_cache("thumbs", "thumbnails")
            .log_file("main-log", "app.log")
            .temp_workspace("exports", "exports")
            .build_checked()
            .unwrap();

        assert_eq!(plan.app_id(), "com.example.app");
        assert_eq!(plan.entries().len(), 6);
        assert_eq!(plan.entry_count(), 6);
        assert_eq!(plan.durability_count(AppStorageDurability::Durable), 3);
        assert_eq!(plan.durability_count(AppStorageDurability::Rebuildable), 2);
        assert_eq!(plan.durability_count(AppStorageDurability::Temporary), 1);
        assert_eq!(plan.sensitive_count(), 0);
        assert_eq!(plan.quota_count(), 6);
        assert_eq!(
            plan.to_text(),
            format!(
                "app storage plan: entries 6, durable 3, rebuildable 2, temporary 1, sensitive 0, quotas 6, roles 5, required-dirs {}",
                plan.required_directories().len()
            )
        );
        assert!(!plan.to_text().contains("com.example.app"));
        assert!(!plan.to_text().contains("settings"));
        assert!(!plan.to_text().contains("state/app.sqlite"));
        assert!(plan.paths().data_dir().is_some());
        assert!(plan.paths().config_dir().is_some());
        assert!(plan.paths().cache_dir().is_some());
        assert!(plan.paths().logs_dir().is_some());
        assert!(plan.paths().temp_dir().is_some());

        let settings = plan.entry("settings").unwrap();
        assert_eq!(settings.kind(), &AppStorageKind::SettingsJson);
        assert_eq!(settings.durability(), AppStorageDurability::Durable);
        assert_eq!(settings.role(), AppPathRole::Config);
        assert_eq!(settings.relative_path(), Path::new("settings.json"));
        assert!(settings.absolute_path().ends_with("settings.json"));
        assert!(settings.has_max_bytes());
        assert_eq!(
            settings.to_text(),
            "app storage entry: kind settings-json, durability durable, role config, quota true, sensitive false"
        );
        assert!(!settings.to_text().contains("settings.json"));
        assert_eq!(
            settings.write_capability(),
            Capability::FilesystemWrite {
                scope: PathScope::AppData
            }
        );
        assert_eq!(
            settings.read_capability(),
            Capability::FilesystemRead {
                scope: PathScope::AppData
            }
        );

        assert_eq!(
            plan.entries_with_durability(AppStorageDurability::Rebuildable)
                .len(),
            2
        );
        assert!(plan.declared_max_bytes() > 0);
    }

    #[test]
    fn app_storage_plan_can_prepare_required_directories() {
        let app_id = format!("kael-storage-plan-test-{}", std::process::id());
        let plan = AppStoragePlanBuilder::new(&app_id)
            .entry(AppStorageEntryBuilder::new(
                "db",
                AppStorageKind::SqliteDatabase,
                AppPathRole::Temp,
                "state/app.sqlite",
            ))
            .entry(AppStorageEntryBuilder::new(
                "kv",
                AppStorageKind::KeyValueStore,
                AppPathRole::Temp,
                "stores/kv",
            ))
            .build_checked()
            .unwrap();

        let temp_root = plan.paths().temp_dir().unwrap().to_path_buf();
        assert!(
            plan.entry("db")
                .unwrap()
                .required_directory()
                .ends_with("state")
        );
        assert!(
            plan.entry("kv")
                .unwrap()
                .required_directory()
                .ends_with("stores/kv")
        );

        let directories = plan.required_directories();
        assert!(directories.iter().any(|path| path == &temp_root));
        assert!(directories.iter().any(|path| path.ends_with("state")));
        assert!(directories.iter().any(|path| path.ends_with("stores/kv")));

        plan.ensure_directories_checked().unwrap();
        assert!(temp_root.is_dir());
        assert!(temp_root.join("state").is_dir());
        assert!(temp_root.join("stores/kv").is_dir());

        std::fs::remove_dir_all(temp_root).unwrap();
    }

    #[test]
    fn app_storage_plan_builder_rejects_unsafe_storage_contracts() {
        assert!(
            AppStoragePlanBuilder::new("")
                .settings_json("settings", "settings.json")
                .validate()
                .is_err()
        );
        assert!(
            AppStoragePlanBuilder::new("com.example.app")
                .validate()
                .is_err()
        );
        assert!(
            AppStoragePlanBuilder::new("com.example.app")
                .settings_json("settings", "settings.json")
                .settings_json("settings", "other.json")
                .validate()
                .is_err()
        );
        assert!(
            AppStoragePlanBuilder::new("com.example.app")
                .entry(AppStorageEntryBuilder::settings_json(
                    "bad/id",
                    "settings.json"
                ))
                .validate()
                .is_err()
        );
        assert!(
            AppStoragePlanBuilder::new("com.example.app")
                .entry(AppStorageEntryBuilder::settings_json(
                    "settings",
                    "../settings.json"
                ))
                .validate()
                .is_err()
        );
        assert!(
            AppStoragePlanBuilder::new("com.example.app")
                .entry(AppStorageEntryBuilder::new(
                    "downloads",
                    AppStorageKind::Custom("download-export".into()),
                    AppPathRole::Downloads,
                    "file.bin",
                ))
                .validate()
                .is_err()
        );
        assert!(
            AppStoragePlanBuilder::new("com.example.app")
                .entry(
                    AppStorageEntryBuilder::settings_json("settings", "settings.json").max_bytes(0)
                )
                .validate()
                .is_err()
        );
    }

