    #[test]
    fn storage_migration_plan_builder_validates_path_and_schema_steps() {
        let plan = StorageMigrationPlanBuilder::new("com.example.app")
            .move_path(
                "move-cache",
                1,
                2,
                AppPathRole::Cache,
                "old/thumbs",
                AppPathRole::Cache,
                "new/thumbs",
            )
            .rewrite_in_place("settings-v2", 2, 3, AppPathRole::Config, "settings.json")
            .build_checked()
            .unwrap();

        assert_eq!(plan.app_id(), "com.example.app");
        assert_eq!(plan.step_count(), 2);
        assert_eq!(plan.backup_count(), 2);
        assert!(!plan.crosses_roles());
        assert_eq!(
            plan.to_text(),
            "storage migration plan: 2 steps, 2 backups, crosses roles false"
        );
        assert!(!plan.to_text().contains("com.example.app"));
        assert!(!plan.to_text().contains("old/thumbs"));
        assert!(!plan.to_text().contains("settings-v2"));
        assert!(!plan.to_text().contains('1'));

        let first = &plan.steps()[0];
        assert_eq!(first.id(), "move-cache");
        assert_eq!(first.kind(), StorageMigrationKind::MovePath);
        assert_eq!(first.from_version(), 1);
        assert_eq!(first.to_version(), 2);
        assert_eq!(first.source_role(), AppPathRole::Cache);
        assert_eq!(first.source_path(), Path::new("old/thumbs"));
        assert_eq!(first.target_role(), AppPathRole::Cache);
        assert_eq!(first.target_path(), Path::new("new/thumbs"));
        assert!(first.backup_required());
        assert_eq!(
            first.to_text(),
            "storage migration step: kind move-path, source role cache, target role cache, backup true, version change true"
        );
        assert!(!first.to_text().contains("old/thumbs"));
        assert!(!first.to_text().contains("move-cache"));

        assert!(
            StorageMigrationPlanBuilder::new("")
                .rewrite_in_place("settings", 1, 2, AppPathRole::Config, "settings.json")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .rewrite_in_place("same", 1, 2, AppPathRole::Config, "settings.json")
                .rewrite_in_place("same", 2, 3, AppPathRole::Config, "other.json")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .rewrite_in_place("zero", 0, 1, AppPathRole::Config, "settings.json")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .rewrite_in_place("backward", 3, 2, AppPathRole::Config, "settings.json")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .rewrite_in_place("parent", 1, 2, AppPathRole::Config, "../settings.json")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .rewrite_in_place("downloads", 1, 2, AppPathRole::Downloads, "settings.json")
                .validate()
                .is_err()
        );
        assert!(
            StorageMigrationPlanBuilder::new("com.example.app")
                .move_path(
                    "same-path",
                    1,
                    2,
                    AppPathRole::Cache,
                    "thumbs",
                    AppPathRole::Cache,
                    "thumbs",
                )
                .validate()
                .is_err()
        );
    }

    #[test]
    fn storage_cleanup_plan_builder_validates_cleanup_targets() {
        let plan = StorageCleanupPlanBuilder::new("com.example.app")
            .cache("thumbs", "thumbnails")
            .logs("logs", "app.log")
            .temporary("exports", "exports")
            .target(
                StorageCleanupTargetBuilder::orphaned(
                    "old-settings",
                    AppPathRole::Config,
                    "old/settings.json",
                )
                .include_sensitive(),
            )
            .apply()
            .build_checked()
            .unwrap();

        assert_eq!(plan.app_id(), "com.example.app");
        assert_eq!(plan.target_count(), 4);
        assert!(!plan.is_dry_run());
        assert_eq!(plan.sensitive_target_count(), 1);
        assert_eq!(
            plan.to_text(),
            "storage cleanup plan: 4 targets, dry run false, sensitive targets 1"
        );
        assert!(!plan.to_text().contains("com.example.app"));
        assert!(!plan.to_text().contains("thumbnails"));
        assert!(!plan.to_text().contains("old-settings"));

        let cache = &plan.targets()[0];
        assert_eq!(cache.id(), "thumbs");
        assert_eq!(cache.kind(), &StorageCleanupKind::Cache);
        assert_eq!(cache.role(), AppPathRole::Cache);
        assert_eq!(cache.relative_path(), Path::new("thumbnails"));
        assert!(!cache.include_sensitive());
        assert_eq!(
            cache.to_text(),
            "storage cleanup target: kind cache, role cache, sensitive false"
        );
        assert!(!cache.to_text().contains("thumbs"));
        assert!(!cache.to_text().contains("thumbnails"));

        let builder = StorageCleanupPlanBuilder::new("com.example.app")
            .cache("thumbs", "thumbnails")
            .dry_run();
        assert_eq!(builder.target_count(), 1);
        assert_eq!(
            builder.to_text(),
            "storage cleanup plan builder: 1 targets, dry run true"
        );

        assert!(
            StorageCleanupPlanBuilder::new("")
                .cache("thumbs", "thumbnails")
                .validate()
                .is_err()
        );
        assert!(
            StorageCleanupPlanBuilder::new("com.example.app")
                .validate()
                .is_err()
        );
        assert!(
            StorageCleanupPlanBuilder::new("com.example.app")
                .cache("same", "thumbnails")
                .logs("same", "app.log")
                .validate()
                .is_err()
        );
        assert!(
            StorageCleanupPlanBuilder::new("com.example.app")
                .cache("parent", "../thumbnails")
                .validate()
                .is_err()
        );
        assert!(
            StorageCleanupPlanBuilder::new("com.example.app")
                .orphaned("downloads", AppPathRole::Downloads, "old.bin")
                .validate()
                .is_err()
        );
        assert!(
            StorageCleanupPlanBuilder::new("com.example.app")
                .target(StorageCleanupTargetBuilder::new(
                    "bad-role",
                    StorageCleanupKind::Cache,
                    AppPathRole::Data,
                    "cache",
                ))
                .validate()
                .is_err()
        );
        assert!(
            StorageCleanupPlanBuilder::new("com.example.app")
                .target(StorageCleanupTargetBuilder::new(
                    "bad-kind",
                    StorageCleanupKind::Custom("bad kind".into()),
                    AppPathRole::Data,
                    "data",
                ))
                .validate()
                .is_err()
        );
    }

