    #[test]
    fn app_storage_session_handoff_guides_paths_storage_migration_cleanup_and_hosted_profiles() {
        let paths = AppStorageSessionHandoffBuilder::app_paths("com.example.kael");
        assert_eq!(
            paths.next_action(),
            AppStorageSessionNextAction::ResolveAppPaths
        );
        assert!(paths.validate().is_ok());
        assert_eq!(
            paths.to_text(),
            "app storage session handoff builder: app storage session request: action resolve-app-paths, app path builder: roles 5, create-dirs false, data true, config true, cache true, logs true, temp true, downloads false"
        );
        assert!(!paths.to_text().contains("com.example.kael"));

        let paths = paths.build_checked().unwrap();
        assert!(paths.is_paths());
        assert_eq!(
            paths.next_action(),
            AppStorageSessionNextAction::ResolveAppPaths
        );
        assert_eq!(paths.path_builder().unwrap().role_count(), 5);

        let storage = AppStorageSessionHandoff::storage_plan(
            AppStoragePlanBuilder::new("com.example.kael")
                .settings_json("settings", "settings.json")
                .blob_cache("thumbs", "thumbs"),
        )
        .unwrap();
        assert!(storage.is_storage_plan());
        assert_eq!(
            storage.next_action(),
            AppStorageSessionNextAction::PrepareStoragePlan
        );
        assert_eq!(storage.storage_plan_builder().unwrap().entry_count(), 2);
        assert!(!storage.to_text().contains("settings.json"));
        assert!(!storage.to_text().contains("thumbs"));

        let migration = AppStorageSessionHandoff::migration(
            StorageMigrationPlanBuilder::new("com.example.kael").rewrite_in_place(
                "settings-v2",
                1,
                2,
                AppPathRole::Config,
                "settings.json",
            ),
        )
        .unwrap();
        assert!(migration.is_migration());
        assert_eq!(
            migration.next_action(),
            AppStorageSessionNextAction::RunStorageMigration
        );
        assert_eq!(migration.migration_builder().unwrap().step_count(), 1);
        assert!(!migration.to_text().contains("settings-v2"));
        assert!(!migration.to_text().contains("settings.json"));

        let cleanup = AppStorageSessionHandoff::cleanup(
            StorageCleanupPlanBuilder::new("com.example.kael")
                .cache("thumbs", "thumbs")
                .apply(),
        )
        .unwrap();
        assert!(cleanup.is_cleanup());
        assert_eq!(
            cleanup.next_action(),
            AppStorageSessionNextAction::RunStorageCleanup
        );
        assert_eq!(cleanup.cleanup_builder().unwrap().target_count(), 1);
        assert!(!cleanup.to_text().contains("thumbs"));

        let hosted = AppStorageSessionHandoff::hosted_profile_storage("auth-profile").unwrap();
        assert!(hosted.is_hosted_profile_storage());
        assert_eq!(
            hosted.next_action(),
            AppStorageSessionNextAction::UseHostedProfileStorage
        );
        assert_eq!(hosted.hosted_profile_id(), Some("auth-profile"));
        assert_eq!(
            AppStorageSessionNextAction::UseHostedProfileStorage.key(),
            "use-hosted-profile-storage"
        );
        assert!(!hosted.to_text().contains("auth-profile"));
    }

