    #[test]
    fn app_storage_session_handoff_checked_uses_builder_validation() {
        let cx = TestAppContext::single();

        let storage = cx
            .read(|app| {
                app.app_storage_session_handoff_checked(
                    AppStorageSessionHandoffBuilder::storage_plan(
                        AppStoragePlanBuilder::new("com.example.kael")
                            .settings_json("settings", "settings.json")
                            .blob_cache("thumbs", "thumbs"),
                    ),
                )
            })
            .unwrap();
        assert!(storage.is_storage_plan());
        assert_eq!(
            storage.next_action(),
            AppStorageSessionNextAction::PrepareStoragePlan
        );

        let hosted = cx
            .read(|app| {
                app.app_storage_session_handoff_checked(
                    AppStorageSessionHandoffBuilder::hosted_profile_storage("auth-profile"),
                )
            })
            .unwrap();
        assert!(hosted.is_hosted_profile_storage());
        assert_eq!(
            hosted.next_action(),
            AppStorageSessionNextAction::UseHostedProfileStorage
        );

        assert!(
            cx.read(|app| {
                app.app_storage_session_handoff_checked(
                    AppStorageSessionHandoffBuilder::storage_plan(AppStoragePlanBuilder::new(
                        "com.example.kael",
                    )),
                )
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                app.app_storage_session_handoff_checked(
                    AppStorageSessionHandoffBuilder::hosted_profile_storage("bad profile"),
                )
            })
            .is_err()
        );
    }

    #[test]
    fn browser_profile_storage_bridge_routes_browser_profile_state() {
        let plan = BrowserProfileStorageBridgePlanBuilder::new("com.example.kael")
            .native_storage_plan(
                AppStoragePlanBuilder::new("com.example.kael")
                    .settings_json("settings", "settings.json")
                    .sqlite_database("workspace-index", "state/index.sqlite"),
            )
            .cleanup_plan(
                StorageCleanupPlanBuilder::new("com.example.kael")
                    .cache("http-cache", "webview-http-cache"),
            )
            .hosted_profile_id("auth-profile")
            .local_storage_to_native("settings")
            .indexed_db_to_native("workspace-index")
            .cookies_to_secure_credentials("refresh-cookie")
            .auth_session_hosted("oauth-session")
            .http_cache_cleanup("cache-reset")
            .build_checked()
            .unwrap();

        assert_eq!(plan.item_count(), 5);
        assert_eq!(
            plan.next_action(),
            BrowserProfileStorageNextAction::PrepareNativeStorage
        );
        assert!(plan.has_native_storage());
        assert!(plan.has_secure_credentials());
        assert!(plan.has_hosted_profile_storage());
        assert!(plan.has_cleanup());
        assert_eq!(plan.sensitive_count(), 1);
        assert_eq!(plan.migration_count(), 2);
        assert!(plan.native_storage().is_some());
        assert!(plan.cleanup().is_some());
        assert_eq!(plan.hosted_profile_id(), Some("auth-profile"));
        assert_eq!(
            plan.destination_count(BrowserProfileStorageDestination::NativeStorage),
            2
        );
        assert_eq!(
            plan.to_text(),
            "browser profile storage bridge: items 5, native 2, secure 1, hosted 1, cleanup 1, browser island 0, roadmap 0, sensitive 1, migrations 2, next action prepare-native-storage"
        );
        assert!(!plan.to_text().contains("com.example.kael"));
        assert!(!plan.to_text().contains("auth-profile"));
        assert!(!plan.to_text().contains("settings"));
        assert!(!plan.to_text().contains("refresh-cookie"));
    }

