    #[test]
    fn file_dialog_handoff_guides_open_save_path_prompt_and_hosted_picker() {
        let path_prompt = PathPromptOptions {
            files: true,
            directories: true,
            multiple: false,
            prompt: Some("Choose workspace".into()),
            filters: Vec::new(),
        };

        let handoff = FileDialogHandoffBuilder::new()
            .open(
                OpenDialogBuilder::files()
                    .image_files()
                    .filter("Markdown", ["md", "markdown"])
                    .prompt("Open"),
            )
            .save(
                SaveDialogBuilder::new(std::env::current_dir().unwrap())
                    .suggested_name("document")
                    .text(),
            )
            .path_prompt(path_prompt)
            .hosted_file_picker("workspace-picker")
            .roadmap_work("native save-as accessory views")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 5);
        assert_eq!(handoff.next_action(), FileDialogNextAction::ShowOpenDialog);
        assert!(handoff.has_open_dialog());
        assert!(handoff.has_save_dialog());
        assert!(handoff.has_path_prompt());
        assert!(handoff.has_hosted_file_picker());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.to_text(),
            "file dialog handoff: 5 requests, open true, save true, path prompt true, hosted picker true, roadmap true, next ShowOpenDialog"
        );
        assert!(!handoff.to_text().contains("Markdown"));
        assert!(!handoff.to_text().contains("document"));
        assert!(!handoff.to_text().contains("workspace-picker"));
        assert!(!handoff.to_text().contains("accessory"));
    }

