    #[test]
    fn app_metadata_builder_validates_identity_fields() {
        let metadata = AppMetadataBuilder::new("Kael Studio")
            .version("1.2.3")
            .build("2026.07.01")
            .identifier("com.example.kael")
            .website_url("https://example.com")
            .support_url("https://example.com/support")
            .copyright("Copyright 2026 Example")
            .license("Apache-2.0")
            .credits("Built with Kael")
            .build_checked()
            .unwrap();

        assert_eq!(metadata.name(), "Kael Studio");
        assert_eq!(metadata.version(), Some("1.2.3"));
        assert_eq!(metadata.build(), Some("2026.07.01"));
        assert_eq!(metadata.identifier(), Some("com.example.kael"));
        assert_eq!(metadata.website_url(), Some("https://example.com"));
        assert_eq!(metadata.support_url(), Some("https://example.com/support"));
        assert_eq!(metadata.display_title(), "Kael Studio 1.2.3");
        let summary = metadata.summary();
        assert_eq!(summary.display_title(), "Kael Studio 1.2.3");
        assert_eq!(summary.optional_field_count(), 8);
        assert!(summary.has_recommended_identity());
        assert!(summary.has_version());
        assert!(summary.has_identifier());
        assert!(summary.has_support_url());
        assert!(summary.has_website_url());
        assert!(summary.has_support_links());
        assert!(summary.missing_recommended_fields().is_empty());
        assert_eq!(
            summary.to_text(),
            "Kael Studio 1.2.3: 8 optional fields, missing recommended [none]"
        );

        let minimal = AppMetadataBuilder::new("Kael").build_checked().unwrap();
        let summary = minimal.summary();
        assert_eq!(
            summary.missing_recommended_fields(),
            &["version", "identifier", "support_url"]
        );
        assert!(!summary.has_recommended_identity());
        assert_eq!(
            summary.to_text(),
            "Kael: 0 optional fields, missing recommended [version, identifier, support_url]"
        );

        assert!(AppMetadataBuilder::new("").validate().is_err());
        assert!(AppMetadataBuilder::new(" Kael").validate().is_err());
        assert!(
            AppMetadataBuilder::new("Kael")
                .version("1.0\nbad")
                .validate()
                .is_err()
        );
        assert!(
            AppMetadataBuilder::new("Kael")
                .identifier("com/example/kael")
                .validate()
                .is_err()
        );
        assert!(
            AppMetadataBuilder::new("Kael")
                .website_url("file:///tmp/app")
                .validate()
                .is_err()
        );
        assert!(
            AppMetadataBuilder::new("Kael")
                .support_url("https://")
                .validate()
                .is_err()
        );
    }

