    #[test]
    fn message_dialog_handoff_builder_validates_prompt_stack() {
        let handoff = MessageDialogHandoffBuilder::new()
            .message(MessageDialogBuilder::info(
                "Export Complete",
                "The export finished.",
            ))
            .confirm(MessageDialogBuilder::confirm(
                "Close Window?",
                "Close this project window?",
            ))
            .destructive_confirm(MessageDialogBuilder::destructive_confirm(
                "Delete Draft?",
                "This cannot be undone.",
                "Delete",
            ))
            .unsaved_changes(MessageDialogBuilder::save_discard_cancel(
                "Save changes?",
                "This document has unsaved changes.",
            ))
            .about(
                AppMetadataBuilder::new("Kael Studio")
                    .version("1.2.3")
                    .identifier("com.example.kael"),
            )
            .hosted_browser_dialog("checkout-beforeunload")
            .roadmap_work("localized button roles")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 7);
        assert_eq!(
            handoff.next_action(),
            MessageDialogNextAction::ShowNativeMessage
        );
        assert!(handoff.has_message());
        assert!(handoff.has_confirm());
        assert!(handoff.has_destructive_confirm());
        assert!(handoff.has_unsaved_changes_prompt());
        assert!(handoff.has_about_dialog());
        assert!(handoff.uses_hosted_browser_dialog());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            MessageDialogNextAction::UseHostedBrowserDialog.key(),
            "use-hosted-browser-dialog"
        );

        let text = handoff.to_text();
        assert!(text.contains("message dialog handoff: 7 requests"));
        assert!(text.contains("next action show-native-message"));
        assert!(text.contains("destructive-confirm:1"));
        assert!(!text.contains("Export Complete"));
        assert!(!text.contains("Delete Draft"));
        assert!(!text.contains("Delete"));
        assert!(!text.contains("Kael Studio"));
        assert!(!text.contains("checkout-beforeunload"));
        assert!(!text.contains("localized button roles"));
    }

