    #[test]
    fn launch_argument_policy_classifies_startup_args_safely() {
        let launch = LaunchContextSnapshot {
            process_id: 7,
            executable_path: Some(PathBuf::from("/Applications/Kael.app/kael")),
            current_dir: Some(PathBuf::from("/tmp")),
            args: vec![
                "kael".into(),
                "--profile=dev".into(),
                "kael://open/document".into(),
                "/Users/example/report.kael".into(),
                "opaque-token".into(),
            ],
            environment: Vec::new(),
            debug_build: true,
        };

        let policy = LaunchArgumentPolicyBuilder::new()
            .flag("--profile=dev")
            .url_scheme("kael")
            .allow_file_paths()
            .allow_opaque_tokens()
            .build_checked()
            .unwrap();
        let report = policy.classify_snapshot(&launch).unwrap();
        assert_eq!(report.argument_count(), 4);
        assert_eq!(report.flag_count(), 1);
        assert_eq!(report.url_count(), 1);
        assert_eq!(report.file_path_count(), 1);
        assert_eq!(report.opaque_token_count(), 1);
        assert!(!report.to_text().contains("opaque-token"));
        assert!(!policy.to_text().contains("--profile=dev"));

        assert!(
            LaunchArgumentPolicyBuilder::new()
                .flag("profile")
                .build_checked()
                .is_err()
        );
        assert!(
            LaunchArgumentPolicyBuilder::new()
                .url_scheme("bad scheme")
                .build_checked()
                .is_err()
        );
        assert!(
            LaunchArgumentPolicyBuilder::new()
                .flag("--profile=dev")
                .build_checked()
                .unwrap()
                .classify_snapshot(&launch)
                .is_err()
        );
    }

    #[test]
    fn launch_environment_allowlist_and_diagnostics_are_redacted() {
        let launch = LaunchContextSnapshot {
            process_id: 9,
            executable_path: Some(PathBuf::from("/Applications/Kael.app/kael")),
            current_dir: Some(PathBuf::from("/tmp")),
            args: vec!["kael".into(), "--safe-mode".into()],
            environment: vec![
                ("APP_CHANNEL".into(), "nightly".into()),
                ("SECRET_TOKEN".into(), "super-secret".into()),
            ],
            debug_build: true,
        };

        let allowlist = LaunchEnvironmentAllowlistBuilder::new()
            .keys(["APP_CHANNEL", "KAEL_PROFILE"])
            .build_checked()
            .unwrap();
        let env = allowlist.summarize_snapshot(&launch).unwrap();
        assert_eq!(env.allowlisted_key_count(), 2);
        assert_eq!(env.present_count(), 1);
        assert_eq!(env.missing_count(), 1);
        assert_eq!(env.denied_count(), 1);
        assert!(!env.to_text().contains("APP_CHANNEL"));
        assert!(!env.to_text().contains("super-secret"));

        let args = LaunchArgumentPolicyBuilder::new()
            .flag("--safe-mode")
            .build_checked()
            .unwrap()
            .classify_snapshot(&launch)
            .unwrap();
        let payload = DuplicateLaunchPayload::from_launch(
            &launch,
            &LaunchArgumentPolicyBuilder::new()
                .flag("--safe-mode")
                .build_checked()
                .unwrap(),
            &allowlist,
            StartupMode::Development,
        )
        .unwrap();
        let handoff = DuplicateLaunchHandoff::new(payload.clone()).without_document_restore();
        assert!(handoff.activates_existing_window());
        assert!(!handoff.restores_documents());
        assert_eq!(handoff.payload().startup_mode(), StartupMode::Development);
        assert!(!handoff.to_text().contains("SECRET_TOKEN"));
        assert!(!handoff.to_text().contains("--safe-mode"));

        let diagnostics = StartupDiagnosticBuilder::new(StartupMode::Development)
            .argument_report(args)
            .environment_snapshot(env)
            .duplicate_launch(handoff)
            .build_checked()
            .unwrap();
        assert_eq!(diagnostics.mode(), StartupMode::Development);
        assert!(diagnostics.argument_report().is_some());
        assert!(diagnostics.environment_snapshot().is_some());
        assert!(diagnostics.duplicate_launch().is_some());
        assert!(!diagnostics.to_text().contains("APP_CHANNEL"));
        assert!(!diagnostics.to_text().contains("nightly"));

        assert!(
            LaunchEnvironmentAllowlistBuilder::new()
                .key("APP_CHANNEL")
                .key("APP_CHANNEL")
                .build_checked()
                .is_err()
        );
    }

