    #[test]
    fn launch_environment_handoff_builder_validates_full_startup_stack() {
        let launch = test_launch_snapshot();
        let arg_policy = LaunchArgumentPolicyBuilder::new()
            .flag("--safe-mode")
            .url_scheme("kael")
            .build_checked()
            .unwrap();
        let env_policy = LaunchEnvironmentAllowlistBuilder::new()
            .key("APP_CHANNEL")
            .build_checked()
            .unwrap();
        let env_snapshot = env_policy.summarize_snapshot(&launch).unwrap();
        let duplicate = DuplicateLaunchPayload::from_launch(
            &launch,
            &arg_policy,
            &env_policy,
            StartupMode::Development,
        )
        .map(DuplicateLaunchHandoff::new)
        .unwrap();
        let diagnostics = StartupDiagnosticBuilder::new(StartupMode::Development)
            .argument_report(arg_policy.classify_snapshot(&launch).unwrap())
            .environment_snapshot(env_snapshot.clone())
            .duplicate_launch(duplicate.clone());

        let handoff = LaunchEnvironmentHandoffBuilder::new()
            .launch_context(
                LaunchContextBuilder::new()
                    .environment_key("APP_CHANNEL")
                    .require_current_dir(),
            )
            .argument_policy(
                LaunchArgumentPolicyBuilder::new()
                    .flag("--safe-mode")
                    .url_scheme("kael"),
            )
            .environment_allowlist(LaunchEnvironmentAllowlistBuilder::new().key("APP_CHANNEL"))
            .environment_snapshot(env_snapshot)
            .duplicate_launch(duplicate)
            .startup_diagnostics(diagnostics)
            .hosted_startup_state("browser-startup-state")
            .roadmap_work("deep-link startup normalization")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 8);
        assert!(handoff.has_launch_context());
        assert!(handoff.has_argument_policy());
        assert!(handoff.has_environment_policy());
        assert!(handoff.has_duplicate_launch());
        assert!(handoff.has_startup_diagnostics());
        assert!(handoff.has_hosted_startup_state());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            LaunchEnvironmentNextAction::CaptureLaunchContext
        );

        let text = handoff.to_text();
        assert!(text.contains("launch environment handoff"));
        assert!(text.contains("launch-context"));
        assert!(text.contains("hosted-startup-state"));
        assert!(!text.contains("APP_CHANNEL"));
        assert!(!text.contains("SECRET_TOKEN"));
        assert!(!text.contains("nightly"));
        assert!(!text.contains("--safe-mode"));
        assert!(!text.contains("kael://"));
        assert!(!text.contains("browser-startup-state"));
        assert!(!text.contains("deep-link startup normalization"));
    }

