    #[test]
    fn launch_environment_handoff_next_action_covers_routes() {
        let env_snapshot = LaunchEnvironmentAllowlistBuilder::new()
            .key("APP_CHANNEL")
            .build_checked()
            .unwrap()
            .summarize_snapshot(&test_launch_snapshot())
            .unwrap();
        let cases = [
            (
                LaunchEnvironmentHandoffBuilder::new()
                    .launch_context(LaunchContextBuilder::new().without_args()),
                LaunchEnvironmentNextAction::CaptureLaunchContext,
            ),
            (
                LaunchEnvironmentHandoffBuilder::new()
                    .argument_policy(LaunchArgumentPolicyBuilder::new().allow_file_paths()),
                LaunchEnvironmentNextAction::ValidateArgumentPolicy,
            ),
            (
                LaunchEnvironmentHandoffBuilder::new().environment_snapshot(env_snapshot),
                LaunchEnvironmentNextAction::ValidateEnvironmentPolicy,
            ),
            (
                LaunchEnvironmentHandoffBuilder::new()
                    .duplicate_launch(test_launch_duplicate_handoff()),
                LaunchEnvironmentNextAction::RouteDuplicateLaunch,
            ),
            (
                LaunchEnvironmentHandoffBuilder::new()
                    .startup_diagnostics(StartupDiagnosticBuilder::new(StartupMode::Test)),
                LaunchEnvironmentNextAction::RecordStartupDiagnostics,
            ),
            (
                LaunchEnvironmentHandoffBuilder::new().hosted_startup_state("startup-state"),
                LaunchEnvironmentNextAction::UseHostedStartupState,
            ),
            (
                LaunchEnvironmentHandoffBuilder::new().roadmap_work("startup source recipes"),
                LaunchEnvironmentNextAction::TrackRoadmapWork,
            ),
        ];

        for (builder, expected) in cases {
            let handoff = builder.build_checked().unwrap();
            assert_eq!(handoff.next_action(), expected);
        }
    }

