    #[test]
    fn form_validation_handoff_builder_validates_native_form_surface() {
        let handoff = FormValidationHandoff::builder()
            .field(
                FormFieldDescriptorBuilder::new("email", FormFieldKind::Email)
                    .label("Email address")
                    .required(),
            )
            .field(
                FormFieldDescriptorBuilder::new("plan", FormFieldKind::Select)
                    .label("Plan")
                    .option_count(3),
            )
            .text_checking(
                TextCheckingRequestBuilder::new("helo world")
                    .locale("en_US")
                    .check_grammar(),
            )
            .submit("signup")
            .reset("signup")
            .autofill_policy("signup", false)
            .hosted_form_bridge("checkout")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 7);
        assert!(handoff.has_native_fields());
        assert!(handoff.has_text_checking());
        assert!(handoff.has_autofill_policy());
        assert!(handoff.has_hosted_form_bridge());
        assert_eq!(
            handoff.next_action(),
            FormValidationNextAction::ValidateNativeFields
        );
        assert!(handoff.to_text().contains("form validation handoff"));
        assert!(handoff.to_text().contains("hosted-form-bridge"));
        assert!(!handoff.to_text().contains("helo world"));
        assert!(!handoff.to_text().contains("Email address"));

        let field = match &handoff.requests()[0] {
            FormValidationRequest::Field(field) => field,
            request => panic!("unexpected request {request:?}"),
        };
        assert_eq!(field.id(), "email");
        assert_eq!(field.kind(), FormFieldKind::Email);
        assert!(field.is_required());
    }

    #[test]
    fn native_form_schema_builder_validates_wizard_and_policy() {
        let schema = NativeFormSchema::builder("signup")
            .field(
                FormFieldDescriptorBuilder::new("email", FormFieldKind::Email)
                    .label("Email address")
                    .required(),
            )
            .field(
                FormFieldDescriptorBuilder::new("plan", FormFieldKind::Select)
                    .label("Plan")
                    .option_count(3),
            )
            .step("account", ["email"])
            .step("billing", ["plan"])
            .dirty_state_tracking()
            .disable_submit_until_valid()
            .autofill_enabled(false)
            .build_checked()
            .unwrap();

        assert_eq!(schema.form_id(), "signup");
        assert_eq!(schema.field_count(), 2);
        assert_eq!(schema.step_count(), 2);
        assert!(schema.has_wizard_steps());
        assert!(schema.tracks_dirty_state());
        assert!(schema.disables_submit_until_valid());
        assert_eq!(schema.autofill_enabled(), Some(false));
        assert_eq!(
            schema.to_text(),
            "native form schema: fields=2 steps=2 dirty_state=true disable_submit_until_valid=true autofill_policy=true wizard=true"
        );
        assert!(!schema.to_text().contains("signup"));
        assert!(!schema.to_text().contains("Email address"));

        let handoff = schema
            .validation_handoff_builder()
            .submit(schema.form_id())
            .build_checked()
            .unwrap();
        assert_eq!(handoff.request_count(), 4);
        assert_eq!(
            handoff.next_action(),
            FormValidationNextAction::ValidateNativeFields
        );
        assert!(handoff.has_native_fields());
        assert!(handoff.has_autofill_policy());
    }

    #[test]
    fn native_form_schema_builder_rejects_invalid_generated_schemas() {
        assert!(NativeFormSchemaBuilder::new("signup").validate().is_err());
        assert!(
            NativeFormSchemaBuilder::new("bad form id")
                .field(
                    FormFieldDescriptorBuilder::new("email", FormFieldKind::Email).label("Email")
                )
                .validate()
                .is_err()
        );
        assert!(
            NativeFormSchemaBuilder::new("signup")
                .field(
                    FormFieldDescriptorBuilder::new("email", FormFieldKind::Email).label("Email")
                )
                .field(
                    FormFieldDescriptorBuilder::new("email", FormFieldKind::Text)
                        .label("Email again")
                )
                .validate()
                .is_err()
        );
        assert!(
            NativeFormSchemaBuilder::new("signup")
                .field(
                    FormFieldDescriptorBuilder::new("email", FormFieldKind::Email).label("Email")
                )
                .step("account", ["missing"])
                .validate()
                .is_err()
        );
        assert!(
            NativeFormSchemaBuilder::new("signup")
                .field(
                    FormFieldDescriptorBuilder::new("email", FormFieldKind::Email).label("Email")
                )
                .step("account", Vec::<&str>::new())
                .validate()
                .is_err()
        );
        assert!(
            NativeFormSchemaBuilder::new("signup")
                .field(FormFieldDescriptorBuilder::new("plan", FormFieldKind::Select).label("Plan"))
                .validate()
                .is_err()
        );
    }

