    #[test]
    fn find_zoom_handoff_builder_validates_native_document_tools() {
        let handoff = FindZoomHandoff::builder()
            .search_with_options("private query", true, true, true)
            .result_summary(12, Some(3))
            .next_result()
            .previous_result()
            .clear_selection()
            .custom_scale(1.25, true)
            .fit_width()
            .hosted_find_zoom_bridge("docs")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 8);
        assert!(handoff.has_native_search());
        assert!(handoff.has_result_navigation());
        assert!(handoff.has_native_zoom());
        assert!(handoff.has_hosted_find_zoom_bridge());
        assert_eq!(
            handoff.next_action(),
            FindZoomNextAction::SearchNativeDocument
        );
        assert!(handoff.to_text().contains("find/zoom handoff"));
        assert!(handoff.to_text().contains("hosted-find-zoom-bridge"));
        assert!(!handoff.to_text().contains("private query"));
        assert!(!handoff.to_text().contains("1.25"));

        let search = match &handoff.requests()[0] {
            FindZoomRequest::Search {
                query,
                case_sensitive,
                whole_word,
                wrap,
            } => (query, case_sensitive, whole_word, wrap),
            request => panic!("unexpected request {request:?}"),
        };
        assert_eq!(search.0, "private query");
        assert!(*search.1);
        assert!(*search.2);
        assert!(*search.3);
        assert_eq!(FindZoomDirection::Next.as_str(), "next");
        assert_eq!(DocumentZoomMode::FitWidth.as_str(), "fit-width");
    }

