    #[test]
    fn device_access_request_builder_validates_runtime_policy() {
        let usb = DeviceAccessRequest::usb("Read measurements from a USB scale.")
            .vendor_product(0x1234, 0xabcd)
            .timeout(Duration::from_secs(20))
            .build_checked()
            .unwrap();
        assert_eq!(usb.kind(), DeviceAccessKind::Usb);
        assert_eq!(usb.vendor_id(), Some(0x1234));
        assert_eq!(usb.product_id(), Some(0xabcd));
        assert!(usb.has_vendor_id());
        assert!(usb.has_product_id());
        assert_eq!(usb.required_capability(), Capability::UsbDevice);
        assert_eq!(
            usb.privacy_permission().build_checked().unwrap().kind(),
            AppPrivacyPermissionKind::UsbDevices
        );
        let usb_summary = usb.to_text();
        assert_eq!(
            usb_summary,
            "device access request usb: purpose true, vendor-filter true, product-filter true, service-filter false, port-hint false, timeout true, background false"
        );
        assert!(!usb_summary.contains("USB scale"));
        assert!(!usb_summary.contains("1234"));
        assert!(!usb_summary.contains("abcd"));

        let bluetooth_builder = DeviceAccessRequest::bluetooth("Pair with a heart-rate strap.")
            .service_uuid("180D")
            .allow_background();
        let bluetooth_builder_summary = bluetooth_builder.to_text();
        assert_eq!(
            bluetooth_builder_summary,
            "device access builder bluetooth: purpose true, vendor-filter false, product-filter false, service-filter true, port-hint false, timeout true, background true"
        );
        assert!(!bluetooth_builder_summary.contains("heart-rate"));
        assert!(!bluetooth_builder_summary.contains("180D"));
        let bluetooth = bluetooth_builder.build_checked().unwrap();
        assert_eq!(bluetooth.kind(), DeviceAccessKind::Bluetooth);
        assert_eq!(bluetooth.service_uuid(), Some("180D"));
        assert!(bluetooth.has_service_uuid());
        assert!(bluetooth.allows_background());
        assert_eq!(bluetooth.required_capability(), Capability::Bluetooth);
        assert_eq!(
            bluetooth
                .privacy_permission()
                .build_checked()
                .unwrap()
                .kind(),
            AppPrivacyPermissionKind::Bluetooth
        );

        assert!(DeviceAccessRequestBuilder::usb("").validate().is_err());
        assert!(
            DeviceAccessRequestBuilder::usb("scale")
                .product_id(0xabcd)
                .validate()
                .is_err()
        );
        assert!(
            DeviceAccessRequestBuilder::usb("scale")
                .service_uuid("180D")
                .validate()
                .is_err()
        );
        assert!(
            DeviceAccessRequestBuilder::serial("reader")
                .vendor_id(0x1234)
                .validate()
                .is_err()
        );
        assert!(
            DeviceAccessRequestBuilder::serial("reader")
                .port_name_hint(" tty.usbserial")
                .validate()
                .is_err()
        );
        assert!(
            DeviceAccessRequestBuilder::bluetooth("strap")
                .service_uuid("not-a-uuid")
                .validate()
                .is_err()
        );
        assert!(
            DeviceAccessRequestBuilder::bluetooth("strap")
                .timeout(Duration::from_secs(121))
                .validate()
                .is_err()
        );
    }

