    #[test]
    fn process_memory_metrics_report_support_state() {
        let unsupported = super::ProcessMemoryMetrics::unsupported();
        assert_eq!(unsupported.resident_set_bytes(), None);
        assert_eq!(unsupported.virtual_memory_bytes(), None);
        assert_eq!(unsupported.source(), None);
        assert!(!unsupported.is_supported());

        let sampled = super::current_process_memory_metrics();
        if sampled.is_supported() {
            assert!(sampled.source().is_some());
            assert!(
                sampled.resident_set_bytes().is_some() || sampled.virtual_memory_bytes().is_some()
            );
        }
    }

    #[test]
    fn current_process_metrics_include_runtime_metadata() {
        let cx = TestAppContext::single();

        let snapshot = cx.read(|app| app.current_process_metrics());

        assert_eq!(snapshot.process_id(), std::process::id());
        assert_eq!(snapshot.window_count(), 0);
        assert!(snapshot.uptime() < Duration::from_secs(60));
        assert!(snapshot.current_dir().is_some());
        assert!(snapshot.memory().source().is_some() || !snapshot.memory().is_supported());
        assert_eq!(
            snapshot.resident_set_bytes(),
            snapshot.memory().resident_set_bytes()
        );
        assert_eq!(
            snapshot.virtual_memory_bytes(),
            snapshot.memory().virtual_memory_bytes()
        );
    }

    #[test]
    fn app_resource_budget_builder_validates_thresholds() {
        let budget = AppResourceBudgetBuilder::new()
            .max_resident_set_bytes(256 * 1024 * 1024)
            .max_virtual_memory_bytes(2 * 1024 * 1024 * 1024)
            .max_windows(4)
            .max_uptime(Duration::from_secs(60 * 60))
            .require_memory_metrics()
            .warn_when_power_constrained()
            .build_checked()
            .unwrap();

        assert_eq!(budget.max_resident_set_bytes(), Some(256 * 1024 * 1024));
        assert_eq!(
            budget.max_virtual_memory_bytes(),
            Some(2 * 1024 * 1024 * 1024)
        );
        assert_eq!(budget.max_windows(), Some(4));
        assert_eq!(budget.max_uptime(), Some(Duration::from_secs(60 * 60)));
        assert!(budget.requires_memory_metrics());
        assert!(budget.warns_when_power_constrained());

        assert!(AppResourceBudgetBuilder::new().validate().is_err());
        assert!(
            AppResourceBudgetBuilder::new()
                .max_resident_set_bytes(0)
                .validate()
                .is_err()
        );
        assert!(
            AppResourceBudgetBuilder::new()
                .max_virtual_memory_bytes(0)
                .validate()
                .is_err()
        );
        assert!(
            AppResourceBudgetBuilder::new()
                .max_windows(0)
                .validate()
                .is_err()
        );
        assert!(
            AppResourceBudgetBuilder::new()
                .max_uptime(Duration::ZERO)
                .validate()
                .is_err()
        );
    }

    #[test]
    fn app_resource_budget_evaluation_reports_pass_and_failures() {
        let cx = TestAppContext::single();

        let passing = cx
            .read(|app| {
                app.evaluate_resource_budget_checked(
                    AppResourceBudgetBuilder::new()
                        .max_windows(1)
                        .max_uptime(Duration::from_secs(60)),
                )
            })
            .unwrap();
        assert!(passing.is_within_budget());
        assert!(passing.issues().is_empty());
        assert_eq!(passing.issue_count(), 0);
        assert!(passing.issue_kinds().is_empty());
        assert!(!passing.has_issue(AppResourceBudgetIssueKind::UptimeExceeded));
        assert!(!passing.has_memory_pressure());
        assert!(!passing.has_window_pressure());
        assert!(!passing.has_power_pressure());
        assert_eq!(passing.summary(), "resource budget ok");
        assert_eq!(passing.metrics().process_id(), std::process::id());
        assert_eq!(passing.runtime().window_count(), 0);
        assert_eq!(passing.budget().max_windows(), Some(1));

        let failing = cx
            .read(|app| {
                app.evaluate_resource_budget_checked(
                    AppResourceBudgetBuilder::new().max_uptime(Duration::from_nanos(1)),
                )
            })
            .unwrap();
        assert!(!failing.is_within_budget());
        assert_eq!(failing.issue_count(), 1);
        assert_eq!(
            failing.issue_kinds(),
            vec![AppResourceBudgetIssueKind::UptimeExceeded]
        );
        assert!(failing.has_issue(AppResourceBudgetIssueKind::UptimeExceeded));
        assert!(!failing.has_memory_pressure());
        assert!(
            failing
                .issues()
                .iter()
                .any(|issue| issue.kind() == AppResourceBudgetIssueKind::UptimeExceeded)
        );
        assert!(failing.summary().contains("uptime"));
    }

    #[test]
    fn app_resource_budget_can_require_memory_metrics() {
        let cx = TestAppContext::single();

        let evaluation = cx
            .read(|app| {
                app.evaluate_resource_budget_checked(
                    AppResourceBudgetBuilder::new()
                        .max_resident_set_bytes(u64::MAX)
                        .require_memory_metrics(),
                )
            })
            .unwrap();

        if evaluation.metrics().memory().is_supported() {
            assert!(!evaluation.missing_required_metrics());
            assert!(!evaluation.has_issue(AppResourceBudgetIssueKind::MissingMemoryMetrics));
        } else {
            assert!(evaluation.missing_required_metrics());
            assert!(evaluation.has_issue(AppResourceBudgetIssueKind::MissingMemoryMetrics));
            assert!(evaluation.has_memory_pressure());
        }
    }

    fn benchmark_sample_pair_for(scenario: BenchmarkScenario) -> BenchmarkSamplePair {
        let spec = scenario.workload_spec();
        let baseline = BenchmarkSampleApp::builder(
            BenchmarkSampleRuntime::Baseline,
            scenario,
            "Baseline sample",
        )
        .source("samples/baseline")
        .run_command("npm run bench")
        .interactions(spec.required_interactions.clone())
        .build_checked()
        .unwrap();
        let kael =
            BenchmarkSampleApp::builder(BenchmarkSampleRuntime::Kael, scenario, "Kael sample")
                .source("samples/kael")
                .run_command("cargo run --example bench")
                .interactions(spec.required_interactions)
                .build_checked()
                .unwrap();
        BenchmarkSamplePair::new(baseline, kael)
    }

    fn benchmark_result_for(scenario: BenchmarkScenario, subject: &str) -> BenchmarkResult {
        let measurements = scenario
            .workload_spec()
            .required_metrics
            .into_iter()
            .enumerate()
            .map(|(index, metric)| BenchmarkMeasurement {
                metric,
                value: 10.0 + index as f64,
                unit: match metric {
                    BenchmarkMetric::IdleMemory | BenchmarkMetric::MemoryGrowth => {
                        MetricUnit::Megabytes
                    }
                    BenchmarkMetric::LongSessionCpu
                    | BenchmarkMetric::GpuUsage
                    | BenchmarkMetric::AssetCacheHitRate => MetricUnit::Percent,
                    BenchmarkMetric::WakeupsPerSecond => MetricUnit::WakeupsPerSec,
                    _ => MetricUnit::Milliseconds,
                },
                elapsed: Duration::from_millis(index as u64),
            })
            .collect();

        BenchmarkResult {
            scenario,
            subject: subject.to_string(),
            measurements,
            started_at: Instant::now(),
            duration: Duration::from_secs(1),
            environment: crate::BenchmarkEnvironment {
                os_name: "test-os".to_string(),
                os_version: "1".to_string(),
                cpu: "test-cpu".to_string(),
                memory_gb: 16,
                gpu: "test-gpu".to_string(),
            },
        }
    }

    fn clean_baseline_report_for(scenario: BenchmarkScenario) -> BaselineComparisonReport {
        let pair = benchmark_sample_pair_for(scenario);
        let baseline = benchmark_result_for(scenario, "baseline");
        let kael = benchmark_result_for(scenario, "kael");
        let report = BaselineComparisonReport::generate_with_sample_pairs(
            &[baseline],
            &[kael],
            &[pair],
            Some("trace.json".to_string()),
        );
        assert!(report.evidence_issues.is_empty());
        report
    }

    #[test]
    fn performance_evidence_handoff_validates_resource_and_benchmark_stack() {
        let handoff = PerformanceEvidenceHandoffBuilder::new()
            .process_metrics()
            .resource_budget(
                AppResourceBudgetBuilder::new()
                    .max_resident_set_bytes(512 * 1024 * 1024)
                    .max_windows(4)
                    .require_memory_metrics(),
            )
            .benchmark_scenario(BenchmarkScenario::Chat)
            .benchmark_sample_pair(benchmark_sample_pair_for(BenchmarkScenario::Chat))
            .baseline_comparison(clean_baseline_report_for(BenchmarkScenario::Chat))
            .trace_session(TraceSessionBuilder::new("perf-audit").runtime())
            .support_diagnostics(SupportDiagnosticsBuilder::new())
            .hosted_profiler_island("hosted-profiler")
            .roadmap_work("native timeline inspector")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 9);
        assert_eq!(
            handoff.next_action(),
            PerformanceEvidenceNextAction::CaptureProcessMetrics
        );
        assert!(handoff.captures_process_metrics());
        assert!(handoff.evaluates_resource_budget());
        assert!(handoff.has_benchmark_samples());
        assert!(handoff.has_baseline_comparison());
        assert!(handoff.starts_trace_session());
        assert!(handoff.exports_support_diagnostics());
        assert!(handoff.uses_hosted_profiler_island());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            PerformanceEvidenceNextAction::CompareBenchmarkEvidence.key(),
            "compare-benchmark-evidence"
        );

        let text = handoff.to_text();
        assert!(text.contains("performance evidence handoff: 9 requests"));
        assert!(text.contains("next action capture-process-metrics"));
        assert!(text.contains("baseline-comparison:1"));
        assert!(!text.contains("Baseline sample"));
        assert!(!text.contains("Kael sample"));
        assert!(!text.contains("npm run bench"));
        assert!(!text.contains("trace.json"));
        assert!(!text.contains("native timeline inspector"));
    }

