    #[test]
    fn trace_session_builder_creates_bounded_redacted_descriptor() {
        let trace = TraceSessionBuilder::new("startup-profiler")
            .startup()
            .runtime()
            .network()
            .ipc()
            .max_events(512)
            .max_duration(Duration::from_secs(30))
            .support_diagnostics()
            .payload_shapes()
            .build_checked()
            .unwrap();

        assert_eq!(trace.scope(), "startup-profiler");
        assert_eq!(trace.max_events(), 512);
        assert_eq!(trace.max_duration(), Duration::from_secs(30));
        assert!(trace.includes_runtime_snapshot());
        assert!(trace.includes_process_metrics());
        assert!(trace.includes_support_diagnostics());
        assert!(trace.includes_payload_shapes());
        assert!(trace.includes_kind(TraceSessionKind::Startup));
        assert!(trace.includes_kind(TraceSessionKind::Runtime));
        assert!(trace.includes_kind(TraceSessionKind::Network));
        assert!(trace.includes_kind(TraceSessionKind::Ipc));

        let text = trace.to_text();
        assert!(text.contains("scope=startup-profiler"));
        assert!(text.contains("kinds=startup,runtime,network,ipc"));
        assert!(text.contains("event_budget=512"));
        assert!(text.contains("duration_budget=short"));

        let safe = trace.to_safe_text();
        assert!(!safe.contains("startup-profiler"));
        assert!(safe.contains("event_budget=small"));
        assert!(safe.contains("payload_shapes=true"));
    }

