    #[test]
    fn trace_session_builder_rejects_unbounded_or_unsafe_sessions() {
        assert!(
            TraceSessionBuilder::new("bad scope")
                .runtime()
                .validate()
                .is_err(),
            "scope must be an app-owned identifier"
        );
        assert!(
            TraceSessionBuilder::new("missing-kind").validate().is_err(),
            "at least one trace category is required"
        );
        assert!(
            TraceSessionBuilder::new("zero-events")
                .runtime()
                .max_events(0)
                .validate()
                .is_err()
        );
        assert!(
            TraceSessionBuilder::new("too-many-events")
                .runtime()
                .max_events(100_001)
                .validate()
                .is_err()
        );
        assert!(
            TraceSessionBuilder::new("zero-duration")
                .runtime()
                .max_duration(Duration::ZERO)
                .validate()
                .is_err()
        );
        assert!(
            TraceSessionBuilder::new("too-long")
                .runtime()
                .max_duration(Duration::from_secs(60 * 60 * 24 + 1))
                .validate()
                .is_err()
        );
    }

