    #[test]
    fn developer_observability_handoff_validates_debug_evidence_routes() {
        let handoff = DeveloperObservabilityHandoffBuilder::new()
            .trace_session(
                TraceSessionBuilder::new("agent-audit")
                    .runtime()
                    .network()
                    .ipc()
                    .max_events(256)
                    .max_duration(Duration::from_secs(30))
                    .support_diagnostics(),
            )
            .runtime_snapshot(AppRuntimeSnapshotQueryBuilder::new().require_not_quitting())
            .resource_budget(AppResourceBudgetBuilder::new().max_windows(4))
            .support_diagnostics(SupportDiagnosticsBuilder::new())
            .hosted_console_bridge("webview-console")
            .hosted_devtools_bridge("webview-inspector")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 6);
        assert_eq!(
            handoff.next_action(),
            DeveloperObservabilityNextAction::StartTraceSession
        );
        assert!(handoff.starts_trace_session());
        assert!(handoff.captures_runtime_evidence());
        assert!(handoff.evaluates_resource_budget());
        assert!(handoff.exports_support_diagnostics());
        assert!(handoff.uses_hosted_devtools_bridge());
        assert_eq!(
            DeveloperObservabilityNextAction::UseHostedDevtoolsBridge.key(),
            "use-hosted-devtools-bridge"
        );
        assert_eq!(
            handoff.to_text(),
            "developer observability handoff: 6 requests, next action start-trace-session, trace true, runtime true, resource budget true, support diagnostics true, hosted bridge true"
        );

        let hosted = DeveloperObservabilityHandoffBuilder::new()
            .hosted_console_bridge("hosted-console")
            .build_checked()
            .unwrap();
        assert_eq!(
            hosted.next_action(),
            DeveloperObservabilityNextAction::UseHostedDevtoolsBridge
        );
    }

