    #[test]
    fn key_binding_set_builder_validates_accelerators() {
        let cx = TestAppContext::single();
        let builder = KeyBindingSetBuilder::new()
            .binding("secondary-k", KeyBindingOpen)
            .binding_with_context(
                "secondary-shift-f",
                KeyBindingOpen,
                Some("Editor && mode == normal"),
            )
            .platform_binding("secondary-p", KeyBindingOpen, None::<String>);

        assert_eq!(builder.len(), 3);
        assert_eq!(builder.context_count(), 1);
        assert!(builder.has_contexts());
        assert_eq!(builder.platform_binding_count(), 1);
        assert!(builder.has_platform_bindings());
        assert_eq!(
            builder.to_text(),
            "keybinding builder: 3 bindings, 1 contexts, 1 platform-mapped"
        );
        assert!(!builder.to_text().contains("Editor"));

        let plan = cx.read(|app| builder.build_plan_checked(app)).unwrap();
        assert_eq!(plan.len(), 3);
        assert!(!plan.is_empty());
        let normalized = plan.normalized_keystrokes();
        assert_eq!(normalized.len(), 3);
        assert!(normalized[0].ends_with('K'));
        assert!(normalized[1].ends_with('F'));
        let action_names = plan.action_names();
        assert_eq!(action_names.len(), 3);
        assert!(
            action_names
                .iter()
                .all(|name| name.contains("KeyBindingOpen"))
        );
        assert_eq!(plan.context_count(), 1);
        assert!(plan.has_contexts());
        assert_eq!(plan.to_text(), "keybinding plan: 3 bindings, 1 contexts");
        assert!(!plan.to_text().contains("Editor"));

        let bindings = plan.into_bindings();
        assert_eq!(
            bindings[0].match_keystrokes(&[Keystroke::parse("secondary-k").unwrap()]),
            Some(false)
        );
        assert_eq!(
            bindings[1].predicate().unwrap().to_string(),
            "(Editor && mode == normal)"
        );

        assert!(
            cx.read(|app| KeyBindingSetBuilder::new().validate(app))
                .is_err()
        );
        assert!(
            cx.read(|app| {
                KeyBindingSetBuilder::new()
                    .binding(" secondary-k", KeyBindingOpen)
                    .validate(app)
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                KeyBindingSetBuilder::new()
                    .binding("ctrl-a-b", KeyBindingOpen)
                    .validate(app)
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                KeyBindingSetBuilder::new()
                    .binding_with_context("secondary-k", KeyBindingOpen, Some("Editor &&"))
                    .validate(app)
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                KeyBindingSetBuilder::new()
                    .binding("secondary-k", KeyBindingOpen)
                    .binding("secondary-k", KeyBindingOpen)
                    .validate(app)
            })
            .is_err()
        );
    }

    #[test]
    fn shortcut_input_handoff_builder_validates_keyboard_workflow() {
        let cx = TestAppContext::single();
        let global_hotkeys = GlobalHotkeyBuilder::new()
            .parse_named_hotkey(1, "Command Palette", "cmd-shift-k")
            .unwrap()
            .parse_named_hotkey(2, "Toggle Capture", "cmd-alt-c")
            .unwrap();

        let handoff = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .app_keybindings(
                        KeyBindingSetBuilder::new()
                            .binding("secondary-k", KeyBindingOpen)
                            .binding_with_context(
                                "secondary-shift-f",
                                KeyBindingOpen,
                                Some("Editor && mode == normal"),
                            ),
                    )
                    .global_hotkeys(global_hotkeys)
                    .global_hotkey_cleanup(GlobalHotkeyUnregistration::new().id(1).id(2))
                    .keybinding_cleanup(KeyBindingClearBuilder::mode_changed("command mode"))
                    .keyboard_layout(KeyboardLayoutSnapshotBuilder::new())
                    .hosted_shortcut_island("rich-editor-beforeinput")
                    .roadmap_work("gamepad shortcut capture")
                    .build_checked(app)
            })
            .unwrap();

        assert_eq!(handoff.request_count(), 7);
        assert!(handoff.has_app_keybindings());
        assert!(handoff.has_global_hotkeys());
        assert!(handoff.has_global_hotkey_cleanup());
        assert!(handoff.has_keybinding_cleanup());
        assert!(handoff.has_keyboard_layout_snapshot());
        assert!(handoff.has_hosted_shortcut_island());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            ShortcutInputNextAction::InstallAppKeybindings
        );
        assert_eq!(handoff.next_action().key(), "install-app-keybindings");

        let text = handoff.to_text();
        assert!(text.contains("shortcut input handoff"));
        assert!(text.contains("app-keybindings:1"));
        assert!(text.contains("global-hotkeys:1"));
        assert!(!text.contains("Command Palette"));
        assert!(!text.contains("cmd-shift-k"));
        assert!(!text.contains("Editor"));
        assert!(!text.contains("rich-editor-beforeinput"));
        assert!(!text.contains("gamepad shortcut capture"));
    }

