    #[test]
    fn shortcut_input_handoff_next_action_covers_routes() {
        let cx = TestAppContext::single();

        let global = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .global_hotkeys(
                        GlobalHotkeyBuilder::new()
                            .parse_named_hotkey(7, "Quick Capture", "cmd-alt-c")
                            .unwrap(),
                    )
                    .build_checked(app)
            })
            .unwrap();
        assert_eq!(
            global.next_action(),
            ShortcutInputNextAction::RegisterGlobalHotkeys
        );

        let cleanup = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .global_hotkey_cleanup(GlobalHotkeyUnregistration::new().id(7))
                    .build_checked(app)
            })
            .unwrap();
        assert_eq!(
            cleanup.next_action(),
            ShortcutInputNextAction::UnregisterGlobalHotkeys
        );

        let clear = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .keybinding_cleanup(KeyBindingClearBuilder::extension_unloaded("vim-mode"))
                    .build_checked(app)
            })
            .unwrap();
        assert_eq!(
            clear.next_action(),
            ShortcutInputNextAction::ClearAppKeybindings
        );

        let layout = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .keyboard_layout(KeyboardLayoutSnapshotBuilder::new())
                    .build_checked(app)
            })
            .unwrap();
        assert_eq!(
            layout.next_action(),
            ShortcutInputNextAction::SnapshotKeyboardLayout
        );

        let hosted = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .hosted_shortcut_island("browser-beforeinput")
                    .build_checked(app)
            })
            .unwrap();
        assert_eq!(
            hosted.next_action(),
            ShortcutInputNextAction::UseHostedShortcutIsland
        );

        let roadmap = cx
            .read(|app| {
                ShortcutInputHandoffBuilder::new()
                    .roadmap_work("MIDI shortcut backend")
                    .build_checked(app)
            })
            .unwrap();
        assert_eq!(
            roadmap.next_action(),
            ShortcutInputNextAction::TrackShortcutRoadmap
        );
    }

