    #[test]
    fn focus_traversal_plan_builder_validates_native_keyboard_flow() {
        let plan = FocusTraversalPlanBuilder::overlay("command_palette")
            .default_stop("query")
            .custom_stop(
                FocusTraversalStopBuilder::new("results")
                    .label("Results")
                    .context("Editor"),
            )
            .disabled_stop("preview")
            .build_checked()
            .unwrap();

        assert_eq!(plan.scope(), "command_palette");
        assert_eq!(plan.stop_count(), 3);
        assert_eq!(plan.enabled_stop_count(), 2);
        assert_eq!(plan.disabled_stop_count(), 1);
        assert_eq!(plan.context_count(), 1);
        assert_eq!(plan.default_stop_count(), 1);
        assert!(plan.wraps());
        assert!(plan.traps_focus());
        assert!(plan.restores_previous_focus());
        assert_eq!(plan.default_stop().unwrap().id(), "query");
        assert_eq!(plan.first_enabled_stop().unwrap().id(), "query");
        assert_eq!(
            plan.to_text(),
            "focus traversal plan: 3 stops, 2 enabled, 1 disabled, 1 contexts, default 1, wraps true, traps true, restores true"
        );
        assert!(!plan.to_text().contains("command_palette"));
        assert!(!plan.to_text().contains("query"));
        assert!(!plan.to_text().contains("Results"));

        let results = &plan.stops()[1];
        assert_eq!(results.id(), "results");
        assert_eq!(results.label(), Some("Results"));
        assert_eq!(results.context(), Some("Editor"));
        assert!(results.enabled());
        assert!(!results.is_default());
        assert_eq!(
            results.to_text(),
            "focus traversal stop: label true, context true, disabled false, default false"
        );
        assert!(!results.to_text().contains("Results"));
        assert!(!results.to_text().contains("Editor"));

        let builder = FocusTraversalPlanBuilder::form("settings")
            .labeled_stop("general", "General")
            .stop("advanced");
        assert_eq!(builder.stop_count(), 2);
        assert!(builder.wraps());
        assert!(!builder.traps_focus());
        assert!(!builder.restores_previous_focus());
        assert_eq!(
            builder.to_text(),
            "focus traversal plan builder: 2 stops, wraps true, traps false, restores false"
        );
        assert!(!builder.to_text().contains("settings"));
        assert!(!builder.to_text().contains("advanced"));

        assert!(
            FocusTraversalPlanBuilder::new("")
                .stop("first")
                .validate()
                .is_err()
        );
        assert!(FocusTraversalPlanBuilder::new("scope").validate().is_err());
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .stop("same")
                .stop("same")
                .validate()
                .is_err()
        );
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .custom_stop(FocusTraversalStopBuilder::new("bad/id"))
                .validate()
                .is_err()
        );
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .custom_stop(FocusTraversalStopBuilder::new("bad").label(" bad"))
                .validate()
                .is_err()
        );
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .custom_stop(FocusTraversalStopBuilder::new("bad").context("Editor &&"))
                .validate()
                .is_err()
        );
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .custom_stop(
                    FocusTraversalStopBuilder::new("disabled")
                        .disabled()
                        .default()
                )
                .validate()
                .is_err()
        );
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .default_stop("first")
                .default_stop("second")
                .validate()
                .is_err()
        );
        assert!(
            FocusTraversalPlanBuilder::new("scope")
                .disabled_stop("first")
                .disabled_stop("second")
                .validate()
                .is_err()
        );
    }

