    #[test]
    fn pointer_input_policy_builder_validates_native_pointer_affordances() {
        let policy = PointerInputPolicyBuilder::drag_surface("canvas_tools")
            .hover()
            .secondary_click()
            .minimum_hit_size_px(24.0)
            .build_checked()
            .unwrap();

        assert_eq!(policy.scope(), "canvas_tools");
        assert_eq!(policy.capability_count(), 4);
        assert!(policy.has_capability(PointerInputCapability::PrimaryClick));
        assert!(policy.has_capability(PointerInputCapability::Drag));
        assert!(policy.has_capability(PointerInputCapability::Hover));
        assert!(policy.has_capability(PointerInputCapability::SecondaryClick));
        assert_eq!(policy.minimum_hit_size_px(), Some(24.0));
        assert_eq!(policy.drag_threshold_px(), Some(4.0));
        assert!(policy.captures_during_drag());
        assert!(!policy.requires_hover_fallback());
        assert_eq!(PointerInputCapability::StylusLike.key(), "stylus-like");
        assert_eq!(
            policy.to_text(),
            "pointer input policy: 4 capabilities, hit size true, drag threshold true, hover fallback false, capture drag true"
        );
        assert!(!policy.to_text().contains("canvas_tools"));

        let builder = PointerInputPolicyBuilder::hover_preview("toolbar")
            .touch_like()
            .minimum_hit_size_px(32.0);
        assert_eq!(builder.capability_count(), 2);
        assert_eq!(
            builder.to_text(),
            "pointer input policy builder: 2 capabilities, hit size true, drag threshold false, hover fallback true, capture drag false"
        );
        assert!(!builder.to_text().contains("toolbar"));

        assert!(
            PointerInputPolicyBuilder::new("")
                .hover()
                .validate()
                .is_err()
        );
        assert!(PointerInputPolicyBuilder::new("scope").validate().is_err());
        assert!(
            PointerInputPolicyBuilder::new("scope")
                .drag_threshold_px(4.0)
                .primary_click()
                .validate()
                .is_err()
        );
        assert!(
            PointerInputPolicyBuilder::new("scope")
                .capture_during_drag()
                .primary_click()
                .validate()
                .is_err()
        );
        assert!(
            PointerInputPolicyBuilder::new("scope")
                .require_hover_fallback()
                .primary_click()
                .validate()
                .is_err()
        );
        assert!(
            PointerInputPolicyBuilder::new("scope")
                .hover()
                .minimum_hit_size_px(0.0)
                .validate()
                .is_err()
        );
        assert!(
            PointerInputPolicyBuilder::new("scope")
                .drag()
                .drag_threshold_px(f32::NAN)
                .validate()
                .is_err()
        );
    }

    #[test]
    fn gesture_input_policy_builder_validates_native_gesture_affordances() {
        let policy = GestureInputPolicyBuilder::canvas("image_editor")
            .double_tap()
            .long_press()
            .build_checked()
            .unwrap();

        assert_eq!(policy.scope(), "image_editor");
        assert_eq!(policy.gesture_count(), 5);
        assert!(policy.has_gesture(GestureInputKind::Pan));
        assert!(policy.has_gesture(GestureInputKind::PinchZoom));
        assert!(policy.has_gesture(GestureInputKind::WheelZoom));
        assert!(policy.has_gesture(GestureInputKind::DoubleTap));
        assert!(policy.has_gesture(GestureInputKind::LongPress));
        assert_eq!(policy.pan_threshold_px(), Some(2.0));
        assert_eq!(policy.zoom_min_scale(), Some(0.01));
        assert!(policy.prevents_scroll_conflicts());
        assert_eq!(GestureInputKind::PinchZoom.key(), "pinch-zoom");
        assert_eq!(
            policy.to_text(),
            "gesture input policy: 5 gestures, pan threshold true, swipe threshold false, zoom scale true, prevent scroll conflicts true"
        );
        assert!(!policy.to_text().contains("image_editor"));

        let builder = GestureInputPolicyBuilder::carousel("asset_strip").double_tap();
        assert_eq!(builder.gesture_count(), 3);
        assert_eq!(
            builder.to_text(),
            "gesture input policy builder: 3 gestures, pan threshold true, swipe threshold true, zoom scale false, prevent scroll conflicts true"
        );
        assert!(!builder.to_text().contains("asset_strip"));

        assert!(GestureInputPolicyBuilder::new("").pan().validate().is_err());
        assert!(GestureInputPolicyBuilder::new("scope").validate().is_err());
        assert!(
            GestureInputPolicyBuilder::new("scope")
                .swipe_threshold_px(48.0)
                .pan()
                .validate()
                .is_err()
        );
        assert!(
            GestureInputPolicyBuilder::new("scope")
                .pan_threshold_px(2.0)
                .swipe()
                .validate()
                .is_err()
        );
        assert!(
            GestureInputPolicyBuilder::new("scope")
                .pan()
                .pan_threshold_px(f32::INFINITY)
                .validate()
                .is_err()
        );
        assert!(
            GestureInputPolicyBuilder::new("scope")
                .pan()
                .zoom_min_scale(0.1)
                .validate()
                .is_err()
        );
        assert!(
            GestureInputPolicyBuilder::new("scope")
                .pinch_zoom()
                .zoom_min_scale(2.0)
                .validate()
                .is_err()
        );
    }

