    #[test]
    fn progress_indicator_builder_validates_operation_progress() {
        let progress = ProgressIndicatorBuilder::normal("download", 0.42)
            .window()
            .cancellable()
            .unit("files")
            .build_checked()
            .unwrap();

        assert_eq!(progress.scope(), "download");
        assert_eq!(progress.kind(), ProgressIndicatorKind::Normal);
        assert_eq!(progress.fraction(), Some(0.42));
        assert!(progress.shows_inline());
        assert!(progress.shows_window_progress());
        assert!(progress.is_cancellable());
        assert_eq!(progress.unit(), Some("files"));
        assert!(progress.is_determinate());
        assert_eq!(progress.completion_class(), "partial");
        assert_eq!(
            progress.window_progress_builder().unwrap().to_text(),
            "window progress: kind normal, determinate true"
        );
        assert_eq!(
            progress.to_text(),
            "progress indicator: kind normal, determinate true, completion partial, inline true, window true, cancellable true, unit true"
        );
        assert!(!progress.to_text().contains("download"));
        assert!(!progress.to_text().contains("files"));

        let indeterminate = ProgressIndicatorBuilder::indeterminate("index")
            .window()
            .no_inline()
            .build_checked()
            .unwrap();
        assert_eq!(indeterminate.kind(), ProgressIndicatorKind::Indeterminate);
        assert!(!indeterminate.shows_inline());
        assert!(indeterminate.shows_window_progress());
        assert!(!indeterminate.is_determinate());
        assert_eq!(indeterminate.completion_class(), "indeterminate");
        assert_eq!(
            indeterminate.window_progress_builder().unwrap().to_text(),
            "window progress: kind indeterminate, determinate false"
        );

        let builder = ProgressIndicatorBuilder::paused("sync", 1.0).unit("tasks");
        assert_eq!(builder.configured_kind(), ProgressIndicatorKind::Paused);
        assert_eq!(
            builder.to_text(),
            "progress indicator builder: kind paused, determinate true, inline true, window false, cancellable false, unit true"
        );
        assert!(!builder.to_text().contains("sync"));
        assert!(!builder.to_text().contains("tasks"));

        assert!(
            ProgressIndicatorBuilder::normal("", 0.5)
                .validate()
                .is_err()
        );
        assert!(
            ProgressIndicatorBuilder::normal("download", f64::NAN)
                .validate()
                .is_err()
        );
        assert!(
            ProgressIndicatorBuilder::normal("download", 1.5)
                .validate()
                .is_err()
        );
        assert!(
            ProgressIndicatorBuilder::indeterminate("download")
                .fraction(0.5)
                .validate()
                .is_err()
        );
        assert!(
            ProgressIndicatorBuilder::normal("download", 0.5)
                .no_inline()
                .no_window()
                .validate()
                .is_err()
        );
        assert!(
            ProgressIndicatorBuilder::normal("download", 0.5)
                .unit(" exact\nunit")
                .validate()
                .is_err()
        );
        assert_eq!(ProgressIndicatorKind::Hidden.key(), "hidden");
        assert!(ProgressIndicatorKind::Error.requires_fraction());
        assert!(ProgressIndicatorKind::Hidden.is_clear());
    }

