    #[test]
    fn window_management_handoff_builder_validates_native_window_stack() {
        let handoff = WindowManagementHandoffBuilder::new()
            .window_intent(
                WindowIntentBuilder::main()
                    .title("Project Dashboard")
                    .min_size(size(px(640.0), px(420.0)))
                    .app_id("com.example.kael"),
            )
            .window_placement(WindowPlacementBuilder::new(size(px(960.0), px(640.0))))
            .focused_window_query(FocusedWindowQueryBuilder::new().current_process_only())
            .chrome_command(
                WindowChromeCommand::request_decorations(WindowDecorations::Client)
                    .reason("custom titlebar"),
            )
            .client_inset(WindowClientInsetBuilder::new(px(8.0)))
            .presentation_policy(WindowPresentationPolicyBuilder::fullscreen(
                "Present dashboard",
            ))
            .interaction_command(WindowInteractionCommand::show().reason("restore window"))
            .z_order_policy(WindowZOrderPolicyBuilder::always_on_top(
                "Keep inspector visible",
            ))
            .opacity(WindowOpacityBuilder::fraction(0.92))
            .content_protection(WindowContentProtectionBuilder::exclude_from_capture(
                "Protect checkout secrets",
            ))
            .document_state(WindowDocumentStateBuilder::new().title("Project Dashboard"))
            .hosted_window_island("oauth-popup")
            .roadmap_work("native child-window docking")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 13);
        assert_eq!(
            handoff.next_action(),
            WindowManagementNextAction::BuildWindowIntent
        );
        assert!(handoff.has_window_intent());
        assert!(handoff.has_window_placement());
        assert!(handoff.has_focused_window_query());
        assert!(handoff.configures_window_chrome());
        assert!(handoff.applies_presentation_policy());
        assert!(handoff.dispatches_window_interaction());
        assert!(handoff.applies_window_policy());
        assert!(handoff.applies_document_state());
        assert!(handoff.uses_hosted_window_island());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            WindowManagementNextAction::UseHostedWindowIsland.key(),
            "use-hosted-window-island"
        );

        let text = handoff.to_text();
        assert!(text.contains("window management handoff: 13 requests"));
        assert!(text.contains("next action build-window-intent"));
        assert!(text.contains("window-intent:1"));
        assert!(!text.contains("Project Dashboard"));
        assert!(!text.contains("com.example.kael"));
        assert!(!text.contains("oauth-popup"));
        assert!(!text.contains("native child-window docking"));
        assert!(!text.contains("Protect checkout secrets"));
        assert!(!text.contains("0.92"));
    }

