    #[test]
    fn desktop_shell_chrome_handoff_builder_validates_native_shell_stack() {
        let cx = TestAppContext::single();

        let handoff = cx
            .read(|app| {
                DesktopShellChromeHandoffBuilder::new()
                    .runtime_snapshot(AppRuntimeSnapshotQueryBuilder::new().require_not_quitting())
                    .tray_app(
                        TrayAppBuilder::new()
                            .action("Open", "open")
                            .separator()
                            .toggle("Pause sync", false, "pause-sync")
                            .status_tooltip("Sync running")
                            .panel()
                            .keep_alive_without_windows(true),
                    )
                    .window_placement(WindowPlacementBuilder::new(size(px(360.0), px(240.0))))
                    .progress_indicator(
                        ProgressIndicatorBuilder::normal("sync", 0.5)
                            .window()
                            .cancellable(),
                    )
                    .dock_badge(DockBadgeBuilder::count(3))
                    .user_attention(UserAttentionBuilder::informational().reason("sync complete"))
                    .build_checked(app)
            })
            .unwrap();

        assert_eq!(handoff.request_count(), 6);
        assert!(handoff.has_runtime_snapshot());
        assert!(handoff.has_tray_app());
        assert!(handoff.has_window_placement());
        assert!(handoff.has_progress_indicator());
        assert!(handoff.has_dock_badge());
        assert!(handoff.has_user_attention());
        assert!(!handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            DesktopShellChromeNextAction::ValidateRuntimeState
        );
        assert_eq!(
            DesktopShellChromeNextAction::ConfigureTrayApp.key(),
            "configure-tray-app"
        );
        assert!(handoff.to_text().contains("tray-app"));
        assert!(!handoff.to_text().contains("Sync running"));
        assert!(!handoff.to_text().contains("sync complete"));
        assert!(!handoff.to_text().contains("open"));
    }

