    #[test]
    fn focused_window_query_summaries_are_content_safe() {
        let builder = FocusedWindowQueryBuilder::new()
            .external_only()
            .require_title()
            .require_pid()
            .app_name_contains("Code");

        assert_eq!(
            builder.to_text(),
            "focused window query: title true, pid true, scope true, filters true"
        );
        assert!(!builder.to_text().contains("Code"));

        let query = builder.build_checked().unwrap();
        assert!(query.requires_title());
        assert!(query.requires_pid());
        assert!(query.external_only());
        assert!(query.has_process_scope());
        assert!(query.has_filter());
        assert_eq!(
            query.to_text(),
            "focused window query: title true, pid true, scope true, filters true"
        );
        assert!(!query.to_text().contains("Code"));

        let unfiltered = FocusedWindowQueryBuilder::new().build_checked().unwrap();
        assert!(!unfiltered.has_filter());
        assert!(!unfiltered.has_process_scope());
        assert_eq!(
            unfiltered.to_text(),
            "focused window query: title false, pid false, scope false, filters false"
        );
    }

    #[test]
    fn focused_window_info_summary_avoids_active_window_content() {
        let info = FocusedWindowInfo {
            app_name: "Visual Studio Code".into(),
            window_title: "Secret Project".into(),
            bundle_id: Some("com.microsoft.VSCode".into()),
            pid: Some(std::process::id().saturating_add(1)),
        };

        assert!(info.validate().is_ok());
        assert!(info.has_title());
        assert!(info.has_bundle_id());
        assert!(info.has_pid());
        assert!(info.is_external_process());
        assert_eq!(
            info.to_text(),
            "focused window: title true, bundle true, pid true, external true"
        );
        assert!(!info.to_text().contains("Visual Studio Code"));
        assert!(!info.to_text().contains("Secret Project"));
        assert!(!info.to_text().contains("com.microsoft.VSCode"));
        assert!(!info.to_text().contains(&info.pid.unwrap().to_string()));

        let query = FocusedWindowQueryBuilder::new()
            .external_only()
            .require_title()
            .require_pid()
            .app_name_contains("code")
            .build_checked()
            .unwrap();
        assert!(info.matches_query(&query));

        let current = FocusedWindowInfo {
            app_name: "Kael".into(),
            window_title: String::new(),
            bundle_id: None,
            pid: Some(std::process::id()),
        };
        assert!(!current.has_title());
        assert!(!current.has_bundle_id());
        assert!(current.has_pid());
        assert!(!current.is_external_process());
        assert_eq!(
            current.to_text(),
            "focused window: title false, bundle false, pid true, external false"
        );
    }

