    #[test]
    fn remove_global_checked_validates_reason_and_presence() {
        let cx = TestAppContext::single();

        cx.update(|app| app.set_global(TestRuntimeGlobal("plugin-state")));
        assert!(cx.read(|app| app.has_global::<TestRuntimeGlobal>()));

        assert!(
            cx.update(|app| {
                app.remove_global_checked::<TestRuntimeGlobal>(GlobalRemovalBuilder::new(""))
            })
            .is_err()
        );
        assert!(cx.read(|app| app.has_global::<TestRuntimeGlobal>()));

        let removed = cx
            .update(|app| {
                app.remove_global_checked::<TestRuntimeGlobal>(
                    GlobalRemovalBuilder::extension_unloaded("vim-mode"),
                )
            })
            .unwrap();

        assert_eq!(removed, Some(TestRuntimeGlobal("plugin-state")));
        assert!(!cx.read(|app| app.has_global::<TestRuntimeGlobal>()));

        let missing = cx
            .update(|app| {
                app.remove_global_checked::<TestRuntimeGlobal>(
                    GlobalRemovalBuilder::mode_changed("workspace").allow_missing(),
                )
            })
            .unwrap();
        assert_eq!(missing, None);

        assert!(
            cx.update(|app| {
                app.remove_global_checked::<TestRuntimeGlobal>(
                    GlobalRemovalBuilder::mode_changed("workspace").require_present(),
                )
            })
            .is_err()
        );
        assert!(
            GlobalRemovalBuilder::extension_unloaded("bad\nextension")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn close_workspace_checked_validates_reason_and_open_state() {
        let cx = TestAppContext::single();

        cx.update(|app| {
            app.open_workspace();
        });
        assert!(cx.read(|app| app.workspace().is_some()));

        assert!(
            cx.update(|app| app.close_workspace_checked(WorkspaceCloseBuilder::new("")))
                .is_err()
        );
        assert!(cx.read(|app| app.workspace().is_some()));

        let closed = cx
            .update(|app| {
                app.close_workspace_checked(WorkspaceCloseBuilder::switching_workspace("project-b"))
            })
            .unwrap();
        assert!(closed);
        assert!(cx.read(|app| app.workspace().is_none()));

        let already_closed = cx
            .update(|app| {
                app.close_workspace_checked(WorkspaceCloseBuilder::session_teardown(
                    "window closed",
                ))
            })
            .unwrap();
        assert!(!already_closed);

        assert!(
            cx.update(|app| {
                app.close_workspace_checked(
                    WorkspaceCloseBuilder::session_teardown("window closed").require_open(),
                )
            })
            .is_err()
        );
        assert!(
            WorkspaceCloseBuilder::switching_workspace("bad\nworkspace")
                .validate()
                .is_err()
        );
    }

