    #[test]
    fn schedule_job_checked_validates_metadata_before_queueing() {
        let cx = TestAppContext::single();

        assert!(
            cx.read(|app| app.schedule_job_checked(TestBackgroundJob { id: "".into() }))
                .is_err()
        );
        assert!(cx.read(|app| app.background_jobs.status("").is_none()));

        assert!(
            cx.read(|app| {
                app.schedule_job_with_descriptor_checked(
                    TestBackgroundJob {
                        id: "export/video".into(),
                    },
                    crate::background_jobs::JobDescriptor::new("export/other"),
                )
            })
            .is_err()
        );
        assert!(cx.read(|app| app.background_jobs.status("export/video").is_none()));

        let invalid_retry = crate::background_jobs::RetryPolicy {
            max_retries: 1,
            delay_ms: 0,
            backoff_multiplier: 2.0,
        };
        assert!(
            cx.read(|app| {
                app.schedule_job_with_descriptor_checked(
                    TestBackgroundJob {
                        id: "export/audio".into(),
                    },
                    crate::background_jobs::JobDescriptor::new("export/audio")
                        .with_retry_policy(invalid_retry),
                )
            })
            .is_err()
        );
        assert!(cx.read(|app| app.background_jobs.status("export/audio").is_none()));

        let scheduled = cx
            .read(|app| {
                app.schedule_job_with_descriptor_checked(
                    TestBackgroundJob {
                        id: "export/image".into(),
                    },
                    crate::background_jobs::JobDescriptor::new("export/image")
                        .with_priority(crate::background_jobs::JobPriority::High),
                )
            })
            .unwrap();

        assert_eq!(scheduled, "export/image");
        assert!(cx.read(|app| app.background_jobs.status("export/image").is_some()));
    }

    #[test]
    fn app_ipc_and_background_handoffs_use_checked_builders() {
        let cx = TestAppContext::single();

        let command = cx
            .read(|app| {
                app.command_ipc_handoff_checked(CommandIpcHandoffBuilder::register_command(
                    "editor.save",
                    "Save",
                ))
            })
            .unwrap();
        assert_eq!(command.next_action(), CommandIpcNextAction::RegisterCommand);
        assert!(command.is_register_command());
        assert_eq!(command.command_id(), Some("editor.save"));

        let ipc = cx
            .read(|app| app.command_ipc_handoff_checked(CommandIpcHandoffBuilder::ipc_request(42)))
            .unwrap();
        assert_eq!(ipc.next_action(), CommandIpcNextAction::SendIpcRequest);
        assert!(ipc.is_ipc_request());

        assert!(
            cx.read(|app| {
                app.command_ipc_handoff_checked(CommandIpcHandoffBuilder::hosted_bridge(
                    "bad\nkind",
                ))
            })
            .is_err()
        );

        let background = cx
            .read(|app| {
                app.background_work_handoff_checked(BackgroundWorkHandoffBuilder::descriptor(
                    crate::background_jobs::JobDescriptor::new("export/video")
                        .with_priority(crate::background_jobs::JobPriority::High),
                ))
            })
            .unwrap();
        assert_eq!(
            background.next_action(),
            BackgroundWorkNextAction::ScheduleJob
        );
        assert!(background.is_job());
        assert_eq!(background.job_id(), Some("export/video"));

        let progress = cx
            .read(|app| {
                app.background_work_handoff_checked(
                    BackgroundWorkHandoffBuilder::progress("export/video", 42.0)
                        .progress_message("rendering"),
                )
            })
            .unwrap();
        assert_eq!(
            progress.next_action(),
            BackgroundWorkNextAction::ReportProgress
        );
        assert!(progress.is_progress());

        assert!(
            cx.read(|app| {
                app.background_work_handoff_checked(BackgroundWorkHandoffBuilder::progress(
                    "export/video",
                    101.0,
                ))
            })
            .is_err()
        );
    }

    #[test]
    fn app_helper_plugin_handoff_uses_checked_builder() {
        let cx = TestAppContext::single();
        let helper_path = std::env::current_exe().unwrap();
        let manifest = PluginManifest::builder(
            "com.example.notes",
            "Notes Helper",
            "1.0.0",
            "1.0.0",
            "notes-helper",
            ExecutionModel::ExternalProcess,
        )
        .capability(Capability::Notification)
        .build()
        .unwrap();
        let permission_manifest = PluginPermissionManifest {
            plugin_id: "com.example.notes".into(),
            required: vec![PermissionKind::Notifications],
            optional: Vec::new(),
        };

        let handoff = cx
            .read(|app| {
                app.helper_plugin_handoff_checked(
                    HelperPluginHandoffBuilder::new()
                        .launch_builder(HelperProcessLaunch::plugin_host(
                            crate::ProcessId(90),
                            "notes-plugin-host",
                            &helper_path,
                        ))
                        .plugin_manifest(manifest)
                        .plugin_permissions(
                            permission_manifest.clone(),
                            [PermissionKind::Notifications],
                        )
                        .ipc_schema(IpcSchema::new(2, 1, vec!["plugin.ping".into()]))
                        .crash_policy(crate::CrashPolicy::default()),
                )
            })
            .unwrap();

        assert_eq!(handoff.request_count(), 5);
        assert_eq!(
            handoff.next_action(),
            HelperPluginNextAction::ConfigurePluginContracts
        );
        assert!(handoff.has_plugin_contracts());
        assert!(handoff.has_supervisor_policy());
        assert!(handoff.requires_broker_and_context());
        assert!(!handoff.can_spawn_native_helpers());

        let utility = cx
            .read(|app| {
                app.helper_plugin_handoff_checked(HelperPluginHandoffBuilder::new().launch_builder(
                    HelperProcessLaunch::utility(crate::ProcessId(91), "thumbnailer", &helper_path),
                ))
            })
            .unwrap();
        assert_eq!(
            utility.next_action(),
            HelperPluginNextAction::SpawnNativeHelper
        );
        assert!(!utility.has_supervisor_policy());
        assert!(utility.can_spawn_native_helpers());

        assert!(
            cx.read(|app| {
                app.helper_plugin_handoff_checked(
                    HelperPluginHandoffBuilder::new().plugin_permissions(permission_manifest, []),
                )
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                app.helper_plugin_handoff_checked(HelperPluginHandoffBuilder::new().ipc_schema(
                    IpcSchema::new(1, 1, vec!["plugin.ping".into(), "plugin.ping".into()]),
                ))
            })
            .is_err()
        );
    }

    #[test]
    fn edit_command_state_snapshot_validates_labels() {
        let snapshot = EditCommandStateSnapshot::new(
            true,
            Some("Undo typing".to_string()),
            true,
            Some("Redo typing".to_string()),
        )
        .unwrap();

        assert!(snapshot.can_undo());
        assert!(snapshot.can_redo());
        assert!(snapshot.has_available_command());
        assert_eq!(snapshot.available_command_count(), 2);
        assert!(snapshot.has_undo_label());
        assert!(snapshot.has_redo_label());
        assert_eq!(snapshot.undo_label(), Some("Undo typing"));
        assert_eq!(snapshot.redo_label(), Some("Redo typing"));
        assert_eq!(
            snapshot.to_text(),
            "edit command state: undo true, redo true, available 2, undo label true, redo label true"
        );
        assert!(!snapshot.to_text().contains("Undo typing"));
        assert!(!snapshot.to_text().contains("Redo typing"));

        assert!(
            EditCommandStateSnapshot::new(false, Some("Undo typing".to_string()), false, None)
                .is_err()
        );
        assert!(
            EditCommandStateSnapshot::new(true, Some(" Undo typing".to_string()), false, None)
                .is_err()
        );
        assert!(
            EditCommandStateSnapshot::new(false, None, true, Some("Redo\nline".to_string()))
                .is_err()
        );
    }

