    #[test]
    fn tray_icon_builder_validates_encoded_image_bytes() {
        let clear = TrayIconBuilder::clear();
        assert!(clear.validate().is_ok());
        assert!(clear.is_clear());
        assert!(!clear.has_icon());
        assert_eq!(clear.byte_len(), 0);
        assert_eq!(clear.icon_bytes(), None);
        assert_eq!(
            clear.to_text(),
            "tray icon: clear true, bytes 0, has icon false"
        );

        let png_builder = TrayIconBuilder::png(b"\x89PNG\r\n\x1a\nrest".to_vec());
        assert!(png_builder.has_icon());
        assert_eq!(png_builder.byte_len(), 12);
        assert_eq!(
            png_builder.to_text(),
            "tray icon: clear false, bytes 12, has icon true"
        );
        assert!(!png_builder.to_text().contains("rest"));

        let png = png_builder.build_checked().unwrap().unwrap();
        assert!(png.starts_with(b"\x89PNG\r\n\x1a\n"));

        let ico = TrayIconBuilder::ico(b"\0\0\x01\0rest".to_vec());
        assert!(ico.validate().is_ok());
        let gif = TrayIconBuilder::bytes(b"GIF89arest".to_vec());
        assert!(gif.validate().is_ok());
        let jpeg = TrayIconBuilder::bytes(b"\xff\xd8\xffresting".to_vec());
        assert!(jpeg.validate().is_ok());
        let webp = TrayIconBuilder::bytes(b"RIFFxxxxWEBPrest".to_vec());
        assert!(webp.validate().is_ok());

        assert!(TrayIconBuilder::bytes(Vec::<u8>::new()).validate().is_err());
        assert!(TrayIconBuilder::bytes(b"PNG".to_vec()).validate().is_err());
        assert!(
            TrayIconBuilder::bytes(b"not-an-image".to_vec())
                .validate()
                .is_err()
        );
        assert!(
            TrayIconBuilder::bytes(vec![0; 10 * 1024 * 1024 + 1])
                .validate()
                .is_err()
        );
    }

