    #[test]
    fn tray_app_builder_validates_menu_tooltip_and_background_mode() {
        let builder = TrayAppBuilder::new()
            .action("Show Window", "show")
            .separator()
            .toggle("Pause Sync", false, "pause-sync")
            .status_tooltip("Sync running")
            .panel();

        assert_eq!(builder.menu_item_count(), 3);
        assert_eq!(builder.action_count(), 1);
        assert_eq!(builder.toggle_count(), 1);
        assert_eq!(builder.submenu_count(), 0);
        assert!(builder.has_tooltip());
        assert!(builder.panel_mode_enabled());
        assert!(builder.keeps_alive_without_windows());
        assert_eq!(
            builder.to_text(),
            "tray app builder: items 3, actions 1, toggles 1, submenus 0, tooltip true, panel true, keep-alive true"
        );
        assert!(!builder.to_text().contains("Show Window"));
        assert!(!builder.to_text().contains("show"));
        assert!(!builder.to_text().contains("Pause Sync"));
        assert!(!builder.to_text().contains("pause-sync"));
        assert!(!builder.to_text().contains("Sync running"));

        let config = builder.build_checked().unwrap();

        assert_eq!(config.menu().len(), 3);
        assert_eq!(config.menu_item_count(), 3);
        assert_eq!(config.action_count(), 1);
        assert_eq!(config.toggle_count(), 1);
        assert_eq!(config.submenu_count(), 0);
        assert_eq!(config.action_ids(), vec!["show", "pause-sync"]);
        assert_eq!(config.tooltip(), Some("Sync running"));
        assert!(config.has_tooltip());
        assert!(config.panel_mode());
        assert!(config.keep_alive_without_windows());
        assert_eq!(
            config.to_text(),
            "tray app: items 3, actions 1, toggles 1, submenus 0, tooltip true, panel true, keep-alive true"
        );
        assert!(!config.to_text().contains("Show Window"));
        assert!(!config.to_text().contains("show"));
        assert!(!config.to_text().contains("Pause Sync"));
        assert!(!config.to_text().contains("pause-sync"));
        assert!(!config.to_text().contains("Sync running"));

        assert!(TrayAppBuilder::new().validate().is_err());
        assert!(
            TrayAppBuilder::new()
                .action("Show", "show")
                .status_tooltip(" bad")
                .validate()
                .is_err()
        );
        assert!(
            TrayAppBuilder::new()
                .action("Show", "duplicate")
                .action("Hide", "duplicate")
                .validate()
                .is_err()
        );
    }

