    #[test]
    fn runtime_snapshot_reports_app_lifecycle_state() {
        let cx = TestAppContext::single();

        let initial = cx.read(|app| app.runtime_snapshot());
        assert_eq!(initial.process_id(), ProcessId(0));
        assert_eq!(initial.window_count(), 0);
        assert!(!initial.keep_alive_without_windows());
        assert!(!initial.is_background_runtime());
        assert_eq!(initial.quit_cleanup_timeout(), SHUTDOWN_TIMEOUT);
        assert!(!initial.is_quitting());
        assert_eq!(initial.network_status(), NetworkStatus::Online);
        assert_eq!(initial.power().power_mode(), PowerMode::Performance);
        assert!(initial.theme().is_light());

        cx.update(|app| {
            app.set_keep_alive_without_windows(true);
        });
        let background = cx.read(|app| app.runtime_snapshot());
        assert!(background.keep_alive_without_windows());
        assert!(background.is_background_runtime());

        cx.update(|app| {
            app.configure_lifecycle_policy_checked(
                AppLifecyclePolicyBuilder::new()
                    .quit_when_all_windows_close()
                    .quit_cleanup_timeout(Duration::from_millis(300)),
            )
        })
        .unwrap();
        let foreground = cx.read(|app| app.runtime_snapshot());
        assert!(!foreground.keep_alive_without_windows());
        assert!(!foreground.is_background_runtime());
        assert_eq!(
            foreground.quit_cleanup_timeout(),
            Duration::from_millis(300)
        );
        assert!(foreground.uptime() < Duration::from_secs(60));
    }

    #[test]
    fn runtime_snapshot_checked_validates_startup_requirements() {
        let cx = TestAppContext::single();

        let permissive = cx
            .read(|app| app.runtime_snapshot_checked(AppRuntimeSnapshotQueryBuilder::new()))
            .unwrap();
        assert_eq!(permissive.window_count(), 0);
        assert!(!permissive.is_background_runtime());

        let query = AppRuntimeSnapshotQueryBuilder::new()
            .require_not_quitting()
            .require_network_online()
            .allow_background_runtime();
        let snapshot = cx.read(|app| app.runtime_snapshot_checked(query)).unwrap();
        assert!(!snapshot.is_quitting());
        assert_eq!(snapshot.network_status(), NetworkStatus::Online);
        assert!(query.requires_not_quitting());
        assert!(query.requires_network_online());
        assert!(query.allows_background_runtime());

        assert!(
            cx.read(|app| app
                .runtime_snapshot_checked(AppRuntimeSnapshotQueryBuilder::new().require_window()))
                .is_err()
        );
        assert!(
            cx.read(|app| app.runtime_snapshot_checked(
                AppRuntimeSnapshotQueryBuilder::new().require_background_runtime()
            ))
            .is_err()
        );

        cx.update(|app| {
            app.set_keep_alive_without_windows(true);
        });
        let background = cx
            .read(|app| {
                app.runtime_snapshot_checked(
                    AppRuntimeSnapshotQueryBuilder::new().require_background_runtime(),
                )
            })
            .unwrap();
        assert!(background.is_background_runtime());
        assert!(
            AppRuntimeSnapshotQueryBuilder::new()
                .require_background_runtime()
                .requires_background_runtime()
        );
        assert!(
            cx.read(|app| app
                .runtime_snapshot_checked(AppRuntimeSnapshotQueryBuilder::new().require_window()))
                .is_err()
        );
    }

    #[test]
    fn app_lifecycle_command_validates_activation_and_terminal_commands() {
        let activate =
            AppLifecycleCommand::activate_with_options(true).reason("Show existing project window");
        assert!(activate.validate().is_ok());
        assert_eq!(
            activate.kind(),
            AppLifecycleCommandKind::Activate {
                ignoring_other_apps: true
            }
        );
        assert_eq!(activate.kind().to_text(), "activate");
        assert!(activate.kind().ignores_other_apps());
        assert_eq!(activate.reason_text(), Some("Show existing project window"));
        assert!(!activate.is_terminal());
        assert!(activate.has_reason());
        assert_eq!(
            activate.to_text(),
            "lifecycle command: kind activate, terminal false, reason true, ignoring other apps true"
        );
        assert!(!activate.to_text().contains("Show existing project window"));

        let quit = AppLifecycleCommand::quit("User selected Quit");
        assert!(quit.validate().is_ok());
        assert!(quit.is_terminal());
        assert_eq!(quit.kind().to_text(), "quit");
        assert!(!quit.kind().ignores_other_apps());
        assert_eq!(
            quit.to_text(),
            "lifecycle command: kind quit, terminal true, reason true, ignoring other apps false"
        );
        assert!(!quit.to_text().contains("User selected Quit"));

        let restart = AppLifecycleCommand::restart("Apply update");
        assert!(restart.validate().is_ok());
        assert!(restart.is_terminal());
        assert_eq!(restart.kind().to_text(), "restart");

        assert!(AppLifecycleCommand::quit("").validate().is_err());
        assert!(
            AppLifecycleCommand::restart(" Apply update")
                .validate()
                .is_err()
        );
        assert!(
            AppLifecycleCommand::hide()
                .reason("Line one\nLine two")
                .validate()
                .is_ok()
        );
        assert!(
            AppLifecycleCommand::hide()
                .reason("x".repeat(257))
                .validate()
                .is_err()
        );
    }

    #[test]
    fn lifecycle_command_plan_reports_runtime_readiness() {
        let cx = TestAppContext::single();

        let activate = cx
            .read(|app| {
                app.lifecycle_command_plan_checked(
                    AppLifecycleCommand::activate_with_options(true)
                        .reason("Reveal private project"),
                )
            })
            .unwrap();

        assert_eq!(
            activate.command().kind(),
            AppLifecycleCommandKind::Activate {
                ignoring_other_apps: true
            }
        );
        assert_eq!(activate.kind().to_text(), "activate");
        assert!(!activate.is_terminal());
        assert!(activate.has_reason());
        assert!(activate.ignores_other_apps());
        assert_eq!(activate.window_count(), 0);
        assert!(!activate.has_windows());
        assert!(!activate.is_background_runtime());
        assert!(!activate.is_quitting());
        assert!(!activate.restart_path_configured());
        assert!(activate.is_ready());
        assert!(!activate.has_gap());
        assert_eq!(
            activate.to_text(),
            "lifecycle command plan: kind activate, terminal false, reason true, windows 0, background false, quitting false, restart path false, ready true"
        );
        assert!(!activate.to_text().contains("Reveal private project"));

        let restart_path = std::env::current_exe().unwrap();
        cx.update(|app| {
            app.set_restart_path_checked(RestartPathBuilder::new(restart_path))
                .unwrap();
        });
        let restart = cx
            .read(|app| {
                app.lifecycle_command_plan_checked(AppLifecycleCommand::restart("Apply update"))
            })
            .unwrap();

        assert_eq!(restart.kind().to_text(), "restart");
        assert!(restart.is_terminal());
        assert!(restart.has_reason());
        assert!(restart.restart_path_configured());
        assert!(restart.is_ready());
        assert_eq!(
            restart.to_text(),
            "lifecycle command plan: kind restart, terminal true, reason true, windows 0, background false, quitting false, restart path true, ready true"
        );
        assert!(!restart.to_text().contains("Apply update"));
    }

