    #[test]
    fn visual_capture_handoff_builder_validates_native_and_hosted_evidence() {
        let handoff = VisualCaptureHandoff::builder()
            .app_window_capture_builder(
                AppWindowCaptureRequestBuilder::focused_window(
                    "Capture visual regression evidence.",
                )
                .rgba()
                .include_window_chrome()
                .max_dimensions(1280, 720),
            )
            .unwrap()
            .native_snapshot_evidence("headless-render", 2)
            .hosted_capture(HostedVisualCaptureDescriptor::dom_image(
                "preview", "#receipt",
            ))
            .support_diagnostics(SupportDiagnosticsBuilder::new())
            .roadmap_work("full page stitched capture")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 5);
        assert!(handoff.has_app_window_capture());
        assert!(handoff.has_native_evidence());
        assert!(handoff.has_hosted_capture());
        assert!(handoff.has_support_diagnostics());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            VisualCaptureNextAction::CaptureAppWindow
        );
        assert!(handoff.to_text().contains("visual capture handoff"));
        assert!(handoff.to_text().contains("app-window-capture"));
        assert!(handoff.to_text().contains("native-snapshot-evidence"));
        assert!(handoff.to_text().contains("dom-image"));
        assert!(handoff.to_text().contains("support-diagnostics"));
        assert!(!handoff.to_text().contains("visual regression"));
        assert!(!handoff.to_text().contains("headless-render"));
        assert!(!handoff.to_text().contains("preview"));
        assert!(!handoff.to_text().contains("#receipt"));
        assert!(!handoff.to_text().contains("full page"));

        let descriptor = match &handoff.requests()[2] {
            VisualCaptureRequest::HostedCapture(descriptor) => descriptor,
            request => panic!("unexpected request {request:?}"),
        };
        assert_eq!(descriptor.kind(), HostedVisualCaptureKind::DomImage);
        assert_eq!(
            descriptor.to_text(),
            "hosted visual capture descriptor: kind dom-image, surface true, selector true"
        );
        assert_eq!(HostedVisualCaptureKind::MediaFrame.to_text(), "media-frame");
    }

