    #[cfg(feature = "auto-update")]
    #[test]
    fn app_network_and_download_handoffs_use_checked_builders() {
        let cx = TestAppContext::single();
        let policy = NetworkPolicyBuilder::new()
            .allow_host("api.example.com")
            .allow_host("events.example.com")
            .allow_host("cdn.example.com")
            .build_checked()
            .unwrap();

        let network = cx
            .read(|app| {
                app.network_realtime_handoff_checked(
                    NetworkRealtimeHandoffBuilder::new()
                        .request_builder(
                            AppNetworkRequestBuilder::post("https://api.example.com/v1/sync")
                                .header("Content-Type", "application/json")
                                .body_size_bytes(512)
                                .network_policy(policy.clone()),
                        )?
                        .realtime_connection_builder(
                            AppRealtimeConnection::websocket("wss://events.example.com/socket")
                                .protocol("app.v1")
                                .reconnect_conservative()
                                .network_policy(policy.clone()),
                        )?
                        .network_policy(policy.clone())
                        .hosted_network_bridge("checkout"),
                )
            })
            .unwrap();

        assert_eq!(network.request_count(), 4);
        assert_eq!(
            network.next_action(),
            NetworkRealtimeNextAction::DispatchNativeRequest
        );
        assert!(network.has_native_requests());
        assert!(network.has_realtime_transports());
        assert!(network.has_network_policy());
        assert!(network.has_hosted_network_bridge());

        let realtime = cx
            .read(|app| {
                app.realtime_connection_checked(
                    AppRealtimeConnection::websocket("wss://events.example.com/socket")
                        .protocol("app.v1")
                        .reconnect_conservative(),
                )
            })
            .unwrap();
        assert_eq!(realtime.protocol_count(), 1);
        assert!(realtime.has_reconnect_policy());

        let realtime_set = cx
            .read(|app| {
                app.realtime_connection_set_checked(
                    AppRealtimeConnectionSetBuilder::new()
                        .connection(realtime)
                        .connection_builder(AppRealtimeConnection::server_sent_events(
                            "https://events.example.com/stream",
                        ))?,
                )
            })
            .unwrap();
        assert_eq!(realtime_set.connection_count(), 2);
        assert_eq!(realtime_set.websocket_count(), 1);
        assert_eq!(realtime_set.server_sent_events_count(), 1);

        let download_path = std::env::temp_dir().join("kael-agent-model-download.bin");
        let destination = cx
            .read(|app| {
                app.download_destination_plan_checked(
                    DownloadDestinationPlanBuilder::new("https://cdn.example.com/assets/model.bin")
                        .destination(download_path.clone())
                        .network_policy(policy.clone())
                        .sha256("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
                        .size_bytes(1024)
                        .create_parent_dirs(),
                )
            })
            .unwrap();
        assert!(destination.can_build_request());
        assert!(destination.has_integrity_metadata());

        let request = cx
            .read(|app| app.download_request_checked(destination.request_builder()?))
            .unwrap();
        assert!(request.has_sha256());
        assert!(request.has_size());

        let batch = cx
            .read(|app| app.download_batch_checked(DownloadBatchBuilder::new().request(request)))
            .unwrap();
        assert_eq!(batch.request_count(), 1);

        let execution = cx
            .read(|app| {
                app.download_execution_plan_checked(
                    DownloadExecutionPlanBuilder::new(batch.clone())
                        .max_parallel(2)
                        .retry_attempts(1)
                        .temporary_file_extension("partial"),
                )
            })
            .unwrap();
        assert_eq!(execution.request_count(), 1);
        assert_eq!(execution.max_parallel(), 2);
        assert!(execution.uses_temporary_files());

        let download = cx
            .read(|app| {
                app.download_handoff_checked(
                    DownloadHandoffBuilder::new()
                        .request(batch.requests()[0].clone())
                        .max_parallel(2)
                        .retry_attempts(1),
                )
            })
            .unwrap();

        assert_eq!(download.request_count(), 1);
        assert_eq!(
            download.next_action(),
            DownloadHandoffNextAction::QueueDownloads
        );
        assert!(download.has_complete_network_policy());
        assert!(download.has_complete_integrity_metadata());
        assert!(download.is_queue_ready());
        assert!(
            cx.read(
                |app| app.network_realtime_handoff_checked(NetworkRealtimeHandoffBuilder::new())
            )
            .is_err()
        );
        assert!(
            cx.read(|app| {
                app.realtime_connection_checked(AppRealtimeConnection::websocket(
                    "https://events.example.com/not-a-websocket",
                ))
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                app.realtime_connection_set_checked(AppRealtimeConnectionSetBuilder::new())
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                app.download_destination_plan_checked(DownloadDestinationPlanBuilder::new(
                    "ftp://cdn.example.com/assets/model.bin",
                ))
            })
            .is_err()
        );
        assert!(
            cx.read(|app| app.download_request_checked(DownloadRequest::builder(
                "ftp://cdn.example.com/assets/model.bin",
                std::env::temp_dir().join("bad.bin"),
            )))
            .is_err()
        );
        assert!(
            cx.read(|app| app.download_batch_checked(DownloadBatchBuilder::new()))
                .is_err()
        );
        assert!(
            cx.read(|app| app.download_execution_plan_checked(
                DownloadExecutionPlanBuilder::new(batch).max_parallel(0)
            ))
            .is_err()
        );
        assert!(
            cx.read(|app| app.download_handoff_checked(DownloadHandoffBuilder::new()))
                .is_err()
        );
    }

    #[test]
    fn app_lifecycle_policy_builder_validates_shutdown_policy() {
        let policy = AppLifecyclePolicyBuilder::new()
            .keep_alive_without_windows()
            .quit_cleanup_timeout(Duration::from_millis(250))
            .reason("tray background sync")
            .build_checked()
            .unwrap();

        assert!(policy.keep_alive_without_windows());
        assert_eq!(
            policy.window_close_behavior(),
            super::WindowCloseBehavior::KeepAliveWithoutWindows
        );
        assert_eq!(policy.window_close_behavior().to_text(), "keep-alive");
        assert_eq!(policy.quit_cleanup_timeout(), Duration::from_millis(250));
        assert_eq!(policy.reason(), Some("tray background sync"));
        assert!(policy.has_reason());
        assert_eq!(
            policy.to_text(),
            "app lifecycle policy: behavior keep-alive, keep-alive true, quit cleanup ms 250, reason true"
        );
        assert!(!policy.to_text().contains("tray background sync"));

        let builder = AppLifecyclePolicyBuilder::new()
            .quit_when_all_windows_close()
            .quit_cleanup_timeout(Duration::from_millis(750));
        assert_eq!(builder.window_close_behavior().to_text(), "quit");
        assert!(!builder.has_reason());
        assert_eq!(
            builder.to_text(),
            "app lifecycle policy builder: behavior quit, keep-alive false, quit cleanup ms 750, reason false"
        );

        assert!(
            AppLifecyclePolicyBuilder::new()
                .quit_cleanup_timeout(Duration::ZERO)
                .validate()
                .is_err()
        );
        assert!(
            AppLifecyclePolicyBuilder::new()
                .quit_cleanup_timeout(Duration::from_secs(31))
                .validate()
                .is_err()
        );
        assert!(
            AppLifecyclePolicyBuilder::new()
                .reason(" bad")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn configure_lifecycle_policy_checked_applies_platform_state() {
        let cx = TestAppContext::single();

        let policy = cx
            .update(|app| {
                app.configure_lifecycle_policy_checked(
                    AppLifecyclePolicyBuilder::new()
                        .keep_alive_without_windows()
                        .quit_cleanup_timeout(Duration::from_millis(500)),
                )
            })
            .unwrap();
        assert!(policy.keep_alive_without_windows());
        assert!(cx.keep_alive_without_windows());
        assert_eq!(
            cx.read(|app| app.quit_cleanup_timeout()),
            Duration::from_millis(500)
        );

        let policy = cx
            .update(|app| {
                app.configure_lifecycle_policy_checked(
                    AppLifecyclePolicyBuilder::new()
                        .quit_when_all_windows_close()
                        .quit_cleanup_timeout(Duration::from_millis(100)),
                )
            })
            .unwrap();
        assert!(!policy.keep_alive_without_windows());
        assert!(!cx.keep_alive_without_windows());
        assert_eq!(
            cx.read(|app| app.quit_cleanup_timeout()),
            Duration::from_millis(100)
        );

        assert!(
            cx.update(|app| {
                app.configure_lifecycle_policy_checked(
                    AppLifecyclePolicyBuilder::new().quit_cleanup_timeout(Duration::ZERO),
                )
            })
            .is_err()
        );
    }

    #[test]
    fn biometric_auth_builder_validates_prompt_reason() {
        assert!(
            BiometricAuthBuilder::new("Unlock your vault")
                .validate()
                .is_ok()
        );
        assert!(BiometricAuthBuilder::unlock_vault().validate().is_ok());
        assert_eq!(
            BiometricAuthBuilder::unlock_vault().reason(),
            "Unlock your vault"
        );
        assert!(BiometricAuthBuilder::approve_payment().validate().is_ok());
        assert_eq!(
            BiometricAuthBuilder::approve_payment().reason(),
            "Approve payment"
        );
        assert!(BiometricAuthBuilder::new("  ").validate().is_err());
        assert!(BiometricAuthBuilder::new(" Unlock").validate().is_err());
        assert!(BiometricAuthBuilder::new("Unlock ").validate().is_err());
        assert!(
            BiometricAuthBuilder::new("Unlock\nvault")
                .validate()
                .is_err()
        );
        assert!(
            BiometricAuthBuilder::new("Unlock\0vault")
                .validate()
                .is_err()
        );
        assert!(
            BiometricAuthBuilder::new("a".repeat(257))
                .validate()
                .is_err()
        );

        let prompt = BiometricAuthBuilder::new("Retry biometric unlock").allow_unavailable();
        assert_eq!(prompt.reason(), "Retry biometric unlock");
        assert!(!prompt.requires_available());
        assert_eq!(
            prompt.build_checked().unwrap(),
            ("Retry biometric unlock".to_string(), false)
        );
    }

    #[test]
    fn authenticate_biometric_with_skips_unavailable_prompt_by_default() {
        let cx = TestAppContext::single();
        let called = Arc::new(Mutex::new(false));

        let request = cx
            .read(|app| {
                app.authenticate_biometric_with(BiometricAuthBuilder::new("Unlock secure notes"), {
                    let called = called.clone();
                    move |_| {
                        *called.lock().unwrap() = true;
                    }
                })
            })
            .unwrap();

        assert_eq!(request.status(), BiometricStatus::Unavailable);
        assert!(!request.prompted());
        assert!(!request.available());
        assert_eq!(request.kind(), None);
        assert_eq!(request.reason(), "Unlock secure notes");
        assert_eq!(
            request.to_text(),
            "biometric authentication unavailable, not prompted, reason 'Unlock secure notes'"
        );
        assert!(!*called.lock().unwrap());
        assert!(cx.biometric_auth_reasons().is_empty());
    }

    #[test]
    fn authenticate_biometric_with_routes_available_prompt() {
        let cx = TestAppContext::single();
        cx.set_biometric_status(BiometricStatus::Available(BiometricKind::Fingerprint));
        cx.set_biometric_auth_success(true);
        let result = Arc::new(Mutex::new(None));

        let request = cx
            .read(|app| {
                app.authenticate_biometric_with(BiometricAuthBuilder::new("Approve payment"), {
                    let result = result.clone();
                    move |success| {
                        *result.lock().unwrap() = Some(success);
                    }
                })
            })
            .unwrap();

        assert_eq!(
            request.status(),
            BiometricStatus::Available(BiometricKind::Fingerprint)
        );
        assert!(request.prompted());
        assert!(request.available());
        assert_eq!(request.kind(), Some(BiometricKind::Fingerprint));
        assert_eq!(request.reason(), "Approve payment");
        assert_eq!(
            request.to_text(),
            "biometric authentication available fingerprint, prompted, reason 'Approve payment'"
        );
        assert_eq!(*result.lock().unwrap(), Some(true));
        assert_eq!(
            cx.biometric_auth_reasons(),
            vec!["Approve payment".to_string()]
        );
    }

