    #[test]
    fn secure_credential_helpers_round_trip_through_platform() {
        let cx = TestAppContext::single();

        let write = cx
            .read(|app| {
                app.write_secure_credential(
                    CredentialBuilder::new("https://example.com")
                        .username("ada")
                        .password("correct horse"),
                )
            })
            .unwrap();
        cx.background_executor.block(write).unwrap();

        let stored = cx
            .background_executor
            .block(
                cx.read(|app| {
                    app.read_secure_credential_checked(CredentialServiceBuilder::new(
                        "https://example.com",
                    ))
                })
                .unwrap(),
            )
            .unwrap()
            .unwrap();
        assert_eq!(stored.username(), "ada");
        assert_eq!(stored.secret(), b"correct horse");
        assert_eq!(stored.secret_len(), "correct horse".len());
        assert_eq!(
            stored.to_text(),
            "stored credential for ada, secret 13 bytes"
        );
        assert!(!stored.to_text().contains("correct horse"));

        cx.background_executor
            .block(
                cx.read(|app| {
                    app.delete_secure_credential_checked(CredentialServiceBuilder::new(
                        "https://example.com",
                    ))
                })
                .unwrap(),
            )
            .unwrap();

        let missing = cx
            .background_executor
            .block(cx.read(|app| app.read_secure_credential("https://example.com")))
            .unwrap();
        assert!(missing.is_none());

        assert!(
            cx.read(
                |app| app.read_secure_credential_checked(CredentialServiceBuilder::new(
                    " https://example.com"
                ))
            )
            .is_err()
        );
        assert!(
            cx.read(
                |app| app.delete_secure_credential_checked(CredentialServiceBuilder::new(
                    "https://example.com\0"
                ))
            )
            .is_err()
        );
    }

    fn secure_keychain_report(support: SupportLevel) -> CapabilityReport {
        CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![FeatureReport {
                feature: PlatformFeature::SecureKeychain,
                support,
                note: None,
            }],
        }
    }

    #[test]
    fn secure_credential_handoff_builder_validates_full_secret_flow() {
        let process_id = ProcessId(7);
        let handoff = SecureCredentialHandoffBuilder::new(process_id)
            .feature_preflight(secure_keychain_report(SupportLevel::Full))
            .permission_broker(
                PermissionBrokerInstallBuilder::new()
                    .grant(Capability::Network {
                        hosts: vec!["api.example.com".into()],
                    })
                    .deny_ungranted(),
            )
            .write(
                CredentialBuilder::new("https://api.example.com")
                    .username("ada")
                    .password("refresh-token"),
            )
            .read(CredentialServiceBuilder::new("https://api.example.com"))
            .delete(CredentialServiceBuilder::new("https://api.example.com"))
            .support_diagnostics(SupportDiagnosticsBuilder::new())
            .hosted_auth_profile("browser-login-profile")
            .roadmap_work("native passkey credential recipe")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.process_id(), process_id);
        assert_eq!(handoff.request_count(), 8);
        assert!(handoff.has_feature_preflight());
        assert!(handoff.has_permission_broker());
        assert!(handoff.has_write());
        assert!(handoff.has_read());
        assert!(handoff.has_delete());
        assert!(handoff.has_support_diagnostics());
        assert!(handoff.has_hosted_auth_profile());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            SecureCredentialNextAction::CheckSecureKeychain
        );

        let text = handoff.to_text();
        assert!(text.contains("secure credential handoff"));
        assert!(text.contains("feature-preflight"));
        assert!(text.contains("hosted-auth-profile"));
        assert!(!text.contains("https://api.example.com"));
        assert!(!text.contains("ada"));
        assert!(!text.contains("refresh-token"));
        assert!(!text.contains("browser-login-profile"));
        assert!(!text.contains("native passkey credential recipe"));
    }

