    #[test]
    fn secure_credential_handoff_next_action_covers_routes() {
        let process_id = ProcessId(7);
        let cases = [
            (
                SecureCredentialHandoffBuilder::new(process_id)
                    .feature_preflight(secure_keychain_report(SupportLevel::Full)),
                SecureCredentialNextAction::CheckSecureKeychain,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id)
                    .permission_broker(PermissionBrokerInstallBuilder::new().deny_ungranted()),
                SecureCredentialNextAction::InstallPermissionBroker,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id).write(
                    CredentialBuilder::new("service")
                        .username("ada")
                        .password("secret"),
                ),
                SecureCredentialNextAction::WriteCredential,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id)
                    .read(CredentialServiceBuilder::new("service")),
                SecureCredentialNextAction::ReadCredential,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id)
                    .delete(CredentialServiceBuilder::new("service")),
                SecureCredentialNextAction::DeleteCredential,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id)
                    .support_diagnostics(SupportDiagnosticsBuilder::new()),
                SecureCredentialNextAction::ExportSupportDiagnostics,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id).hosted_auth_profile("auth-profile"),
                SecureCredentialNextAction::UseHostedAuthProfile,
            ),
            (
                SecureCredentialHandoffBuilder::new(process_id).roadmap_work("credential rotation"),
                SecureCredentialNextAction::TrackRoadmapWork,
            ),
        ];

        for (builder, expected) in cases {
            let handoff = builder.build_checked().unwrap();
            assert_eq!(handoff.next_action(), expected);
        }
    }

