    #[test]
    fn power_save_blocker_builder_preserves_intent() {
        let blocker = PowerSaveBlockerBuilder::prevent_display_sleep().reason("video playback");

        assert_eq!(blocker.kind(), PowerSaveBlockerKind::PreventDisplaySleep);
        assert_eq!(blocker.configured_reason(), Some("video playback"));
        assert!(blocker.has_reason());
        assert_eq!(
            blocker.to_text(),
            "power-save blocker builder prevent display sleep, reason true"
        );
        assert!(!blocker.to_text().contains("video playback"));
        assert!(blocker.validate().is_ok());
        let plan = blocker.build_checked().unwrap();
        assert_eq!(plan.kind(), PowerSaveBlockerKind::PreventDisplaySleep);
        assert_eq!(plan.reason(), Some("video playback"));
        assert!(plan.has_reason());
        assert!(plan.prevents_display_sleep());
        assert!(!plan.prevents_app_suspension());
        assert_eq!(
            plan.to_text(),
            "power-save blocker prevent display sleep, reason true"
        );
        assert!(!plan.to_text().contains("video playback"));
        assert_eq!(
            PowerSaveBlockerBuilder::prevent_app_suspension()
                .build_checked()
                .unwrap()
                .to_text(),
            "power-save blocker prevent app suspension, reason false"
        );
        assert!(
            PowerSaveBlockerBuilder::prevent_display_sleep()
                .reason(" ")
                .validate()
                .is_err()
        );
    }

