    #[test]
    fn stop_power_save_blocker_checked_validates_and_stops() {
        let cx = TestAppContext::single();

        let handle = cx
            .read(|app| {
                app.start_power_save_blocker_checked(
                    PowerSaveBlockerBuilder::prevent_display_sleep().reason("video playback"),
                )
            })
            .unwrap()
            .unwrap();

        assert_eq!(
            cx.power_save_blockers(),
            vec![(handle.id(), PowerSaveBlockerKind::PreventDisplaySleep)]
        );

        assert!(
            cx.read(|app| {
                app.stop_power_save_blocker_checked(PowerSaveBlockerStopBuilder::id(0))
            })
            .is_err()
        );
        assert_eq!(
            cx.power_save_blockers(),
            vec![(handle.id(), PowerSaveBlockerKind::PreventDisplaySleep)]
        );

        let stopped = cx
            .read(|app| {
                app.stop_power_save_blocker_checked(
                    PowerSaveBlockerStopBuilder::handle(&handle).reason("video stopped"),
                )
            })
            .unwrap();

        assert_eq!(stopped.blocker_id(), handle.id());
        assert_eq!(stopped.configured_reason(), Some("video stopped"));
        assert!(stopped.has_reason());
        assert_eq!(
            stopped.to_text(),
            "power-save blocker stop id 1, reason true"
        );
        assert!(!stopped.to_text().contains("video stopped"));
        assert!(cx.power_save_blockers().is_empty());
        assert!(
            PowerSaveBlockerStopBuilder::id(42)
                .reason("bad\nreason")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn power_theme_idle_handoff_builder_validates_native_adaptive_surface() {
        let monitor = SystemPowerMonitorBuilder::new()
            .on_power_mode_changed(|_, _| {})
            .on_resume(|_, _| {});
        let handoff = PowerThemeIdleHandoff::builder()
            .power_save_blocker_builder(
                PowerSaveBlockerBuilder::prevent_display_sleep().reason("video playback"),
            )
            .unwrap()
            .stop_power_save_blocker(PowerSaveBlockerStopBuilder::id(7).reason("video stopped"))
            .unwrap()
            .power_monitor_builder(&monitor)
            .unwrap()
            .power_source_query(SystemPowerSourceQueryBuilder::new().require_known_source())
            .native_theme(NativeThemeSnapshot::new(
                WindowAppearance::VibrantDark,
                true,
                PowerMode::LowPower,
            ))
            .idle_policy_builder(SystemIdlePolicyBuilder::minutes(5).require_known_idle_time())
            .unwrap()
            .hosted_power_bridge("player")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 7);
        assert!(handoff.has_power_save_blocker());
        assert!(handoff.has_stop_request());
        assert!(handoff.has_power_monitor());
        assert!(handoff.has_native_theme());
        assert!(handoff.has_idle_policy());
        assert!(handoff.has_hosted_power_bridge());
        assert_eq!(
            handoff.next_action(),
            PowerThemeIdleNextAction::ReviewSleepPrevention
        );
        assert!(handoff.to_text().contains("power/theme/idle handoff"));
        assert!(handoff.to_text().contains("hosted-power-bridge"));
        assert!(!handoff.to_text().contains("video playback"));
        assert!(!handoff.to_text().contains("video stopped"));
        assert!(!handoff.to_text().contains("player"));

        let monitor = match &handoff.requests()[2] {
            PowerThemeIdleRequest::PowerMonitor(monitor) => monitor,
            request => panic!("unexpected request {request:?}"),
        };
        assert_eq!(monitor.callback_count(), 2);
        assert!(monitor.has_resume_callback());
        assert!(monitor.has_power_mode_callback());
        assert!(!monitor.has_suspend_callback());
        assert!(monitor.to_text().contains("callbacks 2"));
    }

