    #[test]
    fn system_power_source_snapshot_reports_battery_state() {
        let cx = TestAppContext::single();
        cx.set_power_mode(PowerMode::Balanced);
        cx.set_system_power_source(SystemPowerSource::Discharging);
        cx.set_battery_percentage(Some(137));

        let snapshot = cx.read(|app| app.system_power_source_snapshot());

        assert_eq!(snapshot.source(), SystemPowerSource::Discharging);
        assert_eq!(snapshot.battery_percentage(), Some(100));
        assert_eq!(snapshot.power_mode(), PowerMode::Balanced);
        assert!(snapshot.is_known());
        assert!(snapshot.is_on_battery());
        assert!(!snapshot.is_external_power());
        assert!(snapshot.should_reduce_work());
        assert_eq!(snapshot.source().to_text(), "discharging");
        assert_eq!(
            snapshot.to_text(),
            "system power source discharging: known true, battery true, external false, battery percentage true, mode balanced, reduce work true"
        );
        assert!(!snapshot.to_text().contains("100"));
    }

    #[test]
    fn system_power_source_snapshot_checked_validates_requirements() {
        let cx = TestAppContext::single();

        let unknown = cx.read(|app| {
            app.system_power_source_snapshot_checked(
                SystemPowerSourceQueryBuilder::new().require_known_source(),
            )
        });
        assert!(unknown.is_err());

        cx.set_system_power_source(SystemPowerSource::Charging);
        let missing_percentage = cx.read(|app| {
            app.system_power_source_snapshot_checked(
                SystemPowerSourceQueryBuilder::new().require_battery_percentage(),
            )
        });
        assert!(missing_percentage.is_err());

        cx.set_battery_percentage(Some(88));
        let query = SystemPowerSourceQueryBuilder::new()
            .require_known_source()
            .require_battery_percentage();
        assert!(query.requires_known_source());
        assert!(query.requires_battery_percentage());
        assert_eq!(
            query.to_text(),
            "system power source query: require known true, require battery percentage true"
        );
        let snapshot = cx
            .read(|app| app.system_power_source_snapshot_checked(query))
            .unwrap();

        assert_eq!(snapshot.source(), SystemPowerSource::Charging);
        assert_eq!(snapshot.battery_percentage(), Some(88));
        assert!(snapshot.is_external_power());
        assert!(!snapshot.should_reduce_work());
    }

    #[test]
    fn native_theme_snapshot_reports_appearance_and_adaptation() {
        let snapshot =
            NativeThemeSnapshot::new(WindowAppearance::VibrantDark, true, PowerMode::Performance);

        assert_eq!(snapshot.appearance(), WindowAppearance::VibrantDark);
        assert!(snapshot.is_dark());
        assert!(!snapshot.is_light());
        assert!(snapshot.is_vibrant());
        assert!(snapshot.reduce_motion());
        assert_eq!(snapshot.power_mode(), PowerMode::Performance);
        assert!(snapshot.should_reduce_effects());
        assert!(snapshot.should_avoid_animation());
        assert!(snapshot.should_avoid_blur_or_vibrancy());
        assert!(!snapshot.should_reduce_background_work());
        assert_eq!(
            snapshot.adaptations(),
            vec![
                NativeThemeAdaptation::DarkAppearance,
                NativeThemeAdaptation::VibrantAppearance,
                NativeThemeAdaptation::ReduceMotion,
            ]
        );
        assert_eq!(snapshot.adaptations()[0].to_text(), "dark appearance");
        assert_eq!(snapshot.choose("dark", "light"), "dark");
        assert_eq!(
            snapshot.to_text(),
            "native theme: appearance vibrant dark, dark true, light false, vibrant true, reduce motion true, power performance, reduce effects true, reduce background work false, adaptations dark appearance, vibrant appearance, reduce motion"
        );

        let low_power =
            NativeThemeSnapshot::new(WindowAppearance::Light, false, PowerMode::LowPower);
        assert!(low_power.is_light());
        assert!(!low_power.is_vibrant());
        assert!(low_power.is_low_power());
        assert!(low_power.should_reduce_effects());
        assert!(!low_power.should_avoid_animation());
        assert!(low_power.should_avoid_blur_or_vibrancy());
        assert!(low_power.should_reduce_background_work());
        assert_eq!(
            low_power.adaptations(),
            vec![
                NativeThemeAdaptation::LightAppearance,
                NativeThemeAdaptation::LowPowerMode,
            ]
        );
        assert_eq!(low_power.choose("dark", "light"), "light");
        assert_eq!(
            low_power.to_text(),
            "native theme: appearance light, dark false, light true, vibrant false, reduce motion false, power low power, reduce effects true, reduce background work true, adaptations light appearance, low power mode"
        );
    }

