    #[test]
    fn system_idle_policy_evaluates_known_idle_time() {
        let policy = SystemIdlePolicyBuilder::minutes(5)
            .require_known_idle_time()
            .build_checked()
            .unwrap();
        assert_eq!(
            policy.to_text(),
            "system idle policy: threshold set true, require known true, treat unknown as idle false"
        );

        let idle_snapshot = SystemPowerSnapshot {
            power_mode: PowerMode::Performance,
            reduce_motion: false,
            idle_time: Some(Duration::from_secs(360)),
        };
        let active_snapshot = SystemPowerSnapshot {
            power_mode: PowerMode::Performance,
            reduce_motion: false,
            idle_time: Some(Duration::from_secs(120)),
        };

        let idle = policy.evaluate(&idle_snapshot);
        assert!(idle.is_idle());
        assert!(!idle.is_active());
        assert!(!idle.is_unknown());
        assert!(idle.has_known_idle_time());
        assert_eq!(idle.idle_time(), Some(Duration::from_secs(360)));
        assert_eq!(idle.threshold(), Duration::from_secs(300));
        assert_eq!(
            idle.to_text(),
            "system idle: idle true, active false, unknown false, known idle true, threshold set true"
        );
        assert!(!idle.to_text().contains("360"));

        let active = idle_snapshot.evaluate_idle(
            &SystemIdlePolicyBuilder::minutes(10)
                .build_checked()
                .unwrap(),
        );
        assert!(!active.is_idle());
        assert!(active.is_active());
        assert_eq!(active.idle_time(), Some(Duration::from_secs(360)));

        assert!(!policy.allows(&active_snapshot));
    }

    #[test]
    fn system_idle_policy_handles_unknown_idle_time_explicitly() {
        let snapshot = SystemPowerSnapshot {
            power_mode: PowerMode::Performance,
            reduce_motion: false,
            idle_time: None,
        };

        let conservative = SystemIdlePolicyBuilder::seconds(30)
            .build_checked()
            .unwrap();
        assert_eq!(
            conservative.evaluate(&snapshot),
            SystemIdleEvaluation::Unknown {
                threshold: Duration::from_secs(30),
                treated_as_idle: false
            }
        );
        assert!(!conservative.allows(&snapshot));

        let permissive_builder = SystemIdlePolicyBuilder::seconds(30).treat_unknown_as_idle();
        assert_eq!(permissive_builder.threshold(), Duration::from_secs(30));
        assert!(!permissive_builder.requires_known_idle_time());
        assert!(permissive_builder.treats_unknown_as_idle());
        assert_eq!(
            permissive_builder.to_text(),
            "system idle policy: threshold set true, require known false, treat unknown as idle true"
        );
        let permissive = permissive_builder.build_checked().unwrap();
        let unknown = permissive.evaluate(&snapshot);
        assert!(unknown.is_idle());
        assert!(unknown.is_unknown());
        assert!(!unknown.has_known_idle_time());
        assert_eq!(
            unknown.to_text(),
            "system idle: idle true, active false, unknown true, known idle false, threshold set true"
        );

        assert!(SystemIdlePolicyBuilder::seconds(0).build_checked().is_err());
        assert!(
            SystemIdlePolicyBuilder::seconds(30)
                .require_known_idle_time()
                .treat_unknown_as_idle()
                .build_checked()
                .is_err()
        );
    }

