    #[test]
    fn display_query_builder_validates_targets() {
        assert!(DisplayQueryBuilder::all().validate().is_ok());
        assert!(DisplayQueryBuilder::primary().validate().is_ok());
        assert!(DisplayQueryBuilder::cursor().validate().is_ok());
        assert!(
            DisplayQueryBuilder::all()
                .fallback_to_primary()
                .validate()
                .is_err()
        );
        assert!(DisplayQueryBuilder::cursor().falls_back_to_primary());
        assert!(DisplayQueryBuilder::primary().requires_match());
    }

    #[test]
    fn query_displays_checked_returns_primary_and_all_displays() {
        let cx = TestAppContext::single();

        let all = cx
            .read(|app| app.query_displays_checked(DisplayQueryBuilder::all()))
            .unwrap();
        assert!(all.has_match());
        assert_eq!(all.displays().len(), 1);
        assert_eq!(all.first().unwrap().id(), crate::DisplayId(1));
        assert!(all.first().unwrap().is_primary());
        assert_eq!(all.first().unwrap().refresh_rate(), Some(60.0));
        assert_eq!(all.first().unwrap().scale_factor(), 2.0);
        assert_eq!(
            all.first().unwrap().bounds().size,
            size(px(1920.), px(1080.))
        );
        let topology = all.topology_summary();
        assert_eq!(topology.display_count(), 1);
        assert_eq!(topology.primary_count(), 1);
        assert!(topology.has_primary());
        assert!(topology.is_single_display());
        assert!(!topology.has_multiple_displays());
        assert_eq!(topology.cursor_position(), None);
        assert_eq!(topology.cursor_display_id(), None);
        assert!(!topology.has_cursor_match());
        assert_eq!(
            topology.virtual_bounds(),
            Some(all.first().unwrap().bounds())
        );
        assert_eq!(topology.max_scale_factor(), Some(2.0));
        assert_eq!(topology.max_refresh_rate(), Some(60.0));
        assert_eq!(topology.high_dpi_display_count(), 1);
        assert_eq!(topology.high_refresh_display_count(), 0);
        assert!(topology.has_high_dpi_display());
        assert!(!topology.has_high_refresh_display());
        assert_eq!(
            topology.to_text(),
            "1 displays, 1 primary, cursor unknown, max scale 2.00x, max refresh 60.0Hz, 1 high-DPI"
        );

        let primary = cx
            .read(|app| app.query_displays_checked(DisplayQueryBuilder::primary()))
            .unwrap();
        assert_eq!(primary.target(), super::DisplayQueryTarget::Primary);
        assert_eq!(primary.first().unwrap().id(), crate::DisplayId(1));
        assert!(primary.first().unwrap().uuid().is_some());
    }

