    #[test]
    fn display_topology_handoff_builder_validates_screen_workflow() {
        let handoff = DisplayTopologyHandoffBuilder::new()
            .display_query(DisplayQueryBuilder::all())
            .display_query(DisplayQueryBuilder::cursor().fallback_to_primary())
            .window_placement(
                WindowPlacementBuilder::new(size(px(420.), px(320.))).bottom_right(px(16.)),
            )
            .runtime_snapshot(AppRuntimeSnapshotQueryBuilder::new().require_window())
            .focused_window(FocusedWindowQueryBuilder::new().current_process_only())
            .hosted_screen_island("chart-device-pixel-ratio")
            .roadmap_work("display change observer recipes")
            .build_checked()
            .unwrap();

        assert_eq!(handoff.request_count(), 7);
        assert!(handoff.has_display_query());
        assert!(handoff.has_window_placement());
        assert!(handoff.has_runtime_snapshot());
        assert!(handoff.has_focused_window_query());
        assert!(handoff.has_hosted_screen_island());
        assert!(handoff.has_roadmap_work());
        assert_eq!(
            handoff.next_action(),
            DisplayTopologyNextAction::QueryNativeDisplays
        );
        assert_eq!(handoff.next_action().key(), "query-native-displays");

        let text = handoff.to_text();
        assert!(text.contains("display topology handoff"));
        assert!(text.contains("display-query:2"));
        assert!(!text.contains("chart-device-pixel-ratio"));
        assert!(!text.contains("display change observer"));
        assert!(!text.contains("DisplayId"));
    }

