    #[test]
    fn display_topology_handoff_next_action_covers_routes() {
        let placement = DisplayTopologyHandoffBuilder::new()
            .window_placement(WindowPlacementBuilder::new(size(px(320.), px(180.))))
            .build_checked()
            .unwrap();
        assert_eq!(
            placement.next_action(),
            DisplayTopologyNextAction::ResolveWindowPlacement
        );

        let runtime = DisplayTopologyHandoffBuilder::new()
            .runtime_snapshot(AppRuntimeSnapshotQueryBuilder::new().require_not_quitting())
            .build_checked()
            .unwrap();
        assert_eq!(
            runtime.next_action(),
            DisplayTopologyNextAction::ReviewRuntimeState
        );

        let focused = DisplayTopologyHandoffBuilder::new()
            .focused_window(FocusedWindowQueryBuilder::new().require_title())
            .build_checked()
            .unwrap();
        assert_eq!(
            focused.next_action(),
            DisplayTopologyNextAction::QueryFocusedWindow
        );

        let hosted = DisplayTopologyHandoffBuilder::new()
            .hosted_screen_island("orientation-widget")
            .build_checked()
            .unwrap();
        assert_eq!(
            hosted.next_action(),
            DisplayTopologyNextAction::UseHostedScreenIsland
        );

        let roadmap = DisplayTopologyHandoffBuilder::new()
            .roadmap_work("native color-space policy")
            .build_checked()
            .unwrap();
        assert_eq!(
            roadmap.next_action(),
            DisplayTopologyNextAction::TrackDisplayRoadmap
        );
    }

