    #[test]
    fn user_attention_builder_preserves_intent() {
        let attention = UserAttentionBuilder::critical().reason("background export failed");

        assert_eq!(attention.attention_type(), AttentionType::Critical);
        assert_eq!(
            attention.configured_reason(),
            Some("background export failed")
        );
        assert!(attention.validate().is_ok());
        let plan = attention.build_plan_checked().unwrap();
        assert_eq!(plan.attention_type(), AttentionType::Critical);
        assert_eq!(plan.reason(), Some("background export failed"));
        assert!(!plan.is_informational());
        assert!(plan.is_critical());
        assert!(plan.has_reason());
        assert_eq!(plan.to_text(), "user attention critical: reason true");
        assert!(!plan.to_text().contains("background export failed"));
        assert_eq!(
            plan.into_parts(),
            (
                AttentionType::Critical,
                Some("background export failed".to_string())
            )
        );
        assert!(
            UserAttentionBuilder::informational()
                .reason(" ")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn request_user_attention_with_returns_cancellable_request() {
        let cx = TestAppContext::single();

        let request = cx.read(|app| {
            app.request_user_attention_with(
                UserAttentionBuilder::informational().reason("download complete"),
            )
        });

        assert_eq!(request.attention_type(), AttentionType::Informational);
        assert_eq!(request.reason(), Some("download complete"));
        assert!(request.is_informational());
        assert!(!request.is_critical());
        assert!(request.has_reason());
        assert_eq!(
            request.to_text(),
            "user attention informational: reason true"
        );
        assert!(!request.to_text().contains("download complete"));
        assert_eq!(cx.user_attention(), Some(AttentionType::Informational));

        cx.read(|app| request.cancel(app));

        assert_eq!(cx.user_attention(), None);
        assert_eq!(cx.user_attention_cancel_count(), 1);
    }

    #[test]
    fn request_user_attention_checked_validates_reason() {
        let cx = TestAppContext::single();

        let plan = cx
            .read(|app| {
                app.user_attention_plan_checked(
                    UserAttentionBuilder::informational().reason("build finished"),
                )
            })
            .unwrap();
        assert_eq!(plan.attention_type(), AttentionType::Informational);
        assert!(plan.is_informational());
        assert!(plan.has_reason());
        assert_eq!(plan.to_text(), "user attention informational: reason true");
        assert!(!plan.to_text().contains("build finished"));
        assert_eq!(cx.user_attention(), None);
        assert!(
            cx.read(|app| {
                app.user_attention_plan_checked(UserAttentionBuilder::critical().reason(""))
            })
            .is_err()
        );

        let request = cx
            .read(|app| {
                app.request_user_attention_checked(
                    UserAttentionBuilder::critical().reason("sync failed"),
                )
            })
            .unwrap();

        assert_eq!(request.attention_type(), AttentionType::Critical);
        assert_eq!(request.reason(), Some("sync failed"));
        assert!(request.is_critical());
        assert_eq!(request.to_text(), "user attention critical: reason true");
        assert!(!request.to_text().contains("sync failed"));
        assert_eq!(cx.user_attention(), Some(AttentionType::Critical));

        let planned = UserAttentionBuilder::informational()
            .reason("build finished")
            .build_plan_checked()
            .unwrap();
        let request = cx
            .read(|app| app.request_user_attention_plan_checked(planned))
            .unwrap();
        assert_eq!(
            request.to_text(),
            "user attention informational: reason true"
        );
        assert!(!request.to_text().contains("build finished"));

        let error = cx.read(|app| {
            app.request_user_attention_checked(UserAttentionBuilder::informational().reason(""))
        });

        assert!(error.is_err());
    }

    #[test]
    fn cancel_user_attention_checked_validates_reason() {
        let cx = TestAppContext::single();

        cx.read(|app| {
            app.request_user_attention(AttentionType::Critical);
        });
        assert_eq!(cx.user_attention(), Some(AttentionType::Critical));

        assert!(
            cx.read(|app| app.cancel_user_attention_checked(UserAttentionCancelBuilder::new("")))
                .is_err()
        );
        assert_eq!(cx.user_attention(), Some(AttentionType::Critical));
        assert_eq!(cx.user_attention_cancel_count(), 0);

        let cancel = cx
            .read(|app| {
                app.cancel_user_attention_checked(UserAttentionCancelBuilder::condition_resolved(
                    "sync recovered",
                ))
            })
            .unwrap();

        assert_eq!(cancel.reason(), "sync recovered");
        assert_eq!(cancel.to_text(), "cancel user attention: reason true");
        assert!(!cancel.to_text().contains("sync recovered"));
        assert_eq!(cx.user_attention(), None);
        assert_eq!(cx.user_attention_cancel_count(), 1);
        assert!(
            UserAttentionCancelBuilder::new("bad\nreason")
                .validate()
                .is_err()
        );
    }

