    #[cfg(feature = "media")]
    #[test]
    fn app_video_element_handoff_and_customization_use_checked_builders() {
        let cx = TestAppContext::single();
        let video_url = "https://cdn.example.com/movie.mp4";

        let handoff = cx
            .read(|app| {
                app.video_element_handoff_checked(
                    VideoElementHandoffBuilder::url(video_url)
                        .initial_controls(
                            VideoPlaybackControlsBuilder::new()
                                .volume(0.6)
                                .muted(false)
                                .playback_rate(1.0),
                        )
                        .playlist(VideoPlaylist::new([MediaSource::url(video_url)])),
                )
            })
            .unwrap();

        assert!(handoff.has_initial_controls());
        assert!(handoff.has_playlist());
        assert_eq!(handoff.playlist_source_count(), 1);
        assert_eq!(
            handoff.next_action(),
            VideoElementHandoffNextAction::AcceptLimitedSupport
        );

        let customization = cx
            .read(|app| {
                app.video_element_customization_plan_checked(
                    VideoElementCustomizationPlanBuilder::new(handoff.clone())
                        .html_video_baseline()
                        .timeline_scrubbing()
                        .captions_ui()
                        .fullscreen()
                        .picture_in_picture()
                        .playlist_media_keys(),
                )
            })
            .unwrap();

        assert!(customization.has_feature(VideoElementCustomizationFeature::CustomControls));
        assert!(customization.has_feature(VideoElementCustomizationFeature::TimelineScrubbing));
        assert_eq!(customization.event_handler_count(), 8);
        assert_eq!(customization.custom_control_count(), 5);
        assert!(customization.feature_count() >= 8);

        assert!(
            cx.read(|app| {
                app.video_element_handoff_checked(VideoElementHandoffBuilder::url(
                    " https://cdn.example.com/movie.mp4",
                ))
            })
            .is_err()
        );
        assert!(
            cx.read(|app| {
                app.video_element_customization_plan_checked(
                    VideoElementCustomizationPlanBuilder::new(handoff),
                )
            })
            .is_err()
        );
    }

    #[cfg(feature = "media")]
    #[test]
    fn media_key_binding_routes_playback_keys_to_video_controller() {
        let cx = TestAppContext::single();
        let controller = VideoController::bytes(Arc::<[u8]>::from([]));

        cx.read(|app| {
            MediaKeyBindingBuilder::new()
                .video(controller.clone())
                .install(app)
        });

        cx.simulate_media_key_event(MediaKeyEvent::Pause);
        cx.simulate_media_key_event(MediaKeyEvent::Stop);

        let events = controller.drain_events();
        assert!(
            events
                .iter()
                .any(|event| matches!(event, VideoEvent::Paused))
        );
        assert!(
            events
                .iter()
                .any(|event| matches!(event, VideoEvent::Stopped))
        );
    }

    #[cfg(feature = "media")]
    #[test]
    fn media_key_binding_routes_track_and_unhandled_callbacks() {
        let cx = TestAppContext::single();
        let next_count = Rc::new(std::cell::Cell::new(0));
        let previous_count = Rc::new(std::cell::Cell::new(0));
        let unhandled_count = Rc::new(std::cell::Cell::new(0));

        cx.read(|app| {
            MediaKeyBindingBuilder::new()
                .on_next_track({
                    let next_count = next_count.clone();
                    move |_| next_count.set(next_count.get() + 1)
                })
                .on_previous_track({
                    let previous_count = previous_count.clone();
                    move |_| previous_count.set(previous_count.get() + 1)
                })
                .on_unhandled({
                    let unhandled_count = unhandled_count.clone();
                    move |_, _| unhandled_count.set(unhandled_count.get() + 1)
                })
                .install(app)
        });

        cx.simulate_media_key_event(MediaKeyEvent::NextTrack);
        cx.simulate_media_key_event(MediaKeyEvent::PreviousTrack);
        cx.simulate_media_key_event(MediaKeyEvent::Stop);

        assert_eq!(next_count.get(), 1);
        assert_eq!(previous_count.get(), 1);
        assert_eq!(unhandled_count.get(), 1);
    }
